def validate_post_battle_report_screen(errors: list[str]) -> None:
    for path in (
        POST_BATTLE_REPORT_SCRIPT_PATH,
        POST_BATTLE_REPORT_SCENE_PATH,
        POST_BATTLE_REPORT_RUNTIME_SCRIPT_PATH,
        POST_BATTLE_REPORT_RUNTIME_SCENE_PATH,
        POST_BATTLE_REPORT_REQUIREMENTS_PATH,
        BATTLE_SCRIPT_PATH,
        BATTLE_SCENE_PATH,
        BATTLE_RULES_PATH,
        APP_ROUTER_PATH,
    ):
        ensure(path.exists(), errors, f"Missing post-battle report file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (
        POST_BATTLE_REPORT_SCRIPT_PATH,
        POST_BATTLE_REPORT_SCENE_PATH,
        POST_BATTLE_REPORT_RUNTIME_SCRIPT_PATH,
        BATTLE_RULES_PATH,
        APP_ROUTER_PATH,
        BATTLE_SCRIPT_PATH,
    )):
        return

    rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        '"report_version": 1',
        '"pending": true',
        '"casualties": casualty_ledger',
        '"report_id"',
        "func pending_battle_report(",
        "func acknowledge_pending_battle_report(",
        "func battle_report_casualty_ledger_bridge(",
        "func _battle_report_side_casualties(",
        '"starting": starting_count',
        '"surviving": surviving_count',
        '"lost": lost_count',
        '"destroyed": starting_count > 0 and surviving_count <= 0',
    ):
        ensure(required_token in rules_text, errors, f"BattleRules.gd is missing post-battle report authority token: {required_token}")
    ensure(
        rules_text.count("_record_battle_aftermath(") >= 8,
        errors,
        "Every terminal battle family must continue through the shared aftermath/report recorder",
    )

    router_text = APP_ROUTER_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const BATTLE_REPORT_SCENE := "res://scenes/battle/BattleReportShell.tscn"',
        "func go_to_battle_report(",
        "func complete_battle_report(",
        "BattleRules.pending_battle_report(session)",
        "BattleRules.acknowledge_pending_battle_report(session)",
        "SaveService.save_runtime_autosave_session(session)",
        "session.from_dict(snapshot)",
        '_record_battle_resolution_checkpoint_route(BATTLE_REPORT_SCENE, "already_saved")',
        "func validation_battle_report_snapshot(",
    ):
        ensure(required_token in router_text, errors, f"AppRouter.gd is missing post-battle report routing token: {required_token}")

    battle_shell_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        '_record_validation_battle_resolution_attempt(result, "battle_report")',
        '_begin_battle_exit_animation_handoff(result, "battle_report")',
        "AppRouter.go_to_battle_report()",
    ):
        ensure(required_token in battle_shell_text, errors, f"BattleShell.gd is missing report-first terminal routing token: {required_token}")

    scene_text = POST_BATTLE_REPORT_SCENE_PATH.read_text(encoding="utf-8")
    for required_token in (
        '[node name="BattleReportShell" type="Control"]',
        '[node name="CasualtyScroll" type="ScrollContainer"',
        '[node name="CasualtyGrid" type="GridContainer"',
        '[node name="PlayerRows" type="VBoxContainer"',
        '[node name="EnemyRows" type="VBoxContainer"',
        '[node name="AftermathPanel" type="PanelContainer"',
        'accessibility_name = "Continue from battle report"',
        'method="_on_continue_pressed"',
    ):
        ensure(required_token in scene_text, errors, f"BattleReportShell.tscn is missing required presentation token: {required_token}")

    shell_text = POST_BATTLE_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_casualty_grid.columns = 1 if _compact_layout else 2",
        "func _populate_side(",
        "func _add_casualty_row(",
        "AppRouter.complete_battle_report()",
        "_continue_button.grab_focus()",
        "func validation_snapshot(",
    ):
        ensure(required_token in shell_text, errors, f"BattleReportShell.gd is missing required runtime token: {required_token}")

    report_text = POST_BATTLE_REPORT_RUNTIME_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "POST_BATTLE_REPORT_RUNTIME_REPORT",
        'const OUTCOME_FAMILIES := ["victory", "defeat", "hero_defeat", "town_lost", "retreat", "surrender", "enemy_retreat", "enemy_surrender", "stalemate"]',
        "BattleAutoResolveRulesScript.resolve_active_battle(session)",
        "SaveService.save_runtime_autosave_session(session)",
        "SaveService.restore_autosave_session()",
        "AppRouter.complete_battle_report(true)",
        'OS.set_environment(FAILURE_ENV, "precommit")',
        "CAPTURE_SIZES := [Vector2i(2048, 1079), Vector2i(1280, 720)]",
        '"compact_960x720_columns": 1',
    ):
        ensure(required_token in report_text, errors, f"Post-battle report runtime coverage is missing token: {required_token}")


def validate_briefing_consumption_autosave_failure_safety(errors: list[str]) -> None:
    for path in (
        BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_REGRESSION_SCRIPT_PATH,
        BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_REGRESSION_SCENE_PATH,
        OVERWORLD_SCRIPT_PATH,
        BATTLE_SCRIPT_PATH,
    ):
        ensure(path.exists(), errors, f"Missing briefing-consumption autosave safety file: {path.relative_to(ROOT)}")
    if not BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_REGRESSION_SCRIPT_PATH.exists():
        return

    report_text = BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_REGRESSION_SCRIPT_PATH.read_text(encoding="utf-8")
    save_service_text = SAVE_SERVICE_PATH.read_text(encoding="utf-8")
    for required_token in (
        "BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_SAFETY_REGRESSION",
        'const FAILURE_PHASES := ["precommit", "after_backup"]',
        'const SURFACES := ["overworld", "battle"]',
        'const DETAIL_SURFACES := ["overworld", "town", "battle", "outcome"]',
        "validation_briefing_consumption_autosave_snapshot",
        "validation_reconcile_briefing_consumption_autosave_recovery_direct",
        "validation_save_to_selected_slot",
        'String(issue.get("event", "")) != "briefing_consumption_autosave_failed"',
        'String(snapshot.get("focus_owner", "")) != "Save"',
        'snapshot.get("autosave_attempt_count", -1)) != 1',
        'snapshot.get("resolution_route_attempt_count", -1)) != 0',
        "_file_state(AUTOSAVE_PATH) != autosave_before",
        "SaveService.validation_summary_cache_snapshot() != cache_before",
        "_transaction_artifacts_absent(AUTOSAVE_PATH)",
        "_prove_ordinary_success",
        "_prove_generated_overworld_defer",
        "_prove_alternate_end_turn_reconciliation",
        "_prove_alternate_end_turn_failure",
        'String(end_result.get("retry_action", "")) != "save"',
        'String(reconciliation.get("reason", "")) != "alternate_autosave_saved"',
        'String(recovery.get("focus_owner", "")) != "EndTurn"',
        "verified_alternate_proof_current",
        "authority_not_canonical",
        "alternate_save_not_verified",
        "validation_request_manual_save",
        "_prove_runtime_summary_detail_parity",
        "_summary_detail_fixture",
        "SaveService.validation_last_runtime_save_profile()",
        "SaveService.describe_slot_details(summary)",
        'String(summary.get("detail", "")) != direct_detail',
        'cached_summary != summary',
        "SaveService.restore_session_from_summary(summary)",
        "_gameplay_payload(restored_from_inline_summary) != _gameplay_payload(session)",
        'bool(summary.get("payload_deferred", true))',
        'summary_owned_session_materialization_count',
        'summary_detail_context_build_count',
        'summary_detail_context_reuse_count',
        'summary_detail_direct_fallback_count',
        'float(buckets.get("summary_cache", 99999.0)) >= 1000.0',
        '_file_state(AUTOSAVE_PATH) != file_before_direct',
        'SaveService.validation_summary_cache_snapshot() != cache_before_direct',
    ):
        ensure(required_token in report_text, errors, f"Briefing-consumption autosave safety regression is missing required token: {required_token}")

    for required_token in (
        "func _finalize_runtime_summary(summary: Dictionary, profile: Dictionary = {}) -> Dictionary:",
        'if bool(summary.get("payload_deferred", false)) or payload.is_empty():',
        "_session_from_owned_detached_payload(payload)",
        "OverworldRulesScript.begin_normalized_read_scope(trusted_session)",
        "TownRulesScript.begin_read_scope(trusted_session)",
        "describe_session_progress_recap_from_normalized_session(trusted_session, true)",
        'progress_recap.trim_prefix("Progress Recap\\n")',
        "_session_save_recap_context(trusted_session, summary, progress_without_header)",
        "_describe_slot_details(summary, trusted_session, recap_context, progress_recap)",
        "TownRulesScript.end_read_scope(trusted_session)",
        "OverworldRulesScript.end_normalized_read_scope(trusted_session)",
        'profile["summary_owned_session_materialization_count"]',
        'profile["summary_detail_context_build_count"]',
        'profile["summary_detail_context_reuse_count"]',
        'profile["summary_detail_direct_fallback_count"]',
        '"summary_detail_context"',
        "func _summary_continuity_lines_from_context(",
        "_summary_objective_line_from_progress_recap",
        "_store_slot_summary_cache(_finalize_runtime_summary(summary, profile))",
    ):
        ensure(required_token in save_service_text, errors, f"SaveService runtime summary-detail context contract is missing token: {required_token}")
    ensure(
        save_service_text.count("func _finalize_runtime_summary(") == 1
        and save_service_text.count("_store_slot_summary_cache(_finalize_runtime_summary(summary, profile))") == 1,
        errors,
        "SaveService must own one runtime summary-detail finalizer and one cache publication call",
    )
    ensure(
        '_slot_summary_cache["summary_detail_context"' not in save_service_text
        and 'session.flags["summary_detail_context"' not in save_service_text
        and "_store_slot_summary_cache(_finalize_summary(summary))" not in save_service_text,
        errors,
        "Runtime summary-detail reuse must remain invocation-local and must replace the old runtime direct finalizer",
    )

    scene_text = BRIEFING_CONSUMPTION_AUTOSAVE_FAILURE_REGRESSION_SCENE_PATH.read_text(encoding="utf-8")
    ensure(
        "res://tests/briefing_consumption_autosave_failure_safety_regression.gd" in scene_text,
        errors,
        "Briefing-consumption autosave safety scene must load its regression script",
    )
    for shell_path in (OVERWORLD_SCRIPT_PATH, BATTLE_SCRIPT_PATH):
        shell_text = shell_path.read_text(encoding="utf-8")
        for required_token in (
            '"briefing_consumption_autosave_failed"',
            "func validation_briefing_consumption_autosave_snapshot()",
            '"autosave_attempt_count"',
            '"failure_pending"',
            '"last_runtime_issue"',
        ):
            ensure(required_token in shell_text, errors, f"{shell_path.name} is missing required briefing-consumption autosave safety token: {required_token}")

    overworld_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func validation_reconcile_briefing_consumption_autosave_recovery_direct()",
        '"reconciliation_count"',
        '"authoritative_briefing_canonical"',
        '"verified_alternate_proof_current"',
        '"alternate_autosave_saved"',
        '"alternate_save_not_verified"',
        "_briefing_consumption_autosave_authority_canonical()",
    ):
        ensure(required_token in overworld_text, errors, f"OverworldShell.gd is missing required briefing alternate-autosave reconciliation token: {required_token}")


