def validate_battle_terrain_context_and_system_frame(errors: list[str]) -> None:
    smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    visual_report_path = ROOT / "tests" / "ui_runtime_skin_visual_report.gd"
    required_paths = (BATTLE_BOARD_VIEW_SCRIPT_PATH, BATTLE_SCRIPT_PATH, smoke_path, visual_report_path)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing Battle terrain-context/System-frame file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    def gdscript_function_block(text: str, name: str) -> str:
        match = re.search(
            rf"^func {re.escape(name)}\([^\n]*\)[^\n]*:\n[\s\S]*?(?=^func |\Z)",
            text,
            re.MULTILINE,
        )
        return match.group(0) if match else ""

    board_text = BATTLE_BOARD_VIEW_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const TERRAIN_TEXTURE_MODULATE := Color(0.84, 0.86, 0.80, 0.24)',
        'const TERRAIN_CONTEXT_TEXTURE_MODULATE := Color(0.78, 0.81, 0.75, 0.92)',
        'const TERRAIN_CONTEXT_READABILITY_WASH := Color(0.015, 0.020, 0.018, 0.10)',
        'const TERRAIN_CONTEXT_MODEL := "continuous_primary_field_with_subordinate_hex_variation"',
        '"terrain_context_underlay_enabled": texture != null',
        '"terrain_context_covers_full_field": texture != null and field_rect.size.x > 0.0 and field_rect.size.y > 0.0',
        '"terrain_context_preserves_hex_authority": texture != null and int(sampling_summary.get("texture_source_sample_count", 0)) == _terrain_hex_tile_count()',
        '"terrain_context_primary": texture != null and TERRAIN_CONTEXT_TEXTURE_MODULATE.a > TERRAIN_TEXTURE_MODULATE.a',
        '"terrain_hex_variation_subordinate": texture != null and TERRAIN_TEXTURE_MODULATE.a >= 0.18 and TERRAIN_TEXTURE_MODULATE.a <= 0.30',
        '"single_board_backdrop": texture != null',
        '"terrain_single_board_backdrop": terrain_texture != null',
        '"texture_sample_mode": "continuous_field_plus_subordinate_per_hex_variation" if texture != null else ""',
    ):
        ensure(required_token in board_text, errors, f"BattleBoardView terrain context is missing exact authority token: {required_token}")
    for rejected_token in (
        'const TERRAIN_TEXTURE_MODULATE := Color(0.98, 0.99, 0.95, 0.98)',
        'const TERRAIN_CONTEXT_TEXTURE_MODULATE := Color(0.56, 0.60, 0.52, 0.72)',
        'const TERRAIN_CONTEXT_MODEL := "subdued_full_field_underlay_beneath_authoritative_hex_grid"',
        '"texture_sample_mode": "per_hex_clipped" if texture != null else ""',
    ):
        ensure(rejected_token not in board_text, errors, f"BattleBoardView must not retain the rejected disconnected terrain blend: {rejected_token}")
    draw_terrain = gdscript_function_block(board_text, "_draw_terrain")
    ensure(draw_terrain != "", errors, "Could not isolate BattleBoardView _draw_terrain")
    if draw_terrain:
        context_index = draw_terrain.find("_draw_terrain_context_underlay(field_rect, terrain_texture)")
        hex_index = draw_terrain.find("_draw_hex_snapped_terrain_texture(hex_layout, terrain_texture)")
        ensure(context_index >= 0 and hex_index > context_index, errors, "Battle continuous terrain field must draw before the subordinate authoritative per-hex variation pass")
        ensure('_draw_terrain_context_underlay(field_rect, terrain_texture)' in draw_terrain.split("else:", 1)[0], errors, "Battle texture context must be confined to the loaded-texture branch")
    context_helper = gdscript_function_block(board_text, "_draw_terrain_context_underlay")
    for required_token in (
        "texture.get_size()",
        "draw_texture_rect(texture, field_rect, false, TERRAIN_CONTEXT_TEXTURE_MODULATE)",
        "draw_rect(field_rect, TERRAIN_CONTEXT_READABILITY_WASH, true)",
    ):
        ensure(required_token in context_helper, errors, f"Battle terrain context helper is missing passive draw token: {required_token}")
    for forbidden_token in ("await ", "Timer", "session", "BattleRules", "Input.", "set_battle_state", "queue_redraw", "_draw_terrain_edge_context", "_terrain_edge_context_rects", "_terrain_edge_source_rect"):
        ensure(forbidden_token not in context_helper, errors, f"Battle terrain context helper must remain a passive full-field underlay: {forbidden_token}")
    for obsolete_token in ("TERRAIN_EDGE_CONTEXT", "_draw_terrain_edge_context", "_terrain_edge_context_rects", "_terrain_edge_source_rect"):
        ensure(obsolete_token not in board_text, errors, f"BattleBoardView must not retain the incomplete rectangular-edge terrain model: {obsolete_token}")
    rendering_mode = gdscript_function_block(board_text, "_terrain_rendering_mode")
    ensure('return "continuous_field_with_hex_variation" if texture_loaded else "hex_snapped_color_fallback"' in rendering_mode, errors, "Battle terrain rendering mode must distinguish the cohesive textured field from the procedural fallback")
    texture_visible = gdscript_function_block(board_text, "_terrain_texture_visible")
    for required_token in (
        "TERRAIN_CONTEXT_TEXTURE_MODULATE.a >= 0.88",
        "TERRAIN_TEXTURE_MODULATE.a >= 0.18",
        "TERRAIN_TEXTURE_MODULATE.a <= 0.30",
        "TERRAIN_CONTEXT_TEXTURE_MODULATE.a > TERRAIN_TEXTURE_MODULATE.a",
    ):
        ensure(required_token in texture_visible, errors, f"Battle cohesive terrain visibility guard is missing exact blend bound: {required_token}")

    for required_token in (
        'const TERRAIN_AMBIENT_MODEL := "deterministic_terrain_specific_passive_motes"',
        'const TERRAIN_AMBIENT_DRAW_ORDER := ["terrain", "ambient_motes", "hex_grid", "objectives", "movement_affordances", "controller_cursor", "battle_vfx", "stack_tokens", "turn_strip", "footer"]',
        'const TERRAIN_AMBIENT_PHASE_SPEED := 0.52',
        'const TERRAIN_AMBIENT_STATIC_PHASE := 0.0',
        '"grass": {"id": "sunlit_pollen", "kind": "pollen", "count": 14',
        '"forest": {"id": "forest_fireflies", "kind": "firefly", "count": 11',
        '"swamp": {"id": "swamp_wisps", "kind": "wisp", "count": 10',
        '"rough": {"id": "roughland_dust", "kind": "dust", "count": 12',
        '"road": {"id": "roadside_dust", "kind": "dust", "count": 9',
        '"mire": {"id": "mire_wisps", "kind": "wisp", "count": 12',
        'var _terrain_ambient_phase := TERRAIN_AMBIENT_STATIC_PHASE',
        'func _terrain_ambient_profile() -> Dictionary:',
        'func _terrain_ambient_available() -> bool:',
        'func _terrain_ambient_should_animate() -> bool:',
        'func _terrain_ambient_entries(field_rect: Rect2, phase: float) -> Array:',
        'func _draw_terrain_ambient(field_rect: Rect2) -> void:',
        'func validation_terrain_ambient_summary() -> Dictionary:',
    ):
        ensure(required_token in board_text, errors, f"Battle terrain ambience is missing exact presentation ownership: {required_token}")
    battle_draw = gdscript_function_block(board_text, "_draw")
    ambient_draw_order = [battle_draw.find(token) for token in (
        "_draw_terrain(field_rect, hex_layout)",
        "_draw_terrain_ambient(field_rect)",
        "_draw_hex_grid(hex_layout, terrain_texture_loaded)",
        "_draw_field_objectives(hex_layout)",
        "_draw_tactical_affordances(hex_layout, stack_cells)",
        "_draw_controller_cursor(hex_layout)",
        "_draw_vfx_cues(hex_layout, stack_cells)",
        "_draw_stack_tokens(hex_layout, stack_cells)",
        "_draw_turn_strip(field_rect)",
        "_draw_footer_line(field_rect)",
    )]
    ensure(all(index >= 0 for index in ambient_draw_order) and ambient_draw_order == sorted(ambient_draw_order), errors, "Battle ambient motes must draw after terrain and before every tactical/UI surface")
    ambient_process = gdscript_function_block(board_text, "_process")
    for required_token in (
        "if _terrain_ambient_should_animate():",
        "_terrain_ambient_phase = fmod(_terrain_ambient_phase + delta * TERRAIN_AMBIENT_PHASE_SPEED, TAU)",
        "_terrain_ambient_phase = TERRAIN_AMBIENT_STATIC_PHASE",
    ):
        ensure(required_token in ambient_process, errors, f"Battle terrain ambient lifecycle is missing exact frame-owned token: {required_token}")
    ambient_profile = gdscript_function_block(board_text, "_terrain_ambient_profile")
    ambient_available = gdscript_function_block(board_text, "_terrain_ambient_available")
    ambient_should_animate = gdscript_function_block(board_text, "_terrain_ambient_should_animate")
    ambient_entries = gdscript_function_block(board_text, "_terrain_ambient_entries")
    ambient_draw = gdscript_function_block(board_text, "_draw_terrain_ambient")
    ambient_summary = gdscript_function_block(board_text, "validation_terrain_ambient_summary")
    for required_token in (
        "TERRAIN_AMBIENT_PROFILES.get(_terrain_texture_id(_battle_terrain_id()), {})",
        "return profile_value if profile_value is Dictionary else {}",
    ):
        ensure(required_token in ambient_profile, errors, f"Battle terrain ambience must resolve only through the authored terrain alias/profile table: {required_token}")
    for required_token in (
        "not _battle.is_empty()",
        "not _terrain_ambient_profile().is_empty()",
        "not FrontierVisualKitScript.high_contrast_enabled()",
    ):
        ensure(required_token in ambient_available, errors, f"Battle terrain ambience availability is missing fail-closed context: {required_token}")
    ensure("not SettingsService.reduced_motion_enabled()" in ambient_should_animate, errors, "Battle terrain ambience must stop animation in Reduced Motion")
    for required_token in (
        'var radius := clampf(minf(field_rect.size.x, field_rect.size.y) * float(profile.get("radius_factor", 0.0024)), 1.15, 2.55)',
        "var safe_rect := field_rect.grow(-safe_inset)",
        "for index in range(int(profile.get(\"count\", 0))):",
        "fmod(0.173 + float(index) * 0.347, 1.0)",
        "fmod(0.291 + float(index) * 0.613, 1.0)",
        "sin(local_phase) * drift.x",
        "cos(local_phase * 0.73 + float(index) * 0.41) * drift.y",
        '"contained": field_rect.encloses(bounds)',
    ):
        ensure(required_token in ambient_entries, errors, f"Battle terrain ambient entries are missing deterministic contained geometry: {required_token}")
    for required_token in (
        "if not _terrain_ambient_available():",
        "var phase := TERRAIN_AMBIENT_STATIC_PHASE if SettingsService.reduced_motion_enabled() else _terrain_ambient_phase",
        "for entry_value in _terrain_ambient_entries(field_rect, phase):",
        'if String(entry.get("kind", "")) == "dust":',
        "draw_line(",
        "draw_circle(",
    ):
        ensure(required_token in ambient_draw, errors, f"Battle terrain ambient painter is missing restrained accessibility-aware draw ownership: {required_token}")
    for required_token in (
        '"model": TERRAIN_AMBIENT_MODEL',
        '"draw_order": TERRAIN_AMBIENT_DRAW_ORDER.duplicate()',
        '"reduced_motion": reduced_motion',
        '"high_contrast": FrontierVisualKitScript.high_contrast_enabled()',
        '"session_mutation_source": "none_presentation_only"',
    ):
        ensure(required_token in ambient_summary, errors, f"Battle terrain ambient validation is missing detached contract evidence: {required_token}")
    for helper_name, helper in (
        ("_terrain_ambient_profile", ambient_profile),
        ("_terrain_ambient_available", ambient_available),
        ("_terrain_ambient_should_animate", ambient_should_animate),
        ("_terrain_ambient_entries", ambient_entries),
        ("_draw_terrain_ambient", ambient_draw),
        ("validation_terrain_ambient_summary", ambient_summary),
    ):
        for forbidden_token in ("BattleRules", "SessionState", "SaveService", "AppRouter", "Input.", "rand", "Time.", "Timer", "Tween", "Particle", "await ", "create_timer", "create_tween", "session.", "_battle["):
            ensure(forbidden_token not in helper, errors, f"Battle terrain ambient helper {helper_name} must remain deterministic presentation-only: {forbidden_token}")

    shell_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "var _wide_system_panel_style: StyleBox = null",
        "var system_panel_style := _system_panel.get_theme_stylebox(\"panel\")",
        "_wide_system_panel_style = system_panel_style.duplicate()",
        '_system_panel.add_theme_stylebox_override("panel", _compact_system_panel_style)',
        '_system_panel.add_theme_stylebox_override("panel", _wide_system_panel_style)',
    ):
        ensure(required_token in shell_text, errors, f"Battle System frame lifecycle is missing token: {required_token}")
    theme_body = gdscript_function_block(shell_text, "_apply_visual_theme")
    authored_apply = theme_body.find("FrontierVisualKit.apply_art_panel(_system_panel, UI_ART_BATTLE_COMBAT_LOG_PANEL")
    wide_capture = theme_body.find("_wide_system_panel_style = system_panel_style.duplicate()")
    ensure(authored_apply >= 0 and wide_capture > authored_apply, errors, "BattleShell must capture the wide System frame only after applying the authored art panel")
    responsive_body = gdscript_function_block(shell_text, "_apply_responsive_layout")
    for required_token in (
        "var compact_layout := available_size.x < 1360.0 or available_size.y < 760.0",
        "if compact_layout:",
        '_system_panel.add_theme_stylebox_override("panel", _compact_system_panel_style)',
        "elif _wide_system_panel_style != null:",
        '_system_panel.add_theme_stylebox_override("panel", _wide_system_panel_style)',
        "_speed_bar.visible = not compact_layout",
    ):
        ensure(required_token in responsive_body, errors, f"Battle responsive System frame is missing exact compact/wide token: {required_token}")

    smoke_text = smoke_path.read_text(encoding="utf-8")
    smoke_helper = gdscript_function_block(smoke_text, "_assert_battle_system_frame_roundtrip")
    for required_token in (
        "var session_before: Dictionary = session.to_dict()",
        "var original_shell_size := shell_control.size",
        'var expected_action_names := ["SaveSlot", "Save", "Settings", "Menu"]',
        "window.size = Vector2i(1280, 720)",
        "shell_control.size = Vector2(1280.0, 720.0)",
        "not compact_style is StyleBoxEmpty",
        "window.size = Vector2i(1920, 1080)",
        "shell_control.size = Vector2(1920.0, 1080.0)",
        'wide_texture_path != "res://art/ui/runtime/battle/combat_log_panel.png"',
        "window.size = original_window_size",
        "shell_control.size = original_shell_size",
        "session.to_dict() != session_before",
    ):
        ensure(required_token in smoke_helper, errors, f"Battle focused System-frame roundtrip is missing token: {required_token}")
    ensure(smoke_text.count("await _assert_battle_system_frame_roundtrip(shell, session)") == 1, errors, "Town/Battle visual smoke must run the responsive System-frame roundtrip exactly once")
    for required_token in (
        'String(terrain_summary.get("rendering_mode", "")) != "continuous_field_with_hex_variation"',
        'String(terrain_summary.get("texture_sample_mode", "")) != "continuous_field_plus_subordinate_per_hex_variation"',
        'String(terrain_summary.get("terrain_context_model", "")) != "continuous_primary_field_with_subordinate_hex_variation"',
        'terrain_summary.get("terrain_context_preserves_hex_authority", false)',
        'terrain_summary.get("terrain_context_primary", false)',
        'terrain_summary.get("terrain_hex_variation_subordinate", false)',
        'terrain_summary.get("terrain_context_texture_modulate_alpha", 0.0)), 0.92',
        'terrain_summary.get("texture_modulate_alpha", 0.0)), 0.24',
        'String(missing_summary.get("terrain_context_model", "")) != "disabled_for_texture_fallback"',
    ):
        ensure(required_token in smoke_text, errors, f"Battle focused terrain-context proof is missing token: {required_token}")

    ambient_smoke = gdscript_function_block(smoke_text, "_assert_battle_terrain_ambient_contract")
    ambient_exact = gdscript_function_block(smoke_text, "_battle_terrain_ambient_summary_exact")
    for required_token in (
        'board.has_method("validation_terrain_ambient_summary")',
        "var original_settings: Dictionary = SettingsService.settings.duplicate(true)",
        "var session_before: Dictionary = session.to_dict()",
        "for terrain_value in BATTLE_TERRAIN_AMBIENT_EXPECTED.keys():",
        'board.call("set_battle_state", session)',
        'board.call("validation_terrain_ambient_summary")',
        'animated_after.get("identities", []) != animated_before.get("identities", [])',
        'animated_after.get("entries", []) == animated_before.get("entries", [])',
        "_set_town_ambient_accessibility(true, false)",
        "reduced_after != reduced_before",
        "_set_town_ambient_accessibility(false, true)",
        'session.battle["terrain"] = "validation_missing_texture"',
        "SettingsService.settings = original_settings.duplicate(true)",
        'session.battle["terrain"] = original_terrain',
        "session.to_dict() != session_before",
    ):
        ensure(required_token in ambient_smoke, errors, f"Battle terrain ambient focused proof is missing method-matched lifecycle token: {required_token}")
    for required_token in (
        'String(summary.get("model", "")) != "deterministic_terrain_specific_passive_motes"',
        'Array(summary.get("draw_order", [])) != ["terrain", "ambient_motes", "hex_grid", "objectives", "movement_affordances", "controller_cursor", "battle_vfx", "stack_tokens", "turn_strip", "footer"]',
        'int(summary.get("entry_count", -1)) != int(expected.get("count", -2))',
        'not bool(summary.get("all_contained", false))',
        'float(summary.get("phase_speed", 0.0)), 0.52',
        'String(summary.get("session_mutation_source", "")) != "none_presentation_only"',
        "not field_rect.encloses(bounds)",
    ):
        ensure(required_token in ambient_exact, errors, f"Battle terrain ambient exact helper is missing deterministic/readability bound: {required_token}")
    ensure(smoke_text.count("await _assert_battle_terrain_ambient_contract(board, session)") == 1, errors, "Town/Battle visual smoke must run the ambient terrain lifecycle exactly once")
    for forbidden_token in ("_terrain_ambient_entries(", "_draw_terrain_ambient(", "_terrain_ambient_phase =", "Time.", "rand", "create_timer", "create_tween", "session.battle.erase"):
        ensure(forbidden_token not in ambient_smoke + ambient_exact, errors, f"Battle ambient focused proof must not bypass public validation or mutate presentation internals: {forbidden_token}")

    visual_text = visual_report_path.read_text(encoding="utf-8")
    banner_contract = gdscript_function_block(visual_text, "_battle_banner_contract")
    for required_token in (
        'shell.get_node_or_null("%Header") as Label',
        'shell.get_node_or_null("%Status") as Label',
        'shell.get_node_or_null("%Pressure") as Label',
        "BattleRules.describe_header(session)",
        "BattleRules.describe_status(session)",
        "BattleRules.describe_pressure(session)",
        "font.get_string_size(expected_status",
        "status_overflow if viewport_size.x == 1280 else (not status_overflow if viewport_size.x >= 1920 else true)",
        "header.is_visible_in_tree()",
        "status.is_visible_in_tree()",
        "pressure.is_visible_in_tree()",
        "top_rect.encloses(header_rect)",
        "top_rect.encloses(status_rect)",
        "top_rect.encloses(pressure_rect)",
        "not header_rect.intersects(status_rect)",
        "not status_rect.intersects(pressure_rect)",
    ):
        ensure(required_token in banner_contract, errors, f"UI visual report Battle-banner contract is missing exact token: {required_token}")
    for forbidden_token in ("visible =", "custom_minimum_size", "size_flags", "sort(", "erase(", "queue_free", "call_deferred"):
        ensure(forbidden_token not in banner_contract, errors, f"UI visual report Battle-banner contract must remain observational: {forbidden_token}")
    ensure(re.search(r"\.text\s*=(?!=)", banner_contract) is None, errors, "UI visual report Battle-banner contract must not assign visible text")
    ensure(visual_text.count('shell_report["battle_banner"] = banner_contract') == 1 and visual_text.count('if shell_id == "battle":') >= 1, errors, "UI visual report must fail closed on one Battle-banner contract per selected Battle viewport")
    terrain_contract = gdscript_function_block(visual_text, "_battle_terrain_cohesion_contract")
    for required_token in (
        'board.has_method("validation_hex_layout_summary")',
        'board.has_method("validation_terrain_rendering_summary")',
        'var authority_before: Dictionary = session.to_dict()',
        'String(terrain_summary.get("rendering_mode", "")) == "continuous_field_with_hex_variation"',
        'String(terrain_summary.get("texture_sample_mode", "")) == "continuous_field_plus_subordinate_per_hex_variation"',
        'String(terrain_summary.get("terrain_context_model", "")) == "continuous_primary_field_with_subordinate_hex_variation"',
        'bool(terrain_summary.get("terrain_context_primary", false))',
        'bool(terrain_summary.get("terrain_hex_variation_subordinate", false))',
        'is_equal_approx(context_alpha, 0.92)',
        'is_equal_approx(variation_alpha, 0.24)',
        'int(terrain_summary.get("texture_source_sample_count", 0)) == 77',
        'session.to_dict() == authority_before',
    ):
        ensure(required_token in terrain_contract, errors, f"UI visual report Battle terrain-cohesion contract is missing exact token: {required_token}")
    for forbidden_token in ("set_battle_state", "queue_redraw", "await ", "create_timer", "sort(", "erase("):
        ensure(forbidden_token not in terrain_contract, errors, f"UI visual report Battle terrain-cohesion contract must remain observational: {forbidden_token}")
    ensure(visual_text.count('shell_report["battle_terrain_cohesion"] = terrain_cohesion_contract') == 1, errors, "UI visual report must run one Battle terrain-cohesion contract per selected Battle viewport")
    expected_style = gdscript_function_block(visual_text, "_expected_panel_style")
    for required_token in (
        'shell_id == "battle" and panel_name == "SystemPanel"',
        "viewport_size.x < 1360 or viewport_size.y < 760",
        'return "<empty stylebox>"',
        "return authored_path",
    ):
        ensure(required_token in expected_style, errors, f"UI visual report is missing method-matched Battle System-frame expectation: {required_token}")
    panel_path = gdscript_function_block(visual_text, "_panel_texture_path")
    ensure('if style is StyleBoxEmpty:\n\t\treturn "<empty stylebox>"' in panel_path, errors, "UI visual report must distinguish the intentional compact empty System style from a missing texture style")


def validate_battle_objective_pressure_slice(errors: list[str]) -> None:
    required_paths = (BATTLE_RULES_PATH, BATTLE_AI_RULES_PATH, BATTLE_SCENE_PATH)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing battle-objective pressure file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const FIELD_OBJECTIVES_KEY := "field_objectives"',
        "func _normalize_field_objectives",
        "func _authored_field_objectives",
        "func _field_objective_pressure_summary",
        "func _field_objective_focus_line",
        "func _field_objective_action_influence",
        "func _apply_field_objective_action_pressure",
        "func _apply_field_objective_round_effects",
        "func _reserve_wave_ready_round",
        "func _reserve_wave_is_active_for_side",
        "func _field_objective_commander_modifier",
        "cover_line",
        "obstruction_line",
        "func _weakest_stack_by_role",
    ):
        ensure(required_token in battle_rules_text, errors, f"BattleRules.gd is missing required battle-objective token: {required_token}")

    battle_ai_text = BATTLE_AI_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const FIELD_OBJECTIVES_KEY := "field_objectives"',
        "func _advance_score",
        "func _objective_action_score",
        "func _field_objective_action_influence",
        "func _reserve_wave_ready_round",
        "func _reserve_wave_is_active_for_side",
        "func _field_objective_attack_bonus",
        "func _field_objective_defense_bonus",
        "func _field_objective_cohesion_bonus",
        "func _field_objective_momentum_bonus",
        "func _field_objective_commander_modifier",
        "cover_line",
        "obstruction_line",
    ):
        ensure(required_token in battle_ai_text, errors, f"BattleAiRules.gd is missing required battle-objective token: {required_token}")

    battle_scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    ensure("objective" in battle_scene_text.lower() or "hazard" in battle_scene_text.lower(), errors, "BattleShell.tscn should reference objective or hazard pressure in its release-facing battle copy")


def validate_battle_order_consequence_board(errors: list[str]) -> None:
    required_paths = (SESSION_STATE_PATH, BATTLE_SCENE_PATH, BATTLE_SCRIPT_PATH, BATTLE_RULES_PATH, BATTLE_AI_RULES_PATH)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing battle order-consequence file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    session_text = SESSION_STATE_PATH.read_text(encoding="utf-8")
    ensure("const SAVE_VERSION := 9" in session_text, errors, "Battle order consequence board must preserve save version 9")

    battle_scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    for node_name, node_type in (
        ("ConsequencePanel", "PanelContainer"),
        ("ConsequenceTitle", "Label"),
        ("Consequence", "Label"),
    ):
        ensure(scene_has_node(battle_scene_text, node_name, node_type), errors, f"BattleShell.tscn must define {node_name} ({node_type}) for the battle order consequence board")

    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func describe_order_consequence_board",
        "func _preferred_player_action_id",
        "func _focused_order_line",
        "func _trade_window_line",
        "func _command_tools_line",
        "func _objective_pull_line",
        "func _enemy_reply_line",
        "func _enemy_action_preview_summary",
        "func _attack_action_summary",
        "func _advance_action_summary",
        "func _defend_action_summary",
        "func _damage_modifier",
        "func _damage_range_preview",
        "func _retaliation_range_preview",
        "func _field_objective_action_preview",
        "func _project_field_objective_state",
        "Order Consequences",
        "Focused order:",
        "Trade window:",
        "Command tools:",
        "Enemy reply:",
        "BattleAiRulesScript.choose_enemy_action",
    ):
        ensure(required_token in battle_rules_text, errors, f"BattleRules.gd is missing required battle order-consequence token: {required_token}")

    battle_script_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_consequence_label",
        "BattleRules.describe_order_consequence_board",
    ):
        ensure(required_token in battle_script_text, errors, f"BattleShell.gd is missing required battle order-consequence token: {required_token}")

    battle_ai_text = BATTLE_AI_RULES_PATH.read_text(encoding="utf-8")
    ensure("func choose_enemy_action" in battle_ai_text, errors, "BattleAiRules.gd must keep choose_enemy_action for battle order consequence surfacing")


def validate_battle_intent_forecast(errors: list[str]) -> None:
    required_paths = (
        BATTLE_SCRIPT_PATH,
        BATTLE_RULES_PATH,
        BATTLE_AI_RULES_PATH,
        BATTLE_INTENT_FORECAST_REPORT_SCRIPT_PATH,
        BATTLE_INTENT_FORECAST_REPORT_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing battle intent forecast file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    def function_block(text: str, function_name: str) -> str:
        match = re.search(
            rf"^(?:static )?func {re.escape(function_name)}\([\s\S]*?(?=^(?:static )?func |\Z)",
            text,
            re.MULTILINE,
        )
        return match.group(0) if match else ""

    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func intent_forecast_payload",
        "func describe_intent_forecast",
        "func _intent_forecast_action_id",
        "func _intent_forecast_tactical_spell_target_is_public",
        "func _intent_forecast_action_matches_tactical_order",
        "func _intent_forecast_expected_result",
        "func _intent_forecast_confidence_line",
        "BattleAiRulesScript.choose_stack_tactical_order",
        "Order Preview",
        "Expected result:",
        "Confidence:",
    ):
        ensure(required_token in battle_rules_text, errors, f"BattleRules.gd is missing required battle intent-forecast token: {required_token}")

    forecast_block = function_block(battle_rules_text, "intent_forecast_payload")
    for required_token in (
        "var spell_actions := get_spell_actions(session)",
        "_intent_forecast_action_id(battle, surface, spell_actions, tactical_order, active_stack)",
        "_intent_forecast_action(surface, spell_actions, action_id)",
        'if tactical_target_id != "" and _intent_forecast_action_matches_tactical_order(action_id, tactical_order):',
        'String(action.get("why", action.get("best_use", "")))',
    ):
        ensure(required_token in forecast_block, errors, f"Battle intent forecast must retain spell-order coherence token: {required_token}")
    ensure(
        'if tactical_target_id != "":\n' not in forecast_block,
        errors,
        "Battle intent forecast must not retain a tactical spell target after falling back to a different action",
    )

    action_id_block = function_block(battle_rules_text, "_intent_forecast_action_id")
    for required_token in (
        'if tactical_action == "cast_spell":',
        '"cast_spell:%s" % String(tactical_order.get("spell_id", ""))',
        "_intent_forecast_tactical_spell_target_is_public(battle, active_stack, tactical_order)",
        'String(spell_action.get("id", "")) == tactical_spell_action_id',
        'not bool(spell_action.get("disabled", true))',
        "return _preferred_player_action_id(surface, active_stack)",
    ):
        ensure(required_token in action_id_block, errors, f"Battle intent forecast action selection must retain exact ready spell mapping: {required_token}")
    ensure(
        "static func _intent_forecast_action_id(surface: Dictionary, tactical_order: Dictionary, active_stack: Dictionary)" not in battle_rules_text,
        errors,
        "Battle intent forecast must not restore the pre-spell action selector signature",
    )

    public_target_block = function_block(battle_rules_text, "_intent_forecast_tactical_spell_target_is_public")
    for required_token in (
        "ContentService.get_spell(spell_id)",
        '"ally_active":',
        'String(active_stack.get("battle_id", ""))',
        '"enemy_selected":',
        'String(get_selected_target(battle).get("battle_id", ""))',
        'return public_target_id != "" and tactical_target_id == public_target_id',
    ):
        ensure(required_token in public_target_block, errors, f"Battle intent forecast public spell target gate is missing: {required_token}")

    battle_shell_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "BattleRules.intent_forecast_payload",
        '"intent_forecast"',
        '"intent_forecast_visible_text"',
        '"intent_forecast_tooltip_text"',
    ):
        ensure(required_token in battle_shell_text, errors, f"BattleShell.gd is missing required battle intent-forecast token: {required_token}")
    preferred_focus_block = function_block(battle_shell_text, "_preferred_battle_keyboard_focus")
    rebuild_spells_block = function_block(battle_shell_text, "_rebuild_spell_actions")
    for required_token in (
        'action_id.begins_with("cast_spell:")',
        'not child.is_queued_for_deletion()',
        'String(child.get_meta("battle_action_id", "")) == action_id',
        "FrontierVisualKit.is_keyboard_focusable(child)",
    ):
        ensure(required_token in preferred_focus_block, errors, f"BattleShell preferred focus must retain exact forecast spell matching: {required_token}")
    ensure(
        'button.set_meta("battle_action_id", String(action.get("id", "")))' in rebuild_spells_block,
        errors,
        "BattleShell spell buttons must expose their exact battle action id for forecast focus",
    )

    report_text = BATTLE_INTENT_FORECAST_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "BATTLE_INTENT_FORECAST_REPORT",
        "Suggested order:",
        "Expected result:",
        "Confidence:",
        "does not spend an action",
        "Incoming order:",
        "_damage_spell_session",
        "_support_spell_session",
        'cast_spell:spell_cinder_burst',
        'cast_spell:spell_stone_veil',
        'target_battle_id", "")) != "enemy_spell_target"',
        'target_battle_id", "")) != "player_guard"',
        'support_confirmation.get("action_id", "")) != "strike"',
        'support_confirmation.get("target", "")) != "enemy_front"',
        '"target_battle_id": "enemy_front"',
        'fallback_action_id != "strike"',
        "_intent_forecast_action_matches_tactical_order(fallback_action_id, rejected_spell_order)",
        'get_selected_target(support_spell_session.battle).get("battle_id", "")) != "enemy_front"',
        'unavailable_mana["current"] = 0',
        'unavailable_fallback_action_id != "strike"',
        "_intent_forecast_action_matches_tactical_order(unavailable_fallback_action_id, unavailable_spell_order)",
        'get_selected_target(unavailable_spell_session.battle).get("battle_id", "")) != "enemy_front"',
        "damage_spell_session.to_dict() != damage_spell_before",
        "support_spell_session.to_dict() != support_spell_before",
        "unavailable_spell_session.to_dict() != unavailable_before",
    ):
        ensure(required_token in report_text, errors, f"battle_intent_forecast_report.gd is missing required token: {required_token}")

    active_focus_text = (ROOT / "tests" / "active_play_keyboard_focus_smoke.gd").read_text(encoding="utf-8")
    focus_match_block = function_block(active_focus_text, "_battle_focus_matches_action")
    for required_token in (
        'action_id.begins_with("cast_spell:")',
        'String(focus_owner.get_meta("battle_action_id", "")) == action_id',
        "_battle_button_name(action_id)",
        'expected_name != "" and String(focus_owner.name) == expected_name',
    ):
        ensure(required_token in focus_match_block, errors, f"active_play_keyboard_focus_smoke.gd must match exact forecast focus: {required_token}")
    ensure(
        active_focus_text.count("_battle_focus_matches_action(") == 3,
        errors,
        "Active-play focus smoke must define and use the exact forecast-action matcher at entry and after refresh",
    )

    scene_text = BATTLE_INTENT_FORECAST_REPORT_SCENE_PATH.read_text(encoding="utf-8")
    ensure("battle_intent_forecast_report.gd" in scene_text, errors, "battle_intent_forecast_report.tscn must reference its report script")


def validate_battle_refresh_derived_surface_reuse(errors: list[str]) -> None:
    required_paths = (
        BATTLE_RULES_PATH,
        BATTLE_SCRIPT_PATH,
        BATTLE_INTENT_FORECAST_REPORT_SCRIPT_PATH,
        BATTLE_CONTROLLER_BOARD_NAVIGATION_SMOKE_SCRIPT_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing battle refresh reuse owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    def function_block(text: str, function_name: str) -> str:
        match = re.search(
            rf"^(?:static )?func {re.escape(function_name)}\([\s\S]*?(?=^(?:static )?func |\Z)",
            text,
            re.MULTILINE,
        )
        return match.group(0) if match else ""

    def require_order(block: str, tokens: tuple[str, ...], message: str) -> None:
        ensure(all(token in block for token in tokens), errors, f"{message} is missing exact ordered tokens")
        if all(token in block for token in tokens):
            positions = [block.index(token) for token in tokens]
            ensure(positions == sorted(positions), errors, f"{message} order drifted")

    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    movement_intent_block = function_block(battle_rules_text, "movement_intent_for_destination")
    movement_intents_block = function_block(battle_rules_text, "legal_movement_intents_for_active_stack")
    preloaded_destination_block = function_block(battle_rules_text, "_legal_destination_from_preloaded")
    hex_summary_block = function_block(battle_rules_text, "battle_hex_state_summary")
    click_intent_block = function_block(battle_rules_text, "active_movement_board_click_intent")
    for block, owner in (
        (movement_intent_block, "movement_intent_for_destination"),
        (movement_intents_block, "legal_movement_intents_for_active_stack"),
        (click_intent_block, "active_movement_board_click_intent"),
    ):
        ensure("preloaded_legal_destinations: Variant = null" in block, errors, f"{owner} must retain its optional invocation-local destination input")
        ensure("if preloaded_legal_destinations is Array" in block, errors, f"{owner} must fail closed to the direct fallback when no exact Array is supplied")
    require_order(
        movement_intents_block,
        (
            "var destinations: Array = (",
            "else legal_destinations_for_active_stack(battle)",
            "for destination in destinations:",
            "movement_intent_for_destination(",
            'int(destination.get("r", -1)),\n\t\t\tdestinations',
        ),
        "Battle movement-intent one-enumeration reuse",
    )
    for required_token in (
        "for destination_value in destinations:",
        "if not (destination_value is Dictionary):",
        'int(destination.get("q", -1)) == q',
        'int(destination.get("r", -1)) == r',
        "return destination",
        "return {}",
    ):
        ensure(required_token in preloaded_destination_block, errors, f"Preloaded legal-destination lookup is missing exact ordered first-match behavior: {required_token}")
    for forbidden_token in ("sort", "erase", "filter", "duplicate", "_legal_destination_for_stack"):
        ensure(forbidden_token not in preloaded_destination_block, errors, f"Preloaded legal destinations must not use behavior-changing {forbidden_token}")
    require_order(
        hex_summary_block,
        (
            "var legal_destinations := legal_destinations_for_active_stack(battle)",
            "active_movement_board_click_intent(battle, legal_destinations)",
            '"legal_destinations": legal_destinations',
            '"legal_movement_intents": legal_movement_intents_for_active_stack(battle, legal_destinations)',
        ),
        "Battle hex-state exact destination reuse",
    )
    ensure(hex_summary_block.count("legal_destinations_for_active_stack(battle)") == 1, errors, "Battle hex-state summary must enumerate legal destinations exactly once")

    battle_shell_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    refresh_block = function_block(battle_shell_text, "_refresh")
    preferred_focus_block = function_block(battle_shell_text, "_preferred_battle_keyboard_focus")
    position_check_block = function_block(battle_shell_text, "_battle_position_check_cue_surface")
    for required_token in (
        "var _last_refresh_intent_forecast: Dictionary = {}",
        "var _last_refresh_intent_forecast_battle_hash := 0",
    ):
        ensure(required_token in battle_shell_text, errors, f"BattleShell refresh reuse is missing invocation-local field: {required_token}")
    require_order(
        refresh_block,
        (
            "_last_refresh_intent_forecast = {}",
            "_last_refresh_intent_forecast_battle_hash = 0",
            "var intent_forecast := BattleRules.intent_forecast_payload(_session)",
            "_last_refresh_intent_forecast = intent_forecast",
            "_last_refresh_intent_forecast_battle_hash = hash(_session.battle)",
            'call_deferred("_configure_battle_keyboard_focus", false)',
        ),
        "Battle refresh forecast lifecycle",
    )
    require_order(
        preferred_focus_block,
        (
            "var intent_forecast := _last_refresh_intent_forecast",
            "if intent_forecast.is_empty() or _last_refresh_intent_forecast_battle_hash != hash(_session.battle):",
            "intent_forecast = BattleRules.intent_forecast_payload(_session)",
            'var action_id := String(intent_forecast.get("action_id", ""))',
        ),
        "Battle preferred-focus cache validation and fresh fallback",
    )
    require_order(
        position_check_block,
        (
            "var legal_destinations := BattleRules.legal_destinations_for_active_stack(battle)",
            "BattleRules.active_movement_board_click_intent(battle, legal_destinations)",
            "BattleRules.legal_movement_intents_for_active_stack(battle, legal_destinations)",
        ),
        "Battle position-check destination reuse",
    )
    ensure(position_check_block.count("legal_destinations_for_active_stack(battle)") == 1, errors, "Battle position-check cue must enumerate legal destinations exactly once")
    ensure("session.battle[\"_last_refresh_intent_forecast\"]" not in battle_shell_text, errors, "Battle forecast reuse must never enter battle/save authority")

    forecast_report_text = BATTLE_INTENT_FORECAST_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "var movement_authority_before: Dictionary = player_session.to_dict()",
        "var legal_destinations: Array = BattleRulesScript.legal_destinations_for_active_stack(player_session.battle)",
        "legacy_movement_intents.append(BattleRulesScript.movement_intent_for_destination(",
        "var preloaded_movement_intents: Array = BattleRulesScript.legal_movement_intents_for_active_stack(",
        "var direct_movement_intents: Array = BattleRulesScript.legal_movement_intents_for_active_stack(player_session.battle)",
        "direct_movement_click != preloaded_movement_click",
        'hex_summary.get("legal_movement_intents", []) != legacy_movement_intents',
        "player_session.to_dict() != movement_authority_before",
        '"whole_ordered_parity": true',
    ):
        ensure(required_token in forecast_report_text, errors, f"Battle intent report is missing exact old-vs-preloaded movement parity: {required_token}")
    ensure("legacy_movement_intents.sort" not in forecast_report_text, errors, "Battle movement parity control must preserve production destination order")

    controller_text = BATTLE_CONTROLLER_BOARD_NAVIGATION_SMOKE_SCRIPT_PATH.read_text(encoding="utf-8")
    require_order(
        controller_text,
        (
            "var refresh_authority_before: Dictionary = session.to_dict()",
            'var cached_intent_forecast: Dictionary = shell.get("_last_refresh_intent_forecast")',
            "var fresh_intent_forecast: Dictionary = BattleRules.intent_forecast_payload(session)",
            'var cached_preferred_focus: Control = shell.call("_preferred_battle_keyboard_focus")',
            'shell.set("_last_refresh_intent_forecast_battle_hash", 0)',
            'var fallback_preferred_focus: Control = shell.call("_preferred_battle_keyboard_focus")',
            "not is_same(cached_preferred_focus, fallback_preferred_focus)",
            "session.to_dict() != refresh_authority_before",
        ),
        "Battle controller cached/fallback focus parity",
    )


def validate_battle_spell_timing_board(errors: list[str]) -> None:
    required_paths = (SESSION_STATE_PATH, BATTLE_SCENE_PATH, BATTLE_SCRIPT_PATH, BATTLE_RULES_PATH, SPELL_RULES_PATH, BATTLE_AI_RULES_PATH)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing battle spell-timing file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    session_text = SESSION_STATE_PATH.read_text(encoding="utf-8")
    ensure("const SAVE_VERSION := 9" in session_text, errors, "Battle spell timing board must preserve save version 9")

    battle_scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    for node_name, node_type in (
        ("TimingPanel", "PanelContainer"),
        ("TimingTitle", "Label"),
        ("Timing", "Label"),
    ):
        ensure(scene_has_node(battle_scene_text, node_name, node_type), errors, f"BattleShell.tscn must define {node_name} ({node_type}) for the battle spell timing board")

    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func describe_spell_timing_board",
        "func _spell_window_line",
        "func _preferred_spell_timing_action",
        "func _spell_timing_action_score",
        "func _support_payoff_line",
        "func _support_followup_line",
        "func _protection_need_line",
        "func _priority_friendly_protection_stack",
        "func _best_ready_support_spell_action",
        "func _burst_risk_line",
        "func _enemy_spell_threat_line",
        "Spell and Ability Timing",
        "Spell window:",
        "Support payoff:",
        "Protection need:",
        "Burst risk:",
        "there is no authored cleanse in the current spellbook",
        "SpellRulesScript.battle_spell_timing_summary",
        "BattleAiRulesScript.choose_enemy_action",
    ):
        ensure(required_token in battle_rules_text, errors, f"BattleRules.gd is missing required battle spell-timing token: {required_token}")

    spell_rules_text = SPELL_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func battle_spell_timing_summary",
        "Timing: ",
        "Best before the next volley or before the lane closes.",
    ):
        ensure(required_token in spell_rules_text, errors, f"SpellRules.gd is missing required battle spell-timing token: {required_token}")

    battle_script_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_timing_label",
        "BattleRules.describe_spell_timing_board",
    ):
        ensure(required_token in battle_script_text, errors, f"BattleShell.gd is missing required battle spell-timing token: {required_token}")

    battle_ai_text = BATTLE_AI_RULES_PATH.read_text(encoding="utf-8")
    ensure("func choose_enemy_action" in battle_ai_text, errors, "BattleAiRules.gd must keep choose_enemy_action for battle spell timing surfacing")


