def validate_in_session_save_controls(errors: list[str]) -> None:
    required_paths = (
        SAVE_SERVICE_PATH,
        APP_ROUTER_PATH,
        MAIN_MENU_SCRIPT_PATH,
        OVERWORLD_SCRIPT_PATH,
        TOWN_SCRIPT_PATH,
        BATTLE_SCRIPT_PATH,
        OUTCOME_SCRIPT_PATH,
        OVERWORLD_SCENE_PATH,
        TOWN_SCENE_PATH,
        BATTLE_SCENE_PATH,
        OUTCOME_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing in-session save-control file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    session_text = SESSION_STATE_PATH.read_text(encoding="utf-8")
    ensure("const SAVE_VERSION := 9" in session_text, errors, "In-session save controls must preserve save version 9")

    save_text = SAVE_SERVICE_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func save_runtime_selected_manual_session",
        "func save_runtime_manual_session",
        "func save_runtime_autosave_session",
        "func build_manual_save_action",
        "func build_in_session_save_surface",
        "func _in_session_save_label",
        "func _in_session_save_tooltip",
        "func _latest_context_line",
        "func _return_to_menu_tooltip",
    ):
        ensure(required_token in save_text, errors, f"SaveService.gd is missing required in-session save token: {required_token}")

    app_router_text = APP_ROUTER_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func return_to_main_menu_from_active_play",
        "func save_active_session_to_selected_manual_slot",
        "func save_active_session_to_manual_slot",
        "func active_manual_save_action",
        "func active_save_surface",
        "func resume_summary",
        "func resume_latest_session",
        "func consume_menu_notice",
        "SaveService.save_runtime_manual_session",
        "SaveService.save_runtime_autosave_session",
    ):
        ensure(required_token in app_router_text, errors, f"AppRouter.gd is missing required in-session save-routing token: {required_token}")

    overworld_script_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_save_status_label",
        "_menu_button",
        "_manual_save_overwrite_dialog",
        "AppRouter.active_manual_save_action",
        "AppRouter.save_active_session_to_manual_slot",
        "AppRouter.active_save_surface",
        "AppRouter.return_to_main_menu_from_active_play",
        "SaveService.save_runtime_autosave_session(_session)",
        "or (_manual_save_overwrite_dialog != null and _manual_save_overwrite_dialog.visible)",
    ):
        ensure(required_token in overworld_script_text, errors, f"OverworldShell.gd is missing required in-session save token: {required_token}")

    def gdscript_function_block(text: str, name: str) -> str:
        match = re.search(rf"(?m)^func {re.escape(name)}\([^\n]*\)(?: -> [^:]+)?:\n", text)
        if match is None:
            return ""
        next_match = re.search(r"(?m)^func [A-Za-z0-9_]+\(", text[match.end():])
        end = match.end() + next_match.start() if next_match is not None else len(text)
        return text[match.start():end]

    save_status_block = gdscript_function_block(overworld_script_text, "_save_status_text")
    ensure(save_status_block != "", errors, "OverworldShell.gd must retain the compact save-status helper")
    required_save_status_tokens = (
        "func _save_status_text(selected_slot: int, summary: Dictionary) -> String:",
        'String(summary.get("validity", "missing")) == "missing"',
        'return "%s empty" % status',
        "SaveService.can_load_summary(summary)",
        'return "%s ready" % status',
        'bool(summary.get("valid", false))',
        'return "%s hold" % status',
        'return "%s lock" % status',
    )
    for required_token in required_save_status_tokens:
        ensure(required_token in save_status_block, errors, f"Overworld compact save status is missing required distinct-state token: {required_token}")
    ensure(
        all(save_status_block.find(required_save_status_tokens[index]) < save_status_block.find(required_save_status_tokens[index + 1]) for index in range(len(required_save_status_tokens) - 1)),
        errors,
        "Overworld compact save status must order missing, loadable, held, and locked states fail-closed",
    )
    ensure("latest_context" not in save_status_block and 'return "%s none"' not in save_status_block, errors, "Overworld selected-slot status must not hide empty or invalid state behind latest-save availability")

    visual_smoke_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    visual_smoke_text = visual_smoke_path.read_text(encoding="utf-8") if visual_smoke_path.exists() else ""
    save_case_block = gdscript_function_block(visual_smoke_text, "_assert_save_resume_clarity_contract")
    for required_token in (
        'String(empty_snapshot.get("save_status_visible_text", "")) != "M1 empty"',
        'String(empty_summary.get("validity", "")) != "missing"',
        'String(empty_summary.get("status_text", "")) != "Empty slot."',
        'contains("Selected slot:")',
        'contains("Integrity: Empty slot")',
        'contains("Load state: Blocked")',
        'contains("Status: Empty slot.")',
        'save_button.disabled',
        'SessionState.ensure_active_session().to_dict() != empty_session_authority',
        'String(snapshot.get("save_status_visible_text", "")) != "M1 ready"',
        'shell.call("validation_save_to_selected_slot")',
    ):
        ensure(required_token in save_case_block, errors, f"Overworld visual save case is missing empty-to-ready authority token: {required_token}")
    ensure(
        save_case_block.find('String(empty_snapshot.get("save_status_visible_text", "")) != "M1 empty"')
        < save_case_block.find('shell.call("validation_save_to_selected_slot")')
        < save_case_block.find('String(snapshot.get("save_status_visible_text", "")) != "M1 ready"'),
        errors,
        "Overworld visual save case must prove empty status before the real save and ready status afterward",
    )

    town_script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_save_status_label",
        "_menu_button",
        "_manual_save_overwrite_dialog",
        "AppRouter.active_manual_save_action",
        "AppRouter.save_active_session_to_manual_slot",
        "AppRouter.active_save_surface",
        "AppRouter.return_to_main_menu_from_active_play",
        "if _manual_save_overwrite_dialog != null and _manual_save_overwrite_dialog.visible:",
    ):
        ensure(required_token in town_script_text, errors, f"TownShell.gd is missing required in-session save token: {required_token}")

    battle_script_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_system_body_label",
        "_menu_button",
        "_manual_save_overwrite_dialog",
        "AppRouter.active_manual_save_action",
        "AppRouter.save_active_session_to_manual_slot",
        "AppRouter.active_save_surface",
        "AppRouter.return_to_main_menu_from_active_play",
    ):
        ensure(required_token in battle_script_text, errors, f"BattleShell.gd is missing required in-session save token: {required_token}")

    outcome_script_text = OUTCOME_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_save_status_label",
        "_save_slot_picker",
        "_save_button",
        "_menu_button",
        "func _configure_save_slot_picker",
        "func _refresh_save_surface",
        "_manual_save_overwrite_dialog",
        "AppRouter.active_manual_save_action",
        "AppRouter.save_active_session_to_manual_slot",
        "AppRouter.return_to_main_menu_from_active_play",
    ):
        ensure(required_token in outcome_script_text, errors, f"ScenarioOutcomeShell.gd is missing required in-session save token: {required_token}")

    overworld_scene_text = OVERWORLD_SCENE_PATH.read_text(encoding="utf-8")
    ensure('name="ManualSaveOverwriteDialog"' in overworld_scene_text, errors, "OverworldShell.tscn must instance the shared manual-save overwrite dialog")
    for node_name, node_type in (
        ("SaveStatus", "Label"),
        ("SaveSlot", "OptionButton"),
        ("Save", "Button"),
        ("Menu", "Button"),
    ):
        ensure(scene_has_node(overworld_scene_text, node_name, node_type), errors, f"OverworldShell.tscn must define {node_name} ({node_type}) for in-session save controls")

    town_scene_text = TOWN_SCENE_PATH.read_text(encoding="utf-8")
    ensure('name="ManualSaveOverwriteDialog"' in town_scene_text, errors, "TownShell.tscn must instance the shared manual-save overwrite dialog")
    for node_name, node_type in (
        ("SaveStatus", "Label"),
        ("SaveSlot", "OptionButton"),
        ("Save", "Button"),
        ("Menu", "Button"),
    ):
        ensure(scene_has_node(town_scene_text, node_name, node_type), errors, f"TownShell.tscn must define {node_name} ({node_type}) for in-session save controls")

    battle_scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    ensure('name="ManualSaveOverwriteDialog"' in battle_scene_text, errors, "BattleShell.tscn must instance the shared manual-save overwrite dialog")
    for node_name, node_type in (
        ("SystemPanel", "PanelContainer"),
        ("SystemBody", "Label"),
        ("SaveSlot", "OptionButton"),
        ("Save", "Button"),
        ("Menu", "Button"),
    ):
        ensure(scene_has_node(battle_scene_text, node_name, node_type), errors, f"BattleShell.tscn must define {node_name} ({node_type}) for in-session save controls")

    outcome_scene_text = OUTCOME_SCENE_PATH.read_text(encoding="utf-8")
    ensure('name="ManualSaveOverwriteDialog"' in outcome_scene_text, errors, "ScenarioOutcomeShell.tscn must instance the shared manual-save overwrite dialog")
    for node_name, node_type in (
        ("SaveStatus", "Label"),
        ("SaveBar", "HFlowContainer"),
        ("SaveSlot", "OptionButton"),
        ("Save", "Button"),
        ("Menu", "Button"),
    ):
        ensure(scene_has_node(outcome_scene_text, node_name, node_type), errors, f"ScenarioOutcomeShell.tscn must define {node_name} ({node_type}) for in-session save controls")


def validate_town_faction_progression(errors: list[str]) -> None:
    required_paths = (
        SESSION_STATE_PATH,
        SCENARIO_FACTORY_PATH,
        OVERWORLD_RULES_PATH,
        TOWN_RULES_PATH,
        SCENARIO_SCRIPT_RULES_PATH,
        TOWN_SCRIPT_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing town/faction progression file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    session_text = SESSION_STATE_PATH.read_text(encoding="utf-8")
    ensure("const SAVE_VERSION := 9" in session_text, errors, "Town/faction progression must preserve save version 9")

    scenario_factory_text = SCENARIO_FACTORY_PATH.read_text(encoding="utf-8")
    for required_token in ("func _seed_recruits_for_town_state", "func _apply_growth_profile"):
        ensure(required_token in scenario_factory_text, errors, f"ScenarioFactory.gd is missing required town progression token: {required_token}")

    overworld_text = OVERWORLD_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "const WEEKLY_GROWTH_INTERVAL := 7",
        "func is_weekly_growth_day",
        "func days_until_next_weekly_growth",
        "func next_weekly_growth_day",
        "func describe_town_context",
        "func town_weekly_growth",
        "func _effective_player_town_weekly_growth",
        'String(town.get("owner", "neutral")) == "player"',
        "var result := _effective_player_town_weekly_growth(session, town) if session != null",
        "var weekly_growth := _effective_player_town_weekly_growth(session, town)",
        "func _project_player_town_at_daybreak",
        "projected_session.day = next_day",
        "projected_session.overworld = session.overworld.duplicate(false)",
        "var projected_town: Dictionary = town.duplicate(true)",
        "var occupation_result := _advance_town_occupation(projected_session, projected_town)",
        "var recovery_result := _advance_town_recovery(projected_session, projected_town)",
        "_end_turn_income_forecast_line(session, next_day)",
        "_end_turn_muster_forecast_line(session, next_day)",
        "func town_income",
        "func town_reinforcement_quality",
        "func town_battle_readiness",
        "func town_pressure_output",
        "func town_development_metrics",
        "func town_recruit_cost",
        "func get_town_build_status",
        "func _normalize_built_buildings_for_town_state",
        "func _economy_profile_income",
        "func _weighted_recruit_value",
        "func _pressure_bonus_from_profile",
        "func _readiness_bonus_from_profile",
        "func _recruitment_discount_percent",
        "Weekly musters",
    ):
        ensure(required_token in overworld_text, errors, f"OverworldRules.gd is missing required town progression token: {required_token}")

    town_rules_text = TOWN_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func describe_status",
        "OverworldRulesScript.town_income",
        "OverworldRulesScript.town_weekly_growth",
        "OverworldRulesScript.town_reinforcement_quality",
        "OverworldRulesScript.town_battle_readiness",
        "OverworldRulesScript.town_pressure_output",
        "OverworldRulesScript.town_market_state",
        "OverworldRulesScript.town_recruit_cost",
        "OverworldRulesScript.get_town_build_status",
        "func _town_identity_summary",
        "func _town_unit_ids",
    ):
        ensure(required_token in town_rules_text, errors, f"TownRules.gd is missing required town progression token: {required_token}")

    scenario_script_text = SCENARIO_SCRIPT_RULES_PATH.read_text(encoding="utf-8")
    ensure("OverworldRules._normalize_built_buildings_for_town_state" in scenario_script_text, errors, "ScenarioScriptRules.gd must normalize scripted town buildings through the shared prerequisite graph")

    town_script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in ("TownRules.describe_status", "TownRules.describe_summary", "TownRules.describe_buildings", "TownRules.describe_market", "TownRules.describe_recruitment", "TownRules.describe_responses"):
        ensure(required_token in town_script_text, errors, f"TownShell.gd is missing required town progression token: {required_token}")


def validate_town_building_skyline_progression(errors: list[str]) -> None:
    required_paths = (
        TOWN_STAGE_SCRIPT_PATH,
        TOWN_DEVELOPMENT_SCENE_MANIFEST_PATH,
        TOWN_BUILDING_SCENE_LAYOUT_PATH,
        TOWN_BUILDING_SCENE_LAYOUT_GENERATOR_PATH,
        TOWN_BUILDING_SKYLINE_REPORT_SCRIPT_PATH,
        TOWN_BUILDING_SKYLINE_REPORT_SCENE_PATH,
        TOWN_DEVELOPMENT_FIRST_IMPORT_PROBE_SCRIPT_PATH,
        TOWN_DEVELOPMENT_FIRST_IMPORT_PROBE_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing seamless Town development-scene owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        'const DEVELOPMENT_SCENE_MODEL := "authoritative_integrated_per_building_settlement"',
        'const INTEGRATED_BUILDING_MODEL := "explicit_faction_ground_anchor_depth_and_perspective"',
        'const TOWN_BUILDING_SCENE_LAYOUT_PATH := "res://content/town_building_scene_layouts.json"',
        "const FACTION_DEVELOPMENT_SCENE_PATHS := {",
        "func _development_scene_texture(faction_id: String, stage_id: String) -> Texture2D:",
        "func _development_scene_import_payload_exists(texture_path: String) -> bool:",
        'ResourceLoader.load(texture_path, "Texture2D")',
        "ImageTexture.create_from_image(source_image)",
        "func _town_building_scene_entries(scene_rect: Rect2) -> Array:",
        "func _draw_integrated_buildings(scene_rect: Rect2) -> void:",
        "func _sync_building_hotspots() -> void:",
        "signal building_activated(building_id: String)",
        "func validation_town_building_progression_summary() -> Dictionary:",
        '"integrated_building_layers_enabled": true',
        '"isolated_building_overlay_enabled": false',
        '"construction_stake_overlay_enabled": false',
        '"faction_development_scene"',
    ):
        ensure(token in stage_text, errors, f"TownStageView is missing seamless development-scene ownership: {token}")
    for forbidden_token in (
        "func _draw_scenic_building_progression(scene_rect: Rect2) -> void:",
        "func _draw_unbuilt_plot_stakes(",
        "_draw_scenic_building_progression(scene_rect)",
        'preload("res://art/towns/runtime/backdrops/development_scenes/',
    ):
        ensure(forbidden_token not in stage_text, errors, f"TownStageView still owns the removed isolated-building skyline: {forbidden_token}")
    draw_match = re.search(r"func _draw\(\) -> void:\n(?P<body>.*?)(?=\nfunc )", stage_text, re.DOTALL)
    draw_block = draw_match.group("body") if draw_match is not None else ""
    ensure(draw_match is not None, errors, "Could not isolate TownStageView seamless scene draw order")
    draw_order = [
        draw_block.find("_draw_scenic_backdrop(scene_rect)"),
        draw_block.find("_draw_integrated_buildings(scene_rect)"),
        draw_block.find("_draw_status_plaques(scene_rect)"),
    ]
    ensure(all(index >= 0 for index in draw_order) and draw_order == sorted(draw_order), errors, "Town building layers must draw over the base scene and below status overlays")

    layout_manifest = load_json(TOWN_BUILDING_SCENE_LAYOUT_PATH)
    ensure(layout_manifest.get("schema_id") == "town_integrated_building_scene_layout_v1", errors, "Town building scene-layout manifest schema must remain explicit")
    ensure(layout_manifest.get("placement_model") == "explicit_faction_ground_anchor_depth_and_perspective", errors, "Town building scene-layout manifest must retain authored faction placement")
    ensure(layout_manifest.get("missing_mapping_policy") == "validation_failure_no_runtime_generated_plot", errors, "Town building scene-layout manifest must fail closed on missing mappings")
    layout_factions = layout_manifest.get("factions", {}) if isinstance(layout_manifest.get("factions"), dict) else {}

    manifest = load_json(TOWN_DEVELOPMENT_SCENE_MANIFEST_PATH)
    ensure(manifest.get("schema_id") == "town_development_scene_manifest_v1", errors, "Town development scene manifest schema must remain explicit")
    factions = manifest.get("factions", {}) if isinstance(manifest.get("factions"), dict) else {}
    expected_factions = {
        "faction_embercourt", "faction_mireclaw", "faction_sunvault",
        "faction_thornwake", "faction_brasshollow", "faction_veilmourn",
    }
    ensure(set(layout_factions) == expected_factions, errors, "Town building scene-layout manifest must cover the six live factions exactly")
    building_ids = {str(item.get("id", "")) for item in load_json(CONTENT_DIR / "buildings.json").get("items", []) if isinstance(item, dict)}
    for faction_id in sorted(expected_factions):
        layout = layout_factions.get(faction_id, {}) if isinstance(layout_factions.get(faction_id), dict) else {}
        plots = layout.get("plots", []) if isinstance(layout.get("plots"), list) else []
        mapped_ids: list[str] = []
        ensure(layout.get("base_stage") == "village", errors, f"{faction_id} integrated Town layout must retain the empty village base")
        ensure(layout.get("source_size") == [1600, 900], errors, f"{faction_id} integrated Town layout source size drifted")
        ensure(len(plots) >= 20, errors, f"{faction_id} integrated Town layout needs authored plots for its catalog")
        for plot in plots:
            if not isinstance(plot, dict):
                ensure(False, errors, f"{faction_id} integrated Town layout contains a non-object plot")
                continue
            anchor = plot.get("anchor", [])
            ids = plot.get("building_ids", [])
            ensure(isinstance(anchor, list) and len(anchor) == 2 and all(isinstance(value, (int, float)) and 0.0 <= float(value) <= 1.0 for value in anchor), errors, f"{faction_id} integrated Town plot has an invalid normalized anchor")
            ensure(isinstance(ids, list) and bool(ids), errors, f"{faction_id} integrated Town plot has no building variants")
            for building_id in ids if isinstance(ids, list) else []:
                ensure(building_id in building_ids, errors, f"{faction_id} integrated Town plot references unknown building {building_id}")
                mapped_ids.append(str(building_id))
        ensure(len(mapped_ids) == len(set(mapped_ids)), errors, f"{faction_id} integrated Town layout maps a building more than once")
    ensure(set(factions) == expected_factions, errors, "Town development scene manifest must cover the six live factions exactly")
    runtime_hashes: set[str] = set()
    for faction_id in sorted(expected_factions):
        faction = factions.get(faction_id, {}) if isinstance(factions.get(faction_id), dict) else {}
        ensure(bool(faction.get("architecture")), errors, f"{faction_id} must describe its settlement architecture")
        ensure(len(faction.get("fully_built_buildings", [])) >= 8, errors, f"{faction_id} must describe at least eight fully built landmarks")
        stages = faction.get("stages", {}) if isinstance(faction.get("stages"), dict) else {}
        ensure(set(stages) == {"village", "developing", "fully_built"}, errors, f"{faction_id} must own all three seamless stages")
        for stage_id in ("village", "developing", "fully_built"):
            row = stages.get(stage_id, {}) if isinstance(stages.get(stage_id), dict) else {}
            for kind in ("source", "runtime"):
                asset_path = ROOT / str(row.get(f"{kind}_path", "")).removeprefix("res://")
                ensure(asset_path.is_file(), errors, f"Missing {faction_id} {stage_id} {kind} Town scene")
                if asset_path.is_file():
                    digest = hashlib.sha256(asset_path.read_bytes()).hexdigest()
                    ensure(digest == row.get(f"{kind}_sha256"), errors, f"{faction_id} {stage_id} {kind} Town scene hash drifted")
                    if kind == "runtime":
                        runtime_hashes.add(digest)
    ensure(len(runtime_hashes) == 18, errors, "The six Town factions must retain eighteen distinct runtime stage paintings")

    report_text = TOWN_BUILDING_SKYLINE_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        "town_rows.size() == 32",
        "TownRules.build_active_town(session, building_id)",
        "restored.from_dict(session.to_dict())",
        '"integrated_building_layers_enabled"',
        '"all_visible_hotspots_aligned"',
        'validation_activate_building_information',
        '"faction_development_scene"',
        'const VIEWPORT_SIZES := [Vector2i(1280, 720), Vector2i(2048, 1079)]',
        'for stage_id_value in ["sparse", "developing", "developed"]',
    ):
        ensure(token in report_text, errors, f"Town development-scene focused report is missing required live proof: {token}")
    scene_text = TOWN_BUILDING_SKYLINE_REPORT_SCENE_PATH.read_text(encoding="utf-8")
    ensure('path="res://tests/town_building_skyline_progression_report.gd"' in scene_text, errors, "Town development-scene report scene must own the focused runtime script")
    ensure_scene_nodes(scene_text, errors, "town_building_skyline_progression_report.tscn", [("TownBuildingSkylineProgressionReport", "Node")])

    first_import_text = TOWN_DEVELOPMENT_FIRST_IMPORT_PROBE_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        'const TownStageViewScript = preload("res://scenes/town/TownStageView.gd")',
        'const STAGE_IDS := ["village", "developing", "fully_built"]',
        'stage.call("_development_scene_texture", faction_id, stage_id)',
        'texture.get_size() == Vector2(1600, 900)',
        'print("TOWN_DEVELOPMENT_FIRST_IMPORT_PROBE %s"',
    ):
        ensure(token in first_import_text, errors, f"Town development first-import probe is missing required proof: {token}")
    first_import_scene_text = TOWN_DEVELOPMENT_FIRST_IMPORT_PROBE_SCENE_PATH.read_text(encoding="utf-8")
    ensure('path="res://tests/town_development_first_import_probe.gd"' in first_import_scene_text, errors, "Town development first-import scene must own its probe script")
    ensure_scene_nodes(first_import_scene_text, errors, "town_development_first_import_probe.tscn", [("TownDevelopmentFirstImportProbe", "Node")])


def validate_town_building_complete_vfx_assets(errors: list[str]) -> None:
    required_paths = (
        TOWN_STAGE_SCRIPT_PATH,
        TOWN_VFX_MANIFEST_PATH,
        TOWN_BUILDING_COMPLETE_VFX_SOURCE_PATH,
        TOWN_BUILDING_COMPLETE_VFX_RUNTIME_PATH,
        TOWN_BUILDING_COMPLETE_VFX_REPORT_SCRIPT_PATH,
        TOWN_BUILDING_COMPLETE_VFX_REPORT_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing Town building-complete VFX owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return
    ensure(load_json(TOWN_VFX_MANIFEST_PATH) == {
        "schema_id": "town_vfx_manifest_v1",
        "cues": {
            "vfx_placeholder_build_complete": {
                "event_id": "town_building_built",
                "texture_path": "res://art/town/runtime/vfx/build_complete.png",
                "render_mode": "town_building_complete",
                "scale": 1.0,
            },
            "vfx_placeholder_recruit_muster": {
                "event_id": "town_units_recruited",
                "texture_path": "res://art/town/runtime/vfx/recruit_muster.png",
                "render_mode": "town_recruit_muster",
                "scale": 1.0,
            },
            "vfx_placeholder_town_route_response": {
                "event_id": "town_route_response_ordered",
                "texture_path": "res://art/town/runtime/vfx/route_response.png",
                "render_mode": "town_route_response_dispatch",
                "scale": 1.0,
            },
            "vfx_placeholder_town_market_exchange": {
                "event_id": "town_market_exchange_completed",
                "texture_path": "res://art/town/runtime/vfx/market_exchange.png",
                "render_mode": "town_market_exchange_completion",
                "scale": 1.0,
            },
            "vfx_placeholder_town_spell_study": {
                "event_id": "town_spell_studied",
                "texture_path": "res://art/town/runtime/vfx/spell_study.png",
                "render_mode": "town_spell_study_completion",
                "scale": 1.0,
            },
            "vfx_placeholder_town_hero_hire": {
                "event_id": "town_hero_hired",
                "texture_path": "res://art/town/runtime/vfx/hero_hire.png",
                "render_mode": "town_hero_hire_completion",
                "scale": 1.0,
            },
            "vfx_placeholder_town_specialty_rank": {
                "event_id": "town_specialty_selected",
                "texture_path": "res://art/town/runtime/vfx/specialty_rank.png",
                "render_mode": "town_specialty_rank_completion",
                "scale": 1.0,
            },
            "vfx_placeholder_town_unit_transfer": {
                "event_id": "town_army_transferred",
                "texture_path": "res://art/town/runtime/vfx/unit_transfer.png",
                "render_mode": "town_unit_transfer_completion",
                "scale": 1.0,
            },
        },
    }, errors, "Town VFX manifest must map only the exact live Town completion cues/events/textures")
    ensure(png_size(TOWN_BUILDING_COMPLETE_VFX_SOURCE_PATH) == (1254, 1254), errors, "Town building-complete source must retain its exact square source image")
    ensure(png_size(TOWN_BUILDING_COMPLETE_VFX_RUNTIME_PATH) == (512, 512), errors, "Town building-complete runtime texture must be 512x512")
    header = TOWN_BUILDING_COMPLETE_VFX_RUNTIME_PATH.read_bytes()[:26]
    ensure(len(header) >= 26 and header[25] in {4, 6}, errors, "Town building-complete runtime texture must retain a PNG alpha channel")

    def block(text: str, name: str) -> str:
        start = text.find(f"func {name}")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        'const TOWN_VFX_MANIFEST_PATH := "res://content/town_vfx_manifest.json"',
        "_load_town_vfx_manifest()",
        '"vfx_asset": _town_action_vfx_asset_state()',
        '"vfx_draw": _town_action_last_draw.duplicate(true)',
        "func validation_town_building_complete_vfx_asset_summary() -> Dictionary:",
    ):
        ensure(token in stage_text, errors, f"TownStageView is missing building-complete VFX ownership: {token}")
    build_draw = block(stage_text, "_draw_town_building_complete_presentation")
    imported = block(stage_text, "_draw_town_building_complete_imported_vfx")
    fallback = block(stage_text, "_draw_town_building_complete_procedural_frame")
    state = block(stage_text, "_town_building_complete_vfx_asset_state")
    ensure(build_draw.find("_draw_town_building_complete_imported_vfx") < build_draw.find("_draw_town_building_complete_procedural_frame") < build_draw.find("draw_rect(badge_rect"), errors, "Town building completion must prefer imported art, retain procedural frame fallback, then draw unchanged badge/text")
    for token in (
        '_town_vfx_texture_for_path(String(asset_state.get("texture_path", "")))',
        "var alpha := clampf(1.0 - progress * 0.52, 0.42, 1.0)",
        "draw_texture_rect(texture, draw_rect, false",
        '"mode": "imported_texture"',
        "return true",
    ):
        ensure(token in imported, errors, f"Town imported build-complete path is missing exact draw behavior: {token}")
    for token in (
        "badge_rect.grow(4.0 + sin(progress * PI) * 7.0)",
        "draw_rect(frame_rect, Color(0.92, 0.72, 0.28, 0.78), false, 3.0)",
        '"mode": "existing_procedural_build_completion_frame"',
    ):
        ensure(token in fallback, errors, f"Town procedural build-complete fallback was not retained exactly: {token}")
    for token in (
        'cue_id == "vfx_placeholder_build_complete"',
        'String(_town_action_presentation.get("event_id", "")) == "town_building_built"',
        'String(spec.get("render_mode", "")) == "town_building_complete"',
        '"uses_procedural_fallback": not uses_imported_asset',
    ):
        ensure(token in state, errors, f"Town build-complete resolver is missing fail-closed cue/event/asset matching: {token}")
    for forbidden in ("session.", "_session.", "TownRules", "await ", "create_timer", "create_tween"):
        ensure(forbidden not in imported and forbidden not in fallback and forbidden not in state, errors, f"Town VFX resolution/draw must not change game or timing authority: {forbidden}")

    report_text = TOWN_BUILDING_COMPLETE_VFX_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    scene_text = TOWN_BUILDING_COMPLETE_VFX_REPORT_SCENE_PATH.read_text(encoding="utf-8")
    ensure_scene_nodes(scene_text, errors, "town_building_complete_vfx_asset_runtime_report.tscn", [("TownBuildingCompleteVfxAssetRuntimeReport", "Node")])
    for token in (
        'const VIEWPORT_SIZES := [Vector2i(1280, 720), Vector2i(1920, 1080)]',
        'TownStageViewScript.new()',
        '_move_active_hero_to_town(session, town)',
        'stage.call("set_town_state", session)',
        'stage.call("present_town_action", _presentation(town, false))',
        'stage.call("validation_town_action_presentation_snapshot")',
        'stage.set("_town_vfx_texture_missing", {TEXTURE_PATH: true})',
        'stage.call("present_town_action", _presentation(town, true))',
        'String(draw.get("mode", "")) == "imported_texture"',
        'String(draw.get("mode", "")) == expected_mode',
        'session.to_dict() == authority_before',
        'Rect2(Vector2.ZERO, Vector2(viewport_size)).encloses(stage.get_global_rect())',
        'SessionStateStore.SAVE_VERSION == 9',
        'PresentationAudio.validation_reset()',
        'print("TOWN_BUILDING_COMPLETE_VFX_ASSET_RUNTIME_REPORT %s"',
    ):
        ensure(token in report_text, errors, f"Town building-complete VFX focused owner is missing live proof: {token}")
    ensure(report_text.count("for viewport_size in VIEWPORT_SIZES:") == 1, errors, "Town building-complete VFX focused owner must run both exact widths")
    for forbidden in ("_draw_town_building_complete_imported_vfx", "_draw_town_building_complete_procedural_frame", "_town_building_complete_vfx_asset_state", "create_timer", "create_tween"):
        ensure(forbidden not in report_text, errors, f"Town building-complete focused owner must not bypass production rendering: {forbidden}")


def validate_town_recruitment_vfx_assets(errors: list[str]) -> None:
    required_paths = (
        TOWN_STAGE_SCRIPT_PATH,
        TOWN_VFX_MANIFEST_PATH,
        TOWN_RECRUITMENT_VFX_SOURCE_PATH,
        TOWN_RECRUITMENT_VFX_RUNTIME_PATH,
        TOWN_RECRUITMENT_VFX_REPORT_SCRIPT_PATH,
        TOWN_RECRUITMENT_VFX_REPORT_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing Town recruitment VFX owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return
    manifest = load_json(TOWN_VFX_MANIFEST_PATH)
    cues = manifest.get("cues", {}) if isinstance(manifest, dict) else {}
    ensure(cues.get("vfx_placeholder_recruit_muster") == {
        "event_id": "town_units_recruited",
        "texture_path": "res://art/town/runtime/vfx/recruit_muster.png",
        "render_mode": "town_recruit_muster",
        "scale": 1.0,
    }, errors, "Town VFX manifest must map the exact recruitment cue/event/texture")
    ensure(set(cues) == {"vfx_placeholder_build_complete", "vfx_placeholder_recruit_muster", "vfx_placeholder_town_route_response", "vfx_placeholder_town_market_exchange", "vfx_placeholder_town_spell_study", "vfx_placeholder_town_hero_hire", "vfx_placeholder_town_specialty_rank", "vfx_placeholder_town_unit_transfer"}, errors, "Town VFX manifest must not remap any other cue")
    ensure(png_size(TOWN_RECRUITMENT_VFX_SOURCE_PATH) == (1254, 1254), errors, "Town recruitment VFX source must retain its exact square source image")
    ensure(png_size(TOWN_RECRUITMENT_VFX_RUNTIME_PATH) == (512, 512), errors, "Town recruitment runtime texture must be 512x512")
    header = TOWN_RECRUITMENT_VFX_RUNTIME_PATH.read_bytes()[:26]
    ensure(len(header) >= 26 and header[25] in {4, 6}, errors, "Town recruitment runtime texture must retain a PNG alpha channel")

    def block(text: str, name: str) -> str:
        start = text.find(f"func {name}")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    recruit_draw = block(stage_text, "_draw_town_action_presentation")
    imported = block(stage_text, "_draw_town_recruitment_imported_vfx")
    fallback = block(stage_text, "_draw_town_recruitment_procedural_rings")
    state = block(stage_text, "_town_recruitment_vfx_asset_state")
    dispatch = block(stage_text, "_town_action_vfx_asset_state")
    ensure(recruit_draw.find("_draw_town_recruitment_imported_vfx") < recruit_draw.find("_draw_town_recruitment_procedural_rings") < recruit_draw.find("draw_rect(badge_rect"), errors, "Town recruitment must prefer imported art, retain procedural rings fallback, then draw unchanged badge/text")
    for token in (
        '_town_vfx_texture_for_path(String(asset_state.get("texture_path", "")))',
        "var alpha := clampf(1.0 - progress * 0.48, 0.46, 1.0)",
        "draw_texture_rect(texture, draw_rect, false",
        '"mode": "imported_texture"',
        "return true",
    ):
        ensure(token in imported, errors, f"Town imported recruitment path is missing exact draw behavior: {token}")
    for token in (
        "for index in range(3):",
        "14.0 + float(index) * 9.0 + progress * 8.0",
        "draw_arc(ring_center, radius",
        '"mode": "existing_procedural_recruit_muster_rings"',
        '"ring_count": 3',
    ):
        ensure(token in fallback, errors, f"Town procedural recruitment fallback was not retained exactly: {token}")
    for token in (
        'cue_id == "vfx_placeholder_recruit_muster"',
        'String(_town_action_presentation.get("event_id", "")) == "town_units_recruited"',
        'String(spec.get("render_mode", "")) == "town_recruit_muster"',
        '"uses_procedural_fallback": not uses_imported_asset',
    ):
        ensure(token in state, errors, f"Town recruitment resolver is missing fail-closed cue/event/asset matching: {token}")
