def validate_town_scenic_overlay_glass_integration(errors: list[str]) -> None:
    smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    required_paths = (TOWN_STAGE_SCRIPT_PATH, smoke_path)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing Town scenic-overlay integration file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    def gdscript_function_block(text: str, name: str) -> str:
        match = re.search(
            rf"^func {re.escape(name)}\([^\n]*\)[^\n]*:\n[\s\S]*?(?=^func |\Z)",
            text,
            re.MULTILINE,
        )
        return match.group(0) if match else ""

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const SCENIC_OVERLAY_MODEL := "responsive_translucent_glass_edge_rails"',
        'const SCENIC_GLASS_FILL := Color(0.025, 0.035, 0.042, 0.78)',
        'const SCENIC_GLASS_CARD_FILL := Color(0.045, 0.058, 0.066, 0.72)',
        'const SCENIC_GLASS_SHADOW := Color(0.0, 0.0, 0.0, 0.28)',
        'const SCENIC_GLASS_BORDER := Color(0.86, 0.72, 0.40, 0.70)',
        "const STATUS_ACCENT_WIDTH := 5.0",
        'const DISTRICT_RIBBON_MODEL := "compact_scenic_district_readiness_ribbon"',
        'const DISTRICT_RIBBON_FILL := Color(0.025, 0.035, 0.042, 0.56)',
        'const DISTRICT_RIBBON_CARD_FILL := Color(0.045, 0.058, 0.066, 0.30)',
        'const DISTRICT_RIBBON_BORDER := Color(0.86, 0.72, 0.40, 0.52)',
        "const DISTRICT_RIBBON_COMPACT_WIDTH := 540.0",
        "const DISTRICT_RIBBON_WIDE_WIDTH := 620.0",
        "const DISTRICT_RIBBON_COMPACT_HEIGHT := 34.0",
        "const DISTRICT_RIBBON_WIDE_HEIGHT := 36.0",
        "const DISTRICT_ACCENT_HEIGHT := 2.0",
        '"military": "Military"',
        '"economy": "Economy"',
        '"spellcraft": "Magic"',
        '"logistics": "Roads"',
        '"defense": "Walls"',
        "func validation_scenic_overlay_summary() -> Dictionary:",
        '"payload_authority": "existing_status_and_district_builders"',
        '"overlay_area_ratio": overlay_area / scene_area',
        '"status_district_nonoverlap": status_district_nonoverlap',
        '"district_ribbon_model": DISTRICT_RIBBON_MODEL',
        '"district_ribbon_span_ratio": district_strip_rect.size.x / maxf(1.0, scene_rect.size.x)',
    ):
        ensure(required_token in stage_text, errors, f"Town scenic glass integration is missing exact source token: {required_token}")

    summary_body = gdscript_function_block(stage_text, "validation_scenic_overlay_summary")
    summary_order = tuple(summary_body.find(token) for token in (
        "var status_payloads := _status_plaque_payloads()",
        "var status_rects := _status_plaque_rects(scene_rect, status_payloads.size())",
        "var district_payloads := _district_strip_payloads()",
        "var district_strip_rect := _district_strip_rect(scene_rect)",
        "var district_rects := _district_card_rects(district_strip_rect, district_payloads.size())",
        "var contained := scene_rect.encloses(district_strip_rect)",
        "return {",
    ))
    ensure(all(index >= 0 for index in summary_order) and list(summary_order) == sorted(summary_order), errors, "Town scenic-overlay summary must consume the exact production payload and geometry builders in order")
    for forbidden_token in ("await ", "Timer", "queue_redraw", "set_town_state", "TownRules", "OverworldRules", "session.", "sort(", "erase("):
        ensure(forbidden_token not in summary_body, errors, f"Town scenic-overlay summary must remain detached observation only: {forbidden_token}")

    plaque_body = gdscript_function_block(stage_text, "_draw_plaque")
    for required_token in (
        "draw_rect(rect, SCENIC_GLASS_FILL, true)",
        "draw_rect(rect, SCENIC_GLASS_BORDER, false, 1.5)",
        "Vector2(STATUS_ACCENT_WIDTH, rect.size.y)",
        "Color(accent.r, accent.g, accent.b, 0.92)",
        "Color(accent.r, accent.g, accent.b, 1.0).lightened(0.24)",
        "TEXT_COLOR, 14",
    ):
        ensure(required_token in plaque_body, errors, f"Town scenic status plaque is missing glass/accent typography token: {required_token}")
    district_body = gdscript_function_block(stage_text, "_draw_district_strip")
    for required_token in (
        "var strip_rect := _district_strip_rect(scene_rect)",
        "var payloads := _district_strip_payloads()",
        "var card_rects := _district_card_rects(strip_rect, payloads.size())",
        "draw_rect(strip_rect, DISTRICT_RIBBON_FILL, true)",
        "draw_rect(strip_rect, DISTRICT_RIBBON_BORDER, false, 1.0)",
        "draw_rect(card_rect, DISTRICT_RIBBON_CARD_FILL, true)",
        "Vector2(card_rect.size.x, DISTRICT_ACCENT_HEIGHT)",
        "card_rect.size.y * 0.5 + 4.0",
        "TEXT_COLOR, 13",
    ):
        ensure(required_token in district_body, errors, f"Town district ribbon is missing glass/accent typography token: {required_token}")
    for draw_body, owner in ((plaque_body, "status plaque"), (district_body, "district ribbon")):
        for forbidden_token in ("await ", "Timer", "queue_redraw", "session", "TownRules", "OverworldRules", "Input.", "grab_focus", "call_deferred"):
            ensure(forbidden_token not in draw_body, errors, f"Town scenic {owner} painter must remain draw-only: {forbidden_token}")

    payload_body = gdscript_function_block(stage_text, "_district_strip_payloads")
    for required_token in (
        "var district_counts := _district_counts()",
        "for key_value in DISTRICT_ORDER:",
        '"id": key',
        '"label": String(DISTRICT_LABELS.get(key, key.to_upper()))',
        '"value": int(district_counts.get(key, 0))',
        '"color": DISTRICT_COLORS.get(key, FRAME_COLOR)',
    ):
        ensure(required_token in payload_body, errors, f"Town district ribbon must preserve exact existing ordered payload authority: {required_token}")
    for forbidden_token in ("sort(", "erase(", "reverse(", "shuffle(", "session", "TownRules", "OverworldRules"):
        ensure(forbidden_token not in payload_body, errors, f"Town district payload materializer must not alter order or authority: {forbidden_token}")

    compact_body = gdscript_function_block(stage_text, "_scenic_overlay_compact")
    ensure("return scene_rect.size.x < 1000.0 or scene_rect.size.y < 520.0" in compact_body, errors, "Town scenic overlays must use the exact bounded live scene-rectangle breakpoint")
    status_rect_body = gdscript_function_block(stage_text, "_status_plaque_rects")
    district_rect_body = gdscript_function_block(stage_text, "_district_strip_rect")
    card_rect_body = gdscript_function_block(stage_text, "_district_card_rects")
    for required_token in ("118.0 if compact else 132.0", "40.0 if compact else 44.0"):
        ensure(required_token in status_rect_body, errors, f"Town status-plaque geometry is missing responsive footprint token: {required_token}")
    for required_token in (
        "var preferred_width := DISTRICT_RIBBON_COMPACT_WIDTH if compact else DISTRICT_RIBBON_WIDE_WIDTH",
        "var width := minf(preferred_width, maxf(0.0, scene_rect.size.x - 32.0))",
        "var height := DISTRICT_RIBBON_COMPACT_HEIGHT if compact else DISTRICT_RIBBON_WIDE_HEIGHT",
        "Vector2(width, height)",
    ):
        ensure(required_token in district_rect_body, errors, f"Town district ribbon is missing compact bounded-width geometry token: {required_token}")
    for required_token in ("var gap := 3.0", "var inset := 5.0", "strip_rect.size.y - 10.0"):
        ensure(required_token in card_rect_body, errors, f"Town district cells are missing bounded shared-ribbon geometry token: {required_token}")
    for obsolete_token in (
        "draw_rect(strip_rect, Color(0.88, 0.85, 0.78, 0.95), true)",
        "draw_rect(card_rect, card_color, true)",
        "var fill: Color = data.get(\"color\", FRAME_COLOR)",
        "draw_rect(rect, fill, true)",
        "Vector2(scene_rect.size.x - 32.0, height)",
        '"WAR"',
        '"COIN"',
        '"MAG"',
        '"ROAD"',
        '"WALL"',
    ):
        ensure(obsolete_token not in stage_text, errors, f"Town scenic overlays must not retain opaque debug-card paint: {obsolete_token}")

    smoke_text = smoke_path.read_text(encoding="utf-8")
    scenic_test_body = gdscript_function_block(smoke_text, "_assert_town_scenic_backdrop_contract")
    helper_body = gdscript_function_block(smoke_text, "_scenic_overlay_contract_exact")
    for required_token in (
        'live_board.has_method("validation_scenic_overlay_summary")',
        'var live_overlay_summary: Dictionary = live_board.call("validation_scenic_overlay_summary")',
        'var live_overlay_scene_rect: Rect2 = live_overlay_summary.get("scene_rect", Rect2()) if live_overlay_summary.get("scene_rect", Rect2()) is Rect2 else Rect2()',
        "var live_overlay_compact_expected := live_overlay_scene_rect.size.x < 1000.0 or live_overlay_scene_rect.size.y < 520.0",
        "_scenic_overlay_contract_exact(live_overlay_summary, live_overlay_compact_expected)",
        "var fresh_live_overlay_summary := live_overlay_summary.duplicate(true)",
        'live_overlay_summary["status_payloads"][0]["value"] = "999"',
        'live_overlay_summary["district_payloads"][0]["value"] = 999',
        'live_board.call("validation_scenic_overlay_summary") != fresh_live_overlay_summary',
        'fixture.validation_scenic_overlay_summary()',
        "stage_size == Vector2(620.0, 320.0)",
    ):
        ensure(required_token in scenic_test_body, errors, f"Town scenic focused owner is missing exact lifecycle/detach token: {required_token}")
    for required_token in (
        '"responsive_translucent_glass_edge_rails"',
        '["guard", "spell", "pressure", "routes"]',
        '["military", "economy", "spellcraft", "logistics", "defense"]',
        '["Military", "Economy", "Magic", "Roads", "Walls"]',
        '"compact_scenic_district_readiness_ribbon"',
        "540.0 if compact_expected else 620.0",
        "34.0 if compact_expected else 36.0",
        "0.25 if compact_expected else 0.08",
        'summary.get("contained", false)',
        'summary.get("status_district_nonoverlap", false)',
        'summary.get("glass_fill_alpha", 0.0)), 0.78',
        'summary.get("glass_card_fill_alpha", 0.0)), 0.72',
        'summary.get("district_ribbon_fill_alpha", 0.0)), 0.56',
        'summary.get("district_ribbon_card_fill_alpha", 0.0)), 0.30',
        'summary.get("district_ribbon_border_alpha", 0.0)), 0.52',
        'summary.get("district_ribbon_span_ratio", -1.0)',
        'summary.get("payload_authority", "")) == "existing_status_and_district_builders"',
    ):
        ensure(required_token in helper_body, errors, f"Town scenic overlay focused contract is missing exact proof token: {required_token}")
    for forbidden_token in ("sort(", "erase(", "set_town_state", "queue_redraw", "call_deferred", "Timer", "await "):
        ensure(forbidden_token not in helper_body, errors, f"Town scenic overlay oracle must remain passive and source-independent: {forbidden_token}")


def validate_town_command_watchplate_visual_hierarchy(errors: list[str]) -> None:
    smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    required_paths = (TOWN_STAGE_SCRIPT_PATH, smoke_path)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing Town command-watchplate file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    def gdscript_function_block(text: str, name: str) -> str:
        match = re.search(
            rf"^func {re.escape(name)}\([^\n]*\)[^\n]*:\n[\s\S]*?(?=^func |\Z)",
            text,
            re.MULTILINE,
        )
        return match.group(0) if match else ""

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        'const COMMAND_WATCH_MODEL := "responsive_translucent_five_cell_watchplate"',
        'const COMMAND_WATCH_FILL := Color(0.025, 0.035, 0.042, 0.72)',
        'const COMMAND_WATCH_CELL_FILL := Color(0.045, 0.058, 0.066, 0.64)',
        'const COMMAND_WATCH_BORDER := Color(0.86, 0.72, 0.40, 0.68)',
        'const COMMAND_WATCH_ACCENT_HEIGHT := 3.0',
        'const COMMAND_WATCH_ORDER := ["heroes", "build", "recruit", "response", "threat"]',
        '"heroes": "HERO"',
        '"recruit": "MUSTER"',
        '"response": "ORDERS"',
        'func validation_command_watch_summary() -> Dictionary:',
        '"payload_authority": "existing_town_command_marker_calculations"',
    ):
        ensure(required_token in stage_text, errors, f"Town command watchplate is missing exact source token: {required_token}")

    payload_body = gdscript_function_block(stage_text, "_command_watch_payloads")
    payload_order = tuple(payload_body.find(token) for token in (
        'var threat_count := int(_threat.get("visible_marching", 0)) + int(_threat.get("visible_pressuring", 0))',
        '"heroes": _stationed.size()',
        '"build": _build_actions.size()',
        '"recruit": _available_recruit_total()',
        '"response": _response_actions.size()',
        '"threat": threat_count',
        'for id_value in COMMAND_WATCH_ORDER:',
        '"display_label": String(COMMAND_WATCH_LABELS.get(id, id.to_upper()))',
        '"value": int(values.get(id, 0))',
    ))
    ensure(all(index >= 0 for index in payload_order) and list(payload_order) == sorted(payload_order), errors, "Town command watchplate must preserve the exact legacy marker calculations and fixed order")
    for forbidden_token in ("sort(", "erase(", "reverse(", "shuffle(", "TownRules", "OverworldRules", "session", "await ", "Timer"):
        ensure(forbidden_token not in payload_body, errors, f"Town command-watch payload materializer must remain local and order-preserving: {forbidden_token}")

    rect_body = gdscript_function_block(stage_text, "_command_watch_rect")
    for required_token in (
        'Vector2(242.0, 60.0) if compact else Vector2(260.0, 62.0)',
        'scene_rect.end.x - watch_size.x - 18.0',
        'scene_rect.position.y + 72.0',
    ):
        ensure(required_token in rect_body, errors, f"Town command watchplate is missing responsive bounded geometry token: {required_token}")
    cell_body = gdscript_function_block(stage_text, "_command_watch_cell_rects")
    for required_token in (
        'var inset := 6.0',
        'var gap := 4.0',
        'var top := 20.0',
        'float(cell_count - 1)',
        'watch_rect.size.y - top - 6.0',
    ):
        ensure(required_token in cell_body, errors, f"Town command watchplate cells are missing exact contained geometry token: {required_token}")

    draw_body = gdscript_function_block(stage_text, "_draw_command_markers")
    for required_token in (
        'var payloads := _command_watch_payloads()',
        'var watch_rect := _command_watch_rect(scene_rect)',
        'var cell_rects := _command_watch_cell_rects(watch_rect, payloads.size())',
        'draw_rect(watch_rect, COMMAND_WATCH_FILL, true)',
        'draw_rect(watch_rect, COMMAND_WATCH_BORDER, false, 1.5)',
        'Vector2(watch_rect.size.x, COMMAND_WATCH_ACCENT_HEIGHT)',
        '_draw_text("TOWN WATCH"',
        'draw_rect(cell_rect, COMMAND_WATCH_CELL_FILL, true)',
        'String(payload.get("display_label", ""))',
        'int(payload.get("value", 0))',
    ):
        ensure(required_token in draw_body, errors, f"Town command watchplate painter is missing glass/cell typography token: {required_token}")
    for forbidden_token in ("await ", "Timer", "queue_redraw", "set_town_state", "TownRules", "OverworldRules", "Input.", "grab_focus", "call_deferred"):
        ensure(forbidden_token not in draw_body, errors, f"Town command watchplate painter must remain draw-only: {forbidden_token}")
    for obsolete_token in (
        'Vector2(156.0, 114.0)',
        'Color(0.15, 0.17, 0.20, 0.90)',
        'draw_circle(Vector2(rect.position.x + 10.0, y - 4.0), 3.0, FRAME_COLOR)',
        '"HEROES %d" % _stationed.size()',
        '"RESPONSE %d" % _response_actions.size()',
    ):
        ensure(obsolete_token not in draw_body, errors, f"Town command watchplate must not retain the opaque bullet-list treatment: {obsolete_token}")

    summary_body = gdscript_function_block(stage_text, "validation_command_watch_summary")
    summary_order = tuple(summary_body.find(token) for token in (
        'var payloads := _command_watch_payloads()',
        'var watch_rect := _command_watch_rect(scene_rect)',
        'var cell_rects := _command_watch_cell_rects(watch_rect, payloads.size())',
        'var status_rects := _status_plaque_rects(scene_rect, _status_plaque_payloads().size())',
        'var district_rect := _district_strip_rect(scene_rect)',
        'var header_rect := _header_stage_rect(scene_rect)',
        'var legacy_area := 156.0 * 114.0',
        'return {',
    ))
    ensure(all(index >= 0 for index in summary_order) and list(summary_order) == sorted(summary_order), errors, "Town command-watch summary must observe exact production payload and geometry builders in order")
    for required_token in (
        '"cells_nonoverlap": cells_nonoverlap',
        '"status_nonoverlap": status_nonoverlap',
        '"district_nonoverlap": not watch_rect.intersects(district_rect)',
        '"header_nonoverlap": not watch_rect.intersects(header_rect)',
        '"legacy_area_ratio": (watch_rect.size.x * watch_rect.size.y) / legacy_area',
    ):
        ensure(required_token in summary_body, errors, f"Town command-watch summary is missing fail-closed geometry token: {required_token}")
    for forbidden_token in ("await ", "Timer", "queue_redraw", "set_town_state", "TownRules", "OverworldRules", "session.", "sort(", "erase("):
        ensure(forbidden_token not in summary_body, errors, f"Town command-watch summary must remain detached observation only: {forbidden_token}")

    smoke_text = smoke_path.read_text(encoding="utf-8")
    scenic_body = gdscript_function_block(smoke_text, "_assert_town_scenic_backdrop_contract")
    helper_body = gdscript_function_block(smoke_text, "_command_watch_contract_exact")
    for required_token in (
        'live_board.has_method("validation_command_watch_summary")',
        'var live_watch_summary: Dictionary = live_board.call("validation_command_watch_summary")',
        'var live_watch_values := _expected_live_command_watch_values(session)',
        '_command_watch_contract_exact(live_watch_summary, live_overlay_compact_expected, live_watch_values)',
        'var fresh_live_watch_summary := live_watch_summary.duplicate(true)',
        'live_watch_summary["payloads"][0]["value"] = 999',
        'live_board.call("validation_command_watch_summary") != fresh_live_watch_summary',
        '"stationed": [{"hero_id": "hero_a"}, {"hero_id": "hero_b"}]',
        '"build_actions": [{"id": "build_a"}, {"id": "build_b"}]',
        '"response_actions": [{"id": "response_a"}]',
        '"threat": {"visible_marching": 2, "visible_pressuring": 1}',
        '_command_watch_contract_exact(watch_summary, stage_size == Vector2(620.0, 320.0), [2, 2, 7, 1, 3])',
        'compact_watch_initial != compact_watch_restored',
        'compact_watch_initial == wide_watch',
        '_command_watch_contract_exact(fallback_watch_summary, false, [0, 0, 0, 0, 0])',
    ):
        ensure(required_token in scenic_body, errors, f"Town command-watch focused owner is missing lifecycle/authority token: {required_token}")
    for required_token in (
        '"responsive_translucent_five_cell_watchplate"',
        '["heroes", "build", "recruit", "response", "threat"]',
        '["HERO", "BUILD", "MUSTER", "ORDERS", "THREAT"]',
        'Vector2(242.0, 60.0) if compact_expected else Vector2(260.0, 62.0)',
        '0.82 if compact_expected else 0.91',
        'summary.get("cells_nonoverlap", false)',
        'summary.get("status_nonoverlap", false)',
        'summary.get("district_nonoverlap", false)',
        'summary.get("header_nonoverlap", false)',
        'summary.get("watch_area", 0.0)) < float(summary.get("legacy_area", 0.0))',
        'summary.get("payload_authority", "")) == "existing_town_command_marker_calculations"',
    ):
        ensure(required_token in helper_body, errors, f"Town command-watch focused contract is missing exact proof token: {required_token}")
    for forbidden_token in ("sort(", "erase(", "set_town_state", "queue_redraw", "call_deferred", "Timer", "await "):
        ensure(forbidden_token not in helper_body, errors, f"Town command-watch oracle must remain passive and source-independent: {forbidden_token}")


def validate_town_capture_frontier_first_view_status(errors: list[str]) -> None:
    town_visual_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    required_paths = (TOWN_SCRIPT_PATH, TOWN_STAGE_SCRIPT_PATH, OVERWORLD_RULES_PATH, town_visual_path)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing captured-town first-view status file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    stage_text = TOWN_STAGE_SCRIPT_PATH.read_text(encoding="utf-8")
    shell_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    visual_text = town_visual_path.read_text(encoding="utf-8")

    for required_token in (
        "var _occupation: Dictionary = {}",
        "var _front: Dictionary = {}",
        "_occupation = OverworldRulesScript.town_occupation_state(session, _town)",
        "_front = OverworldRulesScript.town_front_state(session, _town)",
        '_occupation = _duplicate_dictionary(state.get("occupation", {}))',
        '_front = _duplicate_dictionary(state.get("front", {}))',
        "_occupation = {}",
        "_front = {}",
        "func validation_status_plaques_summary() -> Dictionary:",
    ):
        ensure(required_token in stage_text, errors, f"TownStageView.gd is missing captured-town state ownership token: {required_token}")

    plaque_match = re.search(
        r"func _status_plaque_payloads\(\) -> Array:\n(?P<body>.*?)(?=\nfunc )",
        stage_text,
        re.S,
    )
    ensure(plaque_match is not None, errors, "Could not isolate TownStageView status-plaque payload ownership")
    if plaque_match is not None:
        plaque_body = plaque_match.group("body")
        plaque_tokens = (
            "var readiness := OverworldRulesScript.town_battle_readiness(_town, _session)",
            "var spell_tier := TownRulesScript.current_spell_tier(_town)",
            "var pressure := OverworldRulesScript.town_pressure_output(_town, _session)",
            '"title": "Guard"',
            '"title": "Spell"',
            "_contextual_front_plaque(pressure)",
            '"title": "Routes"',
        )
        plaque_positions = [plaque_body.find(token) for token in plaque_tokens]
        ensure(
            min(plaque_positions) >= 0 and plaque_positions == sorted(plaque_positions),
            errors,
            "Town status plaques must retain exact Guard/Spell/contextual-Front/Routes order from live rule state",
        )
        ensure(plaque_body.count("_contextual_front_plaque(pressure)") == 1, errors, "Town status plaques must own exactly one contextual Front slot")

    contextual_match = re.search(
        r"func _contextual_front_plaque\(pressure: int\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc )",
        stage_text,
        re.S,
    )
    ensure(contextual_match is not None, errors, "Could not isolate TownStageView contextual Front plaque")
    if contextual_match is not None:
        contextual_body = contextual_match.group("body")
        contextual_tokens = (
            'var occupation_active := bool(_occupation.get("active", false))',
            'var retake_active := bool(_front.get("active", false)) and String(_front.get("mode", "")) == "retake"',
            "if occupation_active:",
            '"title": "Occupation"',
            '"kind": "occupation_retake" if retake_active else "occupation"',
            "if retake_active:",
            '"title": "Retake"',
            '"kind": "retake"',
            '"title": "Front"',
            '"value": "%d pressure" % pressure',
            '"kind": "pressure"',
        )
        contextual_positions = [contextual_body.find(token) for token in contextual_tokens]
        ensure(
            min(contextual_positions) >= 0 and contextual_positions == sorted(contextual_positions),
            errors,
            "Town contextual Front plaque must prefer occupation, then retake, then preserve ordinary pressure semantics",
        )
        for forbidden in ("town[", "session.", "OverworldRulesScript.", "queue_redraw", "add_child", "Panel"):
            ensure(forbidden not in contextual_body, errors, f"Town contextual Front plaque must remain a pure view over detached state: {forbidden}")

    summary_match = re.search(
        r"func validation_status_plaques_summary\(\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc )",
        stage_text,
        re.S,
    )
    ensure(summary_match is not None, errors, "Could not isolate TownStageView status-plaque validation summary")
    if summary_match is not None:
        summary_body = summary_match.group("body")
        for required_token in (
            "var plaques := _status_plaque_payloads()",
            "var rects := _status_plaque_rects(scene_rect, plaques.size())",
            '"front_plaque": plaques[2].duplicate(true) if plaques.size() > 2 else {}',
            '"occupation": _occupation.duplicate(true)',
            '"front": _front.duplicate(true)',
            '"contained": contained',
        ):
            ensure(required_token in summary_body, errors, f"Town plaque summary is missing detached live-render proof: {required_token}")
        for forbidden in ("town_occupation_state", "town_front_state", "set_town_state", "set_precomputed_town_state"):
            ensure(forbidden not in summary_body, errors, f"Town plaque summary must observe renderer state without rebuilding authority: {forbidden}")

    shell_build_match = re.search(
        r"func _build_town_stage_view_state\(.*?\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    ensure(shell_build_match is not None, errors, "Could not isolate TownShell stage-state construction")
    if shell_build_match is not None:
        shell_build_body = shell_build_match.group("body")
        for required_token in (
            '"occupation": OverworldRules.town_occupation_state(_session, town).duplicate(true)',
            '"front": OverworldRules.town_front_state(_session, town).duplicate(true)',
        ):
            ensure(required_token in shell_build_body, errors, f"TownShell stage state must carry exact detached frontier authority: {required_token}")

    refresh_match = re.search(
        r"func _refresh_cached_stage_dynamic\(.*?\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    ensure(refresh_match is not None, errors, "Could not isolate TownShell dynamic stage refresh")
    if refresh_match is not None:
        refresh_body = refresh_match.group("body")
        refresh_tokens = (
            'refreshed["occupation"] = OverworldRules.town_occupation_state(_session, town).duplicate(true)',
            'refreshed["front"] = OverworldRules.town_front_state(_session, town).duplicate(true)',
        )
        refresh_positions = [refresh_body.find(token) for token in refresh_tokens]
        ensure(
            min(refresh_positions) >= 0 and refresh_positions == sorted(refresh_positions),
            errors,
            "TownShell cache hits must refresh exact occupation/front state in order",
        )

    signature_match = re.search(
        r"func _town_stage_signature\(.*?\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    ensure(signature_match is not None, errors, "Could not isolate TownShell stage signature")
    if signature_match is not None:
        signature_body = signature_match.group("body")
        ensure('var occupation: Dictionary = stage_state.get("occupation", {})' in signature_body, errors, "Town stage signature must read occupation state")
        ensure('var front: Dictionary = stage_state.get("front", {})' in signature_body, errors, "Town stage signature must read front state")
        ensure("_scalar_pairs_signature(occupation)" in signature_body, errors, "Town stage signature must include occupation state")
        ensure("_scalar_pairs_signature(front)" in signature_body, errors, "Town stage signature must include front state")

    visual_match = re.search(
        r"func _assert_town_capture_frontier_status_contract\(.*?\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    ensure(visual_match is not None, errors, "Could not isolate captured-town focused visual contract")
    if visual_match is not None:
        visual_body = visual_match.group("body")
        visual_tokens = (
            'validation_status_plaques_summary',
            '"pressure", "Front", "%d pressure" % live_pressure',
            '"occupation"',
            '"%dd pacify"',
            '"retake"',
            '"Mireclaw +%d"',
            'for stage_size in [Vector2(620.0, 320.0), Vector2(1180.0, 640.0)]:',
            '"occupation_retake"',
            '"%dd | Retake"',
            'fixture_authority_before_detach: Dictionary = fixture_session.to_dict()',
            'fixture_session.to_dict() != fixture_authority_before_detach',
            'fixture_session.day += 1',
            'fixture_town["occupation"]["pressure"] = 5',
            'fixture.set_precomputed_town_state',
            'fixture.validation_status_plaques_summary() != advanced_summary',
            'live_session.to_dict() != live_session_before',
        )
        visual_positions = [visual_body.find(token) for token in visual_tokens]
        ensure(
            min(visual_positions) >= 0 and visual_positions == sorted(visual_positions),
            errors,
            "Captured-town focused proof must cover ordinary/occupation/retake/two-size combined/detach/day-refresh/precomputed/live-authority in order",
        )
        for forbidden in ("_contextual_front_plaque(", "_status_plaque_payloads(", "_draw_status_plaques(", "create_timer(", "await get_tree().create_timer"):
            ensure(forbidden not in visual_body, errors, f"Captured-town focused proof must use the public live stage without direct renderer callbacks or delays: {forbidden}")


def validate_town_header_player_facing_control_label(errors: list[str]) -> None:
    town_rules_path = ROOT / "scripts/core/TownRules.gd"
    town_test_path = ROOT / "tests/town_battle_visual_smoke.gd"
    town_rules_text = town_rules_path.read_text(encoding="utf-8")
    town_test_text = town_test_path.read_text(encoding="utf-8")
    rules_tokens = [
        'return "%s | %s%s | %s | Spell Tier %d" % [',
        'town_control_label(String(town.get("owner", "neutral")))',
        'static func town_control_label(owner: String) -> String:',
        'return OverworldRulesScript.town_control_label(owner)',
    ]
    rules_positions = [town_rules_text.find(token) for token in rules_tokens]
    ensure(
        min(rules_positions) >= 0 and rules_positions == sorted(rules_positions),
        errors,
        "TownRules player-facing Town control label tokens must exist in exact order",
    )
    header_match = re.search(
        r"static func describe_header\(.*?\) -> String:\n(?P<body>.*?)(?=\nstatic func )",
        town_rules_text,
        re.S,
    )
    ensure(header_match is not None, errors, "Could not isolate TownRules.describe_header")
    header_body = header_match.group("body") if header_match is not None else ""
    ensure(
        'Owner %s' not in header_body
        and 'String(town.get("owner", "neutral")).capitalize()' not in header_body,
        errors,
        "TownRules must not expose the raw owner enum in the release-facing Town header",
    )
    test_match = re.search(
        r"func _assert_town_header_control_label_contract\(.*?\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        town_test_text,
        re.S,
    )
    ensure(test_match is not None, errors, "Town visual smoke must own a focused Town header control-label contract")
    test_block = test_match.group("body") if test_match is not None else ""
    test_tokens = [
        'var header := shell.get_node_or_null("%Header") as Label',
        "var live_header := TownRules.describe_header(live_session)",
        'header.tooltip_text != live_header',
        'live_header.contains(" | Your Control | ")',
        'live_header.contains("Owner Player")',
        "shell.get_global_rect().encloses(header.get_global_rect())",
        'font.get_string_size(live_header, HORIZONTAL_ALIGNMENT_LEFT, -1.0, font_size).x > header.size.x + 0.5',
        "var expected_spell_tier := TownRules.current_spell_tier(fixture_town)",
        '"player": "Your Control"',
        '"enemy": "Enemy Control"',
        '"neutral": "Neutral Control"',
        '"unsupported_internal_owner": "Unknown Control"',
        'var authority_before: Dictionary = fixture_session.to_dict()',
        "var header_text := TownRules.describe_header(fixture_session)",
        'fixture_session.to_dict() != authority_before',
        'header_text.contains("Owner ")',
        'header_text.contains(owner_value)',
        'header_text.begins_with("Riverwatch Hold | Embercourt League | Frontier Stronghold | ")',
        'header_text.ends_with(" | Spell Tier %d" % expected_spell_tier)',
    ]
    test_positions = [test_block.find(token) for token in test_tokens]
    ensure(
        min(test_positions) >= 0 and test_positions == sorted(test_positions),
        errors,
        "Town visual smoke header control-label proof tokens must exist in exact order",
    )
    ensure(
        town_test_text.count("_assert_town_header_control_label_contract(shell, session)") == 1,
        errors,
        "Town visual smoke must invoke the focused header control-label proof exactly once",
    )
    for forbidden in [
        'fixture_town.erase("owner")',
        "header.text =",
        "header.tooltip_text =",
        "owner_value.capitalize()",
    ]:
        ensure(forbidden not in test_block, errors, f"Town header control-label proof must not use shortcut {forbidden}")


def validate_overworld_town_control_label_consistency(errors: list[str]) -> None:
    overworld_rules_text = (ROOT / "scripts/core/OverworldRules.gd").read_text(encoding="utf-8")
    town_rules_text = (ROOT / "scripts/core/TownRules.gd").read_text(encoding="utf-8")
    overworld_shell_text = (ROOT / "scenes/overworld/OverworldShell.gd").read_text(encoding="utf-8")
    route_test_text = (ROOT / "tests/overworld_route_tooltip_smoke.gd").read_text(encoding="utf-8")
    mapping_tokens = [
        'static func town_control_label(owner: String) -> String:',
        'match owner.strip_edges().to_lower():',
        '"player":',
        'return "Your Control"',
        '"enemy":',
        'return "Enemy Control"',
        '"neutral":',
        'return "Neutral Control"',
        'return "Unknown Control"',
    ]
    mapping_match = re.search(
        r"static func town_control_label\(owner: String\) -> String:\n(?P<body>.*?)(?=\nstatic func )",
        overworld_rules_text,
        re.S,
    )
    ensure(mapping_match is not None, errors, "Could not isolate OverworldRules.town_control_label")
    mapping_block = mapping_match.group(0) if mapping_match is not None else ""
    mapping_positions = [mapping_block.find(token) for token in mapping_tokens]
    ensure(
        min(mapping_positions) >= 0 and mapping_positions == sorted(mapping_positions),
        errors,
        "OverworldRules must own the exact ordered shared Town control-label mapping",
    )
    town_delegate = re.search(
        r"static func town_control_label\(owner: String\) -> String:\n(?P<body>.*?)(?=\nstatic func )",
        town_rules_text,
        re.S,
    )
    ensure(town_delegate is not None, errors, "Could not isolate TownRules.town_control_label delegate")
    town_delegate_body = town_delegate.group("body") if town_delegate is not None else ""
    ensure(
        town_delegate_body.strip() == "return OverworldRulesScript.town_control_label(owner)",
        errors,
        "TownRules header mapping must delegate exactly to the shared OverworldRules owner",
    )
    source_contracts = {
        "describe_town_context": [
            'town_control_label(String(town.get("owner", "neutral")))',
        ],
        "_route_decision_affected_text": [
            'return "%s | Town: %s" % [route_label, OverworldRules.town_control_label(String(town.get("owner", "neutral")))]',
        ],
        "_rail_tile_text": [
            'var control_label := OverworldRules.town_control_label(String(town.get("owner", "neutral")))',
            '"%s | %s" % [control_label, terrain]',
        ],
        "_tile_visibility_tooltip": [
            'return _append_hover_order_cue("%s %d,%d | Town: %s | %s | %s" % [',
            'OverworldRules.town_control_label(String(town.get("owner", "neutral")))',
        ],
    }
    for function_name, required_tokens in source_contracts.items():
        source_text = overworld_rules_text if function_name == "describe_town_context" else overworld_shell_text
        function_match = re.search(
            rf"(?:static )?func {re.escape(function_name)}\(.*?\)(?: -> [^:]+)?:\n(?P<body>.*?)(?=\n(?:static )?func )",
            source_text,
            re.S,
        )
        ensure(function_match is not None, errors, f"Could not isolate {function_name} Town control-label owner")
        function_body = function_match.group("body") if function_match is not None else ""
        positions = [function_body.find(token) for token in required_tokens]
        ensure(
            min(positions) >= 0 and positions == sorted(positions),
            errors,
            f"{function_name} must use the exact shared Town control-label mapping in source order",
        )
        ensure(
            'String(town.get("owner", "neutral")).capitalize()' not in function_body
            and '"Owner %s"' not in function_body,
            errors,
            f"{function_name} must not expose the raw Town owner enum",
        )
    mapping_test = re.search(
        r"func _assert_town_control_label_mapping_contract\(\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        route_test_text,
        re.S,
    )
    live_test = re.search(
        r"func _assert_live_town_control_surfaces\(.*?\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        route_test_text,
        re.S,
    )
    ensure(mapping_test is not None and live_test is not None, errors, "Route tooltip smoke must own focused shared and live Town control-label proofs")
    mapping_body = mapping_test.group("body") if mapping_test is not None else ""
    live_body = live_test.group("body") if live_test is not None else ""
    mapping_test_tokens = [
        '"player": "Your Control"',
        '"enemy": "Enemy Control"',
        '"neutral": "Neutral Control"',
        '"unsupported_internal_owner": "Unknown Control"',
        "var overworld_label := OverworldRules.town_control_label(owner_value)",
        "var town_label := TownRules.town_control_label(owner_value)",
    ]
    live_test_tokens = [
        'var context_text := String(snapshot.get("context_summary", ""))',
        'var rail_text := String(snapshot.get("selected_tile_rail_text", ""))',
        'session.scenario_id = ""',
        'var route_affected := String(shell.call("_route_decision_affected_text", decision))',
        "session.scenario_id = scenario_id_before",
        'context_text.contains("Riverwatch Hold | Embercourt League | Your Control | Frontier Stronghold")',
        'rail_text.contains("Your Control | ")',
        'route_affected == "Riverwatch Hold route | Town: Your Control"',
        'not context_text.contains("Owner Player")',
        'not rail_text.contains("Owner Player")',
        'not route_affected.contains("Town: Player")',
        'String(session.scenario_id) == scenario_id_before',
    ]
    for body, tokens, label in [
        (mapping_body, mapping_test_tokens, "mapping"),
        (live_body, live_test_tokens, "live selected-town"),
    ]:
        positions = [body.find(token) for token in tokens]
        ensure(min(positions) >= 0 and positions == sorted(positions), errors, f"Route tooltip smoke {label} control-label proof must remain exact and ordered")
    ensure(
        route_test_text.count("_assert_town_control_label_mapping_contract()") == 2
        and route_test_text.count("_assert_live_town_control_surfaces(shell, session, town, width)") == 1,
        errors,
        "Route tooltip smoke must invoke the shared mapping once and the live proof once per width",
    )
    hover_tokens = [
        'var town_hover: Dictionary = shell.call("validation_hover_tile", 0, 2)',
        'hover_text.contains("Town: Riverwatch Hold | Your Control | ")',
        'hover_text.contains("Owner Player")',
        'hover_text.contains("Town: Player")',
        'shell.call("validation_hover_tile", 1, 0)',
    ]
    hover_positions = [route_test_text.find(token) for token in hover_tokens]
    ensure(min(hover_positions) >= 0 and hover_positions == sorted(hover_positions), errors, "Route tooltip smoke must prove and restore the actual visible Town hover path")
    viewport_tokens = [
        "var height := 1080 if width == 1920 else 720",
        "get_window().size = Vector2i(width, height)",
        "host.size = Vector2(float(width), float(height))",
        "Vector2i(host.size) != Vector2i(width, height)",
        '"height": height',
    ]
    viewport_positions = [route_test_text.find(token) for token in viewport_tokens]
    ensure(min(viewport_positions) >= 0 and viewport_positions == sorted(viewport_positions), errors, "Route tooltip smoke must execute exact 1280x720 and 1920x1080 live host sizes")
    ensure("Vector2i(width, 720)" not in route_test_text, errors, "Route tooltip smoke must not substitute 1920x720 for the registered 1920x1080 gate")
    for forbidden in [
        'fixture_town.erase("owner")',
        "owner_value.capitalize()",
        'context_text.replace("Owner Player"',
        'rail_text.replace("Owner Player"',
        'hover_text.replace("Owner Player"',
        'session.scenario_id = "town-control-label-no-objective-fixture"',
    ]:
        ensure(forbidden not in mapping_body + live_body, errors, f"Overworld Town control-label proof must not use shortcut {forbidden}")


def validate_town_defense_outlook_board(errors: list[str]) -> None:
    required_paths = (TOWN_SCENE_PATH, TOWN_SCRIPT_PATH, TOWN_RULES_PATH, OVERWORLD_RULES_PATH)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing town defense-outlook file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    town_scene_text = TOWN_SCENE_PATH.read_text(encoding="utf-8")
    for node_name, node_type in (
        ("OutlookPanel", "PanelContainer"),
        ("OutlookTitle", "Label"),
        ("Outlook", "Label"),
    ):
        ensure(scene_has_node(town_scene_text, node_name, node_type), errors, f"TownShell.tscn must define {node_name} ({node_type}) for the town defense outlook board")

    town_rules_text = TOWN_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func describe_outlook_board",
        "func _town_outlook_grade",
        "func _town_frontier_outlook_line",
        "func _town_dispatch_readiness_line",
        "func _town_support_watch_line",
        "func _active_hero_movement_state",
        "func _count_ready_actions",
        "func _stationed_reserve_count",
        "Strong defensive posture",
        "Capital chain exposed",
        "No reserve commander covers the walls if the field hero rides out",
    ):
        ensure(required_token in town_rules_text, errors, f"TownRules.gd is missing required town defense-outlook token: {required_token}")

    overworld_text = OVERWORLD_RULES_PATH.read_text(encoding="utf-8")
    ensure("func town_public_threat_state" in overworld_text, errors, "OverworldRules.gd must expose a visibility-safe public town-threat helper for the town outlook board")

    town_script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_outlook_label",
        "TownRules.describe_outlook_board",
    ):
        ensure(required_token in town_script_text, errors, f"TownShell.gd is missing required town defense-outlook token: {required_token}")


def validate_town_order_readiness_ledger(errors: list[str]) -> None:
    required_paths = (TOWN_SCENE_PATH, TOWN_SCRIPT_PATH, TOWN_RULES_PATH, OVERWORLD_RULES_PATH)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing town order-readiness file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    town_scene_text = TOWN_SCENE_PATH.read_text(encoding="utf-8")
    for node_name, node_type in (
        ("CommandLedgerPanel", "PanelContainer"),
        ("CommandLedgerTitle", "Label"),
        ("CommandLedger", "Label"),
    ):
        ensure(scene_has_node(town_scene_text, node_name, node_type), errors, f"TownShell.tscn must define {node_name} ({node_type}) for the town order-readiness ledger")

    town_rules_text = TOWN_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func describe_command_ledger",
        "func _build_order_ledger_line",
        "func _recruit_order_ledger_line",
        "func _response_order_ledger_line",
        "func _coverage_order_ledger_line",
        "func _market_coverage_line",
        "func _cost_shortfall_line",
        "func _max_market_affordable_count",
        "Exchange can unlock",
        "Order Ledger",
    ):
        ensure(required_token in town_rules_text, errors, f"TownRules.gd is missing required town order-readiness token: {required_token}")

    overworld_text = OVERWORLD_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "func town_cost_readiness",
        "market_affordable",
        "direct_shortfall",
    ):
        ensure(required_token in overworld_text, errors, f"OverworldRules.gd is missing required town order-readiness token: {required_token}")

    town_script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    for required_token in (
        "_command_ledger_label",
        "TownRules.describe_command_ledger",
    ):
        ensure(required_token in town_script_text, errors, f"TownShell.gd is missing required town order-readiness token: {required_token}")


def validate_overworld_route_map_cue_refresh(errors: list[str]) -> None:
    required_paths = (
        OVERWORLD_SCRIPT_PATH,
        HERO_COMMAND_RULES_PATH,
        OVERWORLD_ROUTE_TOOLTIP_SMOKE_SCRIPT_PATH,
        OVERWORLD_ROUTE_TOOLTIP_SMOKE_SCENE_PATH,
        OVERWORLD_ROUTE_DESTINATION_ONLY_ACTION_REGRESSION_SCRIPT_PATH,
        OVERWORLD_SELECTED_ROUTE_CONTEXT_ACTIONS_CACHE_REGRESSION_SCRIPT_PATH,
        OVERWORLD_INCREMENTAL_ROUTE_PREVIEW_REFRESH_REGRESSION_SCRIPT_PATH,
        OVERWORLD_INCREMENTAL_ROUTE_PREVIEW_REFRESH_REGRESSION_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing focused overworld route MapCue file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    route_scene_text = OVERWORLD_ROUTE_TOOLTIP_SMOKE_SCENE_PATH.read_text(encoding="utf-8")
    ensure(
        'path="res://tests/overworld_route_tooltip_smoke.gd"' in route_scene_text,
        errors,
        "Overworld route tooltip smoke scene must remain wired to its focused script",
    )
    incremental_scene_text = OVERWORLD_INCREMENTAL_ROUTE_PREVIEW_REFRESH_REGRESSION_SCENE_PATH.read_text(encoding="utf-8")
    ensure(
        'path="res://tests/overworld_incremental_route_preview_refresh_regression.gd"' in incremental_scene_text,
        errors,
        "Incremental route-preview scene must remain wired to its focused script",
    )

    overworld_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    hero_command_text = HERO_COMMAND_RULES_PATH.read_text(encoding="utf-8")
    ensure(
        'const GENERATED_COMPACT_MAP_CUE_TOOLTIP := "Map art and controls are loaded; save summary and detailed rails are deferred off routine generated-map frames."' in overworld_text,
        errors,
        "Overworld MapCue refresh must retain the exact generated compact tooltip policy constant",
    )
    cue_helper_match = re.search(
        r"func _refresh_map_cue_surface\(\) -> void:\n(?P<body>.*?)(?=\nfunc _refresh_selected_route_readiness_surfaces)",
        overworld_text,
        re.S,
    )
    ensure(cue_helper_match is not None, errors, "Could not isolate the focused Overworld MapCue refresh helper")
    if cue_helper_match is not None:
        cue_body = cue_helper_match.group("body")
        for required_token in (
            "if _generated_initial_open_pending():",
            "return",
            "_map_cue_label.text = _map_cue_text()",
            "if _use_generated_compact_refresh():",
            "_map_cue_label.tooltip_text = GENERATED_COMPACT_MAP_CUE_TOOLTIP",
            "_map_cue_label.tooltip_text = _map_cue_tooltip()",
        ):
            ensure(required_token in cue_body, errors, f"Focused MapCue helper is missing exact policy token: {required_token}")
        ensure(
            cue_body.count("_map_cue_label.text = _map_cue_text()") == 1
            and cue_body.count("_map_cue_label.tooltip_text = GENERATED_COMPACT_MAP_CUE_TOOLTIP") == 1
            and cue_body.count("_map_cue_label.tooltip_text = _map_cue_tooltip()") == 1,
            errors,
            "Focused MapCue helper must assign current text and each normal/compact tooltip exactly once",
        )
        pending_index = cue_body.find("if _generated_initial_open_pending():")
        text_index = cue_body.find("_map_cue_label.text = _map_cue_text()")
        compact_index = cue_body.find("if _use_generated_compact_refresh():")
        compact_tooltip_index = cue_body.find("_map_cue_label.tooltip_text = GENERATED_COMPACT_MAP_CUE_TOOLTIP")
        normal_tooltip_index = cue_body.find("_map_cue_label.tooltip_text = _map_cue_tooltip()")
        ensure(
            0 <= pending_index < text_index < compact_index < compact_tooltip_index < normal_tooltip_index,
            errors,
            "Focused MapCue helper must hold pending state, then update text, then choose compact or current tooltip in order",
        )

    route_readiness_match = re.search(
        r"func _refresh_selected_route_readiness_surfaces\(\) -> void:\n(?P<body>.*?)(?=\nfunc _refresh_context_tile_surface)",
        overworld_text,
        re.S,
    )
    ensure(route_readiness_match is not None, errors, "Could not isolate selected-route rendered-readiness helper")
    if route_readiness_match is not None:
        route_readiness_body = route_readiness_match.group("body")
        generated_guard = "if _generated_initial_open_pending() or _use_generated_compact_refresh():"
        generated_guard_index = route_readiness_body.find(generated_guard)
        generated_return_index = route_readiness_body.find("\n\t\treturn", generated_guard_index)
        readiness_index = route_readiness_body.find("var readiness_surface := _field_readiness_surface()")
        objective_index = route_readiness_body.find("_objective_brief_label.tooltip_text = _join_tooltip_sections([", readiness_index)
        event_gate = "if _field_feed_is_idle() and _action_feedback.is_empty():"
        event_gate_index = route_readiness_body.find(event_gate, objective_index)
        event_source_index = route_readiness_body.find("var event_surface := OverworldRules.describe_event_feed_surface(", event_gate_index)
        event_readiness_index = route_readiness_body.find('event_surface["field_readiness"] = readiness_surface', event_source_index)
        event_context_index = route_readiness_body.find("var action_context_surface := _action_context_surface(event_surface, readiness_surface)", event_readiness_index)
        event_render_index = route_readiness_body.find("_set_rail_text(", event_context_index)
        end_turn_index = route_readiness_body.find("var end_turn_check := _end_turn_confirmation_surface(readiness_surface)", event_render_index)
        drawer_index = route_readiness_body.find("_refresh_drawer_handoff_cues(readiness_surface)", end_turn_index)
        ensure(
            route_readiness_body.count("_field_readiness_surface()") == 1
            and -1 < generated_guard_index < generated_return_index < readiness_index < objective_index
            < event_gate_index < event_source_index < event_readiness_index < event_context_index < event_render_index
            < end_turn_index < drawer_index,
            errors,
            "Selected-route readiness must return for generated policies, compute readiness once, refresh Objective/Event/EndTurn/drawer in exact order, and gate Event behind idle plus empty feedback",
        )
        for required_token in (
            "OverworldRules.describe_objective_stakes_board(_session)",
            'String(readiness_surface.get("tooltip_text", ""))',
            "_last_message",
            "_last_turn_resolution_text",
            "_last_enemy_activity_text",
            "_last_enemy_activity_events",
            "_last_action_recap",
            'String(action_context_surface.get("tooltip_text", ""))',
            'String(action_context_surface.get("visible_text", _rail_log_text()))',
            '_end_turn_button.text = String(end_turn_check.get("button_text", "End Turn"))',
            'var end_turn_tooltip := String(end_turn_check.get("tooltip_text", "")).strip_edges()',
            "if end_turn_tooltip != \"\":",
            "_end_turn_button.tooltip_text = end_turn_tooltip",
        ):
            ensure(required_token in route_readiness_body, errors, f"Selected-route readiness helper is missing exact surface token: {required_token}")
        for forbidden_token in (
            "_refresh_status_surfaces(",
            "_refresh_tooltip_context_drawer_surfaces(",
            "_refresh_action_rails(",
            "_refresh_save_surface(",
            "_selected_route_decision_surface(",
            "_selected_route_destination_actions(",
            "_current_primary_action(",
            "_build_path(",
            "OverworldRules.route_",
        ):
            ensure(forbidden_token not in route_readiness_body, errors, f"Selected-route readiness helper must not broaden or recompute through {forbidden_token}")

    status_match = re.search(
        r"func _refresh_status_surfaces\(generated_surface_start: int, preloaded_refresh_watch_context: Dictionary = \{\}\) -> bool:\n(?P<body>.*?)(?=\nfunc _refresh_map_cue_surface)",
        overworld_text,
        re.S,
    )
    ensure(status_match is not None, errors, "Could not isolate full Overworld status refresh for shared MapCue ownership")
    if status_match is not None:
        status_body = status_match.group("body")
        ensure(
            status_body.count("_refresh_map_cue_surface()") == 1,
            errors,
            "Normal full status refresh must use the shared MapCue helper exactly once",
        )
        ensure(
            "_map_cue_label.text = _map_cue_text()" not in status_body
            and "_map_cue_label.tooltip_text = _map_cue_tooltip()" not in status_body,
            errors,
            "Normal full status refresh must not duplicate direct MapCue assignments outside the shared helper",
        )

    refresh_match = re.search(
        r"func _refresh_with_request\(request: Dictionary\) -> void:\n(?P<body>.*?)(?=\nfunc _sync_overworld_ambient_audio)",
        overworld_text,
        re.S,
    )
    ensure(refresh_match is not None, errors, "Could not isolate incremental Overworld refresh ordering")
    if refresh_match is not None:
        refresh_body = refresh_match.group("body")
        action_index = refresh_body.find("_refresh_selected_route_action_surface()")
        readiness_index = refresh_body.find("_refresh_selected_route_readiness_surfaces()")
        cue_index = refresh_body.find("_refresh_map_cue_surface()")
        context_index = refresh_body.find("_refresh_context_tile_surface()")
        ensure(
            refresh_body.count("_refresh_selected_route_readiness_surfaces()") == 1
            and 0 <= action_index < readiness_index < cue_index < context_index,
            errors,
            "Incremental route refresh must update cached action, rendered readiness, MapCue, then context tile exactly once in order",
        )
        route_cue_branch_match = re.search(
            r"elif _refresh_request_has_phase\(request, REFRESH_PHASE_CONTEXT_ROUTE\):\n\s*_refresh_selected_route_readiness_surfaces\(\)\n\s*_refresh_map_cue_surface\(\)\n(?P<body>.*?)(?=\n\s*OverworldRules.end_normalized_read_scope)",
            refresh_body,
            re.S,
        )
        ensure(route_cue_branch_match is not None, errors, "Could not isolate the route-only MapCue/context branch")
        if route_cue_branch_match is not None:
            route_cue_body = route_cue_branch_match.group("body")
            ensure("_refresh_context_tile_surface()" in route_cue_body, errors, "Route-only MapCue branch must retain the targeted context-tile refresh")
            for forbidden_token in (
                "_refresh_status_surfaces(",
                "_refresh_tooltip_context_drawer_surfaces(",
                "_refresh_action_rails(",
                "_refresh_save_surface(",
            ):
                ensure(forbidden_token not in route_cue_body, errors, f"Route-only MapCue branch must not broaden into {forbidden_token}")

    route_preview_match = re.search(
        r"func _refresh_selected_route_preview\(reason: String = \"selected_route_preview\"\) -> void:\n(?P<body>.*?)(?=\nfunc _refresh_with_request)",
        overworld_text,
        re.S,
    )
    ensure(route_preview_match is not None, errors, "Could not isolate the selected-route preview request")
    if route_preview_match is not None:
        route_preview_body = route_preview_match.group("body")
        ensure("REFRESH_PHASE_MAP_VIEW" in route_preview_body and "REFRESH_PHASE_CONTEXT_ROUTE" in route_preview_body, errors, "Selected-route preview must retain only its map and route phases")
        ensure(
            "true,\n\t\tfalse" in route_preview_body and "_refresh()" not in route_preview_body,
            errors,
            "Selected-route preview must remain one non-full targeted request without falling back to full refresh",
        )
        for forbidden_phase in (
            "REFRESH_PHASE_STATUS_SURFACES",
            "REFRESH_PHASE_ACTION_RAILS",
            "REFRESH_PHASE_SAVE_SURFACE",
        ):
            ensure(forbidden_phase not in route_preview_body, errors, f"Selected-route preview must not broaden into {forbidden_phase}")

    route_action_surface_match = re.search(
        r"func _refresh_selected_route_action_surface\(\) -> void:\n(?P<body>.*?)(?=\nfunc _render_context_action_buttons)",
        overworld_text,
        re.S,
    )
    ensure(route_action_surface_match is not None, errors, "Could not isolate selected-route primary-action ownership")
    if route_action_surface_match is not None:
        route_action_surface_body = route_action_surface_match.group("body")
        ensure(
            "var primary_action := _first_enabled_action(actions)" in route_action_surface_body
            and '_refresh_cache["primary_action"] = primary_action' in route_action_surface_body
            and "_refresh_primary_action_button(primary_action)" in route_action_surface_body,
            errors,
            "Selected-route surface must keep disabled current-tile actions out of primary ownership before refreshing the button",
        )
        ensure(
            '_validation_profile["last_route_destination_only_action_path"] = profile_payload' in route_action_surface_body,
            errors,
            "Incremental route-action ownership must retain its destination-only profile payload while the cache regression uses detached live action state",
        )

    primary_button_match = re.search(
        r"func _refresh_primary_action_button\(action: Dictionary\) -> void:\n(?P<body>.*?)(?=\nfunc _activate_primary_action)",
        overworld_text,
        re.S,
    )
    ensure(primary_button_match is not None, errors, "Could not isolate empty primary-action button behavior")
    if primary_button_match is not None:
        primary_button_body = primary_button_match.group("body")
        ensure(
            'if action.is_empty():\n\t\t_primary_action_button.text = "Select Site"\n\t\t_primary_action_button.disabled = true' in primary_button_body
            and "var simple_route_tooltip := _selected_route_simple_tooltip()" in primary_button_body
            and "_primary_action_button.tooltip_text = simple_route_tooltip" in primary_button_body,
            errors,
            "Empty current-tile primary action must retain disabled Select Site with the source-owned simple-route tooltip",
        )
        ensure(
            "var route_decision := _selected_route_decision_surface()" in primary_button_body
            and "var route_tooltip := _route_decision_tooltip(route_decision)" in primary_button_body
            and '_primary_action_button.tooltip_text = route_tooltip if route_tooltip != "" else "Select a visible destination or stand on a site to reveal its primary order."' in primary_button_body,
            errors,
            "Empty primary button must retain the rich route-tooltip fallback used by no-movement destinations",
        )

    route_actions_match = re.search(
        r"func _build_selected_route_destination_actions\(\) -> Array:\n(?P<body>.*?)(?=\nfunc _disabled_route_destination_action)",
        overworld_text,
        re.S,
    )
    ensure(route_actions_match is not None, errors, "Could not isolate selected-route destination action construction")
    if route_actions_match is not None:
        route_actions_body = route_actions_match.group("body")
        ensure(
            'var simple_destination := _selected_route_simple_destination_surface()' in route_actions_body
            and 'if simple_kind == "current":\n\t\t\treturn [_disabled_route_destination_action("hold_position", "Current Position", "The active hero is already on this tile.", simple_decision, simple_destination)]' in route_actions_body,
            errors,
            "Simple current-tile branch must retain its distinct disabled Current Position candidate",
        )
        ensure(
            'var compact_destination := _selected_route_compact_interaction_destination_surface()' in route_actions_body
            and 'var compact_status := String(compact_destination.get("status", ""))' in route_actions_body
            and '"id": "march_selected" if compact_adjacent else "advance_route"' in route_actions_body
            and 'if compact_status == "no_movement":\n\t\t\tcompact_action["disabled"] = true\n\t\treturn [compact_action]' in route_actions_body,
            errors,
            "Compact Wood route must retain its March/Advance candidate, mark no-movement disabled, and return that candidate",
        )

    first_enabled_match = re.search(
        r"func _first_enabled_action\(actions: Array\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc _promote_selected_owned_town_action)",
        overworld_text,
        re.S,
    )
    ensure(first_enabled_match is not None, errors, "Could not isolate selected-route first-enabled action ownership")
    if first_enabled_match is not None:
        first_enabled_body = first_enabled_match.group("body")
        empty_id_guard = 'if String(action.get("id", "")) == "":\n\t\t\tcontinue'
        non_disabled_guard = 'if not bool(action.get("disabled", false)):\n\t\t\treturn action'
        empty_id_index = first_enabled_body.find(empty_id_guard)
        non_disabled_index = first_enabled_body.find(non_disabled_guard)
        return_action_index = first_enabled_body.find("return action", non_disabled_index)
        final_empty_index = first_enabled_body.rfind("return {}")
        ensure(
            -1 < empty_id_index < non_disabled_index < return_action_index < final_empty_index
            and first_enabled_body.count(empty_id_guard) == 1
            and first_enabled_body.count(non_disabled_guard) == 1
            and first_enabled_body.count("return action") == 1
            and first_enabled_body.count("return {}") == 1,
            errors,
            "First-enabled ownership must continue past empty IDs, return only a non-disabled action, and otherwise return an empty primary",
        )

    current_context_match = re.search(
        r"func _current_context_actions\(\) -> Array:\n(?P<body>.*?)(?=\nfunc _build_selected_route_context_actions)",
        overworld_text,
        re.S,
    )
    ensure(current_context_match is not None, errors, "Could not isolate current-context owned-town promotion")
    if current_context_match is not None:
        current_context_body = current_context_match.group("body")
        selected_equals_hero_index = current_context_body.find("if _selected_tile == OverworldRules.hero_position(_session):")
        context_actions_index = current_context_body.find("actions = OverworldRules.get_context_actions(_session)", selected_equals_hero_index)
        promote_town_index = current_context_body.find("actions = _promote_selected_owned_town_action(actions)", context_actions_index)
        ensure(
            -1 < selected_equals_hero_index < context_actions_index < promote_town_index,
            errors,
            "Selected tile equal to active hero must build current context actions and then promote the owned-town action",
        )

    selected_owned_town_match = re.search(
        r"func _selected_owned_town_visit_action\(\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc _is_selected_owned_town_visit_target)",
        overworld_text,
        re.S,
    )
    ensure(selected_owned_town_match is not None, errors, "Could not isolate selected owned-town Visit Town action")
    if selected_owned_town_match is not None:
        selected_owned_town_body = selected_owned_town_match.group("body")
        ensure(
            "if not _is_selected_owned_town_visit_target():\n\t\treturn {}" in selected_owned_town_body
            and "var handoff := _town_entry_handoff_surface()" in selected_owned_town_body
            and '"id": "visit_town"' in selected_owned_town_body
            and '"label": "Visit Town"' in selected_owned_town_body
            and '"town_entry_handoff": handoff' in selected_owned_town_body,
            errors,
            "Selected owned-town action must remain exact Visit Town with its nonempty handoff payload",
        )

    owned_town_target_match = re.search(
        r"func _is_selected_owned_town_visit_target\(\) -> bool:\n(?P<body>.*?)(?=\nfunc _town_entry_handoff_surface)",
        overworld_text,
        re.S,
    )
    ensure(owned_town_target_match is not None, errors, "Could not isolate owned-town Visit target authority")
    if owned_town_target_match is not None:
        owned_town_target_body = owned_town_target_match.group("body")
        ensure(
            "if not _tile_in_bounds(_selected_tile):" in owned_town_target_body
            and "if not OverworldRules.is_tile_explored(_session, _selected_tile.x, _selected_tile.y):" in owned_town_target_body
            and "var town := _town_at(_selected_tile.x, _selected_tile.y)" in owned_town_target_body
            and 'return not town.is_empty() and String(town.get("owner", "neutral")) == "player"' in owned_town_target_body,
            errors,
            "Visit Town promotion must remain bounded to explored player-owned selected towns",
        )

    field_readiness_match = re.search(
        r"func _field_readiness_context\((?P<signature>.*?)\n\) -> Dictionary:\n(?P<body>.*?)(?=\nfunc _field_readiness_surface)",
        overworld_text,
        re.S,
    )
    ensure(field_readiness_match is not None, errors, "Could not isolate full field-readiness context ownership")
    if field_readiness_match is not None:
        field_readiness_body = field_readiness_match.group("body")
        simple_destination_index = field_readiness_body.find("var simple_destination := _selected_route_simple_destination_surface()")
        owned_town_guard = "if not simple_destination.is_empty() and not _is_selected_owned_town_visit_target():"
        owned_town_guard_index = field_readiness_body.find(owned_town_guard)
        simple_return_index = field_readiness_body.find('"simple_destination": simple_destination.duplicate(true)', owned_town_guard_index)
        compact_destination_index = field_readiness_body.find("var compact_interaction_destination := _selected_route_compact_interaction_destination_surface()", simple_return_index)
        compact_owned_town_guard = "if not compact_interaction_destination.is_empty() and not _is_selected_owned_town_visit_target():"
        compact_owned_town_guard_index = field_readiness_body.find(compact_owned_town_guard, compact_destination_index)
        compact_return_index = field_readiness_body.find('"simple_destination": compact_interaction_destination.duplicate(true)', compact_owned_town_guard_index)
        primary_action_index = field_readiness_body.find("var primary_action := _current_primary_action()", compact_return_index)
