def validate_battle_sidebar_tactical_card_height_cap(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    controller_path = ROOT / "tests" / "battle_controller_board_navigation_smoke.gd"
    visual_path = ROOT / "tests" / "ui_runtime_skin_visual_report.gd"
    for path in (BATTLE_SCENE_PATH, controller_path, visual_path):
        ensure(path.exists(), errors, f"Missing Battle sidebar tactical-card owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (BATTLE_SCENE_PATH, controller_path, visual_path)):
        return

    scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    controller_text = controller_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    tabs_match = re.search(
        r'\[node name="BattleTabs" type="TabContainer"[^\n]*\]\n(?P<body>.*?)(?=\n\[node name="InitiativePanel")',
        scene_text,
        re.S,
    )
    ensure(tabs_match is not None, errors, "Could not isolate the authored BattleTabs tactical-card node")
    if tabs_match is not None:
        tabs_body = tabs_match.group("body")
        ensure(tabs_body.count("custom_minimum_size = Vector2(0, 248)") == 1, errors, "BattleTabs must own one exact 248px tactical-card minimum")
        ensure(tabs_body.count("size_flags_horizontal = 3") == 1 and tabs_body.count("size_flags_vertical = 1") == 1, errors, "BattleTabs must fill horizontally without vertically expanding through the sidebar")
        ensure("size_flags_vertical = 3" not in tabs_body, errors, "BattleTabs must not retain the full-height vertical expand flag")
        for forbidden in ("visible = false", "clip_contents", "position =", "offset_", "anchor_", "grow_", "script ="):
            ensure(forbidden not in tabs_body, errors, f"BattleTabs height cap must remain one container-owned sizing policy without {forbidden}")

    controller = gd_function_block(controller_text, "_validate_battle_focus_spell_tab_body_fit")
    ensure(controller, errors, "Could not isolate focused Battle tactical-card geometry owner")
    if controller:
        controller_order = tuple(controller.find(token) for token in (
            '_battle_background_authority(session)',
            'shell.get_node("%SidebarShell")',
            'shell.get_node("%CommandPanel")',
            'shell.get_node("%BattleTabs")',
            "tabs.custom_minimum_size.y, 248.0",
            "tabs.size_flags_vertical != Control.SIZE_FILL",
            "tabs.current_tab = 0",
            "var contained_tabs_height := tabs.size.y",
            "if sidebar_shell.is_visible_in_tree():",
            "var remaining_rail_gutter := sidebar_rect.end.y - tabs_rect.end.y",
            "not is_equal_approx(contained_tabs_height, 248.0)",
            "not sidebar_rect.encloses(command_rect)",
            "not sidebar_rect.encloses(tabs_rect)",
            "command_rect.intersects(tabs_rect)",
            "remaining_rail_gutter < 80.0",
            "elif width >= 1360:",
            "for row_value in rows:",
            "is_equal_approx(tabs.size.y, contained_tabs_height)",
            "tabs.current_tab = initial_tab",
            "_battle_background_authority(session) != authority_before",
        ))
        ensure(all(index >= 0 for index in controller_order) and list(controller_order) == sorted(controller_order), errors, "Focused Battle tactical-card proof must validate authored sizing, wide/compact geometry, stable page height, restore, then whole authority in order")
        for token in (
            'return _fail_bool("Battle wide layout unexpectedly hides the tactical sidebar at requested width %d." % width)',
            "command_rect.end.y > tabs_rect.position.y + 0.01",
            "tabs.get_global_rect().encloses(panel.get_global_rect())",
            "panel.get_global_rect().encloses(label.get_global_rect())",
            "label.get_visible_line_count() == int(line_counts[index])",
        ):
            ensure(token in controller, errors, f"Focused Battle tactical-card proof is missing exact containment/content token: {token}")
        for forbidden in ("custom_minimum_size =", "size_flags_vertical =", "set_deferred", "call_deferred", "create_timer", "await get_tree().create_timer", "queue_sort", "sort(", "erase("):
            ensure(forbidden not in controller, errors, f"Focused Battle tactical-card proof must remain observational and avoid {forbidden}")

    visual_helper = gd_function_block(visual_text, "_battle_sidebar_tactical_card_contract")
    visual_run = gd_function_block(visual_text, "_run_shell")
    ensure(visual_helper and visual_run, errors, "Could not isolate all-size Battle tactical-card visual owner")
    if visual_helper:
        visual_order = tuple(visual_helper.find(token) for token in (
            'shell.get_node_or_null("%SidebarShell")',
            'shell.get_node_or_null("%CommandPanel")',
            'shell.get_node_or_null("%BattleTabs")',
            'shell.get_node_or_null("%TacticalDetails")',
            'shell.get_node_or_null("%Event")',
            'shell.get_node_or_null("%BattleContext")',
            'shell.get_node_or_null("%BattleBoard")',
            'shell.get_node_or_null("%InitiativePanel")',
            'shell.get_node_or_null("%ContextPanel")',
            'shell.get_node_or_null("%SpellPanel")',
            'shell.get_node_or_null("%TimingPanel")',
            "var authority_before: Dictionary = session.to_dict()",
            'var expected_titles := ["Order", "Focus", "Spell", "Timing"]',
            "var compact := viewport_size.x < 1360 or viewport_size.y < 760",
            "var collapsed_board_rect := board.get_global_rect()",
            "var default_field_first_exact := not sidebar_shell.is_visible_in_tree()",
            "details_button.pressed.emit()",
            "for index in range(panels.size()):",
            "titles.append(tabs.get_tab_title(index))",
            "heights.append(tabs.size.y)",
            "pages_contained = pages_contained and tabs.get_global_rect().encloses(panels[index].get_global_rect())",
            "tabs.custom_minimum_size.y, 248.0",
            "tabs.size_flags_vertical == Control.SIZE_FILL",
            "heights.all(func(height): return is_equal_approx(height, 248.0))",
            "remaining_rail_gutter >= 80.0",
            "var compact_geometry_exact := not sidebar_shell.is_visible_in_tree()",
            "tabs.current_tab = original_tab",
            "var restored_board_rect := board.get_global_rect()",
            "var restored_field_first_exact := not sidebar_shell.is_visible_in_tree()",
            "var authority_exact := session.to_dict() == authority_before",
        ))
        ensure(all(index >= 0 for index in visual_order) and list(visual_order) == sorted(visual_order), errors, "All-size Battle tactical-card proof must traverse all native pages, inspect wide/compact geometry, restore selection, then verify authority")
        for token in (
            "sidebar_rect.encloses(command_rect)",
            "sidebar_rect.encloses(tabs_rect)",
            "command_rect.end.y <= tabs_rect.position.y + 0.01",
            "not command_rect.intersects(tabs_rect)",
            "and titles == expected_titles",
            "compact_geometry_exact if compact else wide_geometry_exact",
        ):
            ensure(token in visual_helper, errors, f"All-size Battle tactical-card proof is missing exact native geometry/title token: {token}")
        for forbidden in ("custom_minimum_size =", "tabs.size_flags_vertical = Control.SIZE", "set_deferred", "call_deferred", "create_timer", "await get_tree().create_timer", "minimum_size_changed", "queue_sort", "sort(", "erase("):
            ensure(forbidden not in visual_helper, errors, f"All-size Battle tactical-card proof must remain passive and avoid {forbidden}")
    if visual_run:
        visual_run_order = tuple(visual_run.find(token) for token in (
            "var sidebar_contract := await _battle_sidebar_tactical_card_contract(shell, viewport_size)",
            'shell_report["battle_sidebar_tactical_card"] = sidebar_contract',
            'if not bool(sidebar_contract.get("ok", false)):',
            "var screenshot_size := await _save_screenshot(render_viewport, screenshot_path)",
        ))
        ensure(all(index >= 0 for index in visual_run_order) and list(visual_run_order) == sorted(visual_run_order), errors, "Battle tactical-card all-size contract must pass before every captured screenshot")


def validate_battle_sidebar_heraldic_watermark(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    asset_path = ROOT / "art" / "ui" / "runtime" / "battle" / "sidebar_heraldic_watermark.png"
    controller_path = ROOT / "tests" / "battle_controller_board_navigation_smoke.gd"
    for path in (asset_path, BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, controller_path):
        ensure(path.exists(), errors, f"Missing Battle sidebar watermark owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (asset_path, BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, controller_path)):
        return

    asset_bytes = asset_path.read_bytes()
    ensure(png_size(asset_path) == (512, 512), errors, "Battle sidebar heraldic watermark must remain an exact 512x512 PNG")
    ensure(len(asset_bytes) > 25 and asset_bytes[:8] == b"\x89PNG\r\n\x1a\n" and asset_bytes[25] == 6, errors, "Battle sidebar heraldic watermark must retain its RGBA transparency")

    scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    script_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    controller_text = controller_path.read_text(encoding="utf-8")
    resource_token = '[ext_resource type="Texture2D" path="res://art/ui/runtime/battle/sidebar_heraldic_watermark.png" id="7_sidebar_watermark"]'
    ensure(scene_text.count(resource_token) == 1, errors, "BattleShell must import exactly one authored sidebar heraldic watermark texture")
    watermark_node = scene_node_block(scene_text, "SidebarWatermark", "TextureRect")
    ensure(watermark_node, errors, "BattleShell must author one SidebarWatermark TextureRect")
    if watermark_node:
        ensure(scene_node_parent(scene_text, "SidebarWatermark", "TextureRect") == "ContentMargin/Content/MainRow/SidebarShell/SidebarPad/SidebarBox", errors, "Battle sidebar watermark must remain inside the existing flexible SidebarBox negative-space owner")
        for token in (
            "unique_name_in_owner = true",
            "visible = false",
            "layout_mode = 2",
            "size_flags_vertical = 3",
            "mouse_filter = 2",
            "self_modulate = Color(0.82, 0.72, 0.52, 0.20)",
            'texture = ExtResource("7_sidebar_watermark")',
            "expand_mode = 1",
            "stretch_mode = 5",
        ):
            ensure(watermark_node.count(token) == 1, errors, f"Battle sidebar watermark is missing exact passive presentation token: {token}")
        for forbidden in ("custom_minimum_size", "offset_", "anchor_", "grow_", "script =", "text =", "tooltip_text", "focus_mode", "clip_contents"):
            ensure(forbidden not in watermark_node, errors, f"Battle sidebar watermark must not add layout, focus, text, or behavior through {forbidden}")
    watermark_index = scene_text.find('[node name="SidebarWatermark" type="TextureRect"')
    tabs_index = scene_text.find('[node name="BattleTabs" type="TabContainer"')
    footer_index = scene_text.find('[node name="Footer" type="PanelContainer" parent="ContentMargin/Content"]')
    ensure(0 <= tabs_index < watermark_index < footer_index, errors, "Battle sidebar watermark must remain the final flexible SidebarBox child after BattleTabs and before the existing Footer")

    ensure(script_text.count("const BATTLE_SIDEBAR_WATERMARK_MIN_ROOT_HEIGHT := 1000.0") == 1, errors, "BattleShell must own one exact tall-rail watermark threshold")
    ensure(script_text.count("@onready var _sidebar_watermark: TextureRect = %SidebarWatermark") == 1, errors, "BattleShell must bind the authored watermark exactly once")
    responsive = gd_function_block(script_text, "_apply_responsive_layout")
    ensure(responsive, errors, "Could not isolate BattleShell responsive layout for watermark validation")
    if responsive:
        responsive_order = tuple(responsive.find(token) for token in (
            "var available_size := size",
            "var compact_layout := available_size.x < 1360.0 or available_size.y < 760.0",
            "var tactical_details_visible := not compact_layout and _tactical_details_expanded",
            "_sidebar_shell_panel.visible = tactical_details_visible",
            "_sidebar_watermark.visible = tactical_details_visible and available_size.y >= BATTLE_SIDEBAR_WATERMARK_MIN_ROOT_HEIGHT",
            "_battle_context_label.visible = tactical_details_visible",
        ))
        ensure(all(index >= 0 for index in responsive_order) and list(responsive_order) == sorted(responsive_order), errors, "BattleShell must derive watermark visibility from the existing logical responsive layout after sidebar visibility")
        ensure(responsive.count("_sidebar_watermark.visible =") == 1, errors, "BattleShell responsive layout must own exactly one watermark visibility assignment")
        for forbidden in ("get_window()", "DisplayServer", "_sidebar_watermark.custom_minimum_size", "_sidebar_watermark.size_flags_", "_sidebar_watermark.texture =", "_sidebar_watermark.self_modulate =", "queue_sort", "call_deferred", "create_timer"):
            ensure(forbidden not in responsive, errors, f"Battle watermark responsive policy must not mutate layout/art/timing through {forbidden}")

    run_block = gd_function_block(controller_text, "_run")
    focused = gd_function_block(controller_text, "_validate_battle_sidebar_watermark_responsiveness")
    ensure(run_block and focused, errors, "Battle controller smoke must own the focused sidebar watermark runtime proof")
    if run_block:
        watermark_call = run_block.find("if not await _validate_battle_sidebar_watermark_responsiveness():")
        width_loop = run_block.find("for width in [1280, 1920]:")
        ensure(0 <= watermark_call < width_loop and run_block.count("_validate_battle_sidebar_watermark_responsiveness()") == 1, errors, "Battle watermark proof must run exactly once before existing board input fixtures")
    if focused:
        focused_order = tuple(focused.find(token) for token in (
            "var frame := Control.new()",
            'frame.name = "BattleSidebarWatermarkFrame"',
            "frame.size = Vector2(1920.0, 1080.0)",
            "frame.add_child(shell)",
            "await _settle()",
            "var authority_before := _battle_background_authority(session)",
            'var watermark: TextureRect = shell.get_node("%SidebarWatermark")',
            "var watermark_texture: Texture2D = watermark.texture",
            "var watermark_image: Image = watermark_texture.get_image() if watermark_texture != null else null",
            "watermark_image.get_format() != Image.FORMAT_RGBA8",
            "not is_zero_approx(watermark_image.get_pixel(0, 0).a)",
            "watermark_image.get_pixel(256, 256).a < 0.95",
            "for viewport_size in [Vector2i(1280, 720), Vector2i(1600, 900), Vector2i(1920, 1080), Vector2i(2560, 1440)]:",
            "frame.size = Vector2(viewport_size)",
            "var wide_layout: bool = viewport_size.x >= 1360 and viewport_size.y >= 760",
            "var collapsed_board_rect := board.get_global_rect()",
            "details_button.pressed.emit()",
            "var expected_sidebar_visible := wide_layout",
            "var expected_watermark_visible: bool = wide_layout and viewport_size.y >= 1000",
            "sidebar.visible != expected_sidebar_visible or watermark.visible != expected_watermark_visible",
            "tabs.size.y, 248.0",
            "var watermark_rect := watermark.get_global_rect()",
            "not sidebar_rect.encloses(watermark_rect)",
            "watermark_rect.intersects(command_rect)",
            "watermark_rect.intersects(tabs_rect)",
            'details_button.text != "Tactical Details"',
            "board.get_global_rect().is_equal_approx(collapsed_board_rect)",
            "_battle_background_authority(session) != authority_before",
        ))
        ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused Battle watermark proof must validate authority, real asset alpha, four logical sizes, containment, and cleanup in order")
        ensure(focused.rfind("frame.queue_free()") > focused_order[-1], errors, "Focused Battle watermark proof must free its whole logical host after the final authority gate")
        for token in (
            'watermark_texture.resource_path != "res://art/ui/runtime/battle/sidebar_heraldic_watermark.png"',
            "Vector2i(watermark_texture.get_size()) != Vector2i(512, 512)",
            "watermark.custom_minimum_size != Vector2.ZERO",
            "watermark.size_flags_vertical != Control.SIZE_EXPAND_FILL",
            "watermark.mouse_filter != Control.MOUSE_FILTER_IGNORE",
            "watermark.focus_mode != Control.FOCUS_NONE",
            "watermark.expand_mode != TextureRect.EXPAND_IGNORE_SIZE",
            "watermark.stretch_mode != TextureRect.STRETCH_KEEP_ASPECT_CENTERED",
            "not is_equal_approx(watermark.self_modulate.a, 0.20)",
            "watermark.size.x <= 0.0 or watermark.size.y <= 0.0",
            "watermark_rect.position.y + 0.01 < tabs_rect.end.y",
        ):
            ensure(token in focused, errors, f"Focused Battle watermark proof is missing exact passive asset/geometry token: {token}")
        for forbidden in ("get_window().size = viewport_size", "watermark.visible =", "watermark.texture =", "watermark.self_modulate =", "custom_minimum_size =", "size_flags_vertical =", "grab_focus", "Input.", "push_input", "create_timer", "sort(", "erase("):
            ensure(forbidden not in focused, errors, f"Focused Battle watermark proof must remain observational and avoid {forbidden}")


def validate_battle_field_first_tactical_disclosure(errors: list[str]) -> None:
    def gd_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    controller_path = ROOT / "tests" / "battle_controller_board_navigation_smoke.gd"
    visual_path = ROOT / "tests" / "ui_runtime_skin_visual_report.gd"
    for path in (BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, controller_path, visual_path):
        ensure(path.exists(), errors, f"Missing Battle field-first disclosure owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, controller_path, visual_path)):
        return

    shell_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    controller_text = controller_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    layout_text = (ROOT / "tests" / "battle_layout_smoke.gd").read_text(encoding="utf-8")
    button = scene_node_block(scene_text, "TacticalDetails", "Button")
    ensure(scene_text.count('[node name="TacticalDetails" type="Button"') == 1 and button, errors, "BattleShell must author exactly one TacticalDetails button")
    if button:
        ensure(scene_node_parent(scene_text, "TacticalDetails", "Button") == "ContentMargin/Content/Banner/BannerPad/BannerBox/TopBar/Header", errors, "Battle TacticalDetails must remain overlaid in the existing Header allocation without growing the TopBar minimum")
        for token in (
            "unique_name_in_owner = true",
            "visible = false",
            "layout_mode = 1",
            "anchors_preset = 1",
            "anchor_left = 1.0",
            "anchor_right = 1.0",
            "offset_left = -124.0",
            "offset_bottom = 30.0",
            "grow_horizontal = 0",
            "focus_mode = 2",
            "clip_text = true",
            'text = "Tactical Details"',
            'accessibility_name = "Tactical details"',
        ):
            ensure(button.count(token) == 1, errors, f"Battle TacticalDetails is missing exact authored token: {token}")
        for forbidden in ("script =", "shortcut =", "button_pressed", "toggle_mode", "disabled = true"):
            ensure(forbidden not in button, errors, f"Battle TacticalDetails must remain one ordinary explicit action without {forbidden}")

    for token in (
        "@onready var _tactical_details_button: Button = %TacticalDetails",
        "var _tactical_details_expanded := false",
        "_tactical_details_button.pressed.connect(_on_tactical_details_pressed)",
        "_style_action_button(_tactical_details_button, false, 124)",
        "_tactical_details_button.custom_minimum_size = Vector2.ZERO",
    ):
        ensure(shell_text.count(token) == 1, errors, f"Battle tactical disclosure lifecycle is missing exact token: {token}")
    focus_cycle = gd_block(shell_text, "_configure_battle_keyboard_focus")
    ensure(focus_cycle.count("_tactical_details_button,") == 1, errors, "Battle TacticalDetails must appear exactly once in the normal keyboard/controller focus cycle")
    responsive = gd_block(shell_text, "_apply_responsive_layout")
    for token in (
        "var tactical_details_visible := not compact_layout and _tactical_details_expanded",
        "_tactical_details_button.visible = not compact_layout",
        "_sidebar_shell_panel.visible = tactical_details_visible",
        "_sidebar_watermark.visible = tactical_details_visible and available_size.y >= BATTLE_SIDEBAR_WATERMARK_MIN_ROOT_HEIGHT",
        "_battle_context_label.visible = tactical_details_visible",
        "_event_label.visible = tactical_details_visible",
        "_sync_tactical_details_button()",
    ):
        ensure(responsive.count(token) == 1, errors, f"Battle field-first responsive layout is missing exact token: {token}")
    for forbidden in ("queue_free", "reparent", "remove_child", "BattleRules", "SessionState", "SaveService", "AppRouter", "create_timer"):
        ensure(forbidden not in responsive, errors, f"Battle disclosure must remain presentation-only and avoid {forbidden}")
    pressed = gd_block(shell_text, "_on_tactical_details_pressed")
    sync = gd_block(shell_text, "_sync_tactical_details_button")
    for token in (
        "if _compact_layout_active:",
        "_tactical_details_expanded = not _tactical_details_expanded",
        "_apply_responsive_layout()",
        "_tactical_details_button.grab_focus()",
        'call_deferred("_configure_battle_keyboard_focus", false)',
    ):
        ensure(pressed.count(token) == 1, errors, f"Battle tactical disclosure press handler is missing exact token: {token}")
    for token in (
        '"Hide Details" if _tactical_details_expanded else "Tactical Details"',
        '"%s the full tactical report and battle detail rail." % action',
        "_tactical_details_button.accessibility_name = _tactical_details_button.text",
        "_tactical_details_button.accessibility_description = _tactical_details_button.tooltip_text",
    ):
        ensure(sync.count(token) == 1, errors, f"Battle tactical disclosure semantic sync is missing exact token: {token}")
    for block_name, block in (("pressed", pressed), ("sync", sync)):
        for forbidden in ("BattleRules", "SessionState", "SaveService", "AppRouter", "Input.", "create_timer", "await ", "queue_free", "reparent"):
            ensure(forbidden not in block, errors, f"Battle disclosure {block_name} helper must not change gameplay/authority through {forbidden}")

    focused = gd_block(controller_text, "_validate_battle_sidebar_watermark_responsiveness")
    visual = gd_block(visual_text, "_battle_sidebar_tactical_card_contract")
    for block_name, block in (("focused", focused), ("visual", visual)):
        for token in (
            '"%TacticalDetails"',
            '"%Event"',
            '"%BattleContext"',
            '"%BattleBoard"',
            "details_button.pressed.emit()",
            'details_button.text != "Tactical Details"' if block_name == "focused" else 'details_button.text == "Tactical Details"',
            "is_equal_approx(collapsed_board_rect)",
        ):
            ensure(token in block, errors, f"Battle {block_name} disclosure runtime proof is missing token: {token}")
        for forbidden in ("_on_tactical_details_pressed", "_tactical_details_expanded =", "visible =", "custom_minimum_size =", "BattleRules.perform", "SaveService", "create_timer"):
            ensure(forbidden not in block, errors, f"Battle {block_name} disclosure proof must use the public control without bypass/mutation through {forbidden}")
    for token in (
        'not bool(hex_summary.get("terrain_single_board_backdrop", false))',
        'String(terrain_summary.get("rendering_mode", "")) != "continuous_field_with_hex_variation"',
        'String(terrain_summary.get("texture_sample_mode", "")) != "continuous_field_plus_subordinate_per_hex_variation"',
        'not bool(terrain_summary.get("terrain_context_primary", false))',
        'not bool(terrain_summary.get("terrain_hex_variation_subordinate", false))',
    ):
        ensure(layout_text.count(token) == 1, errors, f"Battle layout compatibility must observe the shipped continuous terrain contract: {token}")
    ensure('"hex_snapped_texture"' not in layout_text, errors, "Battle layout compatibility must not restore the superseded per-cell texture renderer oracle")


def validate_battle_footer_heraldic_watermark(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    for path in (BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, smoke_path):
        ensure(path.exists(), errors, f"Missing Battle footer watermark owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (BATTLE_SCRIPT_PATH, BATTLE_SCENE_PATH, smoke_path)):
        return

    scene_text = BATTLE_SCENE_PATH.read_text(encoding="utf-8")
    script_text = BATTLE_SCRIPT_PATH.read_text(encoding="utf-8")
    smoke_text = smoke_path.read_text(encoding="utf-8")
    resource_token = '[ext_resource type="Texture2D" path="res://art/ui/runtime/battle/sidebar_heraldic_watermark.png" id="7_sidebar_watermark"]'
    ensure(scene_text.count(resource_token) == 1, errors, "Battle footer watermark must reuse the one existing imported heraldic texture")
    footer_node = scene_node_block(scene_text, "FooterWatermark", "TextureRect")
    ensure(scene_text.count('[node name="FooterWatermark" type="TextureRect"') == 1 and footer_node, errors, "BattleShell must author exactly one FooterWatermark TextureRect")
    if footer_node:
        ensure(scene_node_parent(scene_text, "FooterWatermark", "TextureRect") == "ContentMargin/Content/Footer/FooterPad/FooterRow/SystemPanel/SystemPad/SystemBox", errors, "Battle footer watermark must remain in the existing flexible SystemBox rest field")
        for token in (
            "unique_name_in_owner = true",
            "visible = false",
            "layout_mode = 2",
            "size_flags_horizontal = 3",
            "size_flags_vertical = 3",
            "mouse_filter = 2",
            "self_modulate = Color(0.82, 0.72, 0.52, 0.18)",
            'texture = ExtResource("7_sidebar_watermark")',
            "expand_mode = 1",
            "stretch_mode = 5",
        ):
            ensure(footer_node.count(token) == 1, errors, f"Battle footer watermark is missing exact passive scene token: {token}")
        for forbidden in ("custom_minimum_size", "offset_", "anchor_", "grow_", "script =", "text =", "tooltip_text", "focus_mode", "clip_contents"):
            ensure(forbidden not in footer_node, errors, f"Battle footer watermark must not add layout, focus, text, or behavior through {forbidden}")
    menu_index = scene_text.find('[node name="Menu" type="Button" parent="ContentMargin/Content/Footer/FooterPad/FooterRow/SystemPanel/SystemPad/SystemBox/SystemActions"]')
    footer_index = scene_text.find('[node name="FooterWatermark" type="TextureRect"')
    dialog_index = scene_text.find('[node name="QuickResolveConfirmationDialog" type="ConfirmationDialog"')
    ensure(0 <= menu_index < footer_index < dialog_index, errors, "Battle footer watermark must remain the final SystemBox child after all existing System actions")

    ensure(script_text.count("@onready var _footer_watermark: TextureRect = %FooterWatermark") == 1, errors, "BattleShell must bind the footer watermark exactly once")
    responsive = gd_function_block(script_text, "_apply_responsive_layout")
    ensure(responsive, errors, "Could not isolate Battle responsive footer watermark policy")
    if responsive:
        responsive_order = tuple(responsive.find(token) for token in (
            "var horizontal_footer := not compact_layout or available_size.x >= 1180.0",
            "_footer_row.columns = 2 if horizontal_footer else 1",
            "_footer_watermark.visible = horizontal_footer and not FrontierVisualKit.high_contrast_enabled()",
            '_footer_row.add_theme_constant_override("v_separation", 8 if horizontal_footer else 0)',
        ))
        ensure(all(index >= 0 for index in responsive_order) and list(responsive_order) == sorted(responsive_order), errors, "Battle footer watermark visibility must follow the existing horizontal-footer decision before unchanged spacing")
        ensure(responsive.count("_footer_watermark.visible =") == 1, errors, "Battle responsive layout must own exactly one footer-watermark visibility assignment")
        for forbidden in ("_footer_watermark.custom_minimum_size", "_footer_watermark.size_flags_", "_footer_watermark.texture =", "_footer_watermark.self_modulate =", "_footer_watermark.tooltip_text", "_footer_watermark.grab_focus", "call_deferred", "create_timer"):
            ensure(forbidden not in responsive, errors, f"Battle footer watermark policy must not mutate layout, art, focus, text, or timing through {forbidden}")

    focused = gd_function_block(smoke_text, "_assert_battle_system_frame_roundtrip")
    ensure(focused, errors, "Could not isolate focused Battle System/footer roundtrip proof")
    if focused:
        focused_order = tuple(focused.find(token) for token in (
            'var footer_row := shell.get_node_or_null("%FooterRow") as GridContainer',
            'var footer_watermark := shell.get_node_or_null("%FooterWatermark") as TextureRect',
            'var sidebar_watermark := shell.get_node_or_null("%SidebarWatermark") as TextureRect',
            "footer_watermark.texture != sidebar_watermark.texture",
            'footer_watermark.texture.resource_path != "res://art/ui/runtime/battle/sidebar_heraldic_watermark.png"',
            "footer_watermark.custom_minimum_size != Vector2.ZERO",
            "footer_watermark.size_flags_horizontal != Control.SIZE_EXPAND_FILL",
            "footer_watermark.size_flags_vertical != Control.SIZE_EXPAND_FILL",
            "footer_watermark.mouse_filter != Control.MOUSE_FILTER_IGNORE",
            "footer_watermark.focus_mode != Control.FOCUS_NONE",
            "not is_equal_approx(footer_watermark.self_modulate.a, 0.18)",
            "window.size = Vector2i(1280, 720)",
            "not compact_system_box_rect.encloses(compact_watermark_rect)",
            "compact_watermark_rect.intersects(compact_system_actions_rect)",
            "window.size = Vector2i(1920, 1080)",
            "not wide_system_box_rect.encloses(wide_watermark_rect)",
            "wide_watermark_rect.intersects(wide_system_actions_rect)",
            "FrontierVisualKitScript.set_high_contrast_enabled(true)",
            'shell.call("_apply_responsive_layout")',
            "if footer_watermark.visible:",
            "FrontierVisualKitScript.set_high_contrast_enabled(original_high_contrast)",
            "if not footer_watermark.visible:",
            "window.size = Vector2i(1024, 720)",
            "footer_row.columns != 1 or footer_watermark.visible",
            "footer_row.columns != 2 or not footer_watermark.visible",
            "session.to_dict() != session_before",
        ))
        ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused Battle footer watermark proof must validate shared art, passive properties, two horizontal sizes, high contrast, vertical hiding, roundtrip, and authority in order")
        ensure(focused.count("window.size = Vector2i(1280, 720)") == 2, errors, "Focused Battle footer watermark proof must return to the exact 1280 horizontal layout after its wide, high-contrast, and vertical checks")
        ensure(re.search(r"^\s*footer_watermark\.texture\s*=(?!=)", focused, re.M) is None, errors, "Focused Battle footer watermark proof must not assign its production texture")
        ensure(re.search(r"^\s*footer_watermark\.size_flags_\w+\s*=(?!=)", focused, re.M) is None, errors, "Focused Battle footer watermark proof must not assign production size flags")
        for forbidden in ("footer_watermark.visible =", "footer_watermark.self_modulate =", "footer_watermark.custom_minimum_size =", "footer_watermark.grab_focus", "footer_watermark.tooltip_text ="):
            ensure(forbidden not in focused, errors, f"Focused Battle footer watermark proof must remain observational and avoid {forbidden}")


def validate_town_management_card_height_cap(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    # Task #10221 retires the visible five-page management card. Validate the
    # replacement compact command dock, full-bleed composition, direct dialog
    # routes, and crop-aware faction/stage hotspot through its focused owner.
    report_script_path = ROOT / "tests" / "town_screen_layout_and_dialog_controls_report.gd"
    report_scene_path = ROOT / "tests" / "town_screen_layout_and_dialog_controls_report.tscn"
    stage_path = ROOT / "scenes" / "town" / "TownStageView.gd"
    for path in (TOWN_SCRIPT_PATH, TOWN_SCENE_PATH, stage_path, report_script_path, report_scene_path):
        ensure(path.exists(), errors, f"Missing owner-directed Town layout owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (TOWN_SCRIPT_PATH, TOWN_SCENE_PATH, stage_path, report_script_path, report_scene_path)):
        return

    script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    scene_text = TOWN_SCENE_PATH.read_text(encoding="utf-8")
    stage_text = stage_path.read_text(encoding="utf-8")
    report_text = report_script_path.read_text(encoding="utf-8")
    report_scene_text = report_scene_path.read_text(encoding="utf-8")

    ensure_scene_nodes(report_scene_text, errors, "town_screen_layout_and_dialog_controls_report.tscn", [("TownScreenLayoutAndDialogControlsReport", "Node")])
    management_match = re.search(r'\[node name="ManagementTabs" type="TabContainer"[^\n]*\]\n(?P<body>.*?)(?=\n\[node name="BuildPanel")', scene_text, re.S)
    ensure(scene_text.count('[node name="ManagementTabs" type="TabContainer"') == 1, errors, "Town must retain one legacy backing control for existing action ownership")
    ensure(management_match is not None and "visible = false" in management_match.group("body"), errors, "Legacy Town management tabs must remain hidden from the scenic composition")
    ensure(scene_text.count('[node name="ActionDock" type="PanelContainer"') == 1, errors, "Town must own exactly one compact direct-action dock")
    for action_name in ("BuildAction", "MusterAction", "SpellsAction", "TradeAction", "LogAction"):
        action_match = re.search(rf'\[node name="{action_name}" type="Button"[^\n]*\]\n(?P<body>.*?)(?=\n\[node )', scene_text, re.S)
        ensure(action_match is not None, errors, f"Town compact command is missing: {action_name}")
        if action_match is not None:
            body = action_match.group("body")
            for token in ("unique_name_in_owner = true", "custom_minimum_size = Vector2(44, 44)", "focus_mode = 2", "tooltip_text =", "accessibility_name =", "accessibility_description ="):
                ensure(token in body, errors, f"Town {action_name} is missing accessible compact-control ownership: {token}")
    ensure(scene_text.count('[node name="LogBadge" type="Label"') == 1, errors, "Town Log direct action must retain one readiness-count badge")
    ensure(scene_text.count('[node name="DomainActions" type="VBoxContainer"') == 1, errors, "Town direct dialogs must own one shared authoritative domain-action surface")

    for token in (
        "const TOWN_COMPACT_MANAGEMENT_RAIL_WIDTH := 290.0",
        "const TOWN_HEADER_HEIGHT := 48.0",
        "const TOWN_FOOTER_HEIGHT := 48.0",
        "func _promote_town_edge_overlays() -> void:",
        '_town_stage_view.call("set_external_command_overlay", true)',
        '_town_stage_view.connect("main_building_activated", main_building_callable)',
        "func validation_owner_town_layout_snapshot() -> Dictionary:",
        "func validation_direct_action_controls_snapshot() -> Dictionary:",
        "func validation_activate_direct_action(mode: String) -> Dictionary:",
        "func validation_activate_main_building_hotspot() -> Dictionary:",
    ):
        ensure(token in script_text, errors, f"TownShell owner-directed layout contract is missing: {token}")
    open_catalog = gd_function_block(script_text, "_open_town_catalog")
    for mode, title in (("build", "Construction Ledger"), ("muster", "Muster Hall"), ("spells", "Spell Study"), ("trade", "Town Market"), ("log", "Town Log & Logistics")):
        ensure(f'"{mode}"' in open_catalog and f'"{title}"' in open_catalog, errors, f"Town direct {mode} dialog must retain its authored title and route")

    ensure(stage_text.count("const MAIN_BUILDING_HOTSPOTS := {") == 1, errors, "TownStageView must own one explicit normalized main-building hotspot map")
    for faction_id in ("faction_embercourt", "faction_mireclaw", "faction_sunvault", "faction_thornwake", "faction_brasshollow", "faction_veilmourn"):
        ensure(stage_text.count(f'"{faction_id}":') >= 1, errors, f"Town main-building hotspot metadata is missing faction: {faction_id}")
    for token in ("signal main_building_activated", '"village": Rect2(', '"developing": Rect2(', '"fully_built": Rect2(', "func _sync_main_building_hotspot() -> void:", "func validation_main_building_hotspot_summary() -> Dictionary:"):
        ensure(token in stage_text, errors, f"Town main-building hotspot contract is missing: {token}")

    for token in (
        "const VIEWPORT_SIZES := [Vector2i(2048, 1079), Vector2i(1280, 720)]",
        'const STAGE_IDS := ["village", "developing", "fully_built"]',
        'const DIRECT_MODES := ["build", "muster", "spells", "trade", "log"]',
        'shell.call("validation_owner_town_layout_snapshot")',
        'shell.call("validation_direct_action_controls_snapshot")',
        'shell.call("validation_activate_main_building_hotspot")',
        'shell.call("validation_activate_direct_action", mode)',
        'float(layout.get("header_height_ratio", 1.0)) <= 0.10',
        'float(layout.get("scenic_area_ratio", 0.0)) >= 0.78',
        'not bool(layout.get("legacy_management_tabs_visible", true))',
        'int(row.get("focus_mode", Control.FOCUS_NONE)) == Control.FOCUS_ALL',
        'String(row.get("accessibility_description", "")) != ""',
        'for faction_id_value in FACTION_IDS:',
        'for stage_id_value in STAGE_IDS:',
        'image.save_png(ProjectSettings.globalize_path(capture_path)) == OK',
        'print("TOWN_SCREEN_LAYOUT_AND_DIALOG_CONTROLS_REPORT %s"',
    ):
        ensure(token in report_text, errors, f"Focused owner-directed Town layout report is missing runtime proof: {token}")
    return

    smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    visual_path = ROOT / "tests" / "ui_runtime_skin_visual_report.gd"
    for path in (TOWN_SCRIPT_PATH, TOWN_SCENE_PATH, smoke_path, visual_path):
        ensure(path.exists(), errors, f"Missing Town management-card owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (TOWN_SCRIPT_PATH, TOWN_SCENE_PATH, smoke_path, visual_path)):
        return

    script_text = TOWN_SCRIPT_PATH.read_text(encoding="utf-8")
    scene_text = TOWN_SCENE_PATH.read_text(encoding="utf-8")
    smoke_text = smoke_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    tabs_match = re.search(
        r'\[node name="ManagementTabs" type="TabContainer"[^\n]*\]\n(?P<body>.*?)(?=\n\[node name="BuildPanel")',
        scene_text,
        re.S,
    )
    ensure(tabs_match is not None, errors, "Could not isolate authored Town ManagementTabs card")
    if tabs_match is not None:
        tabs_body = tabs_match.group("body")
        ensure(tabs_body.count("custom_minimum_size = Vector2(0, 460)") == 1, errors, "Town ManagementTabs must own one exact 460px content-safe minimum")
        ensure(tabs_body.count("size_flags_horizontal = 3") == 1 and tabs_body.count("size_flags_vertical = 3") == 1, errors, "Town ManagementTabs must fill the remaining management rail from its content-safe minimum")
        ensure(tabs_body.count("tab_alignment = 1") == 1, errors, "Town ManagementTabs must center its five native command plaques inside the compact and wide rails")
        ensure("size_flags_vertical = 1" not in tabs_body, errors, "Town ManagementTabs must not leave the taller management rail unfilled")
    watermark_match = re.search(
        r'\[node name="BuildFactionWatermark" type="TextureRect" parent="ContentMargin/Content/MainRow/SidebarShell/SidebarPad/SidebarBox/ManagementTabs/BuildPanel/BuildPad/BuildBox"\]\n(?P<body>.*?)(?=\n\[node name="RecruitPanel")',
        scene_text,
        re.S,
    )
    ensure(scene_text.count('[node name="BuildFactionWatermark" type="TextureRect"') == 1 and watermark_match is not None, errors, "Town Build page must author exactly one faction watermark after its controls")
    if watermark_match is not None:
        watermark_body = watermark_match.group("body")
        for token in (
            "unique_name_in_owner = true",
            "visible = false",
            "layout_mode = 2",
            "size_flags_vertical = 3",
            "mouse_filter = 2",
            "self_modulate = Color(1, 1, 1, 0.14)",
            "expand_mode = 1",
            "stretch_mode = 5",
        ):
            ensure(watermark_body.count(token) == 1, errors, f"Town Build faction watermark is missing exact passive scene token: {token}")
        for forbidden in ("custom_minimum_size", "tooltip_text", "texture =", "script =", "focus_mode = 1", "focus_mode = 2"):
            ensure(forbidden not in watermark_body, errors, f"Town Build faction watermark must not add layout, text, authored art, script, or focus through {forbidden}")
    launcher_index = scene_text.find('[node name="OpenBuildCatalog" type="Button"')
    watermark_index = scene_text.find('[node name="BuildFactionWatermark" type="TextureRect"')
    recruit_index = scene_text.find('[node name="RecruitPanel" type="PanelContainer"')
    ensure(0 <= launcher_index < watermark_index < recruit_index, errors, "Town Build faction watermark must remain the final BuildBox child after the catalog launcher and before the next native page")

    ensure(script_text.count("@onready var _build_faction_watermark: TextureRect = %BuildFactionWatermark") == 1, errors, "TownShell must bind the Build faction watermark exactly once")
    refresh_crest = gd_function_block(script_text, "_refresh_faction_crest")
    ensure(refresh_crest, errors, "Could not isolate TownShell faction-crest refresh for Build watermark validation")
    if refresh_crest:
        refresh_order = tuple(refresh_crest.find(token) for token in (
            "var texture: Texture2D = load(icon_path) as Texture2D if icon_path != \"\" else null",
            "_crest_icon.texture = texture",
            "_crest_icon.visible = texture != null",
            "_build_faction_watermark.texture = texture",
            "_build_faction_watermark.visible = texture != null and not FrontierVisualKit.high_contrast_enabled()",
            "_crest_glyph.visible = texture == null",
        ))
        ensure(all(index >= 0 for index in refresh_order) and list(refresh_order) == sorted(refresh_order), errors, "TownShell must derive both crest surfaces from one loaded faction texture and hide only the decorative watermark in high contrast")
        ensure(refresh_crest.count("load(icon_path)") == 1 and refresh_crest.count("_build_faction_watermark.texture =") == 1 and refresh_crest.count("_build_faction_watermark.visible =") == 1, errors, "Town Build watermark lifecycle must have one shared texture load and one fail-closed texture/visibility assignment")
        for forbidden in ("_build_faction_watermark.custom_minimum_size", "_build_faction_watermark.size_flags_", "_build_faction_watermark.self_modulate", "_build_faction_watermark.tooltip_text", "_build_faction_watermark.grab_focus", "call_deferred", "create_timer"):
            ensure(forbidden not in refresh_crest, errors, f"Town Build watermark refresh must not mutate layout, focus, timing, or semantic text through {forbidden}")
    ensure(scene_text.count('[node name="LogisticsScroll" type="ScrollContainer"') == 1, errors, "Town Log page must own one native ScrollContainer")
    logistics_scroll_match = re.search(
        r'\[node name="LogisticsScroll" type="ScrollContainer"[^\n]*\]\n(?P<body>.*?)(?=\n\[node name="LogisticsPad")',
        scene_text,
        re.S,
    )
    ensure(logistics_scroll_match is not None, errors, "Could not isolate Town Log native scroll owner")
    if logistics_scroll_match is not None:
        scroll_body = logistics_scroll_match.group("body")
        for token in ("unique_name_in_owner = true", "size_flags_horizontal = 3", "size_flags_vertical = 3", "horizontal_scroll_mode = 0"):
            ensure(token in scroll_body, errors, f"Town Log native scroll owner is missing exact bounded-scroll token: {token}")
    ensure(scene_text.count("/LogisticsPanel/LogisticsScroll/LogisticsPad/LogisticsBox") == 10, errors, "All ten Town Log army/label/action surfaces must remain in exact source order beneath the one native scroll owner")
    for forbidden in ("LogisticsPanel/LogisticsPad/LogisticsBox", "vertical_scroll_mode = 0", "clip_contents = false"):
        ensure(forbidden not in scene_text, errors, f"Town Log page must not bypass bounded native vertical scrolling via {forbidden}")

    focused = gd_function_block(smoke_text, "_assert_town_management_card_contract")
    run_town = gd_function_block(smoke_text, "_run_town_smoke")
    ensure(focused and run_town, errors, "Could not isolate focused Town management-card runtime owner")
    if focused:
        for token in (
            "var tab_bar := tabs.get_tab_bar()",
            "tabs.tab_alignment != HORIZONTAL_ALIGNMENT_CENTER",
            'for style_name in ["tab_selected", "tab_hovered", "tab_unselected", "tab_disabled"]:',
            "is_equal_approx(style.content_margin_left, 4.0)",
            "is_equal_approx(style.content_margin_right, 4.0)",
            'var tab_font := tab_bar.get_theme_font("font")',
            'var tab_font_size := tab_bar.get_theme_font_size("font_size")',
            "for tab_index in range(rows.size()):",
            "var tab_rect := tab_bar.get_tab_rect(tab_index)",
            "var text_width := tab_font.get_string_size(tab_title, HORIZONTAL_ALIGNMENT_LEFT, -1.0, tab_font_size).x if tab_font != null and tab_font_size > 0 else INF",
            "tab_rect.position.x + 0.01 < prior_tab_end",
            "tab_rect.end.x > tab_bar.size.x + 0.01",
            "tab_rect.size.x + 0.5 < text_width + 8.0",
            "absf(first_tab_start - (tab_bar.size.x - prior_tab_end)) > 1.0",
        ):
            ensure(token in focused, errors, f"Focused Town management-tab breathing-room proof is missing exact passive geometry token: {token}")
        focused_order = tuple(focused.find(token) for token in (
            "var authority_before: Dictionary = session.to_dict()",
            'shell.get_node("%ManagementTabs")',
            '"title": "Build"',
            '"title": "Muster"',
            '"title": "Spells"',
            '"title": "Trade"',
            '"title": "Log"',
            "tabs.custom_minimum_size.y, 460.0",
            "tabs.size_flags_vertical != Control.SIZE_EXPAND_FILL",
            "for index in range(rows.size()):",
            "tabs.get_tab_title(index)",
            "tabs.size.y + 0.01 < 460.0",
            "tabs.get_global_rect().encloses(page.get_global_rect())",
            'shell.get_node("%LogisticsScroll")',
            "logistics_scroll.get_v_scroll_bar().max_value <= logistics_scroll.get_v_scroll_bar().page + 0.01",
            "logistics_scroll.scroll_vertical = int(logistics_scroll.get_v_scroll_bar().max_value)",
            "logistics_scroll.get_global_rect().encloses(response_actions.get_global_rect())",
            "logistics_scroll.scroll_vertical = 0",
            "tabs.current_tab = original_tab",
            "session.to_dict() != authority_before",
        ))
        ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused Town management-card proof must traverse five native pages, prove real Log scrolling, restore UI state, then verify authority")
        for forbidden in ("custom_minimum_size =", "tabs.size_flags_vertical = Control.SIZE", "set_deferred", "call_deferred", "create_timer", "queue_sort", "sort(", "erase("):
            ensure(forbidden not in focused, errors, f"Focused Town management-card proof must not mutate layout/content authority via {forbidden}")
        ensure('actual_title != expected_title and not actual_title.begins_with("%s " % expected_title)' in focused, errors, "Focused Town management-card proof must preserve exact native base titles plus authored readiness-count suffixes")
        watermark_order = tuple(focused.find(token) for token in (
            'var watermark: TextureRect = shell.get_node("%BuildFactionWatermark")',
            'var crest_icon: TextureRect = shell.get_node("%CrestIcon")',
            "watermark.texture != crest_icon.texture",
            'watermark.texture.resource_path != TownRules.faction_crest_icon_path("faction_embercourt")',
            "watermark.custom_minimum_size != Vector2.ZERO",
            "watermark.size_flags_vertical != Control.SIZE_EXPAND_FILL",
            "watermark.mouse_filter != Control.MOUSE_FILTER_IGNORE",
            "watermark.focus_mode != Control.FOCUS_NONE",
            "watermark.expand_mode != TextureRect.EXPAND_IGNORE_SIZE",
            "watermark.stretch_mode != TextureRect.STRETCH_KEEP_ASPECT_CENTERED",
            "not is_equal_approx(watermark.self_modulate.a, 0.14)",
            "for viewport_size in [Vector2i(1280, 720), Vector2i(1920, 1080)]:",
            "not build_box_rect.encloses(watermark_rect)",
            "watermark_rect.intersects(confirm_rect)",
            "FrontierVisualKitScript.set_high_contrast_enabled(true)",
            'shell.call("_refresh_faction_crest")',
            "if watermark.visible:",
            "FrontierVisualKitScript.set_high_contrast_enabled(original_high_contrast)",
            "if not watermark.visible:",
        ))
        ensure(all(index >= 0 for index in watermark_order) and list(watermark_order) == sorted(watermark_order), errors, "Focused Town watermark proof must validate shared live art, passive properties, two-size containment, high-contrast hiding, and restoration in order")
        ensure(re.search(r"^\s*watermark\.texture\s*=(?!=)", focused, re.M) is None, errors, "Focused Town watermark proof must not assign its production texture")
        for forbidden in ("watermark.visible =", "watermark.self_modulate =", "watermark.custom_minimum_size =", "watermark.size_flags_vertical =", "watermark.grab_focus", "watermark.tooltip_text ="):
            ensure(forbidden not in focused, errors, f"Focused Town watermark proof must remain observational and avoid {forbidden}")
    if run_town:
        readiness_call = run_town.find("_assert_town_command_tab_readiness_cues(shell)")
        card_call = run_town.find("await _assert_town_management_card_contract(shell, session)")
        return_handoff = run_town.find('shell.call("validation_prepare_town_return_handoff")')
        ensure(0 <= readiness_call < card_call < return_handoff and run_town.count("await _assert_town_management_card_contract(shell, session)") == 1, errors, "Town management-card proof must run once after readiness semantics and before return routing")

    visual = gd_function_block(visual_text, "_town_management_card_contract")
    visual_run = gd_function_block(visual_text, "_run_shell")
    ensure(visual and visual_run, errors, "Could not isolate all-size Town management-card capture owner")
    if visual:
        visual_order = tuple(visual.find(token) for token in (
            'shell.get_node_or_null("%SidebarShell")',
            'shell.get_node_or_null("%CommandPanel")',
            'shell.get_node_or_null("%ManagementTabs")',
            "var sidebar_box := tabs.get_parent() as VBoxContainer if tabs != null else null",
            '"title": "Build"',
            '"title": "Muster"',
            '"title": "Spells"',
            '"title": "Trade"',
            '"title": "Log"',
            "var authority_before: Dictionary = session.to_dict()",
            "for index in range(rows.size()):",
            "control.is_visible_in_tree() and not page.get_global_rect().encloses(control.get_global_rect())",
            'shell.get_node("%LogisticsScroll")',
            "var logistics_top_reachable",
            "var logistics_scroll_required",
            "logistics_scroll.scroll_vertical = int(logistics_scroll.get_v_scroll_bar().max_value)",
            "var logistics_end_reachable",
            "logistics_scroll.scroll_vertical = 0",
            "tabs.custom_minimum_size.y, 460.0",
            "heights.all(func(height): return height + 0.01 >= 460.0)",
            "absf(remaining_rail_gutter) <= 1.0",
            "tabs.current_tab = original_tab",
            "var authority_exact := session.to_dict() == authority_before",
        ))
        ensure(all(index >= 0 for index in visual_order) and list(visual_order) == sorted(visual_order), errors, "All-size Town management-card owner must inspect every page/control, prove top-to-end Log reachability, wide geometry, restore, then verify authority")
        for token in (
            'var expected_titles := ["Build", "Muster", "Spells", "Trade", "Log"]',
            "var tab_bar := tabs.get_tab_bar()",
            "tabs.tab_alignment == HORIZONTAL_ALIGNMENT_CENTER",
            "absf(first_tab_rect.position.x - (tab_bar.size.x - last_tab_rect.end.x)) <= 1.0",
            "sidebar_box_rect.encloses(tabs_rect)",
            "sidebar_box_rect.encloses(command_rect)",
            "not command_rect.intersects(tabs_rect)",
            "not command_panel.is_visible_in_tree()) if compact",
            "logistics_top_reachable",
            "logistics_scroll_required",
            "logistics_end_reachable",
            "tab_group_centered",
        ):
            ensure(token in visual, errors, f"All-size Town management-card proof is missing exact responsive/native-scroll token: {token}")
        for forbidden in ("custom_minimum_size =", "tabs.size_flags_vertical = Control.SIZE", "set_deferred", "call_deferred", "create_timer", "queue_sort", "sort(", "erase("):
            ensure(forbidden not in visual, errors, f"All-size Town management-card proof must remain passive and avoid {forbidden}")
    if visual_run:
        visual_run_order = tuple(visual_run.find(token) for token in (
            'elif shell_id == "town":',
            "var management_contract := await _town_management_card_contract(shell, viewport_size)",
            'shell_report["town_management_card"] = management_contract',
            'if not bool(management_contract.get("ok", false)):',
            "var screenshot_size := await _save_screenshot(render_viewport, screenshot_path)",
        ))
        ensure(all(index >= 0 for index in visual_run_order) and list(visual_run_order) == sorted(visual_run_order), errors, "Town management-card all-size contract must pass before every captured screenshot")


def validate_overworld_small_map_visual_scale(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    report_path = ROOT / "tests" / "overworld_small_map_visual_scale_runtime_report.gd"
    scene_path = ROOT / "tests" / "overworld_small_map_visual_scale_runtime_report.tscn"
    for path in (OVERWORLD_MAP_VIEW_SCRIPT_PATH, report_path, scene_path):
        ensure(path.exists(), errors, f"Missing Overworld small-map visual scale owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (OVERWORLD_MAP_VIEW_SCRIPT_PATH, report_path, scene_path)):
        return

    map_text = OVERWORLD_MAP_VIEW_SCRIPT_PATH.read_text(encoding="utf-8")
    report_text = report_path.read_text(encoding="utf-8")
    scene_text = scene_path.read_text(encoding="utf-8")
    ensure(map_text.count("const MAX_SMALL_MAP_FIT_TILE_EXTENT := 104.0") == 1, errors, "Small-map fit must own one exact 104px visual extent cap")
    ensure(map_text.count('const SMALL_MAP_CARTOGRAPHIC_MATTE_MODEL := "quiet_survey_field_below_playable_board"') == 1, errors, "Small-map surround must own one exact quiet cartographic matte model")
    ensure(map_text.count("const SMALL_MAP_CARTOGRAPHIC_MATTE_MIN_GUTTER := 48.0") == 1, errors, "Small-map cartographic matte must require one exact 48px material gutter")
    ensure(map_text.count("const TOWN_SPRITE_EXTENT_FACTOR := 0.95") == 1, errors, "Town art must own one exact 3x4 visual-landmark scale")
    extent_block = gd_function_block(map_text, "_tile_extent_for_viewport")
    uncapped_block = gd_function_block(map_text, "_uncapped_whole_map_fit_tile_extent")
    metrics_block = gd_function_block(map_text, "validation_view_metrics")
    static_draw_block = gd_function_block(map_text, "_draw_session_static_layer")
    gutters_block = gd_function_block(map_text, "_small_map_cartographic_matte_gutters")
    matte_active_block = gd_function_block(map_text, "_small_map_cartographic_matte_active")
    matte_draw_block = gd_function_block(map_text, "_draw_small_map_cartographic_matte")
    matte_corner_block = gd_function_block(map_text, "_draw_small_map_board_corner_brackets")
    matte_compass_block = gd_function_block(map_text, "_draw_small_map_compass_ornament")
    town_draw_block = gd_function_block(map_text, "_draw_town_sprite")
    town_draw_payload_block = gd_function_block(map_text, "_town_sprite_draw_payload")
    town_payload_block = gd_function_block(map_text, "_town_presentation_payload_for_town")
    extent_order = tuple(extent_block.find(token) for token in (
        "var minimum_tile_extent := _active_minimum_tile_extent()",
        "if _should_fit_entire_map():",
        "var fit_extent := _uncapped_whole_map_fit_tile_extent(viewport_size)",
        "return clampf(fit_extent, minimum_tile_extent, maxf(minimum_tile_extent, MAX_SMALL_MAP_FIT_TILE_EXTENT))",
        "var visible_tile_span := _active_visible_tile_span()",
        "return max(tactical_extent, minimum_tile_extent)",
    ))
    ensure(all(index >= 0 for index in extent_order) and list(extent_order) == sorted(extent_order), errors, "Tile extent must cap only whole-map fit before retaining the existing large-map tactical calculation")
    for token in (
        "viewport_size.x / float(max(_map_size.x, 1))",
        "viewport_size.y / float(max(_map_size.y, 1))",
        "return floor(",
    ):
        ensure(token in uncapped_block, errors, f"Uncapped whole-map fit helper is missing exact source geometry: {token}")
    for forbidden in ("session", "_session", "await ", "create_timer", "queue_redraw", "position =", "size =", "MAX_SMALL_MAP_FIT_TILE_EXTENT"):
        ensure(forbidden not in uncapped_block, errors, f"Uncapped fit helper must remain pure viewport/map geometry without policy or mutation: {forbidden}")
    for token in (
        '"maximum_small_map_fit_tile_extent": MAX_SMALL_MAP_FIT_TILE_EXTENT',
        '"uncapped_whole_map_fit_tile_extent": uncapped_whole_map_fit_tile_extent',
        '"small_map_fit_extent_capped": _should_fit_entire_map() and uncapped_whole_map_fit_tile_extent > cell_size.x',
        '"whole_map_fit_scale_policy": "bounded_small_map_fit_extent"',
    ):
        ensure(token in metrics_block, errors, f"View metrics must expose truthful small-map scale policy evidence: {token}")
    static_matte_order = tuple(static_draw_block.find(token) for token in (
        "var viewport_rect := _map_viewport_rect()",
        "var board_rect = _board_rect()",
        "_canvas_draw_rect(viewport_rect, FRAME_FILL, true)",
        "_draw_small_map_cartographic_matte(viewport_rect, board_rect)",
        "var visible_bounds := _visible_tile_bounds(board_rect, viewport_rect)",
        "_draw_tile_terrain_surface(tile, rect)",
    ))
    ensure(all(index >= 0 for index in static_matte_order) and list(static_matte_order) == sorted(static_matte_order), errors, "Small-map cartographic matte must draw below every authoritative terrain tile")
    for token in (
        '"left": maxf(board_rect.position.x - viewport_rect.position.x, 0.0)',
        '"top": maxf(board_rect.position.y - viewport_rect.position.y, 0.0)',
        '"right": maxf(viewport_rect.end.x - board_rect.end.x, 0.0)',
        '"bottom": maxf(viewport_rect.end.y - board_rect.end.y, 0.0)',
    ):
        ensure(token in gutters_block, errors, f"Small-map matte gutter ownership is missing exact live geometry: {token}")
    matte_active_order = tuple(matte_active_block.find(token) for token in (
        "if not _should_fit_entire_map() or not viewport_rect.encloses(board_rect):",
        "var gutters := _small_map_cartographic_matte_gutters(viewport_rect, board_rect)",
        ") >= SMALL_MAP_CARTOGRAPHIC_MATTE_MIN_GUTTER",
    ))
    ensure(all(index >= 0 for index in matte_active_order) and list(matte_active_order) == sorted(matte_active_order), errors, "Cartographic matte activation must require whole-map containment and a material live gutter")
    matte_draw_order = tuple(matte_draw_block.find(token) for token in (
        "if not _small_map_cartographic_matte_active(viewport_rect, board_rect):",
        "_canvas_draw_rect(viewport_rect, SMALL_MAP_CARTOGRAPHIC_MATTE_FILL, true)",
        "for column in range(1, column_count):",
        "for row in range(1, row_count):",
        "for contour_center in contour_centers:",
        "for shadow_extent in [SMALL_MAP_CARTOGRAPHIC_MATTE_BOARD_SHADOW_EXTENT, 9.0, 5.0]:",
        "_canvas_draw_rect(board_rect.grow(3.0), SMALL_MAP_CARTOGRAPHIC_MATTE_BOARD_EDGE, false, 1.5)",
        "_draw_small_map_board_corner_brackets(board_rect)",
        "_draw_small_map_compass_ornament(viewport_rect, board_rect)",
    ))
    ensure(all(index >= 0 for index in matte_draw_order) and list(matte_draw_order) == sorted(matte_draw_order), errors, "Cartographic matte must retain its restrained field-to-mounted-board draw order")
    for token in ("var arm := 22.0", "var inset := 7.0", "_canvas_draw_line(point", "available_gutter < 132.0", "var radius := minf(34.0", "_canvas_draw_colored_polygon(north"):
        ensure(token in matte_corner_block + matte_compass_block, errors, f"Cartographic matte ornament is missing bounded source token: {token}")
    for forbidden in ("_session", "SessionState", "OverworldRules", "set_meta", "position =", "size =", "queue_redraw", "await ", "create_timer", "tile_pressed", "pan_tiles"):
        ensure(forbidden not in gutters_block + matte_active_block + matte_draw_block + matte_corner_block + matte_compass_block, errors, f"Cartographic matte must remain passive below-board presentation only: {forbidden}")
    for token in (
        '"small_map_cartographic_matte_active": small_map_matte_active',
        '"small_map_cartographic_matte_model": SMALL_MAP_CARTOGRAPHIC_MATTE_MODEL',
        '"small_map_cartographic_matte_minimum_gutter": SMALL_MAP_CARTOGRAPHIC_MATTE_MIN_GUTTER',
        '"small_map_cartographic_matte_grid_spacing": SMALL_MAP_CARTOGRAPHIC_MATTE_GRID_SPACING',
        '"small_map_cartographic_matte_board_shadow_extent": SMALL_MAP_CARTOGRAPHIC_MATTE_BOARD_SHADOW_EXTENT',
        '"small_map_cartographic_matte_gutters": small_map_matte_gutters.duplicate(true)',
        '"small_map_cartographic_matte_below_terrain": true',
        '"small_map_cartographic_matte_noninteractive": true',
        '"small_map_cartographic_matte_fake_tiles": false',
    ):
        ensure(token in metrics_block, errors, f"View metrics must expose exact passive cartographic matte evidence: {token}")
    town_draw_order = tuple(town_draw_block.find(token) for token in (
        "var asset_id := _town_sprite_asset_id(_town_at(tile))",
        "var texture = _object_texture_for_asset(asset_id)",
        "var anchor := _draw_town_grounding_anchor(rect, remembered, tile)",
        "var draw_payload := _town_sprite_draw_payload(asset_id, texture, rect)",
        'var draw_texture: Texture2D = draw_payload.get("draw_texture", texture)',
        "_draw_sprite_silhouette_outline(",
        "_canvas_draw_texture_rect(draw_texture, sprite_rect, false",
        "_draw_town_owner_pennant(",
        "_draw_town_front_contact(anchor, remembered)",
        "_draw_town_entry_approach(",
    ))
    ensure(all(index >= 0 for index in town_draw_order) and list(town_draw_order) == sorted(town_draw_order), errors, "Town drawing must apply the visual-only extent after retaining logical footprint/grounding ownership")
    town_draw_payload_order = tuple(town_draw_payload_block.find(token) for token in (
        "var footprint := _object_profile_footprint(_town_object_profile())",
        "var footprint_extent := minf(footprint_rect.size.x, footprint_rect.size.y)",
        "var visible_extent_px := maxf(12.0, footprint_extent * TOWN_SPRITE_EXTENT_FACTOR)",
        "var single_tile_extent := single_tile_extent_override if single_tile_extent_override > 0.0 else _object_world_tile_extent(footprint_rect, footprint)",
        "var painted_ground_line_y := footprint_rect.end.y - single_tile_extent * TOWN_SPRITE_GROUND_CLEARANCE_TILES",
        "var provisional_center := Vector2(footprint_rect.get_center().x, painted_ground_line_y - visible_extent_px * 0.5)",
        "var payload := _object_painted_sprite_draw_payload(asset_id, texture, provisional_center, visible_extent_px)",
        "var grounding_adjustment := painted_ground_line_y - draw_rect.end.y",
        "draw_rect.position.y += grounding_adjustment",
        'payload["painted_bottom_clearance_px"] = footprint_rect.end.y - draw_rect.end.y',
        "return payload",
    ))
    ensure(all(index >= 0 for index in town_draw_payload_order) and list(town_draw_payload_order) == sorted(town_draw_payload_order), errors, "Town draw payload must scale against the full footprint then ground the actual painted alpha bounds")
    for forbidden in ("_session", "session.", "queue_redraw", "await ", "create_timer", "_canvas_draw", "position.x +=", "footprint_rect.size ="):
        ensure(forbidden not in town_draw_payload_block, errors, f"Town draw payload must remain pure renderer geometry without gameplay or draw mutation: {forbidden}")
    for token in (
        '"visual_sprite_extent_fraction_of_footprint": TOWN_SPRITE_EXTENT_FACTOR',
        '"visual_sprite_extent_tiles": TOWN_SPRITE_EXTENT_FACTOR * float(mini(TOWN_VISUAL_FOOTPRINT.x, TOWN_VISUAL_FOOTPRINT.y))',
    ):
        ensure(token in town_payload_block, errors, f"Town presentation must expose exact visual/logical scale separation: {token}")
    for preserved_token in (
        "const TOWN_PRESENTATION_FOOTPRINT := Vector2i(3, 2)",
        "const TOWN_ENTRY_OFFSET := Vector2i(1, 1)",
        "const TOWN_VISUAL_FOOTPRINT := Vector2i(3, 4)",
        'const TOWN_VISUAL_ANCHOR_MODEL := "three_by_four_entry_center_bottom"',
        "const TOWN_SPRITE_EXTENT_FACTOR := 0.95",
        "const TOWN_SPRITE_GROUND_CLEARANCE_TILES := 0.18",
        "const HERO_FIELD_SPRITE_EXTENT_FACTOR := 0.64",
        "const OBJECT_SPRITE_EXTENT_FACTOR := 0.88",
        'const TOWN_PRESENTATION_MODEL := "town_3x4_visual_landmark_3x2_logical_bottom_middle_entry"',
    ):
        ensure(preserved_token in map_text, errors, f"Small-map visual cap must preserve object presentation authority: {preserved_token}")

    for token in (
        'const SMALL_SCENARIO_ID := "prismhearth-watch"',
        'const LARGE_SCENARIO_ID := "ninefold-confluence"',
        "const VIEWPORT_SIZES := [Vector2i(1280, 720), Vector2i(1920, 1080)]",
        "const MAX_SMALL_MAP_TILE_EXTENT := 104.0",
        'const SMALL_MAP_MATTE_MODEL := "quiet_survey_field_below_playable_board"',
        "const SMALL_MAP_MATTE_MIN_GUTTER := 48.0",
        'const SCALE_HIERARCHY_MODEL := "landscape_mass_and_landmark_bands_v5"',
        "const TOWN_VISUAL_EXTENT_TILES := 2.85",
        "const HERO_FIELD_VISUAL_EXTENT_TILES := 0.64",
        "const HERO_TOWN_VISITOR_VISUAL_EXTENT_TILES := 0.4484",
        'var metrics: Dictionary = map_view.call("validation_view_metrics")',
        "var expected_capped := uncapped_extent > MAX_SMALL_MAP_TILE_EXTENT",
        "viewport_rect.get_center().distance_to(board_rect.get_center()) <= 1.5",
        'bool(metrics.get("fit_entire_map", false))',
        'bool(metrics.get("full_map_visible", false))',
        'not bool(metrics.get("pan_supported", true))',
        'var matte_gutters: Dictionary = metrics.get("small_map_cartographic_matte_gutters", {})',
        'var matte_expected := maximum_gutter >= SMALL_MAP_MATTE_MIN_GUTTER',
        'bool(metrics.get("small_map_cartographic_matte_active", false)) == matte_expected',
        'String(metrics.get("small_map_cartographic_matte_model", "")) == SMALL_MAP_MATTE_MODEL',
        'bool(metrics.get("small_map_cartographic_matte_below_terrain", false))',
        'bool(metrics.get("small_map_cartographic_matte_noninteractive", false))',
        'not bool(metrics.get("small_map_cartographic_matte_fake_tiles", true))',
        "var town_exact := _town_footprint_exact(shell)",
        "var hero_exact := _hero_scale_exact(map_view, tile_extent)",
        "var object_exact := _one_tile_object_footprints_exact(shell, session)",
        "var authority_exact := session.to_dict() == authority_before",
        'not bool(metrics.get("fit_entire_map", true))',
        'bool(metrics.get("pan_supported", false))',
        'print("OVERWORLD_SMALL_MAP_VISUAL_SCALE_RUNTIME_REPORT %s"',
    ):
        ensure(token in report_text, errors, f"Focused small-map scale report is missing exact live proof: {token}")
    ensure(report_text.count("await _small_map_row(viewport_size)") == 1 and report_text.count("await _large_map_control(Vector2i(1920, 1080))") == 1, errors, "Focused scale report must run exactly two small-map viewport rows then one large-map control")
    ensure(report_text.count('if bool(row.get("cartographic_matte_active", false)):') == 1 and 'OS.get_environment("OVERWORLD_WORLD_SURFACE_CAPTURE_DIR").strip_edges() == "" and matte_active_rows != VIEWPORT_SIZES.size()' in report_text, errors, "Focused scale report must require the matte for both logical headless viewports while permitting real-display capture geometry")
    for token in (
        'int(profile.get("footprint_width_tiles", 0)) != 3',
        'int(profile.get("footprint_height_tiles", 0)) != 2',
        'int(profile.get("blocked_footprint_cell_count", 0)) + int(profile.get("off_map_footprint_cell_count", 0)) != 5',
        'String(profile.get("scale_hierarchy_model", "")) != SCALE_HIERARCHY_MODEL',
        'float(profile.get("visual_sprite_extent_fraction_of_footprint", 0.0)), 0.95',
        'float(profile.get("visual_sprite_extent_tiles", 0.0)), TOWN_VISUAL_EXTENT_TILES',
        'String(profile.get("sprite_silhouette_model", "")) != "eight_direction_alpha_silhouette_outline"',
        'String(profile.get("entry_role", "")) != "bottom_middle_visit_approach"',
        'int(readability.get("footprint_width_tiles", 0)) == 1',
        'int(readability.get("footprint_height_tiles", 0)) == 1',
        'sprite_rect.size.x > tile_extent + 0.01',
        'var expected_extent := HERO_TOWN_VISITOR_VISUAL_EXTENT_TILES if bool(layout.get("town_footprint_colocated", false)) else HERO_FIELD_VISUAL_EXTENT_TILES',
        'float(layout.get("sprite_extent_fraction", 0.0)), expected_extent',
        'String(layout.get("sprite_silhouette_model", "")) != "eight_direction_alpha_silhouette_outline"',
        'String(layout.get("command_pennant", {}).get("model", "")) != "compact_player_command_flag"',
    ):
        ensure(token in report_text, errors, f"Focused scale report must retain exact logical/object hierarchy gate: {token}")
    for forbidden in (
        "HERO_FIELD_SPRITE_EXTENT_FACTOR =", "OBJECT_SPRITE_EXTENT_FACTOR =", "TOWN_PRESENTATION_FOOTPRINT =", "TOWN_SPRITE_EXTENT_FACTOR =",
        "session.overworld.erase", "queue_redraw", "_tile_extent_for_viewport(", "large_map_visible_tile_span_override =",
        "sort(", ".erase(", "create_timer",
        "_draw_small_map_cartographic_matte(", "_small_map_cartographic_matte_active(", "SMALL_MAP_CARTOGRAPHIC_MATTE_MIN_GUTTER =",
    ):
        ensure(forbidden not in report_text, errors, f"Focused scale report must observe public live geometry without changing renderer/game authority: {forbidden}")
    ensure('script = ExtResource("1")' in scene_text and 'overworld_small_map_visual_scale_runtime_report.gd' in scene_text, errors, "Small-map scale report scene must own the exact focused script")


def validate_generated_map_object_visual_coherence(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    report_path = ROOT / "tests" / "random_map_live_overworld_render_move_report.gd"
    for path in (OVERWORLD_MAP_VIEW_SCRIPT_PATH, report_path):
        ensure(path.exists(), errors, f"Missing generated-map object visual owner: {path.relative_to(ROOT)}")
    if not OVERWORLD_MAP_VIEW_SCRIPT_PATH.exists() or not report_path.exists():
        return

    map_text = OVERWORLD_MAP_VIEW_SCRIPT_PATH.read_text(encoding="utf-8")
    report_text = report_path.read_text(encoding="utf-8")
    for token in (
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_BASE_MIN_TILES := 0.54",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_SPAN_MIN_STEP_TILES := 0.06",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_DEPTH_MIN_STEP_TILES := 0.08",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_BASE_CAP_TILES := 0.60",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_SPAN_CAP_STEP_TILES := 0.08",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_DEPTH_CAP_STEP_TILES := 0.10",
        "const MULTI_TILE_INTERACTIVE_SPRITE_EXTENT_ABSOLUTE_CAP_TILES := 0.80",
        "const OBJECT_VISIBLE_FOOTPRINT_INSET_TILES := 0.02",
        "const OBJECT_PAINTED_BOUNDS_PADDING_PIXELS := 1",
        "const OBJECT_MIN_PAINTED_EXTENT_FRACTION := 0.34",
        'const OBJECT_VISIBLE_SCALE_MODEL := "cached_alpha_bounds_semantic_visible_extent"',
        "const GENERATED_DECORATIVE_BODY_SPRITE_EXTENT_TILES := 1.20",
        "const GENERATED_DECORATIVE_BODY_SCALE_FACTOR_MIN := 0.93",
        "const GENERATED_DECORATIVE_BODY_SCALE_FACTOR_MAX := 1.07",
        "const GENERATED_DECORATIVE_BODY_ASSET_CLUSTER_TILES := 4",
        "const GENERATED_DECORATIVE_BODY_OFFSET_X_TILES := 0.12",
        "const GENERATED_DECORATIVE_BODY_OFFSET_Y_MIN_TILES := -0.04",
        "const GENERATED_DECORATIVE_BODY_OFFSET_Y_MAX_TILES := 0.04",
        "const GENERATED_DECORATIVE_BODY_MASS_SMALL_EXTENT_TILES := 1.52",
        "const GENERATED_DECORATIVE_BODY_MASS_MEDIUM_EXTENT_TILES := 1.90",
        "const GENERATED_DECORATIVE_BODY_MASS_LARGE_EXTENT_TILES := 2.28",
        "const GENERATED_DECORATIVE_BODY_MASS_BOUNDS_MARGIN_TILES := 0.52",
        'const GENERATED_DECORATIVE_BODY_PRESENTATION_MODEL := "exact_body_cells_overlapping_landscape_mass_anchors_v4"',
        "var _generated_decorative_bodies_by_tile: Dictionary = {}",
        "var _generated_decorative_blocker_asset_ids_by_biome: Dictionary = {}",
        "var _generated_decorative_blocker_fallback_asset_ids: Array = []",
        "var _object_texture_visible_regions: Dictionary = {}",
    ):
        ensure(map_text.count(token) == 1, errors, f"Generated-map visual source must own exactly one token: {token}")
    for terrain_token in (
        '"grass": "biome_grasslands"',
        '"mire": "biome_mire_fen"',
        '"rough": "biome_highland_ridge"',
        '"snow": "biome_snow_frost_marches"',
        '"water": "biome_coast_archipelago"',
        '"underground": "biome_subterranean_underways"',
    ):
        ensure(terrain_token in map_text, errors, f"Generated blocker presentation is missing terrain-to-authored-biome mapping: {terrain_token}")

    manifest_block = gd_function_block(map_text, "_load_decorative_object_sprite_manifest")
    for token in (
        'String(entry.get("source_family", "")).strip_edges() == "blocker"',
        'entry.get("source_biome_ids", [])',
        "asset_id not in _generated_decorative_blocker_fallback_asset_ids",
        "asset_id not in biome_asset_ids",
        "_generated_decorative_blocker_fallback_asset_ids.sort()",
        "biome_asset_ids.sort()",
    ):
        ensure(token in manifest_block, errors, f"Generated blocker palette must derive deterministic original blocker assets from the authored manifest: {token}")
    for forbidden in ("RandomMapGeneratorRules", "h3m_def_name", "package_block_tiles", "session", "_session"):
        ensure(forbidden not in manifest_block, errors, f"Generated blocker palette loading must remain art-manifest-only: {forbidden}")

    index_block = gd_function_block(map_text, "_index_generated_decorative_body_cells")
    index_order = tuple(index_block.find(token) for token in (
        'String(object.get("runtime_object_role", "")).strip_edges() != "decorative_blocker_sprite"',
        'var package_block_tiles = object.get("package_block_tiles", null)',
        "for tile_value in _tiles_from_payloads(package_block_tiles):",
        "if body_tile.x < 0 or body_tile.y < 0 or body_tile.x >= _map_size.x or body_tile.y >= _map_size.y:",
        "body_tiles.append(body_tile)",
        "for body_tile_value in body_tiles:",
        "if _generated_decorative_bodies_by_tile.has(key):",
        "var presentation: Dictionary = object.duplicate(true)",
        'presentation["x"] = body_tile.x',
        'presentation["y"] = body_tile.y',
        'presentation["footprint"] = {"width": 1, "height": 1, "anchor": "bottom_center"}',
        'presentation["generated_body_visual_anchor"] = false',
        '_generated_decorative_bodies_by_tile[key] = presentation',
        "var desired_anchor_count := 1",
        "for anchor_index in range(desired_anchor_count):",
        "selected_anchor_tiles.append(best_tile)",
        "var placement_bounds := {",
        "for anchor_index in range(selected_anchor_tiles.size()):",
        'presentation["bounds"] = placement_bounds.duplicate(true)',
        'presentation["overworld_sprite_asset_id"] = _generated_decorative_body_asset_id(object, anchor_tile)',
        'presentation["generated_body_motif_key"] = _generated_decorative_body_motif_key(object, anchor_tile)',
        "var composition := _generated_decorative_body_composition(",
        'presentation["generated_body_visual_anchor"] = true',
        'presentation["generated_body_placement_tile_count"] = body_tiles.size()',
    ))
    ensure(all(index >= 0 for index in index_order) and list(index_order) == sorted(index_order), errors, "Generated blocker presentation must index exact body cells before selecting bounded sparse placement-mass anchors")
    for token in (
        'presentation["generated_decorative_body_cell"] = true',
        'presentation["generated_body_presentation_model"] = GENERATED_DECORATIVE_BODY_PRESENTATION_MODEL',
        'presentation["generated_body_source_placement_ids"]',
        'existing["generated_body_source_count"] = placement_ids.size()',
        "if body_tiles.size() >= 9:",
        "desired_anchor_count = 3",
        "elif body_tiles.size() >= 5:",
        "desired_anchor_count = 2",
        'if bool(existing.get("generated_body_visual_anchor", false)):',
        'presentation["generated_body_anchor_placement_id"] = source_placement_id',
        'presentation["generated_body_anchor_index"] = anchor_index',
        'presentation["generated_body_anchor_count"] = selected_anchor_tiles.size()',
        'presentation["generated_body_placement_tile_count"] = body_tiles.size()',
        'presentation["generated_body_scale_factor"] = float(composition.get("scale_factor", 1.0))',
        'presentation["generated_body_offset_tiles"] = composition.get("offset_tiles", {}).duplicate(true)',
        'presentation["generated_body_sprite_extent_tiles"] = float(composition.get("sprite_extent_tiles", GENERATED_DECORATIVE_BODY_SPRITE_EXTENT_TILES))',
        'presentation["generated_body_sprite_center_tiles"] = composition.get("sprite_center_tiles", {}).duplicate(true)',
        'presentation["generated_body_composition_key"] = String(composition.get("composition_key", ""))',
    ):
        ensure(token in index_block, errors, f"Generated blocker body index is missing deterministic collision/source evidence: {token}")
    for forbidden in ("object[", "package_block_tiles.append", "package_block_tiles.erase", "OverworldRules", "RandomMapGeneratorRules", "await ", "create_timer"):
        ensure(forbidden not in index_block, errors, f"Generated blocker body indexing must remain detached presentation-only: {forbidden}")

    asset_block = gd_function_block(map_text, "_generated_decorative_body_asset_id")
    for token in (
        "var terrain_id := _terrain_at(tile)",
        "GENERATED_DECORATIVE_BIOME_BY_TERRAIN.get(terrain_id",
        "_generated_decorative_blocker_asset_ids_by_biome.get(biome_id, [])",
        "candidates = _generated_decorative_blocker_fallback_asset_ids",
        "var stable_key := _generated_decorative_body_motif_key(object, tile)",
        "absi(stable_key.hash()) % candidates.size()",
    ):
        ensure(token in asset_block, errors, f"Generated blocker asset choice is missing stable terrain-matched selection: {token}")
    motif_block = gd_function_block(map_text, "_generated_decorative_body_motif_key")
    for token in (
        "var terrain_id := _terrain_at(tile)",
        "GENERATED_DECORATIVE_BIOME_BY_TERRAIN.get(terrain_id",
        'var placement_id := String(object.get("placement_id", "")).strip_edges()',
        'placement_id = String(object.get("h3m_def_name", "")).strip_edges()',
        'var cluster_x := floori(float(tile.x) / float(GENERATED_DECORATIVE_BODY_ASSET_CLUSTER_TILES))',
        'var cluster_y := floori(float(tile.y) / float(GENERATED_DECORATIVE_BODY_ASSET_CLUSTER_TILES))',
        'return "%s|%s|%s|%d,%d"',
        "biome_id,",
        "terrain_id,",
        "placement_id,",
    ):
        ensure(token in motif_block, errors, f"Generated blocker motif key is missing placement-aware bounded clustering: {token}")
    for forbidden in ("rand", "randi", "seed(", "session", "_session", "sort(", "erase(", "package_block_tiles"):
        ensure(forbidden not in asset_block + motif_block, errors, f"Generated blocker asset choice must remain deterministic and presentation-only: {forbidden}")

    composition_block = gd_function_block(map_text, "_generated_decorative_body_composition")
    for token in (
        'var placement_id := String(object.get("placement_id", "")).strip_edges()',
        'var composition_key := "%s|%s|%d,%d|%d/%d"',
        'var scale_factor := lerpf(',
        'GENERATED_DECORATIVE_BODY_SCALE_FACTOR_MIN',
        'GENERATED_DECORATIVE_BODY_SCALE_FACTOR_MAX',
        'var offset_tiles := Vector2(',
        '-GENERATED_DECORATIVE_BODY_OFFSET_X_TILES',
        'GENERATED_DECORATIVE_BODY_OFFSET_Y_MIN_TILES',
        'GENERATED_DECORATIVE_BODY_OFFSET_Y_MAX_TILES',
        'if body_tile_count >= 9:',
        'base_extent_tiles = GENERATED_DECORATIVE_BODY_MASS_LARGE_EXTENT_TILES',
        'elif body_tile_count >= 5:',
        'base_extent_tiles = GENERATED_DECORATIVE_BODY_MASS_MEDIUM_EXTENT_TILES',
        'elif body_tile_count >= 3:',
        'base_extent_tiles = GENERATED_DECORATIVE_BODY_MASS_SMALL_EXTENT_TILES',
        'var sprite_extent_tiles := base_extent_tiles * scale_factor',
        'var sprite_center_tiles := Vector2(',
        'float(tile.x - min_tile.x) + 0.5 + offset_tiles.x',
        'GENERATED_DECORATIVE_BODY_MASS_BOUNDS_MARGIN_TILES',
        'clampf(sprite_center_tiles.x, horizontal_inset, 1.0 - horizontal_inset)',
        'clampf(sprite_center_tiles.y, vertical_inset, 1.0 - vertical_inset)',
        '"sprite_extent_tiles": sprite_extent_tiles',
        '"sprite_center_tiles": {"x": sprite_center_tiles.x, "y": sprite_center_tiles.y}',
    ):
        ensure(token in composition_block, errors, f"Generated blocker composition must own deterministic bounded variation: {token}")
    stable_fraction_block = gd_function_block(map_text, "_stable_unit_fraction")
    ensure('float(posmod(stable_key.hash(), 1000003)) / 1000002.0' in stable_fraction_block, errors, "Generated blocker composition must derive a deterministic unit fraction without RNG state")
    for forbidden in ("rand", "randi", "seed(", "Time.", "session", "_session", "await ", "create_timer"):
        ensure(forbidden not in composition_block + stable_fraction_block, errors, f"Generated blocker composition must be frame-stable and presentation-local: {forbidden}")

    procedural_grounding_block = gd_function_block(map_text, "_procedural_grounding_fraction_metrics")
    mapped_grounding_block = gd_function_block(map_text, "_mapped_sprite_grounding_fraction_metrics")
    for token in ('"blocker":', "half_width = 0.43", "half_height = 0.080"):
        ensure(token in procedural_grounding_block, errors, f"Blocker bodies must own the exact broad terrain-contact bed: {token}")
    for token in ('"blocker":', "half_width *= 1.02", "half_height *= 1.05"):
        ensure(token in mapped_grounding_block, errors, f"Mapped blocker bodies must retain their exact grounded mass multiplier: {token}")
