def validate_overworld_130_scale_footer_containment(errors: list[str]) -> None:
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (OVERWORLD_SCENE_PATH, OVERWORLD_SCRIPT_PATH, visual_path):
        ensure(path.exists(), errors, f"Missing Overworld 130% footer containment owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (OVERWORLD_SCENE_PATH, OVERWORLD_SCRIPT_PATH, visual_path)):
        return

    scene_text = OVERWORLD_SCENE_PATH.read_text(encoding="utf-8")
    shell_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    map_cue_block = scene_node_block(scene_text, "MapCue", "Label")
    ensure(scene_text.count('[node name="MapCue" type="Label"') == 1, errors, "OverworldShell must author exactly one MapCue Label")
    for required_token in (
        "unique_name_in_owner = true",
        "clip_text = true",
        'text = "Action ready"',
        "text_overrun_behavior = 4",
    ):
        ensure(required_token in map_cue_block, errors, f"Overworld MapCue is missing its exact native containment property: {required_token}")
    for forbidden_token in ("autowrap_mode", "custom_minimum_size", "size_flags", "visible = false"):
        ensure(forbidden_token not in map_cue_block, errors, f"Overworld MapCue must stay a visible inherited-single-line Label without geometry ownership: {forbidden_token}")

    responsive_match = re.search(
        r"func _apply_responsive_layout\(\) -> void:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    ensure(responsive_match is not None, errors, "OverworldShell must retain one isolated responsive footer allocator")
    if responsive_match is not None:
        responsive_body = responsive_match.group("body")
        responsive_order = tuple(responsive_body.find(token) for token in (
            "var available_size := _responsive_available_size()",
            "var compact_layout := available_size.x < 1360.0 or available_size.y < 760.0",
            "var narrow_layout := available_size.x < 1100.0",
            "var constrained_desktop_band := not compact_layout and available_size.x <= 1600.0",
            "var large_scale_footer := constrained_desktop_band and SettingsService.ui_scale_percent() >= 130",
            '_command_row.add_theme_constant_override("separation", 4 if constrained_desktop_band else 6)',
            "_resource_chip_panel.custom_minimum_size.x = 96.0 if resource_compact else (190.0 if large_scale_footer else 210.0)",
            "_resource_label.custom_minimum_size.x = 80.0 if resource_compact else (170.0 if large_scale_footer else 210.0)",
            "_status_label.clip_text = narrow_layout or large_scale_footer",
            "_status_label.text_overrun_behavior = TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "_system_panel.custom_minimum_size.x = 220.0 if narrow_layout else (252.0 if compact_layout else 308.0)",
            "_primary_action_button.custom_minimum_size.x = 170.0 if large_scale_footer else 210.0",
            "_primary_action_button.clip_text = true",
            "_primary_action_button.text_overrun_behavior = TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
        ))
        ensure(all(index >= 0 for index in responsive_order) and list(responsive_order) == sorted(responsive_order), errors, "Overworld responsive allocator must derive the existing breakpoint, apply 130%-only flexible minima, then retain system and primary-action ownership in order")
        ensure(responsive_body.count("large_scale_footer") == 5, errors, "Overworld 130% footer mode must affect only its predicate, resource/chip minima, Status clipping, and PrimaryAction minimum")
        for forbidden_token in (
            "_cue_chip_panel.custom_minimum_size",
            "_system_panel.visible",
            "_save_status_label.visible = not large_scale_footer",
            "_save_slot_picker.visible = not large_scale_footer",
            "_end_turn_button.visible",
            "_save_button.visible",
            "_settings_button.visible",
            "_menu_button.visible",
            "custom_minimum_size.y",
            "font_size",
            "set_ui_scale_percent",
            "call_deferred",
            "await ",
        ):
            ensure(forbidden_token not in responsive_body, errors, f"Overworld 130% footer allocator must not hide/reorder/resize system controls or change timing/settings: {forbidden_token}")

    focused_match = re.search(
        r"func _assert_render_cache_split\(shell: Node\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    ensure(focused_match is not None, errors, "Overworld visual smoke must retain the focused render-cache/MapCue layout control")
    if focused_match is None:
        return
    focused_body = focused_match.group("body")
    focused_order = tuple(focused_body.find(token) for token in (
        'var selection_result: Dictionary = shell.call("validation_select_tile", target.x, target.y)',
        'var map_view := shell.get_node_or_null("%Map") as Control',
        'var command_band := shell.get_node_or_null("%CommandBand") as Control',
        'var cue_chip := shell.get_node_or_null("%CueChip") as Control',
        'var map_cue := shell.get_node_or_null("%MapCue") as Label',
        "map_cue.autowrap_mode != TextServer.AUTOWRAP_OFF",
        "map_cue.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
        "if not _assert_130_scale_footer_containment(shell, map_cue):",
        "var selection_map_rect := map_view.get_global_rect()",
        "var selection_command_band_rect := command_band.get_global_rect()",
        "var selection_cue_chip_rect := Rect2(cue_chip.position, cue_chip.size)",
        "var selection_map_cue_rect := Rect2(map_cue.position, map_cue.size)",
        "var selection_map_cue_minimum := map_cue.get_combined_minimum_size()",
        'var move_result: Dictionary = shell.call("validation_perform_primary_action")',
        "await get_tree().process_frame",
        'var move_snapshot: Dictionary = shell.call("validation_snapshot")',
        "var move_map_rect := map_view.get_global_rect()",
        "var move_command_band_rect := command_band.get_global_rect()",
        "var move_cue_chip_rect := Rect2(cue_chip.position, cue_chip.size)",
        "var move_map_cue_rect := Rect2(map_cue.position, map_cue.size)",
        "var move_map_cue_minimum := map_cue.get_combined_minimum_size()",
        "selection_map_rect != move_map_rect",
        "selection_command_band_rect != move_command_band_rect",
        "selection_cue_chip_rect != move_cue_chip_rect",
        "selection_map_cue_rect != move_map_cue_rect",
        "selection_map_cue_minimum != move_map_cue_minimum",
        'map_cue.text != String(move_snapshot.get("map_cue_text", ""))',
        'map_cue.tooltip_text != String(move_snapshot.get("map_cue_tooltip_text", ""))',
        'map_cue.tooltip_text.find("Action Recap") < 0',
        'int(move_cache.get("session_static_generation", -1)) != int(selection_cache.get("session_static_generation", -1))',
    ))
    ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused MapCue proof must select, capture the native contract/allocation, move one frame, compare exact geometry/text/tooltip, then gate the static cache")
    for required_token in (
        "or not map_cue.clip_text",
        "or map_cue.get_line_count() != 1",
        "or map_cue.get_visible_line_count() != 1",
        "map_view == null or command_band == null or cue_chip == null or map_cue == null",
    ):
        ensure(required_token in focused_body, errors, f"Focused MapCue containment proof is missing exact fail-closed token: {required_token}")
    ensure(focused_body.count("await get_tree().process_frame") == 1, errors, "Focused MapCue movement gate must cross exactly one real process frame")
    ensure("cue_chip.get_global_rect()" not in focused_body and "map_cue.get_global_rect()" not in focused_body and "cue_chip.get_rect()" not in focused_body and "map_cue.get_rect()" not in focused_body, errors, "Animated MapCue controls must be compared from their raw position and size, not any rect transformed by the intentional feedback tween")
    for forbidden_token in (
        "map_cue.text =",
        "map_cue.tooltip_text =",
        "map_cue.clip_text =",
        "map_cue.text_overrun_behavior =",
        "custom_minimum_size =",
        ".size =",
        "set_deferred",
        "call_deferred",
        "queue_redraw",
    ):
        ensure(forbidden_token not in focused_body, errors, f"Focused MapCue proof must remain observation-only without layout or semantic mutation: {forbidden_token}")

    footer_match = re.search(
        r"func _assert_130_scale_footer_containment\(shell: Control, map_cue: Label\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    ensure(footer_match is not None, errors, "Overworld visual smoke must own one independent 130% full-footer containment control")
    if footer_match is not None:
        footer_body = footer_match.group("body")
        footer_order = tuple(footer_body.find(token) for token in (
            'var shell_panel := shell.get_node_or_null("%Shell") as Control',
            'var resource_chip := shell.get_node_or_null("%ResourceChip") as Control',
            'var resource_label := shell.get_node_or_null("%Resources") as MenuButton',
            'var status_chip := shell.get_node_or_null("%StatusChip") as Control',
            'var cue_chip := shell.get_node_or_null("%CueChip") as Control',
            'var orders_panel := shell.get_node_or_null("%OrdersPanel") as Control',
            'var primary_action := shell.get_node_or_null("%PrimaryAction") as Button',
            'var system_panel := shell.get_node_or_null("%SystemPanel") as Control',
            'var menu_button := shell.get_node_or_null("%Menu") as Button',
            "var required_controls: Array[Control] = [",
            "required_controls.any",
            "var large_scale_footer := SettingsService.ui_scale_percent() >= 130",
            "var expected_resource_chip_width := 190.0 if large_scale_footer else 210.0",
            "var expected_resource_label_width := 170.0 if large_scale_footer else 210.0",
            "var expected_primary_width := 170.0 if large_scale_footer else 210.0",
            "status_label.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "map_cue.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "primary_action.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "resource_label.tooltip_text.strip_edges() == \"\"",
            "status_label.tooltip_text != status_label.text",
            "primary_action.tooltip_text.strip_edges() == \"\"",
            "var root_rect := shell.get_global_rect()",
            "var footer_surfaces: Array[Control] = [resource_chip, status_chip, cue_chip, orders_panel, system_panel]",
            "var system_controls: Array[Control] = [save_status, end_turn, save_slot, save_button, settings_button, menu_button]",
            "not root_rect.encloses(shell_rect) or not shell_rect.encloses(footer_rect)",
            "for index in range(footer_surfaces.size()):",
            "for index in range(system_controls.size()):",
            "return true",
        ))
        ensure(all(index >= 0 for index in footer_order) and list(footer_order) == sorted(footer_order), errors, "Focused 130% footer control must resolve every authored surface, compare exact responsive properties/full tooltips, then prove root/footer/system containment and order")
        for required_token in (
            "not surface.is_visible_in_tree() or not footer_rect.encloses(surface_rect)",
            "footer_surfaces[index - 1].get_global_rect().end.x > surface_rect.position.x + 0.5",
            "not control.is_visible_in_tree() or not system_rect.encloses(control_rect)",
            "system_controls[index - 1].get_global_rect().end.x > control_rect.position.x + 0.5",
            "or not map_cue.clip_text",
            "or not primary_action.clip_text",
        ):
            ensure(required_token in footer_body, errors, f"Focused 130% footer containment control is missing exact fail-closed token: {required_token}")
        for forbidden_token in (
            "custom_minimum_size =",
            ".text =",
            ".tooltip_text =",
            ".visible =",
            "hide()",
            "show()",
            "sort(",
            "erase(",
            "call(",
            "await ",
            "queue_redraw",
        ):
            ensure(forbidden_token not in footer_body, errors, f"Focused 130% footer containment control must remain public and observation-only: {forbidden_token}")


def validate_overworld_hero_card_mana_first_view(errors: list[str]) -> None:
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (OVERWORLD_SCRIPT_PATH, visual_path):
        ensure(path.exists(), errors, f"Missing Overworld hero-card mana-first owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (OVERWORLD_SCRIPT_PATH, visual_path)):
        return
    shell_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")

    full_match = re.search(
        r"func _hero_card_text\(\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    visible_match = re.search(
        r"func _hero_card_visible_text\(\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    focused_match = re.search(
        r"func _assert_hero_identity_progression_contract\(shell: Control\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    ensure(full_match is not None and visible_match is not None and focused_match is not None, errors, "Overworld hero card must isolate exact full-tooltip, visible mana-first, and focused live contracts")
    ensure(shell_text.count("func _hero_card_visible_text()") == 1, errors, "OverworldShell must own exactly one visible hero-card formatter")
    ensure('_set_rail_text(_hero_label, hero_text, _hero_card_visible_text(), 2)' in shell_text, errors, "Overworld hero rail must pair the prior full tooltip with the mana-first visible summary")
    ensure('_set_rail_text(_hero_label, hero_text, hero_text, 2)' not in shell_text, errors, "Overworld hero rail must not duplicate movement in the first view and adjacent command row")
    if full_match is not None:
        full_body = full_match.group("body")
        for required_token in (
            'var movement = _session.overworld.get("movement", {})',
            'return "%s Lv%d | Move %d/%d | Mana %d/%d\\nA%d D%d P%d K%d | Scout %d" % [',
            'HeroCommandRules.scouting_radius_for_hero(hero)',
        ):
            ensure(required_token in full_body, errors, f"Full hero-card tooltip authority drifted from the prior identity/movement/mana contract: {required_token}")
        ensure("_hero_card_visible_text" not in full_body and "_short" not in full_body and "_compact" not in full_body, errors, "Full hero-card tooltip authority must remain complete and independent of visible compaction")
    if visible_match is not None:
        visible_body = visible_match.group("body")
        visible_order = tuple(visible_body.find(token) for token in (
            'var hero = _session.overworld.get("hero", {})',
            'var command = hero.get("command", {})',
            'var mana = hero.get("spellbook", {}).get("mana", {})',
            'return "%s Lv%d | Mana %d/%d\\nA%d D%d P%d K%d | Scout %d" % [',
            'String(hero.get("name", "Hero"))',
            'int(hero.get("level", 1))',
            'int(mana.get("current", 0))',
            'int(mana.get("max", 0))',
            'int(command.get("attack", 0))',
            'int(command.get("defense", 0))',
            'int(command.get("power", 0))',
            'int(command.get("knowledge", 0))',
            'HeroCommandRules.scouting_radius_for_hero(hero)',
        ))
        ensure(all(index >= 0 for index in visible_order) and list(visible_order) == sorted(visible_order), errors, "Visible hero card must retain exact name/level/mana then four stats/scouting order")
        for forbidden_token in ("movement", "Move", "_hero_card_text", "_set_rail_text", "Label", "Control", "size", "tooltip", "sort(", "erase(", "await ", "call_deferred"):
            ensure(forbidden_token not in visible_body, errors, f"Visible hero-card formatter must remain value-only and must not duplicate movement or mutate layout via {forbidden_token}")
    ensure(visual_text.count("await _assert_hero_identity_progression_contract(shell)") == 1, errors, "Overworld visual smoke must run the responsive hero-card contract exactly once")
    ensure('var hero_card_only := OS.get_environment("OVERWORLD_HERO_CARD_ONLY") == "1"' in visual_text, errors, "Overworld visual smoke must expose the bounded focused hero-card owner")
    ensure(visual_text.find("await _assert_rail_word_boundary_ellipsis_contract(shell)") < visual_text.find("await _assert_hero_identity_progression_contract(shell)") < visual_text.find("_assert_wireframe_contract(shell)"), errors, "Focused hero-card proof must follow native rail setup and finish before broad visual mutations")
    if focused_match is not None:
        focused_body = focused_match.group("body")
        focused_order = tuple(focused_body.find(token) for token in (
            "session.to_dict()",
            'session.overworld.get("hero", {})',
            'session.overworld.get("movement", {})',
            'HeroCommandRules.scouting_radius_for_hero(hero)',
            'var expected_full := "%s Lv%d | Move %d/%d | Mana %d/%d',
            'var expected_visible := "%s Lv%d | Mana %d/%d',
            'var expected_command := "Command: Solo | Move %d/%d"',
            'shell.get_node("%Hero")',
            'shell.get_node("%HeroPanel")',
            'shell.get_node("%SidebarShell")',
            'shell.get_node("%HeroPortrait")',
            'var portrait_contract := {',
            "for width in [1280, 1920]:",
            "get_window().size = requested_size",
            'shell.call("validation_snapshot")',
            "_visible_text_lines(hero_label.text)",
            "hero_label.get_global_rect()",
            "hero_portrait.get_global_rect()",
            "hero_label.text != expected_visible",
            "hero_label.tooltip_text != expected_full",
            'String(snapshot.get("command_check_visible_text", "")) != expected_command',
            'String(visible_lines[0]).contains("Move")',
            'not String(visible_lines[0]).contains("Mana")',
            "_themed_label_text_width(hero_label) > hero_label.size.x + 0.5",
            "not sidebar_rect.encloses(panel_rect)",
            "not panel_rect.encloses(identity_rect)",
            "not identity_rect.encloses(hero_rect)",
            "not identity_rect.encloses(portrait_rect)",
            "portrait_rect.intersects(hero_rect)",
            "current_portrait_contract != portrait_contract",
            "get_window().size = original_window_size",
            "session.to_dict() != authority_before",
        ))
        ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused hero-card proof must independently derive authority, inspect both live widths/text/geometry, restore, then verify session authority")
        for required_token in (
            "visible_lines.size() != 2",
            "_themed_label_text_width(hero_label) <= 0.0",
            "not hero_label.clip_text",
            "hero_label.autowrap_mode != TextServer.AUTOWRAP_OFF",
            "hero_label.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "not hero_portrait.is_visible_in_tree()",
            '"custom_minimum_size": hero_portrait.custom_minimum_size',
            '"expand_mode": hero_portrait.expand_mode',
            '"stretch_mode": hero_portrait.stretch_mode',
            '"Lyra Emberwell"',
            '"XP 0/250"',
            '"Wayfinder I"',
        ):
            ensure(required_token in focused_body, errors, f"Focused hero-card proof is missing exact first-view, portrait, or identity authority: {required_token}")
        for forbidden_token in ('shell.call("_hero_card', 'shell.call("_refresh', "_set_rail_text", ".text =", ".tooltip_text =", "custom_minimum_size =", "sort(", "erase(", "SessionStateStore", "SaveService"):
            ensure(forbidden_token not in focused_body, errors, f"Focused hero-card proof must remain public, independent, and observation-only; forbidden {forbidden_token}")


def validate_overworld_rail_word_boundary_ellipsis(errors: list[str]) -> None:
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (OVERWORLD_SCRIPT_PATH, visual_path):
        ensure(path.exists(), errors, f"Missing Overworld rail word-boundary owner: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in (OVERWORLD_SCRIPT_PATH, visual_path)):
        return
    shell_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")

    rail_helper_match = re.search(
        r"func _short_rail_text\(text: String, max_chars: int\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    compact_match = re.search(
        r"func _compact_rail_text\(full_text: String, max_lines: int, max_chars: int = RAIL_LINE_CHARS, drop_headings: bool = true\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    trim_match = re.search(
        r"func _trim_rail_visible_text\(visible_text: String, max_lines: int, max_chars: int\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    set_rail_match = re.search(
        r"func _set_rail_text\(label: Label, full_text: String, visible_text: String, max_lines: int = 1, max_chars: int = RAIL_LINE_CHARS\) -> void:\n(?P<body>.*?)(?=\nfunc )",
        shell_text,
        re.S,
    )
    ensure(rail_helper_match is not None and compact_match is not None and trim_match is not None and set_rail_match is not None, errors, "OverworldShell must isolate rail-only word-boundary truncation, native Label fit, and both existing rail consumers")
    ensure(shell_text.count("func _short_rail_text(") == 1, errors, "OverworldShell must own exactly one rail-only truncator")
    ensure(shell_text.count("lines.append(_short_rail_text(") == 2 and shell_text.count("var line := _short_rail_text(raw_line, max_chars)") == 1, errors, "Only the three compact/trim rail call sites may use the rail-only truncator")
    ensure('return "%s..." % normalized.left(max(1, max_chars - 3)).strip_edges()' in shell_text, errors, "The general _short_text compactor must remain unchanged outside the rail slice")
    if rail_helper_match is not None:
        helper_body = rail_helper_match.group("body")
        helper_order = tuple(helper_body.find(token) for token in (
            'text.strip_edges().replace("\\n", " ")',
            'while normalized.find("  ") >= 0:',
            "if normalized.length() <= max_chars:",
            "if max_chars <= 0:",
            "if max_chars == 1:",
            "var prefix := normalized.left(max_chars - 1).strip_edges()",
            'var boundary := prefix.rfind(" ")',
            "if boundary > 0:",
            "if prefix == \"\":",
            'return "%s…" % prefix',
        ))
        ensure(all(index >= 0 for index in helper_order) and list(helper_order) == sorted(helper_order), errors, "Rail truncator must normalize, preserve fitting values, handle bounds, then choose the last whole word before one Unicode ellipsis")
        for forbidden_token in ("_short_text", '"..."', "Label", "Control", "font", "size", "tooltip", "sort(", "erase(", "call_deferred", "await "):
            ensure(forbidden_token not in helper_body, errors, f"Rail-only truncator must not change general compactors, layout, timing, or authority via {forbidden_token}")
    if compact_match is not None:
        compact_body = compact_match.group("body")
        ensure(compact_body.count("_short_rail_text(") == 2 and "_short_text(" not in compact_body, errors, "Rail compact selection must use the rail-only word-boundary helper for selected lines and fallback only")
    if trim_match is not None:
        trim_body = trim_match.group("body")
        ensure(trim_body.count("_short_rail_text(") == 1 and "_short_text(" not in trim_body, errors, "Rail visible trimming must use the rail-only word-boundary helper exactly once")
    if set_rail_match is not None:
        set_rail_body = set_rail_match.group("body")
        set_rail_order = tuple(set_rail_body.find(token) for token in (
            "label.tooltip_text = full_text",
            "label.autowrap_mode = TextServer.AUTOWRAP_OFF",
            "label.clip_text = true",
            "label.text_overrun_behavior = TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "label.text = _trim_rail_visible_text(visible_text, max_lines, max_chars)",
        ))
        ensure(all(index >= 0 for index in set_rail_order) and list(set_rail_order) == sorted(set_rail_order), errors, "Rail Label assignment must retain the full tooltip, no-wrap clipping, native word ellipsis, and semantic text order")
        ensure(set_rail_body.count("text_overrun_behavior") == 1, errors, "Rail Label assignment must own exactly one native word-ellipsis configuration")
        for forbidden_token in ("OVERRUN_TRIM_ELLIPSIS", "OVERRUN_TRIM_WORD_ELLIPSIS_FORCE", "get_string_size", "get_global_rect", "size.x", "call_deferred", "await ", "queue_redraw"):
            ensure(forbidden_token not in set_rail_body, errors, f"Rail native fit must stay Label-owned and timing/layout neutral; forbidden {forbidden_token}")

    focused_match = re.search(
        r"func _assert_rail_word_boundary_ellipsis_contract\(shell: Control\) -> bool:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    expected_match = re.search(
        r"func _expected_briefing_rail_text\(full_text: String\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    control_match = re.search(
        r"func _word_safe_rail_line_for_test\(text: String, max_chars: int\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    army_expected_match = re.search(
        r"func _expected_army_rail_text\(full_text: String\) -> String:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    width_match = re.search(
        r"func _themed_label_text_width\(label: Label\) -> float:\n(?P<body>.*?)(?=\nfunc )",
        visual_text,
        re.S,
    )
    ensure(focused_match is not None and expected_match is not None and army_expected_match is not None and control_match is not None and width_match is not None, errors, "Overworld visual smoke must own focused rail, independent briefing/army/word-boundary, and themed-width controls")
    ensure(visual_text.count("await _assert_rail_word_boundary_ellipsis_contract(shell)") == 1, errors, "Overworld visual smoke must run the real rail word-boundary contract exactly once")
    ensure(visual_text.find("await _assert_objective_brief_native_ellipsis_contract(shell)") < visual_text.find("await _assert_rail_word_boundary_ellipsis_contract(shell)") < visual_text.find("_assert_wireframe_contract(shell)"), errors, "Focused native ObjectiveBrief and rail contracts must finish before broad visual mutations")
    if focused_match is not None:
        focused_body = focused_match.group("body")
        focused_order = tuple(focused_body.find(token) for token in (
            "session.to_dict()",
            'shell.get_node("%Briefing")',
            'shell.get_node("%BriefingPanel")',
            'shell.get_node("%Army")',
            'shell.get_node("%HeroPanel")',
            'shell.get_node("%SidebarShell")',
            "var rail_labels: Array[Label] = [",
            'shell.call("validation_briefing_consumption_autosave_snapshot")',
            '_expected_briefing_rail_text(full_briefing)',
            "OverworldRules.describe_army(session)",
            "_expected_army_rail_text(full_army)",
            'full_briefing.contains("Opening objectives: Claim Duskfen Bastion")',
            'expected_visible.contains("Duskfen…")',
            "for width in [1280, 1920]:",
            "get_window().size = requested_size",
            "_visible_text_lines(briefing.text)",
            "var sidebar_rect := sidebar_shell.get_global_rect()",
            "var army_text_width := _themed_label_text_width(army)",
            "for rail_label in rail_labels:",
            "rail_label.is_visible_in_tree()",
            "rail_label.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "_themed_label_text_width(rail_label)",
            "not sidebar_rect.encloses(rail_rect)",
            "briefing.text != expected_visible",
            "briefing.tooltip_text != full_briefing",
            "army.text != expected_army",
            "army.tooltip_text != full_army",
            'visible_lines[1].ends_with("…")',
            'String(visible_lines[1]).contains("...")',
            "briefing.autowrap_mode != TextServer.AUTOWRAP_OFF",
            "not briefing.clip_text",
            "briefing.text_overrun_behavior != TextServer.OVERRUN_TRIM_WORD_ELLIPSIS",
            "not panel_rect.encloses(label_rect)",
            "not hero_panel.get_global_rect().encloses(army_rect)",
            "width == 1280 and army_text_width <= army_rect.size.x + 0.5",
            "get_window().size = original_window_size",
            "session.to_dict() != authority_before",
        ))
        ensure(all(index >= 0 for index in focused_order) and list(focused_order) == sorted(focused_order), errors, "Focused rail proof must capture independent source, resize, compare exact visible/full values and geometry, restore, then verify authority")
        for required_token in (
            'expected_visible.contains("Basti...")',
            'expected_visible.contains("...")',
            'expected_army.ends_with("Strength 495")',
            "expected_army.length() > 42",
            "visible_lines.size() != 2",
            "String(visible_lines[0]).length() > 42",
            "String(visible_lines[1]).length() > 42",
            "not briefing.is_visible_in_tree()",
            "visible_rail_count < (2 if width == 1280 else 4)",
            "fitting_rail_count < 1",
        ):
            ensure(required_token in focused_body, errors, f"Focused rail proof is missing exact budget/mid-token token: {required_token}")
        for required_label in ("%Hero", "%Army", "%Heroes", "%Specialties", "%Spellbook", "%Artifacts", "%Event", "%Briefing", "%Commitment", "%Visibility", "%Objectives", "%Threats", "%Forecast", "%Context"):
            ensure(f'shell.get_node("{required_label}")' in focused_body, errors, f"Focused native rail proof is missing existing Label {required_label}")
        for forbidden_token in ('shell.call("_short_rail', 'shell.call("_compact_rail', 'shell.call("_trim_rail', 'shell.call("_refresh', "sort(", "erase(", ".text =", "queue_redraw", "set_text_overrun_behavior"):
            ensure(forbidden_token not in focused_body, errors, f"Focused rail proof must remain public, independent, and observation-only; forbidden {forbidden_token}")
    if expected_match is not None:
        expected_body = expected_match.group("body")
        for required_token in ('full_text.split("\\n", false)', 'posture.begins_with("Command posture:")', 'posture = "Posture: %s" % posture.trim_prefix("Command posture:").strip_edges()', 'posture.begins_with("Posture:")', 'objective.begins_with("Opening objectives:")', '_word_safe_rail_line_for_test(posture, 42)', '_word_safe_rail_line_for_test(objective, 42)'):
            ensure(required_token in expected_body, errors, f"Independent briefing rail control is missing exact source/order token: {required_token}")
        for forbidden_token in ("shell", "OverworldShell", "_compact_rail_text", "_trim_rail_visible_text", "sort(", "erase("):
            ensure(forbidden_token not in expected_body, errors, f"Independent briefing control must avoid production/canonicalization dependency: {forbidden_token}")
    if army_expected_match is not None:
        army_expected_body = army_expected_match.group("body")
        army_expected_order = tuple(army_expected_body.find(token) for token in (
            'full_text.split("\\n", false)',
            'String(lines[0]).strip_edges() != "Marching Army"',
            'String(lines[1]).strip_edges()',
            'detail.contains("troops")',
            'detail.contains("Strength")',
            '_word_safe_rail_line_for_test(detail, 42)',
            '_word_safe_rail_line_for_test("Army: %s" % selected, 42)',
        ))
        ensure(all(index >= 0 for index in army_expected_order) and list(army_expected_order) == sorted(army_expected_order), errors, "Independent Army rail control must drop the established heading, select the first detail, and apply both semantic trim stages")
        for forbidden_token in ("shell", "OverworldShell", "_compact_rail_text", "_trim_rail_visible_text", "_rail_prefixed_summary", "sort(", "erase("):
            ensure(forbidden_token not in army_expected_body, errors, f"Independent Army rail control must avoid production/canonicalization dependency: {forbidden_token}")
    if control_match is not None:
        control_body = control_match.group("body")
        for required_token in ('text.strip_edges().replace("\\n", " ")', "if normalized.length() <= max_chars:", "if max_chars <= 0:", "if max_chars == 1:", "var prefix := normalized.left(max_chars - 1).strip_edges()", 'var boundary := prefix.rfind(" ")', 'return "%s…" % prefix'):
            ensure(required_token in control_body, errors, f"Independent word-boundary control is missing exact token: {required_token}")
        for forbidden_token in ("shell", "OverworldShell", "_short_rail_text", "_short_text", "sort(", "erase(", "Label", "Control"):
            ensure(forbidden_token not in control_body, errors, f"Independent word-boundary control must avoid production/layout dependency: {forbidden_token}")
    if width_match is not None:
        width_body = width_match.group("body")
        width_order = tuple(width_body.find(token) for token in (
            'label.get_theme_font("font")',
            'label.get_theme_font_size("font_size")',
            "if font == null or font_size <= 0:",
            "for line_value in label.text.split(\"\\n\", false):",
            "font.get_string_size(String(line_value), HORIZONTAL_ALIGNMENT_LEFT, -1.0, font_size).x",
            "return widest",
        ))
        ensure(all(index >= 0 for index in width_order) and list(width_order) == sorted(width_order), errors, "Independent themed-width control must inspect the live Label font and every semantic line in order")
        for forbidden_token in ("shell", "OverworldShell", "_set_rail_text", "text_overrun_behavior", "tooltip", "sort(", "erase(", "call("):
            ensure(forbidden_token not in width_body, errors, f"Independent themed-width control must avoid production/canonicalization dependency: {forbidden_token}")


def validate_overworld_shell_release_polish(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    sidebar_ornament_path = ROOT / "scenes" / "overworld" / "OverworldSidebarOrnament.gd"
    visual_smoke_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    required_paths = (OVERWORLD_SCENE_PATH, OVERWORLD_SCRIPT_PATH, OVERWORLD_RULES_PATH, sidebar_ornament_path, visual_smoke_path)
    for path in required_paths:
        ensure(path.exists(), errors, f"Missing overworld-shell polish file: {path.relative_to(ROOT)}")
    if not all(path.exists() for path in required_paths):
        return

    overworld_scene_text = OVERWORLD_SCENE_PATH.read_text(encoding="utf-8")
    ensure_scene_nodes(
        overworld_scene_text,
        errors,
        "OverworldShell.tscn",
        [
            ("TopStrip", "PanelContainer"),
            ("EventPanel", "PanelContainer"),
            ("CommitmentPanel", "PanelContainer"),
            ("BriefingPanel", "PanelContainer"),
            ("MapPanel", "PanelContainer"),
            ("CommandBand", "PanelContainer"),
            ("ActionPanel", "PanelContainer"),
            ("OpenCommand", "Button"),
            ("OpenFrontier", "Button"),
            ("FrontierIndicator", "Label"),
            ("CommandSpine", "VBoxContainer"),
            ("ContextPanel", "PanelContainer"),
            ("CommandPanel", "PanelContainer"),
            ("FrontierPanel", "PanelContainer"),
            ("CloseCommand", "Button"),
            ("CloseFrontier", "Button"),
            ("HeroActions", "VBoxContainer"),
            ("ContextActions", "VBoxContainer"),
            ("SpecialtyActions", "VBoxContainer"),
            ("SpellActions", "VBoxContainer"),
            ("ArtifactActions", "VBoxContainer"),
            ("BriefingTitle", "Label"),
            ("Briefing", "Label"),
            ("Visibility", "Label"),
            ("Objectives", "Label"),
            ("Threats", "Label"),
            ("Forecast", "Label"),
            ("Event", "Label"),
            ("SaveSlot", "OptionButton"),
        ],
    )
    ensure(
        'name="MapColumn"' not in overworld_scene_text,
        errors,
        "OverworldShell.tscn must not keep the old map-column dashboard wrapper",
    )
    ensure(
        'name="SummaryStrip"' not in overworld_scene_text,
        errors,
        "OverworldShell.tscn must not keep contextual report panels embedded above the adventure map",
    )
    ensure(
        'type="TabContainer"' not in overworld_scene_text and 'name="SidebarTabs"' not in overworld_scene_text,
        errors,
        "OverworldShell.tscn must not reintroduce the cramped right-rail tab strip",
    )
    for removed_node in ("MapHint", "MarchPanel", "MoveNorth", "MoveSouth", "MoveWest", "MoveEast", "MoveState"):
        ensure(
            f'name="{removed_node}"' not in overworld_scene_text,
            errors,
            f"OverworldShell.tscn must not reintroduce permanent movement hint/control node {removed_node}",
        )
    for hidden_node, hidden_type in (
        ("CommitmentPanel", "PanelContainer"),
        ("CommandSpine", "VBoxContainer"),
        ("ContextPanel", "PanelContainer"),
        ("CommandPanel", "PanelContainer"),
        ("FrontierPanel", "PanelContainer"),
    ):
        ensure(
            "visible = false" in scene_node_block(overworld_scene_text, hidden_node, hidden_type),
            errors,
            f"OverworldShell.tscn must keep {hidden_node} hidden by default so it cannot reserve permanent map-side space",
        )
    ensure(
        scene_node_parent(overworld_scene_text, "MapPanel", "PanelContainer")
        == "ShellMargin/Shell/ShellPad/Content/BodyRow",
        errors,
        "OverworldShell.tscn must make MapPanel the direct dominant BodyRow surface",
    )
    ensure(
        scene_node_parent(overworld_scene_text, "SidebarShell", "PanelContainer")
        == "ShellMargin/Shell/ShellPad/Content/BodyRow",
        errors,
        "OverworldShell.tscn must keep one fixed right-side command spine beside the map",
    )
    ensure_scene_nodes(overworld_scene_text, errors, "OverworldShell.tscn", [("SidebarOrnament", "Control")])
    ornament_scene_block = scene_node_block(overworld_scene_text, "SidebarOrnament", "Control")
    for required_token in (
        'parent="ShellMargin/Shell/ShellPad/Content/BodyRow/SidebarShell"',
        "anchors_preset = 15",
        "anchor_right = 1.0",
        "anchor_bottom = 1.0",
        "mouse_filter = 2",
        'script = ExtResource("8_sidebar_ornament")',
    ):
        ensure(required_token in ornament_scene_block, errors, f"Overworld rail ornament scene ownership is missing: {required_token}")
    ensure(overworld_scene_text.find('name="SidebarOrnament"') < overworld_scene_text.find('name="SidebarPad"'), errors, "Overworld rail ornament must draw behind every existing rail card")
    ornament_text = sidebar_ornament_path.read_text(encoding="utf-8")
    for required_token in (
        'const MODEL := "quiet_cartographic_rail"',
        "const INK := Color(0.72, 0.58, 0.30, 0.13)",
        "mouse_filter = Control.MOUSE_FILTER_IGNORE",
        "focus_mode = Control.FOCUS_NONE",
        "_draw_chart_grid()",
        "_draw_route_trace()",
        "_draw_compass_rose()",
        "_draw_corner_registration()",
        '"grid_lines": 9',
        '"route_points": 5',
        '"compass_spokes": 8',
    ):
        ensure(required_token in ornament_text, errors, f"Overworld rail ornament is missing bounded passive visual token: {required_token}")
    for forbidden_token in ("_process", "_input", "_gui_input", "Input.", "SessionState", "OverworldRules", "set_process", "create_timer", "Tween", "Button", "Label", "TextureRect"):
        ensure(forbidden_token not in ornament_text, errors, f"Overworld rail ornament must remain passive and authority-free: {forbidden_token}")
    visual_smoke_text = visual_smoke_path.read_text(encoding="utf-8")
    ornament_test_block = gd_function_block(visual_smoke_text, "_assert_sidebar_ornament_contract")
    for required_token in (
        'shell.get_node_or_null("%SidebarOrnament")',
        '[Vector2i(1280, 720), Vector2i(1920, 1080)]',
        'String(contract.get("model", "")) == "quiet_cartographic_rail"',
        'float(contract.get("maximum_alpha", 1.0)) <= 0.13',
        "ornament.position == sidebar_pad.position",
        "ornament.size == sidebar_pad.size",
        "ornament.get_parent() == sidebar",
        "card_rects_before == card_rects_hidden",
        "card_rects_before == card_rects_restored",
        "session.to_dict() != authority_before",
    ):
        ensure(required_token in ornament_test_block, errors, f"Overworld rail ornament focused owner is missing exact geometry/authority token: {required_token}")
    for forbidden_token in ("ornament.set_position", "ornament.set_size", "queue_redraw", "create_timer", "Input.", "SessionState.set", "sort(", "erase("):
        ensure(forbidden_token not in ornament_test_block, errors, f"Overworld rail ornament focused owner must remain observational: {forbidden_token}")
    ensure(
        scene_node_parent(overworld_scene_text, "CommandBand", "PanelContainer")
        == "ShellMargin/Shell/ShellPad/Content",
        errors,
        "OverworldShell.tscn must keep CommandBand as a footer ribbon below the map stage",
    )
    ensure(
        "custom_minimum_size = Vector2(0, 74)" in overworld_scene_text,
        errors,
        "OverworldShell.tscn must keep the overworld command footer slim",
    )
    sidebar_prefix = "ShellMargin/Shell/ShellPad/Content/BodyRow/SidebarShell/"
    for node_name in ("TopStrip", "EventPanel", "CommitmentPanel", "BriefingPanel", "HeroPanel", "ActionPanel", "CommandSpine"):
        ensure(
            scene_node_parent(overworld_scene_text, node_name, "PanelContainer" if node_name != "CommandSpine" else "VBoxContainer").startswith(sidebar_prefix),
            errors,
            f"OverworldShell.tscn must keep {node_name} inside the light right-side status shell",
        )
    command_spine_prefix = "ShellMargin/Shell/ShellPad/Content/BodyRow/SidebarShell/SidebarPad/SidebarBox/CommandSpine"
    for node_name in ("ContextPanel", "CommandPanel", "FrontierPanel"):
        ensure(
            scene_node_parent(overworld_scene_text, node_name, "PanelContainer").startswith(command_spine_prefix),
            errors,
            f"OverworldShell.tscn must keep {node_name} as a hidden drawer section opened by explicit context/buttons",
        )
    footer_prefix = "ShellMargin/Shell/ShellPad/Content/CommandBand/"
    for node_name in ("ResourceChip", "StatusChip", "CueChip", "OrdersPanel", "SystemPanel"):
        ensure(
            scene_node_parent(overworld_scene_text, node_name, "PanelContainer").startswith(footer_prefix),
            errors,
            f"OverworldShell.tscn must keep {node_name} inside the slim footer ribbon",
        )
    for forbidden_text in ("Click route | WASD march", "Click adjacent tiles to march", "WASD march"):
        ensure(
            forbidden_text not in overworld_scene_text,
            errors,
            f"OverworldShell.tscn must not keep permanent movement explainer text: {forbidden_text}",
        )

    overworld_rules_text = OVERWORLD_RULES_PATH.read_text(encoding="utf-8")
    for required_token in (
        "const COMMAND_BRIEFING_KEY := \"command_briefing\"",
        "const COMMAND_RISK_FORECAST_KEY := \"command_risk_forecast\"",
        "func describe_status",
        "func describe_visibility_panel",
        "func describe_objective_board",
        "func describe_frontier_threats",
        "func describe_command_briefing",
        "func consume_command_briefing",
        "func describe_command_risk",
        "func describe_command_risk_forecast",
        "func consume_command_risk_forecast",
        "func describe_dispatch",
        "func _normalize_command_briefing",
        "func _normalize_command_risk_forecast",
        "func _command_briefing_lines",
        "func _command_briefing_orders_line",
        "func _command_risk_forecast",
        "func _command_risk_town_items",
        "func _command_risk_logistics_items",
        "func _command_risk_objective_items",
        "func _command_risk_posture_items",
        "func _command_risk_field_item",
        "Immediate orders:",
        "Logistics watch:",
        "Next-day posture:",
        "func _local_visible_threat_summary",
        "func _dispatch_context_brief",
        "func _terrain_name_at",
    ):
        ensure(required_token in overworld_rules_text, errors, f"OverworldRules.gd is missing required overworld-shell polish token: {required_token}")

    overworld_script_text = OVERWORLD_SCRIPT_PATH.read_text(encoding="utf-8")
