    ember_signal_source_path = ROOT / "art" / "overworld" / "source" / "trimmed" / "map_objects" / "distinct" / "ember_signal_post-trimmed.png"
    ember_signal_runtime_path = ROOT / "art" / "overworld" / "runtime" / "objects" / "landmarks" / "ember_signal_post.png"
    ember_signal_asset = object_assets.get("ember_signal_post", {})
    ember_signal_site_sprite = site_sprites.get("site_ember_signal_post", {})
    ensure(ember_signal_source_path.is_file() and png_size(ember_signal_source_path) == (1248, 1254), errors, "Ember Signal Post must retain its exact original generated transparent source cutout")
    ensure(ember_signal_runtime_path.is_file() and png_size(ember_signal_runtime_path) == (512, 512), errors, "Ember Signal Post runtime field sprite must remain an exact 512x512 PNG")
    if ember_signal_source_path.is_file():
        source_header = ember_signal_source_path.read_bytes()[:26]
        ensure(len(source_header) >= 26 and source_header[25] == 6, errors, "Ember Signal Post source cutout must retain an RGBA PNG alpha channel")
        ensure(hashlib.sha256(ember_signal_source_path.read_bytes()).hexdigest() == "791728c423795a973af6a2ecbdf8f50a62aefc8dc3a33395095a3ba6dc242089", errors, "Ember Signal Post original generated source cutout drifted")
    if ember_signal_runtime_path.is_file():
        runtime_header = ember_signal_runtime_path.read_bytes()[:26]
        ensure(len(runtime_header) >= 26 and runtime_header[25] == 6, errors, "Ember Signal Post runtime field sprite must retain an RGBA PNG alpha channel")
        ensure(hashlib.sha256(ember_signal_runtime_path.read_bytes()).hexdigest() == "f820d4c3f18d8b39b06efb0850123ae9e7a86ad14ec3fd3f5175326050bed3de", errors, "Ember Signal Post runtime field sprite drifted")
    ensure(ember_signal_asset == {
        "path": "res://art/overworld/runtime/objects/landmarks/ember_signal_post.png",
        "source_trimmed": "res://art/overworld/source/trimmed/map_objects/distinct/ember_signal_post-trimmed.png",
        "source_model": "built_in_image_gen_original_transparent_cutout",
        "asset_policy": "original_generated_runtime_sprite_no_homm3_art_import",
        "assigned_resource_site_id": "site_ember_signal_post",
        "distinct_sprite_assignment": True,
    }, errors, "Ember Signal Post manifest entry must retain exact original generated-art provenance and site ownership")
    ensure(ember_signal_site_sprite == {
        "asset_id": "ember_signal_post",
        "fit": "Distinct original Embercourt brazier, mirror, bell, and pennant outpost for the persistent signal-post identity.",
    }, errors, "Ember Signal Post resource site must retain its exact distinct field-sprite mapping")

    visual_text = (ROOT / "tests" / "overworld_visual_smoke.gd").read_text(encoding="utf-8")
    art_contract_block = gd_function_block(visual_text, "_assert_overworld_art_contract")
    signal_contract_start = art_contract_block.find("var signal_authority_before: Dictionary = session.to_dict()")
    signal_contract_block = art_contract_block[signal_contract_start:] if signal_contract_start >= 0 else ""
    for required_token in (
        'var signal_authority_before: Dictionary = session.to_dict()',
        'shell.call("validation_tile_presentation", 2, 3)',
        '_assert_art_sprite(signal_presentation, "ember_signal_post", false)',
        'signal_art.get("sprite_asset_ids", []) != ["ember_signal_post"]',
        'signal_art.get("sprite_footprints", []) != [{"width": 1, "height": 1}]',
        'var repeated_signal_presentation: Dictionary = shell.call("validation_tile_presentation", 2, 3)',
        'repeated_signal_presentation != signal_presentation or session.to_dict() != signal_authority_before',
    ):
        ensure(required_token in signal_contract_block, errors, f"Overworld visual smoke is missing exact Ember Signal Post field-sprite authority: {required_token}")
    for forbidden_token in (
        'unmapped faction outpost did not preserve procedural marker fallback',
        'fallback_presentation',
        '_resource_site_asset_ids[',
        'session.overworld[',
        'queue_redraw',
        'create_timer',
    ):
        ensure(forbidden_token not in signal_contract_block, errors, f"Ember Signal Post visual proof must not restore fallback or mutate renderer/game authority: {forbidden_token}")

    decorative_manifest_path = res_path_to_disk(str(manifest.get("decorative_object_sprite_manifest", "")))
    ensure(decorative_manifest_path.exists(), errors, "Overworld art manifest must reference the decorative object sprite manifest")
    if decorative_manifest_path.exists():
        decorative_manifest = load_json(decorative_manifest_path)
        ensure(str(decorative_manifest.get("schema_id", "")) == "aurelion_decorative_object_sprite_mapping_v1", errors, "Decorative object sprite manifest must use the expected schema id")
        source = decorative_manifest.get("source", {})
        ensure(isinstance(source, dict), errors, "Decorative object sprite manifest must record source provenance")
        if isinstance(source, dict):
            ensure("no_homm3" in str(source.get("asset_policy", "")).lower(), errors, "Decorative object sprite manifest must record the no-HoMM3-art import policy")
            ensure(int(source.get("preserved_existing_generated_sprite_count", 0)) == 16, errors, "Decorative object sprite manifest must preserve the 16 previously generated representative sprites")
            ensure(int(source.get("new_generated_sprite_count", 0)) == 184, errors, "Decorative object sprite manifest must record 184 newly generated distinct sprites")
            generated_batches = source.get("generated_batches", [])
            ensure(isinstance(generated_batches, list) and len(generated_batches) == 12, errors, "Decorative object sprite manifest must record 12 generated distinct source atlases")
            if isinstance(generated_batches, list):
                for batch in generated_batches:
                    ensure(isinstance(batch, dict), errors, "Decorative generated batch provenance must be a dictionary")
                    if not isinstance(batch, dict):
                        continue
                    source_atlas_path = res_path_to_disk(str(batch.get("workspace_source_atlas", "")))
                    ensure(source_atlas_path.exists(), errors, f"Decorative object sprite source atlas is missing: {batch.get('workspace_source_atlas')}")
        legacy_archetype_asset_ids = decorative_manifest.get("legacy_archetype_asset_ids", [])
        distinct_asset_ids = decorative_manifest.get("distinct_asset_ids", [])
        mappings = decorative_manifest.get("object_sprite_mappings", {})
        coverage = decorative_manifest.get("coverage", {})
        ensure(isinstance(legacy_archetype_asset_ids, list) and len(legacy_archetype_asset_ids) == 16, errors, "Decorative object sprite manifest must keep the 16 legacy generated representative asset ids")
        ensure(isinstance(distinct_asset_ids, list) and len(distinct_asset_ids) == 200, errors, "Decorative object sprite manifest must define 200 distinct asset ids")
        if isinstance(distinct_asset_ids, list):
            ensure(len(set(map(str, distinct_asset_ids))) == 200, errors, "Decorative object sprite manifest distinct_asset_ids must not reuse asset ids")
        ensure(isinstance(coverage, dict), errors, "Decorative object sprite manifest must record coverage")
        if isinstance(coverage, dict):
            ensure(int(coverage.get("authored_decoration_or_blocker_object_count", 0)) == 200, errors, "Decorative object sprite coverage must count 200 authored decorative/blocker objects")
            ensure(int(coverage.get("mapped_object_count", 0)) == 200, errors, "Decorative object sprite coverage must map 200 objects")
            ensure(int(coverage.get("distinct_asset_count", 0)) == 200, errors, "Decorative object sprite coverage must prove 200 distinct assets")
            ensure(int(coverage.get("new_distinct_asset_count", 0)) == 184, errors, "Decorative object sprite coverage must count 184 newly generated distinct assets")
            ensure(int(coverage.get("preserved_existing_asset_count", 0)) == 16, errors, "Decorative object sprite coverage must count 16 preserved generated assets")
        ensure(isinstance(mappings, dict), errors, "Decorative object sprite manifest must define object_sprite_mappings")
        map_objects = items_index(load_json(CONTENT_DIR / "map_objects.json"))
        decorative_object_ids = {
            object_id
            for object_id, obj in map_objects.items()
            if str(obj.get("primary_class", "")) == "decoration" or str(obj.get("family", "")) in {"blocker", "decoration"}
        }
        ensure(len(decorative_object_ids) == 200, errors, f"Expected 200 authored decorative/blocker map objects, found {len(decorative_object_ids)}")
        if isinstance(mappings, dict):
            ensure(decorative_object_ids.issubset(set(map(str, mappings.keys()))), errors, "Decorative object sprite manifest must map every authored decorative/blocker map object")
            mapped_asset_ids: list[str] = []
            for object_id in sorted(decorative_object_ids):
                entry = mappings.get(object_id, {})
                ensure(isinstance(entry, dict), errors, f"Decorative object mapping {object_id} must be a dictionary with provenance")
                if not isinstance(entry, dict):
                    continue
                asset_id = str(entry.get("asset_id", ""))
                mapped_asset_ids.append(asset_id)
                ensure(asset_id in object_assets, errors, f"Decorative object mapping {object_id} references missing object asset {asset_id}")
                ensure(str(entry.get("fit", "")) != "", errors, f"Decorative object mapping {object_id} must record its semantic-fit note")
            ensure(len(mapped_asset_ids) == 200 and len(set(mapped_asset_ids)) == 200, errors, "Decorative object mappings must assign one unique asset id per authored decorative/blocker object")
            if isinstance(distinct_asset_ids, list):
                ensure(set(mapped_asset_ids) == set(map(str, distinct_asset_ids)), errors, "Decorative object mappings must match the manifest distinct_asset_ids set")
        if isinstance(distinct_asset_ids, list):
            for asset_id in map(str, distinct_asset_ids):
                ensure(asset_id in object_assets, errors, f"Decorative distinct asset {asset_id} is missing from overworld object_assets")
                entry = object_assets.get(asset_id, {})
                if isinstance(entry, dict):
                    runtime_path = res_path_to_disk(str(entry.get("path", "")))
                    source_trimmed_path = res_path_to_disk(str(entry.get("source_trimmed", "")))
                    source_atlas_path = res_path_to_disk(str(entry.get("source_generated_atlas", "")))
                    ensure(str(entry.get("asset_policy", "")) == "original_generated_runtime_sprite_no_homm3_art_import", errors, f"Decorative distinct asset {asset_id} must record generated no-HoMM3 policy")
                    ensure(bool(entry.get("distinct_sprite_assignment", False)), errors, f"Decorative distinct asset {asset_id} must be marked as a distinct sprite assignment")
                    ensure(str(entry.get("assigned_decorative_object_id", "")) in decorative_object_ids, errors, f"Decorative distinct asset {asset_id} must record its assigned object id")
                    ensure(runtime_path.with_name(runtime_path.name + ".import").exists(), errors, f"Decorative distinct runtime asset is missing Godot import sidecar: {runtime_path.relative_to(ROOT)}.import")
                    ensure(source_trimmed_path.exists(), errors, f"Decorative distinct asset {asset_id} is missing trimmed source {entry.get('source_trimmed')}")
                    ensure(source_atlas_path.exists(), errors, f"Decorative distinct asset {asset_id} is missing generated source atlas {entry.get('source_generated_atlas')}")

    map_object_manifest_path = res_path_to_disk(str(manifest.get("map_object_sprite_manifest", "")))
    ensure(map_object_manifest_path.exists(), errors, "Overworld art manifest must reference the map object sprite manifest")
    if map_object_manifest_path.exists():
        map_object_manifest = load_json(map_object_manifest_path)
        ensure(str(map_object_manifest.get("schema_id", "")) == "aurelion_map_object_sprite_mapping_v1", errors, "Map object sprite manifest must use the expected schema id")
        source = map_object_manifest.get("source", {})
        ensure(isinstance(source, dict), errors, "Map object sprite manifest must record source provenance")
        if isinstance(source, dict):
            ensure("no_homm3" in str(source.get("asset_policy", "")).lower(), errors, "Map object sprite manifest must record the no-HoMM3-art import policy")
            ensure(int(source.get("new_generated_sprite_count", 0)) >= 204, errors, "Map object sprite manifest must retain all baseline distinct non-decoration sprites")
            generated_batches = source.get("generated_batches", [])
            ensure(isinstance(generated_batches, list) and len(generated_batches) >= 17, errors, "Map object sprite manifest must retain the baseline generated source batches")
            if isinstance(generated_batches, list):
                for batch in generated_batches:
                    ensure(isinstance(batch, dict), errors, "Map object generated batch provenance must be a dictionary")
                    if not isinstance(batch, dict):
                        continue
                    source_owner = str(batch.get("workspace_source_atlas", batch.get("workspace_source_manifest", "")))
                    source_owner_path = res_path_to_disk(source_owner)
                    ensure(bool(source_owner) and source_owner_path.exists(), errors, f"Map object source batch owner is missing: {source_owner}")
        distinct_asset_ids = map_object_manifest.get("distinct_asset_ids", [])
        mappings = map_object_manifest.get("object_sprite_mappings", {})
        coverage = map_object_manifest.get("coverage", {})
        map_objects = items_index(load_json(CONTENT_DIR / "map_objects.json"))
        decorative_object_ids = {
            object_id
            for object_id, obj in map_objects.items()
            if str(obj.get("primary_class", "")) == "decoration" or str(obj.get("family", "")) in {"blocker", "decoration"}
        }
        non_decorative_object_ids = set(map_objects.keys()) - decorative_object_ids
        ensure(len(non_decorative_object_ids) >= 204, errors, f"Expected at least 204 authored non-decoration map objects, found {len(non_decorative_object_ids)}")
        ensure(isinstance(distinct_asset_ids, list) and len(distinct_asset_ids) == len(non_decorative_object_ids), errors, "Map object sprite manifest must define one distinct asset id per non-decoration object")
        if isinstance(distinct_asset_ids, list):
            ensure(len(set(map(str, distinct_asset_ids))) == len(distinct_asset_ids), errors, "Map object sprite distinct_asset_ids must not reuse asset ids")
        ensure(isinstance(coverage, dict), errors, "Map object sprite manifest must record coverage")
        if isinstance(coverage, dict):
            ensure(int(coverage.get("authored_map_object_count", 0)) == len(map_objects), errors, "Map object sprite coverage must count all authored map objects")
            ensure(int(coverage.get("foundation_decorative_or_blocker_distinct_count", 0)) == 200, errors, "Map object sprite coverage must preserve the 200 decorative/blocker distinct assignments")
            ensure(int(coverage.get("preexisting_unique_non_decorative_count", -1)) == 0, errors, "Map object sprite coverage must not retain the eight former generic foundation assignments")
            ensure(int(coverage.get("new_distinct_non_decorative_asset_count", 0)) == len(non_decorative_object_ids), errors, "Map object sprite coverage must count every exact non-decoration assignment")
            ensure(int(coverage.get("total_distinct_authored_map_object_count_after_pass", 0)) == len(map_objects), errors, "Map object sprite coverage must prove all authored map objects have distinct assignments after the pass")
        ensure(isinstance(mappings, dict), errors, "Map object sprite manifest must define object_sprite_mappings")
        if isinstance(mappings, dict):
            ensure(len(mappings) == len(non_decorative_object_ids) and set(map(str, mappings)) == non_decorative_object_ids, errors, "Map object sprite manifest must map all authored non-decoration objects")
            mapped_asset_ids: list[str] = []
            for object_id, entry in mappings.items():
                ensure(str(object_id) in non_decorative_object_ids, errors, f"Map object sprite mapping references unexpected object {object_id}")
                ensure(isinstance(entry, dict), errors, f"Map object sprite mapping {object_id} must be a dictionary with provenance")
                if not isinstance(entry, dict):
                    continue
                asset_id = str(entry.get("asset_id", ""))
                mapped_asset_ids.append(asset_id)
                ensure(asset_id in object_assets, errors, f"Map object sprite mapping {object_id} references missing object asset {asset_id}")
                ensure(str(entry.get("fit", "")) != "", errors, f"Map object sprite mapping {object_id} must record its semantic-fit note")
            ensure(len(mapped_asset_ids) == len(non_decorative_object_ids) and len(set(mapped_asset_ids)) == len(non_decorative_object_ids), errors, "Map object sprite mappings must assign one unique asset id per authored non-decoration object")
            if isinstance(distinct_asset_ids, list):
                ensure(set(mapped_asset_ids) == set(map(str, distinct_asset_ids)), errors, "Map object sprite mappings must match the manifest distinct_asset_ids set")
        if isinstance(distinct_asset_ids, list):
            for asset_id in map(str, distinct_asset_ids):
                ensure(asset_id in object_assets, errors, f"Map object distinct asset {asset_id} is missing from overworld object_assets")
                entry = object_assets.get(asset_id, {})
                if isinstance(entry, dict):
                    runtime_path = res_path_to_disk(str(entry.get("path", "")))
                    source_trimmed_path = res_path_to_disk(str(entry.get("source_trimmed", "")))
                    source_owner_path = res_path_to_disk(str(entry.get("source_generated_atlas", entry.get("source_generated", ""))))
                    ensure(str(entry.get("asset_policy", "")) == "original_generated_runtime_sprite_no_homm3_art_import", errors, f"Map object distinct asset {asset_id} must record generated no-HoMM3 policy")
                    ensure(bool(entry.get("distinct_sprite_assignment", False)), errors, f"Map object distinct asset {asset_id} must be marked as a distinct sprite assignment")
                    ensure(str(entry.get("assigned_map_object_id", "")) in non_decorative_object_ids, errors, f"Map object distinct asset {asset_id} must record its assigned map object id")
                    ensure(runtime_path.with_name(runtime_path.name + ".import").exists(), errors, f"Map object distinct runtime asset is missing Godot import sidecar: {runtime_path.relative_to(ROOT)}.import")
                    ensure(source_trimmed_path.exists(), errors, f"Map object distinct asset {asset_id} is missing trimmed source {entry.get('source_trimmed')}")
                    ensure(source_owner_path.exists(), errors, f"Map object distinct asset {asset_id} is missing its generated source owner")

