def validate_overworld_compact_town_owner_pennants(errors: list[str]) -> None:
    def gdscript_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    map_path = ROOT / "scenes" / "overworld" / "OverworldMapView.gd"
    focused_path = ROOT / "tests" / "overworld_town_pennant_runtime_report.gd"
    focused_scene_path = ROOT / "tests" / "overworld_town_pennant_runtime_report.tscn"
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    paths = (map_path, focused_path, focused_scene_path, visual_path)
    for path in paths:
        ensure(path.is_file(), errors, f"Missing compact town-pennant owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in paths):
        return

    map_text = map_path.read_text(encoding="utf-8")
    focused_text = focused_path.read_text(encoding="utf-8")
    focused_scene = focused_scene_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    for token in (
        'const TOWN_OWNER_PENNANT_MODEL := "single_pass_compact_heraldic_cloth_pennant"',
        "const TOWN_OWNER_PENNANT_WIDTH_FACTOR := 0.052",
        "const TOWN_OWNER_PENNANT_HEIGHT_FACTOR := 0.040",
        "const TOWN_OWNER_PENNANT_POLE_HEIGHT_FACTOR := 0.128",
        "const TOWN_OWNER_PENNANT_LEGACY_WIDTH_FACTOR := 0.17",
        "const TOWN_OWNER_PENNANT_LEGACY_HEIGHT_FACTOR := 0.12",
        "const TOWN_OWNER_PENNANT_CLOTH_ALPHA := 0.96",
        "const TOWN_OWNER_PENNANT_MEMORY_ALPHA := 0.68",
        "const TOWN_OWNER_PENNANT_SHADOW_ALPHA := 0.42",
        "const TOWN_OWNER_PENNANT_FOLD_ALPHA := 0.34",
        "const TOWN_OWNER_PENNANT_HIGHLIGHT_ALPHA := 0.42",
        "const TOWN_OWNER_PENNANT_SHADOW_OFFSET_FACTOR := 0.010",
        "const TOWN_OWNER_PENNANT_OUTLINE_WIDTH_FACTOR := 0.014",
    ):
        ensure(map_text.count(token) == 1, errors, f"Compact town pennant must own one exact presentation constant: {token}")

    draw_block = gdscript_function_block(map_text, "_draw_town_owner_pennant")
    profile_block = gdscript_function_block(map_text, "_town_owner_pennant_profile")
    variants_block = gdscript_function_block(map_text, "validation_town_owner_pennant_variants")
    payload_block = gdscript_function_block(map_text, "_town_owner_pennant_validation_payload")
    ensure(all((draw_block, profile_block, variants_block, payload_block)), errors, "Could not isolate compact town-pennant production and validation ownership")
    if draw_block:
        ordered_tokens = (
            "var profile := _town_owner_pennant_profile(",
            "_canvas_draw_line(\n\t\tpole_bottom + shadow_offset",
            "_canvas_draw_colored_polygon(shadow_points",
            "_canvas_draw_line(pole_bottom, pole_top",
            "_canvas_draw_colored_polygon(cloth_points",
            "_canvas_draw_polyline(outline_points",
            "if fold_line.size() == 2:",
            "if highlight_line.size() == 2:",
            "_canvas_draw_circle(pole_top",
            'if bool(profile.get("color_cue_assist", false)):',
            "_draw_town_owner_flag_mark(",
        )
        ensure(all(token in draw_block for token in ordered_tokens), errors, "Town-pennant drawing is missing its ordered single-pass cloth composition")
        if all(token in draw_block for token in ordered_tokens):
            ensure([draw_block.index(token) for token in ordered_tokens] == sorted(draw_block.index(token) for token in ordered_tokens), errors, "Town-pennant draw order must remain shadow, pole, one cloth, contour, stitching, finial, optional assist mark")
        ensure(draw_block.count("_canvas_draw_colored_polygon(cloth_points") == 1, errors, "Town pennant must paint exactly one owner-colored cloth polygon")
        for forbidden in ("_canvas_draw_rect(", "await ", "create_timer", "create_tween", "queue_redraw", "session.", "_session."):
            ensure(forbidden not in draw_block, errors, f"Town-pennant draw must remain synchronous presentation only: {forbidden}")
    if profile_block:
        for token in (
            "var width := extent * TOWN_OWNER_PENNANT_WIDTH_FACTOR",
            "var height := extent * TOWN_OWNER_PENNANT_HEIGHT_FACTOR",
            'var shape_id := "compact_forked"',
            "if not color_cue_assist:",
            'shape_id = "compact_square_folded"',
            'shape_id = "compact_tapered"',
            'shape_id = "compact_diamond"',
            "var cloth_alpha := TOWN_OWNER_PENNANT_MEMORY_ALPHA if remembered else TOWN_OWNER_PENNANT_CLOTH_ALPHA",
            '"single_pass_draw_count": 1',
            '"cloth_layer_count": 1',
            '"painted_area_ratio_to_legacy": (TOWN_OWNER_PENNANT_WIDTH_FACTOR * TOWN_OWNER_PENNANT_HEIGHT_FACTOR) / (TOWN_OWNER_PENNANT_LEGACY_WIDTH_FACTOR * TOWN_OWNER_PENNANT_LEGACY_HEIGHT_FACTOR)',
        ):
            ensure(token in profile_block, errors, f"Town-pennant profile is missing exact compact/differentiated geometry: {token}")
        for forbidden in ("_session", "session.", "Input.", "await ", "create_timer", "queue_redraw", "_canvas_draw", ".erase(", "sort_custom"):
            ensure(forbidden not in profile_block, errors, f"Town-pennant profile must remain detached, deterministic geometry: {forbidden}")
    ensure(map_text.count("_draw_town_owner_pennant(") == 3, errors, "Town pennant must have one definition and exactly one draw call in sprite and procedural-town paths")
    if variants_block:
        for token in (
            "for remembered in [false, true]:",
            "for color_cue_assist in [false, true]:",
            'for owner in ["player", "enemy", "neutral"]:',
            "_town_owner_pennant_profile(rect, color, remembered, owner, color_cue_assist)",
            '"live_owner": _town_owner_id(town)',
            '"variant_count": variants.size()',
        ):
            ensure(token in variants_block, errors, f"Public town-pennant validation is missing exact 12-variant ownership: {token}")
        for forbidden in ("_draw_town_owner_pennant(", "await ", "create_timer", "queue_redraw", "Input.", ".erase("):
            ensure(forbidden not in variants_block, errors, f"Town-pennant validation must remain read-only: {forbidden}")
    if payload_block:
        for token in (
            '"cloth_contained": rect.encloses(_points_bounds(cloth_points))',
            '"shadow_contained": rect.encloses(_points_bounds(shadow_points))',
            '"pole_contained": rect.has_point(profile.get("pole_top", Vector2.ZERO)) and rect.has_point(profile.get("pole_bottom", Vector2.ZERO))',
            '"painted_area_ratio_to_legacy": float(profile.get("painted_area_ratio_to_legacy", 1.0))',
        ):
            ensure(token in payload_block, errors, f"Town-pennant validation payload is missing actual containment/area evidence: {token}")

    ensure_scene_nodes(focused_scene, errors, "overworld_town_pennant_runtime_report.tscn", [("OverworldTownPennantRuntimeReport", "Node")])
    for token in (
        'const VIEWPORT_SIZES := [Vector2i(1280, 720), Vector2i(1920, 1080)]',
        'const EXPECTED_VARIANT_COUNT := 12',
        'var authority_before: Dictionary = session.to_dict()',
        'map_view.call("validation_town_owner_pennant_variants", entry_tile)',
        'shell.call("validation_tile_presentation", entry_tile.x, entry_tile.y)',
        'for owner in ["player", "enemy", "neutral"]:',
        'for remembered in [false, true]:',
        'for assist in [false, true]:',
        'String(variant.get("shape_id", "")) == expected_shape',
        'int(variant.get("single_pass_draw_count", 0)) == 1',
        'int(variant.get("cloth_layer_count", 0)) == 1',
        'expected_ratio < 0.75',
        'session.to_dict() == authority_before',
        'print("OVERWORLD_TOWN_PENNANT_RUNTIME_REPORT %s"',
    ):
        ensure(token in focused_text, errors, f"Focused town-pennant owner is missing exact runtime proof: {token}")
    ensure(focused_text.count("for viewport_size in VIEWPORT_SIZES:") == 1, errors, "Focused town-pennant owner must run exactly the registered two widths")
    for forbidden in ("_draw_town_owner_pennant(", "_town_owner_pennant_profile(", "create_timer", "create_tween", "OS.delay", 'session.overworld["towns"] ='):
        ensure(forbidden not in focused_text, errors, f"Focused town-pennant owner must observe public production geometry without bypass/mutation: {forbidden}")
    for token in (
        'String(town_presentation.get("owner_pennant_model", "")) != "single_pass_compact_heraldic_cloth_pennant"',
        'int(owner_pennant.get("single_pass_draw_count", 0)) != 1',
        'int(owner_pennant.get("cloth_layer_count", 0)) != 1',
        'float(owner_pennant.get("painted_area_ratio_to_legacy", 1.0)) >= 0.75',
        'var expected_pennant_alpha := 0.68 if remembered else 0.96',
        'String(town_presentation.get("sprite_silhouette_model", "")) != "eight_direction_alpha_silhouette_outline"',
        'float(town_presentation.get("sprite_silhouette_width_factor", 0.0)) < 0.010',
    ):
        ensure(token in visual_text, errors, f"Broad Overworld visual smoke is missing compact town-pennant compatibility proof: {token}")


def validate_overworld_town_selection_cartographic_perimeter(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    map_path = ROOT / "scenes" / "overworld" / "OverworldMapView.gd"
    focused_path = ROOT / "tests" / "overworld_faction_hero_sprite_runtime_report.gd"
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (map_path, focused_path, visual_path):
        ensure(path.is_file(), errors, f"Missing Overworld town-selection cartographic perimeter owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in (map_path, focused_path, visual_path)):
        return

    map_text = map_path.read_text(encoding="utf-8")
    focused_text = focused_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    for token in (
        'const TOWN_SELECTION_VISUAL_MODEL := "open_cartographic_footprint_corner_and_midpoint_ticks"',
        "const TOWN_SELECTION_PERIMETER_INSET_FACTOR := 0.045",
        "const TOWN_SELECTION_CORNER_ALPHA := 0.78",
        "const TOWN_SELECTION_CORNER_LENGTH_FACTOR := 0.10",
        "const TOWN_SELECTION_CORNER_WIDTH_FACTOR := 0.010",
        "const TOWN_SELECTION_MIDPOINT_ALPHA := 0.34",
        "const TOWN_SELECTION_MIDPOINT_LENGTH_FACTOR := 0.035",
        "const TOWN_SELECTION_MIDPOINT_WIDTH_FACTOR := 0.008",
        'const TILE_SELECTION_VISUAL_MODEL := "open_cartographic_tile_corner_and_midpoint_ticks"',
        "const TILE_SELECTION_PERIMETER_INSET_FACTOR := 0.085",
        "const TILE_SELECTION_CORNER_ALPHA := 0.82",
        "const TILE_SELECTION_CORNER_LENGTH_FACTOR := 0.18",
        "const TILE_SELECTION_CORNER_WIDTH_FACTOR := 0.022",
        "const TILE_SELECTION_MIDPOINT_ALPHA := 0.42",
        "const TILE_SELECTION_MIDPOINT_LENGTH_FACTOR := 0.08",
        "const TILE_SELECTION_MIDPOINT_WIDTH_FACTOR := 0.016",
    ):
        ensure(map_text.count(token) == 1, errors, f"Town-selection cartographic perimeter must own one exact visual constant: {token}")

    draw_block = gd_function_block(map_text, "_draw_tile_focus")
    layout_block = gd_function_block(map_text, "_tile_focus_layout")
    profile_block = gd_function_block(map_text, "_town_selection_visual_profile")
    perimeter_block = gd_function_block(map_text, "_draw_town_selection_perimeter")
    tile_profile_block = gd_function_block(map_text, "_tile_selection_visual_profile")
    tile_reticle_block = gd_function_block(map_text, "_draw_tile_selection_reticle")
    corners_block = gd_function_block(map_text, "_draw_cartographic_selection_corners")
    midpoints_block = gd_function_block(map_text, "_draw_cartographic_selection_midpoints")
    validation_block = gd_function_block(map_text, "validation_tile_focus_layout")
    ensure(all((draw_block, layout_block, profile_block, perimeter_block, tile_profile_block, tile_reticle_block, corners_block, midpoints_block, validation_block)), errors, "Could not isolate Overworld cartographic selection production ownership")
    if draw_block:
        order = tuple(draw_block.find(token) for token in (
            'var selection_rect: Rect2 = layout.get("selection_rect", rect)',
            'if bool(layout.get("selection_uses_cartographic_town_perimeter", false)):',
            "_draw_town_selection_perimeter(selection_rect)",
            'elif bool(layout.get("selection_uses_cartographic_tile_reticle", false)):',
            "_draw_tile_selection_reticle(selection_rect)",
            'if tile == _hover_tile:',
        ))
        ensure(all(index >= 0 for index in order) and list(order) == sorted(order), errors, "Selection drawing must choose the town perimeter or ordinary tile reticle before hover drawing")
        for forbidden in ('Color(SELECTION_COLOR.r, SELECTION_COLOR.g, SELECTION_COLOR.b, 0.10)', '_canvas_draw_rect(selection_rect.grow(-5.0)', '_draw_selection_corners('):
            ensure(forbidden not in draw_block, errors, f"Ordinary selected-tile drawing must not retain the dominant filled/continuous treatment: {forbidden}")
    if layout_block:
        for token in (
            '"selection_rect": town_rect',
            '"selection_uses_town_footprint_rect": uses_town_footprint',
            '"selection_uses_interior_fill": false',
            '"selection_uses_cartographic_town_perimeter": uses_town_footprint',
            '"selection_uses_cartographic_tile_reticle": not uses_town_footprint',
            '"selection_visual_model": TOWN_SELECTION_VISUAL_MODEL if uses_town_footprint else TILE_SELECTION_VISUAL_MODEL',
            '"hover_rect": town_rect',
        ):
            ensure(token in layout_block, errors, f"Town focus layout is missing exact geometry/visual ownership: {token}")
    if profile_block:
        for token in (
            "minf(rect.size.x, rect.size.y)",
            "maxf(4.0, extent * TOWN_SELECTION_PERIMETER_INSET_FACTOR)",
            "maxf(10.0, extent * TOWN_SELECTION_CORNER_LENGTH_FACTOR)",
            "maxf(1.5, extent * TOWN_SELECTION_CORNER_WIDTH_FACTOR)",
            "maxf(6.0, extent * TOWN_SELECTION_MIDPOINT_LENGTH_FACTOR)",
            "maxf(1.25, extent * TOWN_SELECTION_MIDPOINT_WIDTH_FACTOR)",
            '"perimeter_rect": rect.grow(-perimeter_inset)',
            '"corner_alpha": TOWN_SELECTION_CORNER_ALPHA',
            '"midpoint_alpha": TOWN_SELECTION_MIDPOINT_ALPHA',
            '"continuous_outline": false',
            '"interior_fill_alpha": 0.0',
        ):
            ensure(token in profile_block, errors, f"Town selection visual profile is missing exact derived geometry: {token}")
        for forbidden in ("_session", "session.", "_selected_tile", "_hero_tile", "Input.", "await ", "create_timer", "queue_redraw", ".erase("):
            ensure(forbidden not in profile_block, errors, f"Town selection visual profile must remain pure and read-only: {forbidden}")
    if perimeter_block:
        for token in (
            "var profile := _town_selection_visual_profile(rect)",
            "TOWN_SELECTION_CORNER_ALPHA",
            "TOWN_SELECTION_MIDPOINT_ALPHA",
            "_draw_cartographic_selection_corners(perimeter_rect, corner_color, corner_width, corner_length)",
            "_draw_cartographic_selection_midpoints(perimeter_rect, midpoint_color, midpoint_width, midpoint_length)",
        ):
            ensure(token in perimeter_block, errors, f"Town selection perimeter draw is missing exact visual ownership: {token}")
        for forbidden in ("_canvas_draw_rect(", "await ", "create_timer", "create_tween", "Input.", "session.", "_session"):
            ensure(forbidden not in perimeter_block, errors, f"Town selection perimeter must remain fill-free and presentation-only: {forbidden}")
    if tile_profile_block:
        for token in (
            "minf(rect.size.x, rect.size.y)",
            "maxf(4.0, extent * TILE_SELECTION_PERIMETER_INSET_FACTOR)",
            "maxf(8.0, extent * TILE_SELECTION_CORNER_LENGTH_FACTOR)",
            "maxf(1.5, extent * TILE_SELECTION_CORNER_WIDTH_FACTOR)",
            "maxf(5.0, extent * TILE_SELECTION_MIDPOINT_LENGTH_FACTOR)",
            "maxf(1.25, extent * TILE_SELECTION_MIDPOINT_WIDTH_FACTOR)",
            '"perimeter_rect": rect.grow(-perimeter_inset)',
            '"corner_alpha": TILE_SELECTION_CORNER_ALPHA',
            '"midpoint_alpha": TILE_SELECTION_MIDPOINT_ALPHA',
            '"continuous_outline": false',
            '"interior_fill_alpha": 0.0',
        ):
            ensure(token in tile_profile_block, errors, f"Ordinary tile selection profile is missing exact open-reticle geometry: {token}")
        for forbidden in ("_session", "session.", "_selected_tile", "_hero_tile", "Input.", "await ", "create_timer", "queue_redraw", ".erase("):
            ensure(forbidden not in tile_profile_block, errors, f"Ordinary tile selection profile must remain pure and read-only: {forbidden}")
    if tile_reticle_block:
        for token in (
            "var profile := _tile_selection_visual_profile(rect)",
            "TILE_SELECTION_CORNER_ALPHA",
            "TILE_SELECTION_MIDPOINT_ALPHA",
            "_draw_cartographic_selection_corners(perimeter_rect, corner_color",
            "_draw_cartographic_selection_midpoints(perimeter_rect, midpoint_color",
        ):
            ensure(token in tile_reticle_block, errors, f"Ordinary tile reticle draw is missing exact visual ownership: {token}")
        for forbidden in ("_canvas_draw_rect(", "await ", "create_timer", "create_tween", "Input.", "session.", "_session"):
            ensure(forbidden not in tile_reticle_block, errors, f"Ordinary tile reticle must remain fill-free and presentation-only: {forbidden}")
    if corners_block:
        ensure(corners_block.count("_canvas_draw_line(") == 8, errors, "Town cartographic selection must draw exactly two short ticks at each of four corners")
        for forbidden in ("0.22", "0.075", "_draw_selection_corners", "await ", "create_timer"):
            ensure(forbidden not in corners_block, errors, f"Town cartographic corners must avoid the old long-bracket geometry or timing paths: {forbidden}")
    if midpoints_block:
        ensure(midpoints_block.count("_canvas_draw_line(") == 4, errors, "Town cartographic selection must draw exactly one subtle registration tick at each footprint edge midpoint")
        for forbidden in ("_canvas_draw_rect(", "_draw_selection_corners", "await ", "create_timer"):
            ensure(forbidden not in midpoints_block, errors, f"Town cartographic midpoint ticks must remain open and timing-free: {forbidden}")
    ensure("func _draw_selection_corners(" not in map_text, errors, "The superseded long-corner ordinary selection helper must be removed")
    if validation_block:
        for token in (
            'var town_selection_visual_profile := _town_selection_visual_profile(selection_rect) if bool(layout.get("selection_uses_cartographic_town_perimeter", false)) else {}',
            'town_selection_visual_profile["perimeter_rect"] = _rect_payload(town_selection_visual_profile.get("perimeter_rect", selection_rect))',
            'var tile_selection_visual_profile := _tile_selection_visual_profile(selection_rect) if bool(layout.get("selection_uses_cartographic_tile_reticle", false)) else {}',
            'tile_selection_visual_profile["perimeter_rect"] = _rect_payload(tile_selection_visual_profile.get("perimeter_rect", selection_rect))',
            '"selection_uses_cartographic_town_perimeter": bool(layout.get("selection_uses_cartographic_town_perimeter", false))',
            '"selection_uses_cartographic_tile_reticle": bool(layout.get("selection_uses_cartographic_tile_reticle", false))',
            '"selection_visual_model": String(layout.get("selection_visual_model", ""))',
            '"town_selection_visual_profile": town_selection_visual_profile.duplicate(true)',
            '"tile_selection_visual_profile": tile_selection_visual_profile.duplicate(true)',
        ):
            ensure(token in validation_block, errors, f"Public focus validation is missing detached town-selection visual evidence: {token}")
        for forbidden in ("_draw_town_selection_perimeter(", "_draw_cartographic_selection_corners(", "_draw_cartographic_selection_midpoints(", "await ", "create_timer", "Input."):
            ensure(forbidden not in validation_block, errors, f"Town selection validation must remain public/read-only and avoid {forbidden}")

    for text, owner in ((focused_text, "focused faction-hero owner"), (visual_text, "broad Overworld visual owner")):
        for token in (
            '"open_cartographic_footprint_corner_and_midpoint_ticks"',
            'selection_uses_cartographic_town_perimeter',
            'town_selection_visual_profile',
            '0.045',
            '0.78',
            '0.10',
            '0.010',
            '0.34',
            '0.035',
            '0.008',
            'continuous_outline',
            'interior_fill_alpha',
            '"open_cartographic_tile_corner_and_midpoint_ticks"',
            'selection_uses_cartographic_tile_reticle',
            'tile_selection_visual_profile',
            '0.085',
            '0.82',
            '0.18',
            '0.022',
            '0.42',
            '0.08',
            '0.016',
        ):
            ensure(token in text, errors, f"{owner} is missing exact town-selection cartographic proof: {token}")
        for forbidden in ("_draw_town_selection_perimeter(", "_draw_cartographic_selection_corners(", "_draw_cartographic_selection_midpoints(", "_town_selection_visual_profile(", "create_timer", "create_tween"):
            ensure(forbidden not in text, errors, f"{owner} must observe only public production geometry and avoid {forbidden}")
    ensure('String(ordinary_layout.get("selection_visual_model", "")) == "open_cartographic_tile_corner_and_midpoint_ticks"' in focused_text, errors, "Focused owner must require the exact ordinary open selected-tile reticle")
    ensure('String(focus_layout.get("selection_visual_model", "")) != "open_cartographic_tile_corner_and_midpoint_ticks"' in visual_text, errors, "Broad Overworld visual owner must require the exact ordinary open selected-tile reticle")


def validate_overworld_cartographic_hover_reticle(errors: list[str]) -> None:
    def function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    map_path = ROOT / "scenes" / "overworld" / "OverworldMapView.gd"
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (map_path, visual_path):
        ensure(path.is_file(), errors, f"Missing Overworld cartographic hover-reticle owner: {path.relative_to(ROOT)}")
    if not map_path.is_file() or not visual_path.is_file():
        return

    map_text = map_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    for token in (
        'const HOVER_COLOR := Color(0.92, 0.95, 0.98, 0.55)',
        'const HOVER_RETICLE_VISUAL_MODEL := "open_cartographic_hover_corners"',
        'const HOVER_RETICLE_PERIMETER_INSET_FACTOR := 0.10',
        'const HOVER_RETICLE_PERIMETER_INSET_MIN_PX := 6.0',
        'const HOVER_RETICLE_PERIMETER_INSET_MAX_PX := 18.0',
        'const HOVER_RETICLE_CORNER_LENGTH_FACTOR := 0.12',
        'const HOVER_RETICLE_CORNER_LENGTH_MIN_PX := 6.0',
        'const HOVER_RETICLE_CORNER_LENGTH_MAX_PX := 18.0',
        'const HOVER_RETICLE_CORNER_WIDTH_FACTOR := 0.014',
        'const HOVER_RETICLE_CORNER_WIDTH_MIN_PX := 1.25',
        'const HOVER_RETICLE_CORNER_WIDTH_MAX_PX := 2.0',
        'const HOVER_RETICLE_SHADOW_ALPHA := 0.24',
        'const HOVER_RETICLE_SHADOW_WIDTH_ADD_PX := 1.25',
    ):
        ensure(map_text.count(token) == 1, errors, f"Cartographic hover reticle must own one exact visual constant: {token}")

    draw_focus = function_block(map_text, "_draw_tile_focus")
    profile = function_block(map_text, "_hover_reticle_visual_profile")
    draw_reticle = function_block(map_text, "_draw_cartographic_hover_reticle")
    layout = function_block(map_text, "_tile_focus_layout")
    validation = function_block(map_text, "validation_tile_focus_layout")
    hover_validation = function_block(map_text, "validation_hover_presentation")
    ensure(all((draw_focus, profile, draw_reticle, layout, validation, hover_validation)), errors, "Could not isolate Overworld cartographic hover-reticle ownership")
    if draw_focus:
        ensure('if tile == _hover_tile:\n\t\t_draw_cartographic_hover_reticle(layout.get("hover_visual_profile", {}))' in draw_focus, errors, "Live hover drawing must consume the resolved cartographic profile")
        ensure(draw_focus.find("if tile == _selected_tile:") < draw_focus.find("if tile == _hover_tile:"), errors, "Selected focus must retain draw priority before the subordinate hover reticle")
        for forbidden in ('_canvas_draw_rect(hover_rect.grow(-7.0), HOVER_COLOR, false, 2.0)', '_canvas_draw_rect(', '_canvas_draw_colored_polygon(', '_canvas_draw_polygon('):
            ensure(forbidden not in draw_focus, errors, f"Live hover drawing must not restore a generic continuous/fill treatment: {forbidden}")
    if profile:
        for token in (
            'var extent := minf(rect.size.x, rect.size.y)',
            'extent * HOVER_RETICLE_PERIMETER_INSET_FACTOR',
            'HOVER_RETICLE_PERIMETER_INSET_MIN_PX',
            'HOVER_RETICLE_PERIMETER_INSET_MAX_PX',
            'extent * HOVER_RETICLE_CORNER_LENGTH_FACTOR',
            'extent * HOVER_RETICLE_CORNER_WIDTH_FACTOR',
            '"model": HOVER_RETICLE_VISUAL_MODEL',
            '"perimeter_rect": rect.grow(-perimeter_inset)',
            '"corner_color": HOVER_COLOR',
            '"shadow_alpha": HOVER_RETICLE_SHADOW_ALPHA',
            '"shadow_width_px": corner_width + HOVER_RETICLE_SHADOW_WIDTH_ADD_PX',
            '"continuous_outline": false',
            '"interior_fill_alpha": 0.0',
        ):
            ensure(token in profile, errors, f"Hover profile is missing exact detached geometry: {token}")
        for forbidden in ("_session", "session.", "_hover_tile", "Input.", "await ", "create_timer", "create_tween", "queue_redraw", ".erase("):
            ensure(forbidden not in profile, errors, f"Hover profile must remain pure presentation geometry: {forbidden}")
    if draw_reticle:
        for token in (
            'var perimeter_rect: Rect2 = profile.get("perimeter_rect", Rect2())',
            'var shadow_color := Color(0.02, 0.025, 0.03, float(profile.get("shadow_alpha", HOVER_RETICLE_SHADOW_ALPHA)))',
            '_draw_cartographic_selection_corners(perimeter_rect, shadow_color, shadow_width, corner_length)',
            '_draw_cartographic_selection_corners(perimeter_rect, corner_color, corner_width, corner_length)',
        ):
            ensure(token in draw_reticle, errors, f"Hover reticle drawing is missing exact two-pass open corners: {token}")
        ensure(draw_reticle.find("shadow_color") < draw_reticle.find("corner_color") < draw_reticle.find("shadow_color, shadow_width") < draw_reticle.find("corner_color, corner_width"), errors, "Hover reticle must draw shadow then subdued foreground corners")
        for forbidden in ("_canvas_draw_rect(", "_canvas_draw_circle(", "_canvas_draw_colored_polygon(", "_draw_cartographic_selection_midpoints(", "await ", "create_timer", "create_tween", "session.", "_session"):
            ensure(forbidden not in draw_reticle, errors, f"Hover reticle must remain open, fill-free, and presentation-only: {forbidden}")
    if layout:
        for token in (
            '"hover_rect": town_rect',
            '"hover_uses_town_footprint_rect": uses_town_footprint',
            '"hover_visual_model": HOVER_RETICLE_VISUAL_MODEL',
            '"hover_visual_profile": _hover_reticle_visual_profile(town_rect)',
        ):
            ensure(token in layout, errors, f"Hover layout must preserve exact tile/town footprint ownership: {token}")
    if validation:
        for token in (
            'var hover_visual_profile: Dictionary = layout.get("hover_visual_profile", {}).duplicate(true)',
            'hover_visual_profile["perimeter_rect"] = _rect_payload(hover_visual_profile.get("perimeter_rect", hover_rect))',
            'hover_visual_profile["corner_color"] = _color_payload(hover_color)',
            '"hover_visual_model": String(layout.get("hover_visual_model", ""))',
            '"hover_visual_profile": hover_visual_profile',
        ):
            ensure(token in validation, errors, f"Public focus validation must detach exact hover geometry: {token}")
    if hover_validation:
        for token in (
            'func validation_hover_presentation() -> Dictionary:',
            '"active": false',
            '"hover_tile": _vector2i_payload(_hover_tile)',
            '"active": true',
            '"focus_layout": validation_tile_focus_layout(_hover_tile)',
        ):
            ensure(token in hover_validation, errors, f"Public hover observation is missing fail-closed live ownership: {token}")
        for forbidden in ("_gui_input(", "Input.", "push_input", "position =", "_hover_tile =", "await ", "create_timer", "queue_redraw"):
            ensure(forbidden not in hover_validation, errors, f"Public hover observation must remain read-only: {forbidden}")

    capture = function_block(visual_text, "_capture_object_scale_viewports")
    layout_case = function_block(visual_text, "_assert_hover_reticle_layout_contract")
    exact_profile = function_block(visual_text, "_hover_reticle_profile_exact")
    ensure(all((capture, layout_case, exact_profile)), errors, "Could not isolate focused hover-reticle runtime ownership")
    if capture:
        for token in (
            'var hover_tiles := _visible_empty_hover_tiles(session, map_node, 2)',
            'var authority_before: Dictionary = session.to_dict()',
            'var save_surface_before: Dictionary = shell.call("validation_snapshot").get("save_surface", {}).duplicate(true)',
            'var pointer_motion := InputEventMouseMotion.new()',
            'pointer_motion.position = pointer_position',
            'get_viewport().push_input(pointer_motion, true)',
            'map_node.call("validation_hover_presentation")',
            'String(cache_after.get("dynamic_reason", "")) != "hover_changed"',
            'session.to_dict() != authority_before',
            'save_surface_after != save_surface_before',
            'await RenderingServer.frame_post_draw',
        ):
            ensure(token in capture, errors, f"Focused pointer capture is missing real input/authority evidence: {token}")
        ensure(capture.find("push_input(pointer_motion, true)") < capture.find('map_node.call("validation_hover_presentation")') < capture.find("await RenderingServer.frame_post_draw"), errors, "Focused pointer input must settle and validate before each capture")
        for forbidden in ("._gui_input(", "_hover_tile =", 'shell.call("validation_hover_tile"', "create_timer", "create_tween", "set_map_state("):
            ensure(forbidden not in capture, errors, f"Focused pointer capture must not bypass the viewport input path or mutate authority: {forbidden}")
    if layout_case:
        for token in (
            '{"tile": town_tile, "town": true}',
            '{"tile": field_tile, "town": false}',
            'map_node.call("validation_tile_focus_layout", tile)',
            'not _hover_reticle_profile_exact(profile, hover_rect)',
            'uses_town and (not hover_rect.encloses(tile_rect) or hover_rect.size == tile_rect.size)',
            'not uses_town and hover_rect != tile_rect',
        ):
            ensure(token in layout_case, errors, f"Focused hover owner must prove town and ordinary tile containment: {token}")
    if exact_profile:
        for token in (
            'clampf(extent * 0.10, 6.0, 18.0)',
            'clampf(extent * 0.12, 6.0, 18.0)',
            'clampf(extent * 0.014, 1.25, 2.0)',
            '"open_cartographic_hover_corners"',
            'hover_rect.grow(-expected_inset)',
            'float(color.get("a", 0.0)), 0.55',
            'float(profile.get("shadow_alpha", 0.0)), 0.24',
            'not bool(profile.get("continuous_outline", true))',
            'is_zero_approx(float(profile.get("interior_fill_alpha", -1.0)))',
        ):
            ensure(token in exact_profile, errors, f"Focused hover profile proof is missing exact geometry/color: {token}")


def validate_overworld_contained_hover_card(errors: list[str]) -> None:
    def function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}(")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    map_path = ROOT / "scenes" / "overworld" / "OverworldMapView.gd"
    visual_path = ROOT / "tests" / "overworld_visual_smoke.gd"
    for path in (map_path, visual_path):
        ensure(path.is_file(), errors, f"Missing Overworld contained hover-card owner: {path.relative_to(ROOT)}")
    if not map_path.is_file() or not visual_path.is_file():
        return

    map_text = map_path.read_text(encoding="utf-8")
    visual_text = visual_path.read_text(encoding="utf-8")
    for token in (
        'const HOVER_TOOLTIP_VISUAL_MODEL := "contained_cartographic_hover_card"',
        'const HOVER_TOOLTIP_CONTENT_WIDTH_FACTOR := 0.34',
        'const HOVER_TOOLTIP_CONTENT_WIDTH_MIN_PX := 280.0',
        'const HOVER_TOOLTIP_CONTENT_WIDTH_MAX_PX := 420.0',
        'const HOVER_TOOLTIP_MAX_LINES := 4',
        'const HOVER_TOOLTIP_MARGIN_HORIZONTAL_PX := 12',
        'const HOVER_TOOLTIP_MARGIN_VERTICAL_PX := 9',
        'const HOVER_TOOLTIP_PANEL_COLOR := Color(0.035, 0.050, 0.045, 0.96)',
        'const HOVER_TOOLTIP_BORDER_COLOR := Color(0.64, 0.57, 0.38, 0.86)',
        'const HOVER_TOOLTIP_TEXT_COLOR := Color(0.93, 0.91, 0.82, 1.0)',
        'const HOVER_TOOLTIP_SHADOW_COLOR := Color(0.01, 0.015, 0.012, 0.72)',
        'const HOVER_TOOLTIP_BORDER_WIDTH_PX := 1',
        'const HOVER_TOOLTIP_CORNER_RADIUS_PX := 3',
        'const HOVER_TOOLTIP_SHADOW_SIZE_PX := 6',
        'const HOVER_TOOLTIP_SHADOW_OFFSET := Vector2(0.0, 3.0)',
    ):
        ensure(map_text.count(token) == 1, errors, f"Contained hover card must own one exact presentation constant: {token}")

    profile = function_block(map_text, "_hover_tooltip_visual_profile")
    builder = function_block(map_text, "_build_hover_tooltip_card")
    delegate = function_block(map_text, "_make_custom_tooltip")
    validation = function_block(map_text, "validation_hover_tooltip_card")
    ensure(all((profile, builder, delegate, validation)), errors, "Could not isolate Overworld contained hover-card production ownership")
    if profile:
        for token in (
            'size.x * HOVER_TOOLTIP_CONTENT_WIDTH_FACTOR',
            'HOVER_TOOLTIP_CONTENT_WIDTH_MIN_PX',
            'HOVER_TOOLTIP_CONTENT_WIDTH_MAX_PX',
            '"model": HOVER_TOOLTIP_VISUAL_MODEL',
            '"full_text": for_text',
            '"content_width_px": content_width',
            '"card_width_px": content_width + float(HOVER_TOOLTIP_MARGIN_HORIZONTAL_PX * 2 + HOVER_TOOLTIP_BORDER_WIDTH_PX * 2)',
            '"max_lines": HOVER_TOOLTIP_MAX_LINES',
            '"autowrap_mode": TextServer.AUTOWRAP_WORD_SMART',
            '"overrun_behavior": TextServer.OVERRUN_TRIM_ELLIPSIS',
        ):
            ensure(token in profile, errors, f"Contained hover-card profile is missing exact responsive semantics: {token}")
        for forbidden in ("split(", "replace(", "substr(", "left(", "_session", "session.", "_hover_tile", "Input.", "await ", "create_timer", "create_tween", ".erase("):
            ensure(forbidden not in profile, errors, f"Hover-card profile must retain full text and stay pure: {forbidden}")
    if builder:
        required = (
            'var profile := _hover_tooltip_visual_profile(for_text)',
            'var card := PanelContainer.new()',
            'card.name = "CartographicHoverCard"',
            'card.mouse_filter = Control.MOUSE_FILTER_IGNORE',
            'card.custom_minimum_size = Vector2(float(profile.get("card_width_px", HOVER_TOOLTIP_CONTENT_WIDTH_MIN_PX)), 0.0)',
            'var panel_style := StyleBoxFlat.new()',
            'panel_style.bg_color = profile.get("panel_color", HOVER_TOOLTIP_PANEL_COLOR)',
            'panel_style.set_border_width_all(int(profile.get("border_width_px", HOVER_TOOLTIP_BORDER_WIDTH_PX)))',
            'panel_style.set_corner_radius_all(int(profile.get("corner_radius_px", HOVER_TOOLTIP_CORNER_RADIUS_PX)))',
            'card.add_theme_stylebox_override("panel", panel_style)',
            'var margin := MarginContainer.new()',
            'margin.name = "CardMargin"',
            'var label := Label.new()',
            'label.name = "CardText"',
            'label.custom_minimum_size = Vector2(float(profile.get("content_width_px", HOVER_TOOLTIP_CONTENT_WIDTH_MIN_PX)), 0.0)',
            'label.autowrap_mode = int(profile.get("autowrap_mode", TextServer.AUTOWRAP_WORD_SMART))',
            'label.text_overrun_behavior = int(profile.get("overrun_behavior", TextServer.OVERRUN_TRIM_ELLIPSIS))',
            'label.max_lines_visible = int(profile.get("max_lines", HOVER_TOOLTIP_MAX_LINES))',
            'label.text = for_text',
            'margin.add_child(label)',
            'return card',
        )
        positions = [builder.find(token) for token in required]
        ensure(all(index >= 0 for index in positions), errors, "Contained hover-card builder is missing an exact card/style/margin/label contract")
        ensure(positions == sorted(positions), errors, "Contained hover-card builder must construct panel, style, margin, then full-text label in exact order")
        for forbidden in ("tooltip_text =", "split(", "replace(", "substr(", "_session", "session.", "_hover_tile", "Input.", "await ", "create_timer", "create_tween", "queue_redraw"):
            ensure(forbidden not in builder, errors, f"Hover-card construction must be presentation-only and retain full text: {forbidden}")
    if delegate:
        ensure(delegate.strip() == 'func _make_custom_tooltip(for_text: String) -> Object:\n\treturn _build_hover_tooltip_card(for_text)', errors, "Map custom-tooltip ownership must be one exact builder delegate")
    if validation:
        for token in (
            'var profile := _hover_tooltip_visual_profile(for_text).duplicate(true)',
            'var card := _build_hover_tooltip_card(for_text)',
            'var margin := card.get_node_or_null("CardMargin") as MarginContainer',
            'var label := card.get_node_or_null("CardMargin/CardText") as Label',
            '"label_text": label.text if label != null else ""',
            '"label_autowrap_mode": label.autowrap_mode if label != null else -1',
            '"label_overrun_behavior": label.text_overrun_behavior if label != null else -1',
            '"label_max_lines": label.max_lines_visible if label != null else -1',
            'card.free()',
            'return result',
        ):
            ensure(token in validation, errors, f"Public hover-card observation is missing exact detached control evidence: {token}")
        ensure(validation.find("_build_hover_tooltip_card") < validation.find('"label_text"') < validation.find("card.free()") < validation.find("return result"), errors, "Public hover-card validation must observe then free its detached card")
        for forbidden in ("add_child(card", "tooltip_text =", "_make_custom_tooltip(", "_gui_input(", "Input.", "await ", "create_timer", "queue_redraw", "_session"):
            ensure(forbidden not in validation, errors, f"Public hover-card observation must not attach or mutate live state: {forbidden}")

    capture = function_block(visual_text, "_capture_object_scale_viewports")
    exact = function_block(visual_text, "_hover_tooltip_card_contract_exact")
    ensure(bool(capture and exact), errors, "Could not isolate focused hover-card capture/contract ownership")
    if capture:
        for token in (
            'map_node.has_method("validation_hover_tooltip_card")',
            'var full_tooltip_text := String(shell_snapshot_after.get("map_tooltip", ""))',
            'map_node.tooltip_text != full_tooltip_text',
            'map_node.call("validation_hover_tooltip_card", full_tooltip_text)',
            'not _hover_tooltip_card_contract_exact(tooltip_card, full_tooltip_text, map_node.size.x)',
            '"tooltip_text_exact": true',
            '"tooltip_card_width_px": float(tooltip_card.get("profile", {}).get("card_width_px", 0.0))',
            'await RenderingServer.frame_post_draw',
        ):
            ensure(token in capture, errors, f"Focused real-pointer capture is missing exact hover-card evidence: {token}")
        ensure(capture.find("push_input(pointer_motion, true)") < capture.find("var full_tooltip_text") < capture.find('map_node.call("validation_hover_tooltip_card"') < capture.find("frame_post_draw"), errors, "Real pointer must own the full tooltip before card validation and capture")
        for forbidden in ('shell.call("validation_hover_tile"', "._make_custom_tooltip(", "._build_hover_tooltip_card(", "map_node.tooltip_text =", "create_timer", "create_tween"):
            ensure(forbidden not in capture, errors, f"Focused hover-card capture must not bypass production tooltip/input ownership: {forbidden}")
    if exact:
        for token in (
            'clampf(map_width * 0.34, 280.0, 420.0)',
            'var card_width := content_width + 26.0',
            'String(profile.get("full_text", "")) == full_text',
            'String(card.get("label_text", "")) == full_text',
            'card_width < map_width',
            'int(card.get("label_max_lines", 0)) == 4',
            'TextServer.AUTOWRAP_WORD_SMART',
            'TextServer.OVERRUN_TRIM_ELLIPSIS',
            'Control.MOUSE_FILTER_IGNORE',
            'margins == {"left": 12, "right": 12, "top": 9, "bottom": 9}',
            'float(panel_color.get("a", 0.0)), 0.96',
            'float(border_color.get("a", 0.0)), 0.86',
            'int(panel_style.get("shadow_size", 0)) == 6',
        ):
            ensure(token in exact, errors, f"Focused hover-card contract is missing exact width/wrap/style/full-text proof: {token}")


def validate_faction_encounter_landmarks(errors: list[str]) -> None:
    manifest_path = ROOT / "art" / "overworld" / "manifest.json"
    encounter_path = CONTENT_DIR / "encounters.json"
    army_group_path = CONTENT_DIR / "army_groups.json"
    required_paths = (manifest_path, encounter_path, army_group_path, OVERWORLD_MAP_VIEW_SCRIPT_PATH)
    for path in required_paths:
        ensure(path.is_file(), errors, f"Missing faction encounter landmark owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in required_paths):
        return

    expected = {
        "faction_embercourt": ("encounter_faction_embercourt", "embercourt", "encounter_embercourt_beacon_muster_source.png", "beacon_muster_field_command"),
        "faction_mireclaw": ("encounter_faction_mireclaw", "mireclaw", "encounter_mireclaw_reedjaw_den_source.png", "reedjaw_war_den_field_command"),
        "faction_sunvault": ("encounter_faction_sunvault", "sunvault", "encounter_sunvault_prism_relay_source.png", "prism_relay_field_command"),
        "faction_thornwake": ("encounter_faction_thornwake", "thornwake", "encounter_thornwake_graftroot_lodge_source.png", "graftroot_war_lodge_field_command"),
        "faction_brasshollow": ("encounter_faction_brasshollow", "brasshollow", "encounter_brasshollow_quenchrail_yard_source.png", "quenchrail_levy_yard_field_command"),
        "faction_veilmourn": ("encounter_faction_veilmourn", "veilmourn", "encounter_veilmourn_bellwake_mooring_source.png", "bellwake_signal_mooring_field_command"),
    }
    manifest = load_json(manifest_path)
    object_assets = manifest.get("object_assets", {})
    faction_sprites = manifest.get("encounter_faction_sprites", {})
    ensure(isinstance(object_assets, dict), errors, "Overworld art manifest object_assets must remain a dictionary")
    ensure(faction_sprites == {faction_id: row[0] for faction_id, row in expected.items()}, errors, "Faction encounter sprite mapping must cover the exact six production factions")
    runtime_payloads: list[bytes] = []
    source_payloads: list[bytes] = []
    if isinstance(object_assets, dict):
        for faction_id, (asset_id, short_id, source_name, role) in expected.items():
            entry = object_assets.get(asset_id, {})
            ensure(isinstance(entry, dict), errors, f"Missing faction encounter landmark asset {asset_id}")
            if not isinstance(entry, dict):
                continue
            runtime_res = f"res://art/overworld/runtime/objects/encounters/factions/{short_id}.png"
            source_res = f"res://art/overworld/source/generated/encounters/faction_landmarks/{source_name}"
            town_reference = f"res://art/overworld/runtime/objects/towns/factions/{short_id}.png"
            ensure(str(entry.get("path", "")) == runtime_res, errors, f"Faction encounter landmark {asset_id} must own its exact runtime path")
            ensure(str(entry.get("source_generated", "")) == source_res, errors, f"Faction encounter landmark {asset_id} must retain its generated source")
            ensure(str(entry.get("source_model", "")) == "built_in_image_gen_original_faction_encounter_landmark", errors, f"Faction encounter landmark {asset_id} must retain built-in image-generation provenance")
            ensure(str(entry.get("visual_language_reference", "")) == town_reference, errors, f"Faction encounter landmark {asset_id} must retain its faction town visual-language reference")
            ensure(str(entry.get("assigned_faction_id", "")) == faction_id, errors, f"Faction encounter landmark {asset_id} must remain assigned to exactly {faction_id}")
            ensure(str(entry.get("presentation_role", "")) == role, errors, f"Faction encounter landmark {asset_id} must retain its unique production role")
            runtime_path = res_path_to_disk(runtime_res)
            source_path = res_path_to_disk(source_res)
            reference_path = res_path_to_disk(town_reference)
            ensure(runtime_path.is_file() and png_size(runtime_path) == (512, 512), errors, f"Faction encounter landmark {asset_id} must use the production 512x512 runtime canvas")
            ensure(source_path.is_file(), errors, f"Faction encounter landmark {asset_id} is missing its high-resolution generated source")
            ensure(reference_path.is_file(), errors, f"Faction encounter landmark {asset_id} is missing its production faction reference")
            ensure(Path(f"{runtime_path}.import").is_file(), errors, f"Faction encounter landmark {asset_id} is missing runtime Godot import metadata")
            ensure(Path(f"{source_path}.import").is_file(), errors, f"Faction encounter landmark {asset_id} is missing source Godot import metadata")
            if runtime_path.is_file():
                payload = runtime_path.read_bytes()
                ensure(len(payload) >= 26 and payload[25] in {4, 6}, errors, f"Faction encounter landmark {asset_id} must retain a real alpha channel")
                runtime_payloads.append(payload)
            if source_path.is_file():
                payload = source_path.read_bytes()
                ensure(len(payload) >= 26 and payload[25] in {4, 6}, errors, f"Faction encounter source {asset_id} must retain a real alpha channel")
                source_payloads.append(payload)
    ensure(len(runtime_payloads) == 6 and len(set(runtime_payloads)) == 6, errors, "All six faction encounter runtime PNG payloads must be distinct")
    ensure(len(source_payloads) == 6 and len(set(source_payloads)) == 6, errors, "All six faction encounter generated sources must be distinct")

    encounters_value = load_json(encounter_path).get("items", [])
    groups_value = load_json(army_group_path).get("items", [])
    encounters = [row for row in encounters_value if isinstance(row, dict)] if isinstance(encounters_value, list) else []
    groups = {str(row.get("id", "")): row for row in groups_value if isinstance(row, dict)} if isinstance(groups_value, list) else {}
    owned_encounters = [row for row in encounters if str(groups.get(str(row.get("enemy_group_id", "")), {}).get("faction_id", "")) in expected]
    neutral_encounters = [row for row in encounters if row not in owned_encounters]
    ensure(len(encounters) >= 185, errors, "Faction encounter landmark adoption must retain all 161 authored encounters")
    ensure(len(owned_encounters) >= 146 and len(neutral_encounters) >= 40, errors, "Faction encounter landmark adoption must retain faction and neutral authored encounter coverage")
    ensure({str(groups.get(str(row.get("enemy_group_id", "")), {}).get("faction_id", "")) for row in owned_encounters} == set(expected), errors, "Authored faction encounters must exercise all six landmark identities")

    map_text = OVERWORLD_MAP_VIEW_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        "const OBJECT_FACTION_ENCOUNTER_VISIBLE_EXTENT_TILES := 0.82",
        "var _encounter_faction_asset_ids: Dictionary = {}",
        "var _encounter_faction_cache: Dictionary = {}",
        '_overworld_art_manifest.get("encounter_faction_sprites", {})',
        "_encounter_faction_asset_ids[faction_id] = asset_id",
        "func _draw_encounter_faction_landmark(",
        "func _encounter_faction_asset_id(",
        "func _encounter_faction_id(",
        'ContentService.get_army_group(group_id).get("faction_id", "")',
        "func validation_encounter_presentation_payload(",
        '"uses_faction_encounter_sprite": sprite_asset_id == "" and not identity_encounter_loaded and faction_encounter_loaded',
        '"faction_landmark_visible_extent_tiles": OBJECT_FACTION_ENCOUNTER_VISIBLE_EXTENT_TILES',
    ):
        ensure(token in map_text, errors, f"Production faction encounter landmark runtime is missing exact ownership: {token}")
    draw_start = map_text.find("func _draw_encounter_sprite")
    draw_end = map_text.find("\nfunc ", draw_start + 1)
    draw_block = map_text[draw_start:draw_end]
    draw_order = [draw_block.find(name) for name in ("_draw_encounter_commander_sprite", "_draw_encounter_identity_landmark", "_draw_encounter_faction_landmark", "_draw_encounter_unit_icon", "_draw_object_sprite")]
    ensure(all(index >= 0 for index in draw_order) and draw_order == sorted(draw_order), errors, "Encounter drawing must prefer commander, exact identity, faction landmark, unit icon, then generic object fallback")
    resolver_start = map_text.find("func _encounter_faction_id")
    resolver_end = map_text.find("\nfunc ", resolver_start + 1)
    resolver_block = map_text[resolver_start:resolver_end]
    resolver_order = [resolver_block.find(token) for token in ('encounter.get("spawned_by_faction_id", "")', 'encounter.get("faction_id", "")', 'encounter.get("enemy_group_id", "")', "ContentService.get_encounter(encounter_id)", "_encounter_faction_cache.has(group_id)", "ContentService.get_army_group(group_id)")]
    ensure(all(index >= 0 for index in resolver_order) and resolver_order == sorted(resolver_order), errors, "Faction encounter resolution must retain spawned, direct, authored encounter, cached army-group priority")
    for forbidden in ("SessionStateStore.SAVE_VERSION =", "NativeRmg", "native_rmg"):
        ensure(forbidden not in resolver_block + draw_block, errors, f"Faction encounter art must not change save or Native RMG authority: {forbidden}")
    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        packaging_text = packaging_path.read_text(encoding="utf-8")
        ensure("REQUIRED_FACTION_ENCOUNTER_PCK_IMPORT_ENTRIES" in packaging_text and "REQUIRED_FACTION_ENCOUNTER_NAMES" in packaging_text, errors, f"{packaging_path.name} must audit the six faction encounter landmarks")
        ensure('bool(terrain_payload["faction_encounter_entries_present"])' in packaging_text, errors, f"{packaging_path.name} must fail the release export when faction encounter landmarks are absent")
        ensure('"faction_encounter_pck_entries_present"' in packaging_text, errors, f"{packaging_path.name} must report packaged faction encounter coverage")
        for _faction_id, (_asset_id, short_id, _source_name, _role) in expected.items():
            ensure(f'"{short_id}"' in packaging_text, errors, f"{packaging_path.name} is missing packaged faction encounter identity {short_id}")


def validate_signature_encounter_landmarks(errors: list[str]) -> None:
    def gd_function_block(text: str, name: str) -> str:
        start = text.find(f"func {name}")
        if start < 0:
            return ""
        end = text.find("\nfunc ", start + 1)
        return text[start:] if end < 0 else text[start:end]

    expected = {
        "encounter_reed_totemists": ("encounter_signature_reed_totemists", "reed_totemists", "faction_mireclaw", "reed_jaw_totem_cluster", "fb1d54d1adcb2cc11b0de3e325510df951194b6b4673ecb5eee364b1e74e93e2", "1bdec017b1ee78e44acbbdd63324ef42f2cee65672dc67392718dc4d30097409"),
        "encounter_archive_wardens": ("encounter_signature_archive_wardens", "archive_wardens", "faction_embercourt", "fortified_field_archive", "74654aaa30227d13654a10f6955a4465625d789fc8c665ab355261b1881e9e25", "facaa22b71c437e04eba11b4fbe9268776452aa507d1364b6c1e2f6be2dd2f13"),
        "encounter_relay_pickets": ("encounter_signature_relay_pickets", "relay_pickets", "faction_sunvault", "portable_prism_relay", "084bcdd027ec381d9a6af02a8729279bfc5b5a8b3d8d8c090d89cff6d4033005", "cd052973abf683273a8436741dca207b53945be65ee987b82110170a72339226"),
        "encounter_graftroot_wardens": ("encounter_signature_graftroot_wardens", "graftroot_wardens", "faction_thornwake", "living_graftroot_ward", "8f00212e8b6e7886097c11ec72e98ee0570780f6d5dab7bdb067f2019a6498cb", "9ff44ccb38d86ad2c5f14ff6527780f41bb78f22ebc728eaa0a89d2a1d4190e2"),
        "encounter_orevein_exactors": ("encounter_signature_orevein_exactors", "orevein_exactors", "faction_brasshollow", "portable_assay_station", "c7796216fe328efbd6d92af247b231c4883fa250e8f142b74ef09d8d226bb8ca", "bd97990f2d08b18b9ad1b116159ff7d074585163b3c1228a617989cea965793f"),
        "encounter_bellwake_privateers": ("encounter_signature_bellwake_privateers", "bellwake_privateers", "faction_veilmourn", "fog_coast_signal_mooring", "9eecd5405f440aeba39a9e2e3536a6eea70643544ad15234aa8caea9b3789fd9", "3fed3ac28e7dad9ef12c391cea153e6b1b006089c61d6c8ece3210d12ec766a4"),
    }
    required_paths = (
        OVERWORLD_ART_MANIFEST_PATH,
        CONTENT_DIR / "encounters.json",
        CONTENT_DIR / "army_groups.json",
        CONTENT_DIR / "scenarios.json",
        OVERWORLD_MAP_VIEW_SCRIPT_PATH,
        OVERWORLD_SIGNATURE_ENCOUNTER_LANDMARK_RUNTIME_REPORT_SCRIPT_PATH,
        OVERWORLD_SIGNATURE_ENCOUNTER_LANDMARK_RUNTIME_REPORT_SCENE_PATH,
    )
    for path in required_paths:
        ensure(path.is_file(), errors, f"Missing signature encounter landmark owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in required_paths):
        return

    manifest = load_json(OVERWORLD_ART_MANIFEST_PATH)
    object_assets = manifest.get("object_assets", {})
    identity_sprites = manifest.get("encounter_identity_sprites", {})
    ensure(
        {encounter_id: identity_sprites.get(encounter_id) for encounter_id in expected}
        == {encounter_id: row[0] for encounter_id, row in expected.items()},
        errors,
        "Signature encounter mapping must retain the selected six identities",
    )
    source_payloads: list[bytes] = []
    runtime_payloads: list[bytes] = []
    for encounter_id, (asset_id, stem, faction_id, role, source_sha, runtime_sha) in expected.items():
        entry = object_assets.get(asset_id, {}) if isinstance(object_assets, dict) else {}
        ensure(isinstance(entry, dict), errors, f"Missing signature encounter asset {asset_id}")
        if not isinstance(entry, dict):
            continue
        source_res = f"res://art/overworld/source/generated/encounters/signatures/{stem}_source.png"
        runtime_res = f"res://art/overworld/runtime/objects/encounters/signatures/{stem}.png"
        ensure(str(entry.get("source_generated", "")) == source_res and str(entry.get("path", "")) == runtime_res, errors, f"Signature encounter {encounter_id} paths changed")
        ensure(str(entry.get("source_model", "")) == "built_in_image_gen_original_signature_encounter_landmark", errors, f"Signature encounter {encounter_id} lost built-in generation provenance")
        ensure(str(entry.get("assigned_encounter_id", "")) == encounter_id and str(entry.get("assigned_faction_id", "")) == faction_id, errors, f"Signature encounter {encounter_id} ownership changed")
        ensure(str(entry.get("presentation_role", "")) == role and bool(str(entry.get("accessible_description", "")).strip()), errors, f"Signature encounter {encounter_id} role or non-color description changed")
        source_path = res_path_to_disk(source_res)
        runtime_path = res_path_to_disk(runtime_res)
        source_size = png_size(source_path) if source_path.is_file() else (0, 0)
        ensure(source_path.is_file() and min(source_size) >= 1024, errors, f"Signature encounter {encounter_id} must retain its high-resolution generated source")
        ensure(runtime_path.is_file() and png_size(runtime_path) == (64, 64), errors, f"Signature encounter {encounter_id} must use a compact 64x64 runtime texture")
        ensure(Path(f"{source_path}.import").is_file() and Path(f"{runtime_path}.import").is_file(), errors, f"Signature encounter {encounter_id} import metadata is missing")
        if source_path.is_file():
            payload = source_path.read_bytes()
            ensure(hashlib.sha256(payload).hexdigest() == source_sha and len(payload) >= 26 and payload[25] in {4, 6}, errors, f"Signature encounter {encounter_id} source bytes or alpha changed")
            source_payloads.append(payload)
        if runtime_path.is_file():
            payload = runtime_path.read_bytes()
            ensure(hashlib.sha256(payload).hexdigest() == runtime_sha and len(payload) >= 26 and payload[25] in {4, 6}, errors, f"Signature encounter {encounter_id} runtime bytes or alpha changed")
            runtime_payloads.append(payload)
    ensure(len(source_payloads) == 6 and len(set(source_payloads)) == 6 and len(runtime_payloads) == 6 and len(set(runtime_payloads)) == 6, errors, "All six signature encounter sources and runtimes must remain byte-distinct")

    encounters_value = load_json(CONTENT_DIR / "encounters.json").get("items", [])
    groups_value = load_json(CONTENT_DIR / "army_groups.json").get("items", [])
    scenarios_value = load_json(CONTENT_DIR / "scenarios.json").get("items", [])
    encounters = {str(row.get("id", "")): row for row in encounters_value if isinstance(row, dict)} if isinstance(encounters_value, list) else {}
    groups = {str(row.get("id", "")): row for row in groups_value if isinstance(row, dict)} if isinstance(groups_value, list) else {}
    placement_counts = {encounter_id: 0 for encounter_id in expected}
    if isinstance(scenarios_value, list):
        for scenario in scenarios_value:
            if not isinstance(scenario, dict):
                continue
            for placement in scenario.get("encounters", []):
                if isinstance(placement, dict) and str(placement.get("encounter_id", "")) in placement_counts:
                    placement_counts[str(placement.get("encounter_id", ""))] += 1
    for encounter_id, (_asset_id, _stem, faction_id, _role, _source_sha, _runtime_sha) in expected.items():
        definition = encounters.get(encounter_id, {})
        group = groups.get(str(definition.get("enemy_group_id", "")), {}) if isinstance(definition, dict) else {}
        ensure(str(group.get("faction_id", "")) == faction_id, errors, f"Signature encounter {encounter_id} must retain its authored faction")
        ensure(placement_counts[encounter_id] > 0, errors, f"Signature encounter {encounter_id} must remain present in a playable authored scenario")

    map_text = OVERWORLD_MAP_VIEW_SCRIPT_PATH.read_text(encoding="utf-8")
    for token in (
        "var _encounter_identity_asset_ids: Dictionary = {}",
        "_encounter_identity_asset_ids.clear()",
        'var encounter_identity_sprites = _overworld_art_manifest.get("encounter_identity_sprites", {})',
        "_encounter_identity_asset_ids[encounter_id] = asset_id",
        "func _draw_encounter_identity_landmark(",
        "func _encounter_identity_asset_id(",
        'encounter.get("encounter_id", encounter.get("id", ""))',
        '"identity_encounter_asset_id": identity_encounter_asset_id',
        '"uses_identity_encounter_sprite": sprite_asset_id == "" and identity_encounter_loaded',
    ):
        ensure(token in map_text, errors, f"Signature encounter runtime is missing exact ownership: {token}")
    draw_block = gd_function_block(map_text, "_draw_encounter_sprite")
    draw_order = [draw_block.find(name) for name in ("_draw_encounter_commander_sprite", "_draw_encounter_identity_landmark", "_draw_encounter_faction_landmark", "_draw_encounter_unit_icon", "_draw_object_sprite")]
    ensure(all(index >= 0 for index in draw_order) and draw_order == sorted(draw_order), errors, "Signature encounter draw order must remain commander, exact identity, faction, unit, generic")
    identity_draw_block = gd_function_block(map_text, "_draw_encounter_identity_landmark")
    for token in ("_encounter_identity_asset_id(encounter)", "OBJECT_FACTION_ENCOUNTER_VISIBLE_EXTENT_TILES", "_draw_hostile_actor_marker", "_draw_procedural_contact_marks"):
        ensure(token in identity_draw_block, errors, f"Signature encounter drawing is missing shared hostile presentation: {token}")
    for forbidden in ("session.", "_session.", "await ", "create_timer", "create_tween"):
        ensure(forbidden not in identity_draw_block, errors, f"Signature encounter drawing must remain presentation-only: {forbidden}")

    report_text = OVERWORLD_SIGNATURE_ENCOUNTER_LANDMARK_RUNTIME_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    report_scene = OVERWORLD_SIGNATURE_ENCOUNTER_LANDMARK_RUNTIME_REPORT_SCENE_PATH.read_text(encoding="utf-8")
    ensure_scene_nodes(report_scene, errors, "overworld_signature_encounter_landmark_runtime_report.tscn", [("OverworldSignatureEncounterLandmarkRuntimeReport", "Node")])
    for token in (
        'const EXPECTED := {',
        'const VIEWPORT_SIZES := [Vector2i(1280, 720), Vector2i(1920, 1080)]',
        'ScenarioFactory.create_session(SCENARIO_ID, "hard", SessionState.LAUNCH_MODE_SKIRMISH)',
        'map_view.call("validation_encounter_presentation_payload"',
        '"fallback_order": ["commander", "exact_encounter", "faction", "unit", "generic"]',
        'bool(payload.get("uses_identity_encounter_sprite", false))',
        'String(faction.get("faction_encounter_asset_id", "")) == "encounter_faction_mireclaw"',
        'bool(neutral.get("uses_unit_icon_fallback", false))',
        'String(unknown.get("encounter_asset_id", "")) == "hostile_camp"',
        'session.to_dict() != authority_before',
        'OS.get_environment("SIGNATURE_ENCOUNTER_CAPTURE")',
        'print("OVERWORLD_SIGNATURE_ENCOUNTER_LANDMARK_RUNTIME_REPORT %s"',
    ):
        ensure(token in report_text, errors, f"Signature encounter focused owner is missing exact proof: {token}")

    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        packaging_text = packaging_path.read_text(encoding="utf-8")
        ensure("REQUIRED_SIGNATURE_ENCOUNTER_PCK_IMPORT_ENTRIES" in packaging_text and "REQUIRED_SIGNATURE_ENCOUNTER_NAMES" in packaging_text, errors, f"{packaging_path.name} must audit all six signature encounter landmarks")
        ensure('bool(terrain_payload["signature_encounter_entries_present"])' in packaging_text, errors, f"{packaging_path.name} must fail when signature encounter landmarks are absent")
        ensure('"signature_encounter_pck_entries_present"' in packaging_text, errors, f"{packaging_path.name} must report packaged signature encounter coverage")
        for _encounter_id, (_asset_id, stem, _faction_id, _role, _source_sha, _runtime_sha) in expected.items():
            ensure(f'"{stem}"' in packaging_text, errors, f"{packaging_path.name} is missing signature encounter identity {stem}")


def validate_six_faction_dissident_fronts(errors: list[str]) -> None:
    expected = {
        "encounter_lockflame_turncoats": ("encounter_dissident_lockflame_turncoats", "lockflame_turncoats", "army_lockflame_turncoats", "faction_embercourt", [("unit_embercourt_fordhook_cadets", 8), ("unit_embercourt_lantern_sappers", 5), ("unit_embercourt_bargebow_crews", 3), ("unit_embercourt_ash_oath_bailiffs", 1)], "causeway-stand", "causeway_lockflame_turncoats", 2204, "lockflame_broken_sluice", "lane_battery", "embergrain", "lockflame_turncoats_broken", [0, 0, 48, 48], "174c5c1321036645d6969cbc520815cacf6301fb5908187d9e5f82eafd3986a8"),
        "encounter_mossglass_moonhunt": ("encounter_dissident_mossglass_moonhunt", "mossglass_moonhunt", "army_mossglass_moonhunt", "faction_mireclaw", [("unit_mireclaw_reedsnare_kin", 8), ("unit_mireclaw_mudglass_slingers", 5), ("unit_mireclaw_bogplate_maulers", 3), ("unit_mireclaw_ferrychain_lashers", 1)], "bogbound-oath", "bogbound_mossglass_moonhunt", 7204, "moonhunt_scent_gate", "hazard_zone", "peatwax", "mossglass_moonhunt_broken", [48, 0, 48, 48], "18e154d1d26cbc37fc1d2bac905970dde1ff71ee0e7fa3fe185ed06ef50690e3"),
        "encounter_parallax_choir": ("encounter_dissident_parallax_choir", "parallax_choir", "army_parallax_choir", "faction_sunvault", [("unit_sunvault_shard_wardens", 2), ("unit_sunvault_prism_adepts", 2), ("unit_sunvault_mirror_duelists", 1), ("unit_sunvault_resonant_choristers", 1)], "prismhearth-watch", "prismhearth_parallax_choir", 11204, "parallax_chime_frame", "signal_beacon", "aetherglass", "parallax_choir_broken", [96, 0, 48, 48], "e5ad9a262fe6ed2580030e732960ab668d0bfad1305777b475519eb60efb648c"),
        "encounter_graftbound_pilgrims": ("encounter_dissident_graftbound_pilgrims", "graftbound_pilgrims", "army_graftbound_pilgrims", "faction_thornwake", [("unit_thornwake_seedcutters", 8), ("unit_thornwake_thornwhip_carriers", 5), ("unit_thornwake_sporeglass_menders", 3), ("unit_thornwake_barkmantle_rams", 1)], "mireford-skirmish", "mireford_graftbound_pilgrims", 10204, "graftbound_walking_arch", "cover_line", "verdant_grafts", "graftbound_pilgrims_broken", [144, 0, 48, 48], "86cb337f1f2e7f40f52ffafd3e918dcf942389f9766bc1d29fee1ade2370eff6"),
        "encounter_redline_foreclosure": ("encounter_dissident_redline_foreclosure", "redline_foreclosure", "army_redline_foreclosure", "faction_brasshollow", [("unit_brasshollow_scrip_haulers", 8), ("unit_brasshollow_rivet_hounds", 5), ("unit_brasshollow_furnace_pavis_teams", 3), ("unit_brasshollow_boiler_rivetcasters", 1)], "orevein-contract", "orevein_redline_foreclosure", 17204, "redline_seizure_gauge", "supply_post", "brass_scrip", "redline_foreclosure_broken", [192, 0, 48, 48], "8c2b8de6b9134bc2e49da3f015d35587b0c4f6b372fa9d69952b01a47c5307d1"),
        "encounter_drowned_bell_procession": ("encounter_dissident_drowned_bell_procession", "drowned_bell_procession", "army_drowned_bell_procession", "faction_veilmourn", [("unit_veilmourn_bellwake_oars", 8), ("unit_veilmourn_mourning_lanterns", 5), ("unit_veilmourn_maskglass_corsairs", 3), ("unit_veilmourn_undertow_harpooners", 1)], "bellwake-wreck-claim", "bellwake_drowned_bell_procession", 18204, "drowned_procession_bell", "ritual_pylon", "memory_salt", "drowned_bell_procession_broken", [240, 0, 48, 48], "90ea55485a09b14245959b63fe1ac5f1dae67856f8e17ae9f0320fc359fe7d1c"),
    }
    source_dir = ROOT / "art" / "overworld" / "source" / "generated" / "encounters" / "dissident_fronts"
    source_manifest_path = source_dir / "manifest.json"
    atlas_path = ROOT / "art" / "overworld" / "runtime" / "objects" / "encounters" / "dissident_fronts" / "dissident_fronts_atlas.png"
    report_script_path = ROOT / "tests" / "six_faction_dissident_fronts_report.gd"
    report_scene_path = ROOT / "tests" / "six_faction_dissident_fronts_report.tscn"
    required_paths = (OVERWORLD_ART_MANIFEST_PATH, source_manifest_path, atlas_path, report_script_path, report_scene_path)
    for path in required_paths:
        ensure(path.is_file(), errors, f"Missing six-faction dissident-front owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in required_paths):
        return

    atlas_payload = atlas_path.read_bytes()
    ensure(png_size(atlas_path) == (288, 48), errors, "Dissident-front atlas must remain a compact 288x48 strip")
    ensure(hashlib.sha256(atlas_payload).hexdigest() == "5629ffe1f45e311c6994fcc83d781832bb6a6cae04f526e02e12744c04ee3342" and len(atlas_payload) >= 26 and atlas_payload[25] in {4, 6}, errors, "Dissident-front atlas bytes or alpha changed")
    ensure(Path(f"{atlas_path}.import").is_file(), errors, "Dissident-front atlas import metadata is missing")

    encounters = {str(row.get("id", "")): row for row in load_json(CONTENT_DIR / "encounters.json").get("items", []) if isinstance(row, dict)}
    groups = {str(row.get("id", "")): row for row in load_json(CONTENT_DIR / "army_groups.json").get("items", []) if isinstance(row, dict)}
    scenarios = {str(row.get("id", "")): row for row in load_json(CONTENT_DIR / "scenarios.json").get("items", []) if isinstance(row, dict)}
    ensure(len(encounters) >= 185 and len(groups) >= 309 and len(scenarios) >= 183, errors, "Expanded contract roster must retain 179 encounters, 249 army groups, and 129 scenarios")
    all_placements = [placement for scenario in scenarios.values() for placement in scenario.get("encounters", []) if isinstance(placement, dict)]
    ensure(len(all_placements) >= 682 and len({str(row.get("encounter_id", "")) for row in all_placements}) >= 182, errors, "Authored battle fronts must retain the expanded playable breadth")

    art_manifest = load_json(OVERWORLD_ART_MANIFEST_PATH)
    object_assets = art_manifest.get("object_assets", {})
    identity_sprites = art_manifest.get("encounter_identity_sprites", {})
    source_manifest = load_json(source_manifest_path)
    source_rows = {str(row.get("encounter_id", "")): row for row in source_manifest.get("items", []) if isinstance(row, dict)}
    ensure(source_manifest.get("schema_version") == 1 and source_manifest.get("generator_mode") == "built_in_image_gen", errors, "Dissident-front source manifest provenance changed")
    ensure(source_manifest.get("runtime_atlas_size") == [288, 48] and source_manifest.get("runtime_atlas_sha256") == "5629ffe1f45e311c6994fcc83d781832bb6a6cae04f526e02e12744c04ee3342", errors, "Dissident-front source manifest atlas contract changed")
    ensure(set(source_rows) == set(expected), errors, "Dissident-front source manifest must own exactly the six selected encounters")

    source_payloads = []
    for encounter_id, contract in expected.items():
        asset_id, stem, group_id, faction_id, units, scenario_id, placement_id, seed, objective_id, objective_type, resource_id, victory_flag, region, source_sha = contract
        definition = encounters.get(encounter_id, {})
        group = groups.get(group_id, {})
        stacks = [(str(row.get("unit_id", "")), int(row.get("count", 0))) for row in group.get("stacks", []) if isinstance(row, dict)]
        objectives = definition.get("field_objectives", [])
        objective = objectives[0] if isinstance(objectives, list) and len(objectives) == 1 and isinstance(objectives[0], dict) else {}
        rewards = definition.get("rewards", {})
        ensure(definition.get("enemy_group_id") == group_id and definition.get("max_rounds") == 14, errors, f"{encounter_id} lost its battle owner or round cap")
        ensure(group.get("faction_id") == faction_id and stacks == units, errors, f"{encounter_id} lost its exact faction army composition")
        ensure(objective.get("id") == objective_id and objective.get("type") == objective_type, errors, f"{encounter_id} lost its faction-specific field objective")
        ensure(rewards.get("gold") == 190 and rewards.get("experience") == 200 and rewards.get(resource_id) == 1 and definition.get("victory_flags") == [victory_flag], errors, f"{encounter_id} reward or victory-state contract changed")

        scenario = scenarios.get(scenario_id, {})
        placements = [row for row in scenario.get("encounters", []) if isinstance(row, dict) and row.get("placement_id") == placement_id]
        placement = placements[0] if len(placements) == 1 else {}
        ensure(len(placements) == 1 and placement.get("encounter_id") == encounter_id and [placement.get("x"), placement.get("y")] == [2, 4] and placement.get("difficulty") == "medium" and placement.get("combat_seed") == seed and placement.get("prefer_identity_landmark") is True, errors, f"{encounter_id} must remain one optional medium landmark placement at (2,4) with its fixed seed")
        occupied = [row for kind in ("towns", "resource_nodes", "artifact_nodes") for row in scenario.get(kind, []) if isinstance(row, dict) and [row.get("x"), row.get("y")] == [2, 4]]
        competing = [row for row in scenario.get("encounters", []) if isinstance(row, dict) and row.get("placement_id") != placement_id and [row.get("x"), row.get("y")] == [2, 4]]
        terrain_map = scenario.get("map", [])
        terrain = terrain_map[4][2] if isinstance(terrain_map, list) and len(terrain_map) > 4 and isinstance(terrain_map[4], list) and len(terrain_map[4]) > 2 else ""
        ensure(not occupied and not competing and terrain not in {"", "water"}, errors, f"{encounter_id} optional route tile must remain free and traversable")

        entry = object_assets.get(asset_id, {}) if isinstance(object_assets, dict) else {}
        source_res = f"res://art/overworld/source/generated/encounters/dissident_fronts/{stem}_source.png"
        ensure(identity_sprites.get(encounter_id) == asset_id and entry.get("path") == "res://art/overworld/runtime/objects/encounters/dissident_fronts/dissident_fronts_atlas.png", errors, f"{encounter_id} exact live art mapping is missing")
        ensure(entry.get("atlas_region") == region and entry.get("atlas_size") == [288, 48] and entry.get("source_generated") == source_res, errors, f"{encounter_id} atlas region or source ownership changed")
        ensure(entry.get("assigned_encounter_id") == encounter_id and entry.get("assigned_faction_id") == faction_id and len(str(entry.get("accessible_description", "")).strip()) >= 24, errors, f"{encounter_id} art assignment or non-color description changed")
        source_path = res_path_to_disk(source_res)
        ensure(source_path.is_file() and min(png_size(source_path)) >= 1024 and Path(f"{source_path}.import").is_file(), errors, f"{encounter_id} must retain its imported high-resolution generated source")
        if source_path.is_file():
            payload = source_path.read_bytes()
            ensure(hashlib.sha256(payload).hexdigest() == source_sha and len(payload) >= 26 and payload[25] in {4, 6}, errors, f"{encounter_id} source bytes or alpha changed")
            source_payloads.append(payload)
        source_row = source_rows.get(encounter_id, {})
        ensure(source_row.get("asset_id") == asset_id and source_row.get("source_path") == source_res and source_row.get("source_sha256") == source_sha and source_row.get("atlas_region") == region, errors, f"{encounter_id} generated-source manifest row changed")
    ensure(len(source_payloads) == 6 and len(set(source_payloads)) == 6, errors, "All six dissident-front sources must remain byte-distinct")

    report_text = report_script_path.read_text(encoding="utf-8")
    report_scene = report_scene_path.read_text(encoding="utf-8")
    ensure_scene_nodes(report_scene, errors, "six_faction_dissident_fronts_report.tscn", [("SixFactionDissidentFrontsReport", "Node")])
    for token in ('const CASES := [', 'CASES.size()', 'ScenarioFactory.create_session(', 'validation_encounter_presentation_payload', 'texture is AtlasTexture', 'BattleRulesScript.create_battle_payload', 'BattleAutoResolveRulesScript.resolve_active_battle', 'SessionStateStoreScript.SAVE_VERSION', 'print("%s %s" % [REPORT_ID'):
        ensure(token in report_text, errors, f"Dissident-front combined smoke is missing live proof: {token}")
    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        packaging_text = packaging_path.read_text(encoding="utf-8")
