        PACKAGED_SETTINGS_PERSISTENCE_REPORT_SCRIPT_PATH,
        PACKAGED_SETTINGS_PERSISTENCE_REPORT_SCENE_PATH,
        PACKAGED_SETTINGS_PERSISTENCE_SMOKE_SCRIPT_PATH,
