    ensure(ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_DOC_PATH.exists(), errors, "Active scenario town development runway report doc is missing")
    if not ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_SCRIPT_PATH.exists():
        return

    script_text = ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_SCRIPT_PATH.read_text(encoding="utf-8")
    scene_text = ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_SCENE_PATH.read_text(encoding="utf-8") if ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_SCENE_PATH.exists() else ""
    doc_text = ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_DOC_PATH.read_text(encoding="utf-8") if ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT_DOC_PATH.exists() else ""
    for required_token in (
        "ACTIVE_SCENARIO_TOWN_DEVELOPMENT_RUNWAY_REPORT",
        "active_scenario_town_development_runway_report_v1",
        "ScenarioFactory.create_session",
        "TARGET_TIER_COUNT",
        "MIN_COMPLETION_DAY",
        "TownRules.get_build_actions",
        "TownRules.get_recruit_actions",
        "OverworldRules.build_in_active_town",
        "OverworldRules.recruit_in_active_town",
        "_advance_active_scenario_economy_day",
        "OverworldRules.is_weekly_growth_day",
        "OverworldRules.town_weekly_growth",
        "OverworldRules.town_recovery_state",
        "OverworldRules.relieve_town_recovery_pressure",
        "OverworldRules.controlled_resource_site_income",
        "OverworldRules.tile_is_blocked",
        "OverworldRules.tile_is_actionable_route_destination",
        "OverworldRules.tile_step_cuts_blocked_corner",
        "DELAYED_SOURCE_ROUTE_STEPS_PER_DAY",
        "DELAYED_GUARDED_SOURCE_EXTRA_DAYS",
        "_run_delayed_source_replay",
        "_development_source_schedule",
        "_apply_due_development_sources",
        "active_scenario_town_delayed_source_replay_v1",
        "full_session_case_count",
        "full_session_used",
        "delayed_source_replay_case_count",
        "delayed_source_replay_completed_count",
        "delayed_source_replay_ok",
        "delayed_source_save_resume_case_count",
        "delayed_source_save_resume_completed_count",
        "DELAYED_SOURCE_SAVE_RESUME_SLOT",
        "SaveService.save_runtime_manual_session",
        "SaveService.restore_manual_session",
        "_delayed_source_save_resume_checkpoint",
        "same_day_guard_after_restore",
        "source_state_preserved",
        "focused_economy_day_advance_count",
        "post_completion_economy_day_count",
        "scenario_resource_node_count",
        "scenario_encounter_count",
        "scenario_enemy_state_count",
        "secured_daily_income",
        "secured_resource_ids",
        "source_adoption_policy",
        "minimal_required_resource_coverage",
        "source_adoption_policy_case_count",
        "pacing_floor_case_count",
        "campaign_pacing_floor_case_count",
        "skirmish_pacing_floor_case_count",
        "completion_day_min",
        "completion_day_max",
        "rare_spend_observed",
        "recruitment_end_to_end_case_count",
        "seven_tier_recruitment_case_count",
        "recruited_unit_case_count",
        "recruitment_end_to_end_ok",
        "weekly_growth",
        "same_day_reject_ok",
        "market_common_only",
        "ACTIVE_SCENARIO_TOWN_RUNWAY_ONLY",
        "campaign_scenario_count",
        "skirmish_scenario_count",
        "campaign_player_town_case_count",
        "skirmish_player_town_case_count",
        "campaign_completed_case_count",
        "skirmish_completed_case_count",
    ):
        ensure(required_token in script_text, errors, f"Active scenario town development runway report is missing token {required_token}")
    ensure("res://tests/active_scenario_town_development_runway_report.gd" in scene_text, errors, "Active scenario town development runway scene must load its report script")
    for required_text in (
        "Economy Active Scenario Development Runway Report",
        "economy-active-scenario-development-runway-20260524-10184",
        "active_scenario_town_development_runway_report_v1",
        "20 active player-town cases",
        "20 campaign player-town cases",
        "20 skirmish player-town cases",
        "20/20 active player-town recruitment cases",
        "day 25 to day 30",
        "minimal_required_resource_coverage",
        "140/140 tier recruitment cases",
        "20/20 delayed-source replay cases",
        "20/20 delayed-source save/resume checkpoints",
        "route-derived source acquisition delays",
        "SaveService.save_runtime_manual_session",
        "SaveService.restore_manual_session",
        "seven-tier ladder",
        "scenario-authored economy sources",
        "full scenario session state",
        "focused active-scenario economy-day step",
        "weekly musters",
        "not final scenario-wide route balance",
        "No `SAVE_VERSION` bump",
        "`wood` remains canonical",
    ):
        ensure(required_text in doc_text, errors, f"Active scenario town development runway doc is missing required text: {required_text}")

    resource_sites = items_index(load_json(CONTENT_DIR / "resource_sites.json"))
    for site_id, resource_id in (("site_wood_wagon", "wood"), ("site_ore_crates", "ore")):
        site = resource_sites.get(site_id, {})
        ensure(bool(site.get("persistent_control", False)), errors, f"{site_id} must be a persistent common-resource source")
        income = site.get("control_income", {}) if isinstance(site, dict) else {}
        ensure(isinstance(income, dict) and int(income.get(resource_id, 0)) > 0, errors, f"{site_id} must provide persistent {resource_id} income")

    scenarios = items_index(load_json(CONTENT_DIR / "scenarios.json"))
    towns = items_index(load_json(CONTENT_DIR / "towns.json"))
    buildings = items_index(load_json(CONTENT_DIR / "buildings.json"))
    active_scenario_count = 0
    campaign_scenario_count = 0
    skirmish_scenario_count = 0
    player_town_case_count = 0
    campaign_player_town_case_count = 0
    skirmish_player_town_case_count = 0
    for scenario_id, scenario in sorted(scenarios.items()):
        selection = scenario.get("selection", {}) if isinstance(scenario, dict) else {}
        availability = selection.get("availability", {}) if isinstance(selection, dict) else {}
        if not (bool(availability.get("campaign", False)) or bool(availability.get("skirmish", False))):
            continue
        is_campaign = bool(availability.get("campaign", False))
        is_skirmish = bool(availability.get("skirmish", False))
        active_scenario_count += 1
        if is_campaign:
            campaign_scenario_count += 1
        if is_skirmish:
            skirmish_scenario_count += 1
        scenario_nodes = scenario.get("resource_nodes", [])
        scenario_nodes = scenario_nodes if isinstance(scenario_nodes, list) else []
        persistent_income_ids: set[str] = set()
        for node in scenario_nodes:
            if not isinstance(node, dict):
                continue
            site = resource_sites.get(str(node.get("site_id", "")), {})
            if not isinstance(site, dict) or not bool(site.get("persistent_control", False)):
                continue
            income = site.get("control_income", {})
            if not isinstance(income, dict):
                continue
            for resource_id, amount in income.items():
                try:
                    if int(amount) > 0:
                        persistent_income_ids.add(str(resource_id))
                except (TypeError, ValueError):
                    pass
        for town in scenario.get("towns", []):
            if not isinstance(town, dict) or str(town.get("owner", "")) != "player":
                continue
            player_town_case_count += 1
            if is_campaign:
                campaign_player_town_case_count += 1
            if is_skirmish:
                skirmish_player_town_case_count += 1
            town_id = str(town.get("town_id", "")).strip()
            town_template = towns.get(town_id, {})
            required_ids: set[str] = {"wood", "ore"}
            if isinstance(town_template, dict):
                development_balance = town_template.get("development_balance", {})
                development_balance = development_balance if isinstance(development_balance, dict) else {}
                rare_id = str(development_balance.get("rare_resource_id", "")).strip()
                if rare_id:
                    required_ids.add(rare_id)
            for resource_id in sorted(required_ids - {"gold"}):
                ensure(resource_id in persistent_income_ids, errors, f"{scenario_id}.{town_id} must have scenario-authored persistent {resource_id} income for development runway")
    ensure(active_scenario_count >= 16, errors, "Active scenario town development runway must cover the active authored scenario roster")
    ensure(campaign_scenario_count >= 15, errors, "Active scenario town development runway must cover campaign scenarios")
    ensure(skirmish_scenario_count >= 16, errors, "Active scenario town development runway must cover skirmish scenarios")
    ensure(player_town_case_count >= 18, errors, "Active scenario town development runway must cover the active player-town cases")
    ensure(campaign_player_town_case_count >= 17, errors, "Active scenario town development runway must cover campaign player-town cases")
    ensure(skirmish_player_town_case_count >= 18, errors, "Active scenario town development runway must cover skirmish player-town cases")
    for scenario_id in ("ironbridge-stand", "mireford-skirmish"):
        scenario = scenarios.get(scenario_id, {})
        node_ids = {
            str(node.get("placement_id", ""))
            for node in scenario.get("resource_nodes", [])
            if isinstance(node, dict)
        } if isinstance(scenario, dict) else set()
        town_label = "Highwater bridgehead" if scenario_id == "ironbridge-stand" else "Graftroot bridgehead"
        ensure("bridge_ore_reserve" in node_ids, errors, f"{scenario_id} must keep the {town_label} ore reserve for post-development seven-tier recruitment")


