def validate_overworld_encounter_victory_return_feedback(errors: list[str]) -> None:
    router_text = APP_ROUTER_PATH.read_text(encoding="utf-8")
    battle_rules_text = BATTLE_RULES_PATH.read_text(encoding="utf-8")
    overworld_shell_text = (ROOT / "scenes/overworld/OverworldShell.gd").read_text(encoding="utf-8")
    map_view_text = (ROOT / "scenes/overworld/OverworldMapView.gd").read_text(encoding="utf-8")
    report_path = ROOT / "tests/overworld_encounter_victory_return_feedback_report.gd"
    scene_path = ROOT / "tests/overworld_encounter_victory_return_feedback_report.tscn"
    ensure(report_path.exists(), errors, "Encounter-victory return feedback focused report script is missing")
    ensure(scene_path.exists(), errors, "Encounter-victory return feedback focused report scene is missing")
    if not report_path.exists() or not scene_path.exists():
        return

    def function_block(text: str, name: str) -> str:
        markers = (f"func {name}(", f"static func {name}(")
        starts = [text.find(marker) for marker in markers if text.find(marker) >= 0]
        if not starts:
            return ""
        start = min(starts)
        next_offsets = [offset for offset in (
            text.find("\nfunc ", start + 1),
            text.find("\nstatic func ", start + 1),
        ) if offset >= 0]
        next_func = min(next_offsets) if next_offsets else -1
        return text[start:] if next_func < 0 else text[start:next_func]

    finalize_block = function_block(battle_rules_text, "_finalize_victory")
    snapshot_block = function_block(battle_rules_text, "_battle_resolution_static_encounter_snapshot")
    arm_block = function_block(router_text, "arm_battle_resolution_overworld_presentation")
    consume_block = function_block(router_text, "consume_battle_resolution_overworld_presentation")
    record_block = function_block(overworld_shell_text, "_record_object_resolution_presentation")
    sync_block = function_block(map_view_text, "_sync_object_resolution_presentation")
    report_text = report_path.read_text(encoding="utf-8")
    scene_text = scene_path.read_text(encoding="utf-8")

    for token in (
        '"encounter": _battle_resolution_static_encounter_snapshot(session)',
        'var base_summary := _apply_battle_context_victory(session)',
        '_mark_resolved_encounter(session, String(session.battle.get("resolved_key", "")))',
        'session.battle = {}',
        '"battle_resolution_context_snapshot": resolution_context_snapshot',
    ):
        ensure(token in finalize_block, errors, f"Encounter victory snapshot order is missing token: {token}")
    ensure(finalize_block.find('"encounter": _battle_resolution_static_encounter_snapshot(session)') < finalize_block.find('var base_summary := _apply_battle_context_victory(session)') < finalize_block.find('_mark_resolved_encounter(session, String(session.battle.get("resolved_key", "")))') < finalize_block.find('session.battle = {}') < finalize_block.find('"battle_resolution_context_snapshot": resolution_context_snapshot'), errors, "Encounter identity must detach before resolution mutation, mark, battle clear, and returned result")
    for token in (
        'String(context.get("type", "")) != "encounter"',
        'var encounter := _current_battle_encounter_placement(session)',
        'var placement_id := String(encounter.get("placement_id", "")).strip_edges()',
        'var encounter_id := String(encounter.get("encounter_id", encounter.get("id", ""))).strip_edges()',
        'String(encounter.get("spawned_by_faction_id", "")).strip_edges() != ""',
        '"placement_id": placement_id',
        '"encounter_id": encounter_id',
        '"x": int(encounter.get("x", -1))',
        '"y": int(encounter.get("y", -1))',
        '"spawned_by_faction_id": ""',
    ):
        ensure(token in snapshot_block, errors, f"Static encounter snapshot helper is missing fail-closed token: {token}")
    ensure("session.overworld[" not in snapshot_block and "session.flags[" not in snapshot_block and "session.battle[" not in snapshot_block, errors, "Static encounter snapshot helper must remain detached and read-only")
    ensure("create_timer" not in snapshot_block and "await " not in snapshot_block, errors, "Static encounter snapshot helper must not add timing authority")

    for token in (
        'context_type not in ["town_assault", "resource_assault", "encounter"]',
        'var encounter_snapshot_value: Variant = snapshot.get("encounter", {})',
        'OverworldRules._find_encounter_by_placement(session, placement_id)',
        'var live_encounter_id := String(live_encounter.get("encounter_id", live_encounter.get("id", ""))).strip_edges()',
        'var encounter_content := ContentService.get_encounter(live_encounter_id)',
        'encounter_content.is_empty()',
        'not OverworldRules.is_encounter_resolved(session, live_encounter)',
        'String(live_encounter.get("spawned_by_faction_id", "")).strip_edges() != ""',
        'live_encounter_id != String(encounter_snapshot.get("encounter_id", ""))',
        'int(live_encounter.get("x", -1)) != int(encounter_snapshot.get("x", -2))',
        'int(live_encounter.get("y", -1)) != int(encounter_snapshot.get("y", -2))',
        'String(encounter_snapshot.get("spawned_by_faction_id", "")) != ""',
        'family = "encounter"',
        'event_id = "overworld_object_depleted"',
        'owner = "resolved"',
    ):
        ensure(token in arm_block, errors, f"Encounter route-local arming is missing fail-closed token: {token}")
    ensure(arm_block.find('var encounter_snapshot_value: Variant = snapshot.get("encounter", {})') < arm_block.find('OverworldRules._find_encounter_by_placement(session, placement_id)') < arm_block.find('event_id = "overworld_object_depleted"') < arm_block.find('_pending_battle_resolution_overworld_presentation = {'), errors, "Encounter arm path must validate detached and live authority before publishing")
    ensure("session.flags" not in arm_block and "SaveService" not in arm_block, errors, "Encounter return arming must remain route-local and result-only")

    for token in (
        'String(pending.get("family", "")) not in ["town_capture", "resource_site", "encounter"]',
        '(String(pending.get("event_id", "")) == "overworld_object_depleted") != (String(pending.get("family", "")) == "encounter")',
        'OverworldRules._find_encounter_by_placement(session, placement_id)',
        'ContentService.get_encounter(live_encounter_id).is_empty()',
        'not OverworldRules.is_encounter_resolved(session, live_encounter)',
        'String(live_encounter.get("spawned_by_faction_id", "")).strip_edges() != ""',
        'String(pending.get("owner", "")) != "resolved"',
        'pending["consumed"] = true',
    ):
        ensure(token in consume_block, errors, f"Encounter one-shot consumption is missing fail-closed token: {token}")
    ensure(consume_block.find('var pending := _pending_battle_resolution_overworld_presentation.duplicate(true)') < consume_block.find('_clear_pending_battle_resolution_overworld_presentation()') < consume_block.find('String(pending.get("family", "")) not in ["town_capture", "resource_site", "encounter"]') < consume_block.find('OverworldRules._find_encounter_by_placement(session, placement_id)') < consume_block.find('pending["consumed"] = true'), errors, "Encounter payload must clear before validation and consume only after exact live revalidation")
    ensure("session.flags" not in consume_block and "SaveService" not in consume_block, errors, "Encounter return consumption must not mutate session or save authority")

    ensure('family not in ["resource_site", "artifact", "town_capture", "encounter"]' in record_block, errors, "OverworldShell object-result presenter must accept the exact encounter family")
    ensure('event_id := "town_captured" if family == "town_capture" else "overworld_object_depleted"' in record_block, errors, "Encounter family must retain the existing depleted object event while town capture uses its distinct identity")
    ensure('not in ["resource_site", "artifact", "town_capture", "encounter", "site_response", "route_closure"]' in sync_block, errors, "OverworldMapView must accept the exact encounter family through the existing object-resolution lane")
    ensure("session.overworld[" not in record_block and "session.flags[" not in record_block, errors, "Encounter presentation adaptation must remain view-only")

    for token in (
        'const TARGET_WIDTHS := [1280, 1920]',
        'const ENCOUNTER_PLACEMENT_ID := "river_pass_hollow_mire"',
        'const GUARDED_RESOURCE_PLACEMENT_ID := "duskfen_bastion_peatwax_front"',
        '"unit_mireclaw_bogplate_maulers", "count": 4',
        '"unit_mireclaw_mudglass_slingers", "count": 3',
        'var route_start := encounter_tile + Vector2i(-1, 0)',
        'OverworldRules.try_move_along_route(session, [route_start, encounter_tile], 4)',
        'String(route_result.get("route", "")) != "battle"',
        '_battle_enemy_stack_contract(session.battle) != PRODUCTION_STACKS',
        '"unit_mireclaw_bogplate_maulers": ["shielding"]',
        '"unit_mireclaw_mudglass_slingers": ["harry"]',
        'BattleRules.resolve_if_battle_ready(session)',
        'OverworldRules.is_encounter_resolved(session, encounter)',
        '_resource_by_placement(session, GUARDED_RESOURCE_PLACEMENT_ID) != guarded_resource',
        'AppRouter.checkpoint_battle_resolution_for_overworld(false)',
        'var control_shell := OVERWORLD_SCENE.instantiate()',
        'var authority_after_ready_control: Dictionary = control_session.to_dict()',
        'var pending: Dictionary = AppRouter.arm_battle_resolution_overworld_presentation(outcome)',
        'String(cue.get("event_id", "")) != "overworld_object_depleted"',
        'String(cue.get("family", "")) != "encounter"',
        'String(cue.get("animation_state", "")) != "depleted_remove_or_dim"',
        'cue.get("selected_vfx_cue_ids", []) != ["vfx_placeholder_depleted_dim"]',
        'cue.get("selected_audio_cue_ids", []) != ["audio_placeholder_collect"]',
        'shell.call("_refresh")',
        'var later_shell := OVERWORLD_SCENE.instantiate()',
        'func _run_fail_closed_controls() -> bool:',
        '"encounter_missing_return_fixture"',
        'var encounter_before_spawned_control: Dictionary = _encounter_by_placement(session, ENCOUNTER_PLACEMENT_ID).duplicate(true)',
        '_replace_encounter(session, ENCOUNTER_PLACEMENT_ID, encounter_before_spawned_control)',
        '["malformed", "missing_identity", "wrong_placement", "wrong_content", "wrong_tile", "missing_content", "assault", "non_victory", "unresolved", "spawned_raid", "terminal", "stale", "wrong_surface"]',
        'session.to_dict() != authority_before',
    ):
        ensure(token in report_text, errors, f"Encounter return focused report is missing token: {token}")
    ensure(report_text.count('AppRouter.consume_battle_resolution_overworld_presentation("overworld")') == 1, errors, "Encounter stale control must consume exactly once outside live Overworld scenes")
    ensure(report_text.count('session = SessionState.set_active_session(session)') == 2, errors, "Encounter live rows and fail-closed controls must retain active SessionState authority")
    ensure(report_text.find('var control_shell := OVERWORLD_SCENE.instantiate()') < report_text.find('var authority_after_ready_control: Dictionary = control_session.to_dict()') < report_text.find('var pending: Dictionary = AppRouter.arm_battle_resolution_overworld_presentation(outcome)') < report_text.find('var shell := OVERWORLD_SCENE.instantiate()'), errors, "Encounter report must capture method-matched unarmed ready authority before arming and routed shell construction")
    ensure("session.flags[" not in report_text and "_mark_resolved_encounter" not in report_text and "_record_object_resolution_presentation" not in report_text, errors, "Focused encounter report must not synthesize resolution or call view internals directly")
    ensure('res://tests/overworld_encounter_victory_return_feedback_report.gd' in scene_text, errors, "Encounter return focused scene must load its exact report script")


def validate_frontier_claims_direct_encounter_objectives(errors: list[str]) -> None:
    scenario_path = ROOT / "content/scenarios.json"
    encounter_path = ROOT / "content/encounters.json"
    report_path = ROOT / "tests/frontier_claims_campaign_report.gd"
    if not scenario_path.exists() or not encounter_path.exists() or not report_path.exists():
        ensure(False, errors, "Frontier Claims direct encounter objective owner files are missing")
        return
    scenarios = items_index(load_json(scenario_path))
    encounters = items_index(load_json(encounter_path))
    expected = {
        "mireford-skirmish": {
            "break_ford_reavers": ("bridge_ford_reavers", "ford_reavers_broken"),
            "purge_silt_hunters": ("bridge_silt_hunters", "silt_hunters_broken"),
        },
        "orevein-contract": {
            "break_archive_wardens": ("orevein_archive_wardens", "archive_wardens_broken"),
            "break_bridgeward": ("orevein_bridgeward_levies", "bridgeward_levies_broken"),
        },
        "bellwake-wreck-claim": {
            "break_relay_pickets": ("bellwake_relay_pickets", "relay_pickets_broken"),
            "break_mirror_lancers": ("bellwake_mirror_lancers", "mirror_lancers_broken"),
        },
        "rootgate-toll": {
            "break_charter_toll": ("rootgate_charter_guard", "charter_guard_broken"),
            "break_bastion_reserve": ("rootgate_bastion_reserve", "charter_bastion_reserve_broken"),
        },
        "fogchart-mooring": {
            "break_fogchart_relay_pickets": ("fogchart_relay_pickets", "relay_pickets_broken"),
            "break_fogchart_mirror_lancers": ("fogchart_mirror_lancers", "mirror_lancers_broken"),
        },
        "clauseworks-counterclaim": {
            "break_clauseworks_archive_wardens": ("clauseworks_archive_wardens", "archive_wardens_broken"),
            "break_clauseworks_bridge_levies": ("clauseworks_bridge_levies", "bridgeward_levies_broken"),
        },
        "nightglass-ledger-reversal": {
            "break_nightglass_ledger_guard": ("nightglass_ledger_guard", "charter_guard_broken"),
            "break_nightglass_rivet_auditors": ("nightglass_rivet_auditors", "charter_bastion_reserve_broken"),
        },
    }
    ensure(sum(len(rows) for rows in expected.values()) == 14, errors, "Frontier Claims direct encounter objective map must retain exactly fourteen rows")
    mireford = scenarios.get("mireford-skirmish", {})
    mireford_map = mireford.get("map", []) if isinstance(mireford.get("map", []), list) else []
    ensure(len(mireford_map) == 6 and isinstance(mireford_map[3], list) and len(mireford_map[3]) == 10 and str(mireford_map[3][1]) == "grass", errors, "Frontier Claims Mireford start lane must retain exact open grass cell (1,3)")
    mireford_resources = {str(row.get("placement_id", "")): row for row in mireford.get("resource_nodes", []) if isinstance(row, dict)}
    ensure({"x": int(mireford_resources.get("graftroot_rootwatch_hollow", {}).get("x", -1)), "y": int(mireford_resources.get("graftroot_rootwatch_hollow", {}).get("y", -1))} == {"x": 2, "y": 5}, errors, "Frontier Claims Mireford Rootwatch Hollow must retain exact open start-lane placement (2,5)")
    for scenario_id, expected_rows in expected.items():
        scenario = scenarios.get(scenario_id, {})
        victory = {
            str(row.get("id", "")): row
            for row in scenario.get("objectives", {}).get("victory", [])
            if isinstance(row, dict)
        }
        placements = {
            str(row.get("placement_id", "")): row
            for row in scenario.get("encounters", [])
            if isinstance(row, dict)
        }
        for objective_id, (placement_id, flag_id) in expected_rows.items():
            objective = victory.get(objective_id, {})
            ensure(
                objective.get("type") == "encounter_resolved"
                and str(objective.get("placement_id", "")) == placement_id
                and "flag" not in objective,
                errors,
                f"Frontier Claims {scenario_id}/{objective_id} must use exact direct encounter authority {placement_id}",
            )
            placement = placements.get(placement_id, {})
            encounter = encounters.get(str(placement.get("encounter_id", "")), {})
            ensure(flag_id in string_list(encounter.get("victory_flags", [])), errors, f"Frontier Claims {scenario_id}/{placement_id} must retain encounter victory flag {flag_id}")

    report_text = report_path.read_text(encoding="utf-8")
    for token in (
        "const DIRECT_ENCOUNTER_OBJECTIVES := {",
        "func _assert_direct_encounter_objective_authority() -> Dictionary:",
        'objective.get("type") != "encounter_resolved"',
        'objective.has("flag")',
        'ContentService.get_encounter(String(placement.get("encounter_id", "")))',
        'flag_id not in victory_flags',
        'session.flags[String(expected.get("flag", ""))] = true',
        'if placement_id != omitted_placement:',
        'ScenarioRulesScript.evaluate_session(session).get("status", "")',
        '!= "in_progress"',
        'resolved.append(omitted_placement)',
        '!= "victory"',
        '"objective_count": objective_count',
        'String(mireford_map[3][1]) != "grass"',
        'int(mireford_rootwatch.get("x", -1)) != 2 or int(mireford_rootwatch.get("y", -1)) != 5',
    ):
        ensure(token in report_text, errors, f"Frontier Claims direct encounter runtime owner is missing token: {token}")
    ensure(report_text.find('session.flags[String(expected.get("flag", ""))] = true') < report_text.find('if placement_id != omitted_placement:') < report_text.find('!= "in_progress"') < report_text.find('resolved.append(omitted_placement)') < report_text.find('!= "victory"'), errors, "Frontier Claims runtime owner must prove flags cannot bypass exact encounter resolution before proving victory")
    ensure('objective["type"] =' not in report_text and 'objective["placement_id"] =' not in report_text, errors, "Frontier Claims focused owner must observe authored objective authority without mutating it")
    focused_resolved = {
        "tests/thornwake_mireford_player_skirmish_report.gd": '["bridge_ford_reavers", "bridge_silt_hunters", "mireford_reed_totemists"]',
        "tests/brasshollow_orevein_player_skirmish_report.gd": '["orevein_archive_wardens", "orevein_bridgeward_levies", "orevein_beacon_wardens"]',
        "tests/veilmourn_bellwake_wreck_player_skirmish_report.gd": '["bellwake_relay_pickets", "bellwake_mirror_lancers", "bellwake_aurora_battery"]',
        "tests/thornwake_rootgate_toll_chapter_report.gd": '["rootgate_charter_guard", "rootgate_bastion_reserve", "rootgate_boiler_exactors"]',
        "tests/veilmourn_fogchart_mooring_chapter_report.gd": '["fogchart_relay_pickets", "fogchart_mirror_lancers", "fogchart_aurora_battery"]',
        "tests/brasshollow_clauseworks_counterclaim_chapter_report.gd": '["clauseworks_archive_wardens", "clauseworks_bridge_levies", "clauseworks_beacon_wardens"]',
        "tests/mireclaw_nightglass_ledger_reversal_chapter_report.gd": '["nightglass_ledger_guard", "nightglass_rivet_auditors", "nightglass_furnace_exactors"]',
    }
    for relative_path, exact_array in focused_resolved.items():
        owner_text = (ROOT / relative_path).read_text(encoding="utf-8")
        ensure(exact_array in owner_text, errors, f"{relative_path} must resolve all three exact authored encounter placements")
    bellwake_owner_text = (ROOT / "tests/veilmourn_bellwake_wreck_player_skirmish_report.gd").read_text(encoding="utf-8")
    for token in (
        'var expected_enemy_stacks := {"unit_sunvault_shard_wardens": 9, "unit_sunvault_prism_adepts": 7, "unit_sunvault_mirror_duelists": 8}',
        'var expected_enemy_abilities := {"unit_sunvault_shard_wardens": ["shielding"], "unit_sunvault_prism_adepts": ["volley"], "unit_sunvault_mirror_duelists": ["backstab", "reach"]}',
        "enemy_stacks != expected_enemy_stacks",
        "enemy_abilities != expected_enemy_abilities",
        '"enemy_stacks": enemy_stacks',
        '"enemy_abilities": enemy_abilities',
    ):
        ensure(token in bellwake_owner_text, errors, f"Bellwake skirmish owner is missing exact production battle token: {token}")


def validate_thornwake_rootgate_toll_chapter(errors: list[str]) -> None:
    scenario_path = ROOT / "content/scenarios.json"
    campaign_path = ROOT / "content/campaigns.json"
    report_path = ROOT / "tests/thornwake_rootgate_toll_chapter_report.gd"
    scene_path = ROOT / "tests/thornwake_rootgate_toll_chapter_report.tscn"
    frontier_report_path = ROOT / "tests/frontier_claims_campaign_report.gd"
    for path in (scenario_path, campaign_path, report_path, scene_path, frontier_report_path):
        ensure(path.exists(), errors, f"Rootgate Toll chapter owner is missing {path.relative_to(ROOT)}")
    if not scenario_path.exists() or not campaign_path.exists():
        return
    scenario_payload = load_json(scenario_path)
    campaign_payload = load_json(campaign_path)
    scenarios = items_index(scenario_payload)
    campaigns = items_index(campaign_payload)
    ensure(int(scenario_payload.get("player_facing_active_scenario_count", 0)) >= 183, errors, "Rootgate Toll compatibility must cover the current exact ninety-nine-scenario active roster")
    scenario_rows = scenario_payload.get("items", []) if isinstance(scenario_payload.get("items", []), list) else []
    ensure(len(scenario_rows) >= 183 and str(scenario_rows[18].get("id", "")) == "rootgate-toll", errors, "Rootgate Toll must remain the exact nineteenth active authored scenario")
    scenario = scenarios.get("rootgate-toll", {})
    ensure(bool(scenario), errors, "Rootgate Toll scenario is missing")
    ensure(str(scenario.get("player_faction_id", "")) == "faction_thornwake", errors, "Rootgate Toll must remain a Thornwake scenario")
    ensure(str(scenario.get("hero_id", "")) == "hero_thornwake_tova_rootwright", errors, "Rootgate Toll must retain Tova Rootwright")
    ensure(str(scenario.get("player_army_id", "")) == "army_graftroot_wardens", errors, "Rootgate Toll must retain Graftroot Wardens")
    ensure(scenario.get("map_size", {}) == {"width": 11, "height": 6}, errors, "Rootgate Toll must retain its exact 11x6 authored map")
    availability = scenario.get("selection", {}).get("availability", {}) if isinstance(scenario.get("selection", {}), dict) else {}
    ensure(availability == {"campaign": True, "skirmish": True}, errors, "Rootgate Toll must remain campaign- and skirmish-selectable")
    towns = {str(row.get("placement_id", "")): row for row in scenario.get("towns", []) if isinstance(row, dict)}
    ensure(str(towns.get("rootgate_nursery", {}).get("town_id", "")) == "town_thornwake_rootgate_nursery", errors, "Rootgate Toll must use the authored Rootgate Nursery")
    ensure(str(towns.get("rootgate_nursery", {}).get("owner", "")) == "player", errors, "Rootgate Nursery must remain the player town")
    ensure(str(towns.get("clauseworks_toll_depot", {}).get("town_id", "")) == "town_brasshollow_clauseworks_depot", errors, "Rootgate Toll must use the authored Clauseworks Depot")
    ensure(str(towns.get("clauseworks_toll_depot", {}).get("owner", "")) == "enemy", errors, "Clauseworks Depot must remain hostile")
    enemy_factions = [row for row in scenario.get("enemy_factions", []) if isinstance(row, dict)]
    ensure(len(enemy_factions) == 1 and str(enemy_factions[0].get("faction_id", "")) == "faction_brasshollow", errors, "Rootgate Toll must retain one exact Brasshollow enemy empire")
    encounters = {str(row.get("placement_id", "")): row for row in scenario.get("encounters", []) if isinstance(row, dict)}
    ensure(list(encounters) == ["rootgate_charter_guard", "rootgate_bastion_reserve", "rootgate_boiler_exactors"], errors, "Rootgate Toll must retain its exact ordered three encounter fronts")
    ensure([str(encounters[key].get("encounter_id", "")) for key in encounters] == ["encounter_charter_guard", "encounter_charter_bastion_reserve", "encounter_orevein_exactors"], errors, "Rootgate Toll encounter fronts must retain their authored content identities")
    rootgate_stack_counts = {
        placement_id: [
            {"unit_id": str(stack.get("unit_id", "")), "count": int(stack.get("count", 0))}
            for stack in encounter.get("enemy_army", {}).get("stacks", [])
            if isinstance(stack, dict)
        ]
        for placement_id, encounter in encounters.items()
    }
    ensure(rootgate_stack_counts == {
        "rootgate_charter_guard": [
            {"unit_id": "unit_brasshollow_scrip_haulers", "count": 8},
            {"unit_id": "unit_brasshollow_rivet_hounds", "count": 5},
            {"unit_id": "unit_brasshollow_furnace_pavis_teams", "count": 1},
        ],
        "rootgate_bastion_reserve": [
            {"unit_id": "unit_brasshollow_scrip_haulers", "count": 7},
            {"unit_id": "unit_brasshollow_rivet_hounds", "count": 4},
            {"unit_id": "unit_brasshollow_furnace_pavis_teams", "count": 2},
        ],
        "rootgate_boiler_exactors": [
            {"unit_id": "unit_brasshollow_scrip_haulers", "count": 6},
            {"unit_id": "unit_brasshollow_rivet_hounds", "count": 4},
            {"unit_id": "unit_brasshollow_furnace_pavis_teams", "count": 1},
        ],
    }, errors, "Rootgate Toll must retain the method-matched queue-clear encounter rosters")
    objectives = scenario.get("objectives", {}) if isinstance(scenario.get("objectives", {}), dict) else {}
    victory = {str(row.get("id", "")): row for row in objectives.get("victory", []) if isinstance(row, dict)}
    defeat = {str(row.get("id", "")): row for row in objectives.get("defeat", []) if isinstance(row, dict)}
    ensure(str(victory.get("claim_clauseworks_depot", {}).get("placement_id", "")) == "clauseworks_toll_depot", errors, "Rootgate Toll victory must retain Clauseworks capture")
    ensure(str(victory.get("break_charter_toll", {}).get("placement_id", "")) == "rootgate_charter_guard", errors, "Rootgate Toll victory must require exact Charter Guard encounter clearance")
    ensure(str(victory.get("break_bastion_reserve", {}).get("placement_id", "")) == "rootgate_bastion_reserve", errors, "Rootgate Toll victory must require exact Bastion Reserve encounter clearance")
    ensure(str(victory.get("clear_boiler_exactors", {}).get("placement_id", "")) == "rootgate_boiler_exactors", errors, "Rootgate Toll victory must retain Boiler Exactors clearance")
    ensure(int(defeat.get("root_the_road_before_daybreak", {}).get("day", 0)) == 12, errors, "Rootgate Toll must retain its exact Day 12 deadline")
    resource_nodes = {str(row.get("placement_id", "")): row for row in scenario.get("resource_nodes", []) if isinstance(row, dict)}
    required_resources = {
        "rootgate_wood": "site_wood_wagon",
        "rootgate_ore": "site_ore_crates",
        "rootgate_verdant_nursery": "site_verdant_graft_nursery",
        "rootgate_toll_rootgate_nursery_rare_exchange": "site_frontier_rare_exchange",
        "clauseworks_wood": "site_wood_wagon",
        "clauseworks_ore": "site_ore_crates",
        "clauseworks_scrip_mint": "site_brass_scrip_mint",
        "rootgate_toll_clauseworks_toll_depot_rare_exchange": "site_frontier_rare_exchange",
    }
    ensure({key: str(resource_nodes.get(key, {}).get("site_id", "")) for key in required_resources} == required_resources, errors, "Rootgate Toll must retain exact player/enemy common and rare economy sources")
    ensure(all(bool(str(resource_nodes.get(key, {}).get("guard_front_id", ""))) for key in ("rootgate_verdant_nursery", "rootgate_toll_rootgate_nursery_rare_exchange", "clauseworks_scrip_mint", "rootgate_toll_clauseworks_toll_depot_rare_exchange")), errors, "Rootgate Toll rare sources must remain encounter-guarded")
    campaign = campaigns.get("campaign_frontier_claims", {})
    chapters = [row for row in campaign.get("scenarios", []) if isinstance(row, dict)]
    ensure([str(row.get("scenario_id", "")) for row in chapters] == ["mireford-skirmish", "orevein-contract", "bellwake-wreck-claim", "rootgate-toll", "fogchart-mooring", "clauseworks-counterclaim", "nightglass-ledger-reversal", "halo-reserve-refraction-claim", "charter-bastion-counterseal"], errors, "Frontier Claims must retain its exact nine-chapter order")
    if len(chapters) == 9:
        bellwake_export = chapters[2].get("carryover_export", {}) if isinstance(chapters[2].get("carryover_export", {}), dict) else {}
        rootgate_import = chapters[3].get("carryover_import", {}) if isinstance(chapters[3].get("carryover_import", {}), dict) else {}
        rootgate_unlocks = chapters[3].get("unlock_requirements", []) if isinstance(chapters[3].get("unlock_requirements", []), list) else []
        ensure(bellwake_export.get("retain_hero_progression") is False and bellwake_export.get("retain_spells") is False and bellwake_export.get("retain_artifacts") is False, errors, "Bellwake export must not transfer cross-faction personal progression")
        ensure(bellwake_export.get("resource_caps", {}) == {"gold": 1200, "wood": 3, "ore": 3, "memory_salt": 2}, errors, "Bellwake export must retain exact bounded resource caps")
        ensure(rootgate_import == {"from_scenario_id": "bellwake-wreck-claim", "resources": True, "hero_progression": False, "spells": False, "artifacts": False, "flags_prefix": "carryover_"}, errors, "Rootgate import must retain bounded resource/flag-only authority")
        ensure(rootgate_unlocks == [{"type": "scenario_status", "scenario_id": "bellwake-wreck-claim", "status": "victory"}, {"type": "scenario_flag_true", "scenario_id": "bellwake-wreck-claim", "flag": "drowned_chart_recorded"}], errors, "Rootgate chapter must unlock only from exact Bellwake victory and drowned-chart evidence")
    if report_path.exists():
        report_text = report_path.read_text(encoding="utf-8")
        for token in (
            "THORNWAKE_ROOTGATE_TOLL_CHAPTER_REPORT",
            'const SCENARIO_ID := "rootgate-toll"',
            'const HERO_ID := "hero_thornwake_tova_rootwright"',
            'const ARMY_ID := "army_graftroot_wardens"',
            'scenario_ids.size() != 24',
            'scenario_ids[18] != SCENARIO_ID',
            'int(map_size.get("width", 0)) != 11 or int(map_size.get("height", 0)) != 6',
            "ScenarioSelectRulesScript.build_skirmish_setup",
            "ScenarioFactoryScript.create_session",
            "TownRulesScript.get_build_actions",
            "TownRulesScript.recruit_active_town",
            "BattleRulesScript.create_battle_payload",
            "ScenarioRulesScript.evaluate_session",
            "CampaignRulesScript.build_chapter_action",
            "CampaignRulesScript.record_session_completion",
            "CampaignRulesScript.build_session",
            "SaveService.save_runtime_manual_session",
            "SaveService.restore_manual_session",
            '"locked_before_bellwake": true',
            '"unlocked_after_exact_bellwake_evidence": true',
            '"hero_spell_artifact_transfer": false',
            'get_tree().quit(0)',
            'get_tree().quit(1)',
        ):
            ensure(token in report_text, errors, f"Rootgate Toll focused report is missing token: {token}")
        ensure("BattleRulesScript.resolve" not in report_text and "OverworldRules._" not in report_text, errors, "Rootgate Toll focused owner must use public rules and must not synthesize combat or call Overworld internals")
    if scene_path.exists():
        ensure('res://tests/thornwake_rootgate_toll_chapter_report.gd' in scene_path.read_text(encoding="utf-8"), errors, "Rootgate Toll focused scene must load its exact report script")
    if frontier_report_path.exists():
        frontier_text = frontier_report_path.read_text(encoding="utf-8")
        for token in (
            'const ROOTGATE_ID := "rootgate-toll"',
            'const ROOTGATE_HERO_ID := "hero_thornwake_tova_rootwright"',
            'entries.size() != 9',
            '"carryover_drowned_chart_recorded"',
            '[MIREFORD_ID, OREVEIN_ID, BELLWAKE_ID, ROOTGATE_ID, FOGCHART_ID, CLAUSEWORKS_ID, NIGHTGLASS_ID, HALO_RESERVE_ID, CHARTER_COUNTERSEAL_ID]',
            'String(start_action.get("scenario_id", "")) != CHARTER_COUNTERSEAL_ID',
        ):
            ensure(token in frontier_text, errors, f"Frontier Claims runtime owner is missing Rootgate token: {token}")


def validate_veilmourn_fogchart_mooring_chapter(errors: list[str]) -> None:
    scenario_path = ROOT / "content/scenarios.json"
    campaign_path = ROOT / "content/campaigns.json"
