def validate_six_sovereign_wild_habitats(errors: list[str]) -> None:
    slice_id = "content-six-sovereign-wild-habitats-10184"
    atlas_res = "res://art/overworld/runtime/objects/resource_sites/sovereign_wild_habitats/sovereign_wild_habitats_atlas.png"
    atlas_path = res_path_to_disk(atlas_res)
    source_dir = ROOT / "art" / "overworld" / "source" / "generated" / "resource_sites" / "sovereign_wild_habitats"
    source_manifest_path = source_dir / "manifest.json"
    unit_source_manifest_path = ROOT / "art" / "units" / "source" / "generated" / "sovereign_wilds_wave1" / "manifest.json"
    smoke_script_path = ROOT / "tests" / "six_sovereign_wild_habitats_smoke.gd"
    smoke_scene_path = ROOT / "tests" / "six_sovereign_wild_habitats_smoke.tscn"
    smoke_report_path = ROOT / ".artifacts" / "six_sovereign_wild_habitats_smoke" / "report.json"
    required_paths = (atlas_path, source_manifest_path, unit_source_manifest_path, smoke_script_path, smoke_scene_path)
    for path in required_paths:
        ensure(path.is_file(), errors, f"Missing sovereign-wild production owner: {path.relative_to(ROOT)}")
    if not all(path.is_file() for path in required_paths):
        return

    expected = {
        "ashcrown_cinderfold": ("site_ashcrown_cinderfold", "object_ashcrown_cinderfold", "neutral_dwelling_ashcrown_cinderfold", "unit_neutral_ashcrown_kilnelk", 6, ["reach", "bloodrush"], "army_neutral_ashcrown_cinderfold_watch", "encounter_ashcrown_cinderfold_watch", "rainledger-cinder-convergence", "rainledger_ashcrown_cinderfold", "rainledger_ashcrown_cinderfold_watch", [0,0,48,48], [48,0,48,48]),
        "miremoon_crownmere": ("site_miremoon_crownmere", "object_miremoon_crownmere", "neutral_dwelling_miremoon_crownmere", "unit_neutral_miremoon_crownmaws", 6, ["brace", "shielding"], "army_neutral_miremoon_crownmere_watch", "encounter_miremoon_crownmere_watch", "fenwake-bogbell-convergence", "fenwake_miremoon_crownmere", "fenwake_miremoon_crownmere_watch", [96,0,48,48], [144,0,48,48]),
        "noonshard_prism_aviary": ("site_noonshard_prism_aviary", "object_noonshard_prism_aviary", "neutral_dwelling_noonshard_prism_aviary", "unit_neutral_noonshard_prism_kites", 6, ["harry", "volley"], "army_neutral_noonshard_prism_aviary_watch", "encounter_noonshard_prism_aviary_watch", "halometer-icehook-convergence", "halometer_noonshard_prism_aviary", "halometer_noonshard_prism_aviary_watch", [192,0,48,48], [240,0,48,48]),
        "rootvault_heartwood_hollow": ("site_rootvault_heartwood_hollow", "object_rootvault_heartwood_hollow", "neutral_dwelling_rootvault_heartwood_hollow", "unit_neutral_rootvault_barkhulks", 7, ["brace", "shielding"], "army_neutral_rootvault_heartwood_watch", "encounter_rootvault_heartwood_watch", "graftsibyl-lantern-convergence", "graftsibyl_rootvault_heartwood_hollow", "graftsibyl_rootvault_heartwood_watch", [288,0,48,48], [336,0,48,48]),
        "quenchbell_pressure_den": ("site_quenchbell_pressure_den", "object_quenchbell_pressure_den", "neutral_dwelling_quenchbell_pressure_den", "unit_neutral_quenchbell_ironbacks", 7, ["reach", "bloodrush"], "army_neutral_quenchbell_pressure_den_watch", "encounter_quenchbell_pressure_den_watch", "debtrune-default-convergence", "debtrune_quenchbell_pressure_den", "debtrune_quenchbell_pressure_den_watch", [384,0,48,48], [432,0,48,48]),
        "saltwake_belldeep": ("site_saltwake_belldeep", "object_saltwake_belldeep", "neutral_dwelling_saltwake_belldeep", "unit_neutral_saltwake_bellwhales", 7, ["harry", "volley"], "army_neutral_saltwake_belldeep_watch", "encounter_saltwake_belldeep_watch", "nightchart-meridian-convergence", "nightchart_saltwake_belldeep", "nightchart_saltwake_belldeep_watch", [480,0,48,48], [528,0,48,48]),
    }
    units = items_index(load_json(CONTENT_DIR / "units.json"))
    groups = items_index(load_json(CONTENT_DIR / "army_groups.json"))
    encounters = items_index(load_json(CONTENT_DIR / "encounters.json"))
    dwellings = items_index(load_json(CONTENT_DIR / "neutral_dwellings.json"))
    sites = items_index(load_json(CONTENT_DIR / "resource_sites.json"))
    objects = items_index(load_json(CONTENT_DIR / "map_objects.json"))
    scenarios = items_index(load_json(CONTENT_DIR / "scenarios.json"))
    art = load_json(OVERWORLD_ART_MANIFEST_PATH)
    object_assets = art.get("object_assets", {})
    site_sprites = art.get("resource_site_sprites", {})
    encounter_sprites = art.get("encounter_identity_sprites", {})
    unit_art = {str(row.get("unit_id", "")): row for row in load_json(CONTENT_DIR / "unit_art_manifest.json").get("items", []) if isinstance(row, dict)}
    unit_animation = {str(row.get("unit_id", "")): row for row in load_json(CONTENT_DIR / "unit_animation_manifest.json").get("items", []) if isinstance(row, dict)}
    ensure(len(units) >= 136 and (len(groups),len(encounters),len(dwellings),len(sites),len(objects)) == (437,203,49,377,422), errors, "Sovereign-wild batch catalogs changed")
    atlas_payload = atlas_path.read_bytes()
    atlas_sha = "f6259ada356954a727e2b7a9859164ea7b74a0d019fc14e4f0454493962b3a32"
    ensure(png_size(atlas_path) == (576,48) and hashlib.sha256(atlas_payload).hexdigest() == atlas_sha and len(atlas_payload) >= 26 and atlas_payload[25] in {4,6}, errors, "Sovereign-wild habitat atlas bytes, size, or alpha changed")
    ensure(Path(f"{atlas_path}.import").is_file(), errors, "Sovereign-wild habitat atlas Godot import metadata is missing")
    source_manifest = load_json(source_manifest_path)
    unit_source_manifest = load_json(unit_source_manifest_path)
    source_rows = source_manifest.get("assets", [])
    unit_source_rows = {str(row.get("unit_id", "")): row for row in unit_source_manifest.get("items", []) if isinstance(row, dict)}
    ensure(source_manifest.get("content_slice_id") == slice_id and source_manifest.get("runtime_sha256") == atlas_sha and source_manifest.get("atlas_size") == [576,48] and len(source_rows) == 12, errors, "Sovereign-wild habitat generated-source provenance changed")
    ensure(unit_source_manifest.get("content_slice_id") == slice_id and set(unit_source_rows) == {row[3] for row in expected.values()}, errors, "Sovereign-wild unit generated-source provenance changed")

    for stem, row in expected.items():
        site_id, object_id, dwelling_id, unit_id, tier, ability_ids, group_id, encounter_id, scenario_id, placement_id, guard_id, unclaimed_region, controlled_region = row
        unit = units.get(unit_id, {})
        ensure(unit.get("content_status") == "sovereign_wilds_live" and unit.get("affiliation") == "neutral" and unit.get("tier") == tier and [ability.get("id") for ability in unit.get("abilities", [])] == ability_ids, errors, f"{unit_id} live tier or ability identity changed")
        dwelling = dwellings.get(dwelling_id, {})
        ensure(dwelling.get("content_status") == "sovereign_wild_neutral_dwelling_live" and dwelling.get("unit_ids", [None])[0] == unit_id and site_id in dwelling.get("site_ids", []) and object_id in dwelling.get("map_object_ids", []), errors, f"{dwelling_id} content graph changed")
        site = sites.get(site_id, {})
        ensure(site.get("content_batch_id") == slice_id and site.get("persistent_control") is True and unit_id in site.get("claim_recruits", {}) and unit_id in site.get("weekly_recruits", {}) and site.get("guard_profile", {}).get("guard_army_group_id") == group_id and site.get("guard_profile", {}).get("guard_encounter_id") == encounter_id, errors, f"{site_id} recruitment or guard contract changed")
        obj = objects.get(object_id, {})
        ensure(obj.get("resource_site_id") == site_id and obj.get("dwelling_contract", {}).get("neutral_dwelling_family_id") == dwelling_id and obj.get("guard_expectation", {}).get("guard_army_group_id") == group_id and obj.get("runtime_boundary", {}).get("status") == "neutral_dwelling_live", errors, f"{object_id} interaction contract changed")
        group = groups.get(group_id, {})
        encounter = encounters.get(encounter_id, {})
        ensure(group.get("affiliation") == "neutral" and any(stack.get("unit_id") == unit_id and int(stack.get("count", 0)) > 0 for stack in group.get("stacks", [])), errors, f"{group_id} no longer fields {unit_id}")
        ensure(encounter.get("enemy_group_id") == group_id and len(encounter.get("field_objectives", [])) == 1 and len(encounter.get("victory_flags", [])) >= 1, errors, f"{encounter_id} production battle contract changed")
        scenario = scenarios.get(scenario_id, {})
        node = next((value for value in scenario.get("resource_nodes", []) if value.get("placement_id") == placement_id), {})
        guard = next((value for value in scenario.get("encounters", []) if value.get("placement_id") == guard_id), {})
        ensure(node.get("site_id") == site_id and node.get("guard_front_id") == guard_id and (node.get("x"),node.get("y")) == (5,3), errors, f"{placement_id} site placement changed")
        ensure(guard.get("encounter_id") == encounter_id and (guard.get("x"),guard.get("y")) == (6,3) and guard.get("guard_link", {}).get("target_placement_id") == placement_id, errors, f"{guard_id} blocking-front placement changed")
        unclaimed_id = f"mapobj_{stem}"
        controlled_id = f"resource_site_neutral_{stem}_controlled"
        unclaimed = object_assets.get(unclaimed_id, {})
        controlled = object_assets.get(controlled_id, {})
        ensure(unclaimed.get("path") == atlas_res and unclaimed.get("atlas_region") == unclaimed_region and unclaimed.get("atlas_size") == [576,48] and unclaimed.get("assigned_map_object_id") == object_id, errors, f"{object_id} unclaimed art changed")
        ensure(controlled.get("path") == atlas_res and controlled.get("atlas_region") == controlled_region and controlled.get("atlas_size") == [576,48] and controlled.get("assigned_resource_site_id") == site_id, errors, f"{site_id} controlled art changed")
        ensure(site_sprites.get(site_id, {}).get("asset_id") == controlled_id and site_sprites.get(site_id, {}).get("unclaimed_asset_id") == unclaimed_id, errors, f"{site_id} runtime sprite switch changed")
        encounter_asset_id = f"encounter_sovereign_wild_{stem}_watch"
        ensure(encounter_sprites.get(encounter_id) == encounter_asset_id and object_assets.get(encounter_asset_id, {}).get("path") == f"res://art/units/overworld_icons/{unit_id}.png", errors, f"{encounter_id} exact creature identity art changed")
        art_record = unit_art.get(unit_id, {})
        animation_record = unit_animation.get(unit_id, {})
        surface_paths = [res_path_to_disk(str(art_record.get(key, ""))) for key in ("portrait","battle_icon","battle_standee","overworld_icon")] + [res_path_to_disk(str(animation_record.get("sprite_sheet", "")))]
        ensure([png_size(path) for path in surface_paths] == [(384,512),(160,160),(192,224),(96,96),(256,896)], errors, f"{unit_id} runtime art surfaces changed")
        provenance = unit_source_rows.get(unit_id, {})
        curated_path = res_path_to_disk(str(provenance.get("curated_path", "")))
        source_path = res_path_to_disk(str(provenance.get("source_path", "")))
        ensure(png_size(curated_path) == (512,512) and hashlib.sha256(curated_path.read_bytes()).hexdigest() == provenance.get("curated_sha256") and png_size(source_path) == (1254,1254) and hashlib.sha256(source_path.read_bytes()).hexdigest() == provenance.get("source_sha256"), errors, f"{unit_id} source provenance or curated master changed")

    artifacts_payload = load_json(CONTENT_DIR / "artifacts.json")
    artifacts = items_index(artifacts_payload)
    trophy_table = next((row for row in artifacts_payload.get("source_reward_tables", []) if isinstance(row, dict) and row.get("id") == "artifact_source_sovereign_wild_trophies"), {})
    trophy_manifest_path = ROOT / "art" / "artifacts" / "source" / "generated" / "sovereign_wild_trophies" / "manifest.json"
    ensure(trophy_manifest_path.is_file(), errors, "Sovereign-wild trophy generation provenance is missing")
    trophy_manifest = load_json(trophy_manifest_path) if trophy_manifest_path.is_file() else {}
    trophy_rows = {str(row.get("artifact_id", "")): row for row in trophy_manifest.get("items", []) if isinstance(row, dict)}
    trophy_expected = {
        "faction_embercourt": ("site_ashcrown_cinderfold", "artifact_ashcrown_crownring", {"battle_attack":1,"battle_defense":1}),
        "faction_mireclaw": ("site_miremoon_crownmere", "artifact_miremoon_crown_tooth", {"battle_initiative":1,"scouting_radius":1}),
        "faction_sunvault": ("site_noonshard_prism_aviary", "artifact_noonshard_facet_pinion", {"battle_spell_resistance_pct":10,"battle_initiative":1}),
        "faction_thornwake": ("site_rootvault_heartwood_hollow", "artifact_rootvault_heartgrain_mantle", {"battle_defense":2,"overworld_movement":1}),
        "faction_brasshollow": ("site_quenchbell_pressure_den", "artifact_quenchbell_red_gauge_plate", {"battle_attack":1,"battle_defense":2}),
        "faction_veilmourn": ("site_saltwake_belldeep", "artifact_saltwake_resonance_bell", {"scouting_radius":2,"overworld_movement":1}),
    }
    trophy_ids = {row[1] for row in trophy_expected.values()}
    ensure(trophy_manifest.get("generator_mode") == "built_in_image_gen" and trophy_manifest.get("runtime_icon_size") == [128,128] and set(trophy_rows) == trophy_ids, errors, "Sovereign-wild trophy manifest must own exactly six generated runtime icons")
    ensure(trophy_table.get("source_tag") == "dwelling" and trophy_table.get("guard_tiers") == ["sovereign", "apex"] and set(trophy_table.get("artifact_ids", [])) == trophy_ids and trophy_table.get("artifact_ids_by_faction") == {faction_id:[row[1]] for faction_id,row in trophy_expected.items()}, errors, "Sovereign-wild trophy reward table lost exact faction selection")
    for faction_id, (site_id, artifact_id, bonuses) in trophy_expected.items():
        artifact = artifacts.get(artifact_id, {})
        site = sites.get(site_id, {})
        contract = site.get("artifact_reward_contract", {}) if isinstance(site.get("artifact_reward_contract"), dict) else {}
        row = trophy_rows.get(artifact_id, {})
        source_path = res_path_to_disk(str(row.get("source_path", "")))
        runtime_path = res_path_to_disk(str(row.get("runtime_path", "")))
        source_bytes = source_path.read_bytes() if source_path.is_file() else b""
        runtime_bytes = runtime_path.read_bytes() if runtime_path.is_file() else b""
        ensure(artifact.get("family") == "sovereign_wild_trophies" and artifact.get("faction_affinity") == [faction_id] and artifact.get("source_tags") == ["dwelling"] and artifact.get("bonuses") == bonuses and artifact.get("rarity") == "rare", errors, f"{artifact_id} identity or supported bonuses changed")
        ensure(contract.get("source_tag") == "dwelling" and contract.get("artifact_reward_table_id") == "artifact_source_sovereign_wild_trophies" and contract.get("reward_categories") == ["recruit", "artifact"] and site.get("runtime_boundary", {}).get("artifact_reward_execution") is True, errors, f"{site_id} live trophy reward contract changed")
        ensure(source_path.is_file() and len(source_bytes) >= 26 and source_bytes[25] == 6 and hashlib.sha256(source_bytes).hexdigest() == row.get("source_sha256"), errors, f"{artifact_id} transparent generated source or provenance changed")
        ensure(runtime_path.is_file() and png_size(runtime_path) == (128,128) and hashlib.sha256(runtime_bytes).hexdigest() == row.get("runtime_sha256") and Path(f"{runtime_path}.import").is_file(), errors, f"{artifact_id} runtime icon or Godot import changed")
        ensure(len(str(row.get("accessible_description", ""))) >= 64 and str(row.get("generation_original", "")).startswith("/root/.codex/generated_images/"), errors, f"{artifact_id} accessibility or image-generation provenance changed")

    smoke_text = smoke_script_path.read_text(encoding="utf-8")
    for token in ("SIX_SOVEREIGN_WILD_HABITATS_SMOKE", "AbilityRuntimeReportScript", "BattleRules.create_battle_payload", "validation_encounter_presentation_payload", "await super._validate_case", "artifact_source_sovereign_wild_trophies", "ArtifactRules.aggregate_bonuses", "artifact_save_round_trip_exact"):
        ensure(token in smoke_text, errors, f"Sovereign-wild consolidated smoke is missing proof token: {token}")
    ensure("res://tests/six_sovereign_wild_habitats_smoke.gd" in smoke_scene_path.read_text(encoding="utf-8"), errors, "Sovereign-wild smoke scene lost its exact script")
    if smoke_report_path.is_file():
        smoke = load_json(smoke_report_path)
        ensure(smoke.get("ok") is True and smoke.get("case_count") == 6 and smoke.get("save_version") == 9 and len(smoke.get("rows", [])) == 6 and all(row.get("save_round_trip_exact") and row.get("exact_identity_art") and len(row.get("ability_results", {})) == 2 and row.get("artifact_auto_equipped") and row.get("artifact_bonus_exact") and row.get("artifact_provenance_exact") and row.get("artifact_save_round_trip_exact") for row in smoke.get("rows", [])), errors, "Sovereign-wild consolidated habitat/trophy smoke report is not fully green")
    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        packaging_text = packaging_path.read_text(encoding="utf-8")
        ensure("REQUIRED_SOVEREIGN_WILDS_UNIT_IDS" in packaging_text and "sovereign_wild_habitats_atlas.png.import" in packaging_text and "== 47" in packaging_text, errors, f"{packaging_path.name} must audit sovereign-wild unit surfaces and habitat atlas")
        for artifact_id in trophy_ids:
            ensure(artifact_id.removeprefix("artifact_") in packaging_text, errors, f"{packaging_path.name} must audit packaged {artifact_id} icon art")


def validate_six_unbound_wild_concords(errors: list[str]) -> None:
    slice_id = "content-six-unbound-wild-concords-10184"
    campaign_id = "campaign_six_unbound_oaths"
    atlas_res = "res://art/overworld/runtime/objects/resource_sites/unbound_wild_concords_atlas.png"
    atlas_path = res_path_to_disk(atlas_res)
    source_manifest_path = ROOT / "art" / "overworld" / "source" / "generated" / "resource_sites" / "unbound_wild_concords_wave1" / "manifest.json"
    campaign_art_manifest_path = ROOT / "art" / "campaigns" / "source" / "generated" / "six_unbound_oaths" / "manifest.json"
    smoke_script_path = ROOT / "tests" / "unbound_wild_concords_smoke.gd"
    smoke_scene_path = ROOT / "tests" / "unbound_wild_concords_smoke.tscn"
    smoke_launcher_path = ROOT / "tests" / "unbound_wild_concords_smoke.py"
    smoke_report_path = ROOT / ".artifacts" / "unbound_wild_concords_smoke" / "report.json"
    for path in (atlas_path, source_manifest_path, campaign_art_manifest_path, smoke_script_path, smoke_scene_path, smoke_launcher_path):
        ensure(path.is_file(), errors, f"Missing unbound-wild concord production owner: {path.relative_to(ROOT)}")
    if not atlas_path.is_file() or not source_manifest_path.is_file():
        return

    expected = {
        "brambleback_hedgecourt": ("unit_neutral_brambleback_knucklebears", "unit_neutral_orchard_halberds", "pikeward-brambleback-concord", "brambleconcord_dwelling", "brambleconcord_dwelling_guard"),
        "mireglass_bellfen": ("unit_neutral_mireglass_belltoads", "unit_neutral_reedbarge_poles", "mudkeel-mireglass-concord", "mireglassconcord_dwelling", "mireglassconcord_dwelling_guard"),
        "windcairn_wayhouse": ("unit_neutral_cairnshield_porters", "unit_neutral_windglass_slingers", "daynote-windcairn-concord", "windcairnconcord_dwelling", "windcairnconcord_dwelling_guard"),
        "sapwhistle_greenward": ("unit_neutral_greenbranch_cudgels", "unit_neutral_sapwhistle_callers", "thorncart-greenbranch-concord", "greenbranchconcord_dwelling", "greenbranchconcord_dwelling_guard"),
        "scarshield_breakyard": ("unit_neutral_scarshield_veterans", "unit_neutral_scrapbow_teams", "varn-scarshield-concord", "scarshieldconcord_dwelling", "scarshieldconcord_dwelling_guard"),
        "flaremast_pilotage": ("unit_neutral_harbor_polearms", "unit_neutral_flaremast_crews", "mistcorsair-flaremast-concord", "flaremastconcord_dwelling", "flaremastconcord_dwelling_guard"),
    }
    units = items_index(load_json(CONTENT_DIR / "units.json"))
    groups = items_index(load_json(CONTENT_DIR / "army_groups.json"))
    encounters = items_index(load_json(CONTENT_DIR / "encounters.json"))
    dwellings = items_index(load_json(CONTENT_DIR / "neutral_dwellings.json"))
    sites = items_index(load_json(CONTENT_DIR / "resource_sites.json"))
    objects = items_index(load_json(CONTENT_DIR / "map_objects.json"))
    scenarios = items_index(load_json(CONTENT_DIR / "scenarios.json"))
    campaigns = items_index(load_json(CONTENT_DIR / "campaigns.json"))
    art = load_json(OVERWORLD_ART_MANIFEST_PATH)
    object_assets = art.get("object_assets", {})
    site_sprites = art.get("resource_site_sprites", {})
    encounter_sprites = art.get("encounter_identity_sprites", {})
    ensure((len(units),len(groups),len(encounters),len(dwellings),len(sites),len(objects),len(scenarios)) == (160,437,203,49,377,422,299), errors, "Unbound-wild concord catalog counts changed")
    campaign = campaigns.get(campaign_id, {})
    campaign_chapters = campaign.get("scenarios", []) if isinstance(campaign.get("scenarios", []), list) else []
    expected_scenario_order = [row[2] for row in expected.values()]
    ensure([str(row.get("scenario_id", "")) for row in campaign_chapters if isinstance(row, dict)] == expected_scenario_order and campaign.get("starting_scenario_id") == expected_scenario_order[0], errors, "The Six Unbound Oaths lost its exact six-chapter order or opening")
    ensure(all(bool(str(campaign.get(key, "")).strip()) for key in ("name","summary","description","arc_goal","completion_title","completion_summary","emblem_alt_text")), errors, "The Six Unbound Oaths lost complete player-facing campaign copy")
    campaign_art_manifest = load_json(campaign_art_manifest_path) if campaign_art_manifest_path.is_file() else {}
    campaign_art_rows = campaign_art_manifest.get("assets", []) if isinstance(campaign_art_manifest.get("assets", []), list) else []
    ensure(campaign_art_manifest.get("schema_id") == "six_unbound_oaths_campaign_art_v1" and campaign_art_manifest.get("generator_mode") == "built_in_image_gen" and len(campaign_art_rows) == 7 and len(str(campaign_art_manifest.get("final_prompt", ""))) >= 240 and len(str(campaign_art_manifest.get("background_extraction_prompt", ""))) >= 160, errors, "Six Unbound Oaths image-generation provenance or prompt set changed")
    atlas_payload = atlas_path.read_bytes()
    atlas_sha = "e49de9029d745230625b766be9cecc8300375100918640465295c9741ca914d4"
    ensure(png_size(atlas_path) == (576,48) and hashlib.sha256(atlas_payload).hexdigest() == atlas_sha and len(atlas_payload) >= 26 and atlas_payload[25] in {4,6}, errors, "Unbound-wild concord atlas bytes, size, or alpha changed")
    ensure(Path(f"{atlas_path}.import").is_file(), errors, "Unbound-wild concord atlas Godot import metadata is missing")
    source_manifest = load_json(source_manifest_path)
    source_rows = source_manifest.get("assets", [])
    ensure(source_manifest.get("content_slice_id") == slice_id and source_manifest.get("generation_mode") == "built_in_image_gen_original_unclaimed_and_independent_controlled_landmarks" and source_manifest.get("runtime_sha256") == atlas_sha and source_manifest.get("atlas_size") == [576,48] and len(source_rows) == 12, errors, "Unbound-wild generated-source provenance changed")
    ensure(all(str(row.get("generation_original", "")).startswith("/root/.codex/generated_images/") and len(str(row.get("prompt_summary", ""))) >= 64 for row in source_rows if isinstance(row, dict)), errors, "Unbound-wild image-generation prompt or source provenance changed")

    for index, (stem, row) in enumerate(expected.items()):
        first_unit_id, second_unit_id, scenario_id, placement_id, guard_id = row
        site_id = f"site_{stem}"
        object_id = f"object_{stem}"
        dwelling_id = f"neutral_dwelling_{stem}"
        group_id = f"army_neutral_{stem}_watch"
        encounter_id = f"encounter_{stem}_watch"
        unit_ids = [first_unit_id, second_unit_id]
        ensure(all(unit_id in units for unit_id in unit_ids), errors, f"{dwelling_id} lost one of its two live neutral companies")
        dwelling = dwellings.get(dwelling_id, {})
        ensure(dwelling.get("content_batch_id") == slice_id and dwelling.get("unit_ids") == unit_ids and dwelling.get("site_ids") == [site_id] and dwelling.get("map_object_ids") == [object_id] and dwelling.get("content_status") == "unbound_wild_concord_neutral_dwelling_live", errors, f"{dwelling_id} content graph changed")
        site = sites.get(site_id, {})
        ensure(site.get("content_batch_id") == slice_id and set(site.get("claim_recruits", {})) == set(unit_ids) and set(site.get("weekly_recruits", {})) == set(unit_ids) and site.get("persistent_control") is True and site.get("guard_profile", {}).get("guard_army_group_id") == group_id and site.get("guard_profile", {}).get("guard_encounter_id") == encounter_id, errors, f"{site_id} dual-company recruitment or guard contract changed")
        obj = objects.get(object_id, {})
        ensure(obj.get("resource_site_id") == site_id and obj.get("dwelling_contract", {}).get("roster_unit_ids") == unit_ids and obj.get("runtime_boundary", {}).get("status") == "neutral_dwelling_live" and obj.get("approach", {}).get("guard_clearance_required") is True, errors, f"{object_id} interaction contract changed")
        group = groups.get(group_id, {})
        ensure(group.get("content_batch_id") == slice_id and [stack.get("unit_id") for stack in group.get("stacks", [])] == unit_ids and all(int(stack.get("count", 0)) > 0 for stack in group.get("stacks", [])), errors, f"{group_id} no longer fields both companies")
        encounter = encounters.get(encounter_id, {})
        ensure(encounter.get("content_batch_id") == slice_id and encounter.get("enemy_group_id") == group_id and len(encounter.get("field_objectives", [])) == 1 and len(encounter.get("victory_flags", [])) == 1, errors, f"{encounter_id} production battle contract changed")
        scenario = scenarios.get(scenario_id, {})
        chapter = campaign_chapters[index] if index < len(campaign_chapters) and isinstance(campaign_chapters[index], dict) else {}
        node = next((value for value in scenario.get("resource_nodes", []) if isinstance(value, dict) and value.get("placement_id") == placement_id), {})
        guard = next((value for value in scenario.get("encounters", []) if isinstance(value, dict) and value.get("placement_id") == guard_id), {})
        victory = scenario.get("objectives", {}).get("victory", [])
        requirements = victory[0].get("requirements", []) if victory else []
        ensure(scenario.get("content_batch_id") == slice_id and scenario.get("selection", {}).get("availability", {}) == {"campaign":True,"skirmish":True} and scenario.get("map_size") == {"width":14,"height":9} and len(scenario.get("encounters", [])) == 3 and len(scenario.get("script_hooks", [])) == 5 and len(scenario.get("resource_nodes", [])) == 7, errors, f"{scenario_id} route breadth or dual selector availability changed")
        ensure(chapter.get("scenario_id") == scenario_id and int(chapter.get("chapter_index", 0)) == index + 1 and all(bool(str(chapter.get(key, "")).strip()) for key in ("label","chapter_title","status_hint","carryover_summary","briefing","intel","stakes","aftermath_victory","aftermath_defeat","journal_victory","journal_defeat","seal_alt_text")), errors, f"{scenario_id} lost its full Unbound Oaths chapter presentation")
        if index == 0:
            ensure(chapter.get("starts_unlocked") is True and isinstance(chapter.get("carryover_export"), dict), errors, f"{scenario_id} must open the campaign and export the first bounded oath")
        else:
            previous_id = expected_scenario_order[index - 1]
            previous_flag = next((objective.get("flag") for objective in scenarios.get(previous_id, {}).get("objectives", {}).get("victory", []) if isinstance(objective, dict) and objective.get("type") == "flag_true"), "")
            ensure(chapter.get("unlock_requirements") == [{"type":"scenario_status","scenario_id":previous_id,"status":"victory"},{"type":"scenario_flag_true","scenario_id":previous_id,"flag":previous_flag}] and chapter.get("carryover_import") == {"from_scenario_id":previous_id,"resources":True,"hero_progression":False,"spells":False,"artifacts":False,"flags_prefix":"carryover_"}, errors, f"{scenario_id} lost its exact preceding victory-and-oath unlock or isolated import")
        if index < len(expected) - 1:
            export = chapter.get("carryover_export", {})
            oath_flag = next((objective.get("flag") for objective in victory if isinstance(objective, dict) and objective.get("type") == "flag_true"), "")
            ensure(export.get("retain_hero_progression") is False and export.get("retain_spells") is False and export.get("retain_artifacts") is False and export.get("resource_fraction") == 0.1 and export.get("resource_caps") == {"gold":400,"wood":2,"ore":2,"aetherglass":0,"embergrain":0,"peatwax":0,"verdant_grafts":0,"brass_scrip":0,"memory_salt":0} and export.get("flag_ids") == [oath_flag], errors, f"{scenario_id} lost bounded common-store and exact-oath export isolation")
        ensure(node.get("site_id") == site_id and node.get("guard_front_id") == guard_id and guard.get("encounter_id") == encounter_id and guard.get("guardian_role") == "unbound_wild_concord_keeper", errors, f"{scenario_id} dwelling guard link changed")
        ensure(victory and victory[0].get("type") == "hero_army_meets_requirements" and [value.get("unit_id") for value in requirements] == unit_ids and len(victory) == 4, errors, f"{scenario_id} dual-company victory objective changed")
        unclaimed_id = f"mapobj_{stem}"
        controlled_id = f"resource_site_neutral_{stem}_controlled"
        unclaimed = object_assets.get(unclaimed_id, {})
        controlled = object_assets.get(controlled_id, {})
        ensure(unclaimed.get("path") == atlas_res and unclaimed.get("atlas_region") == [index * 96,0,48,48] and unclaimed.get("assigned_map_object_id") == object_id, errors, f"{object_id} unclaimed landmark art changed")
        ensure(controlled.get("path") == atlas_res and controlled.get("atlas_region") == [index * 96 + 48,0,48,48] and controlled.get("assigned_resource_site_id") == site_id, errors, f"{site_id} controlled landmark art changed")
        ensure(site_sprites.get(site_id, {}).get("asset_id") == controlled_id and site_sprites.get(site_id, {}).get("unclaimed_asset_id") == unclaimed_id, errors, f"{site_id} runtime art switch changed")
        encounter_asset_id = f"encounter_unbound_wild_{stem}_watch"
        ensure(encounter_sprites.get(encounter_id) == encounter_asset_id and object_assets.get(encounter_asset_id, {}).get("path") == f"res://art/units/overworld_icons/{first_unit_id}.png", errors, f"{encounter_id} exact company identity art changed")

    finale = scenarios.get("mistcorsair-flaremast-concord", {}).get("encounters", [])[0]
    ensure(finale.get("placement_id") == "flaremastconcord_first_screen" and finale.get("enemy_commander_state") == {"roster_hero_id":"hero_embercourt_helva_tollbrand","faction_id":"faction_embercourt"} and finale.get("spawned_by_faction_id") == "faction_embercourt", errors, "The Six Unbound Oaths finale lost its fixed roster-backed challenger")

    for manifest_name, expected_count, expected_duration in (("music_runtime_manifest.json",75,8000),("ambient_sfx_manifest.json",11,12000)):
        manifest = load_json(CONTENT_DIR / manifest_name)
        cues = manifest.get("cues", {})
        ensure(manifest.get("runtime_codec") == "vorbis" and manifest.get("runtime_container") == "ogg" and manifest.get("encoder_quality") == 4 and len(cues) == expected_count, errors, f"{manifest_name} Vorbis runtime contract changed")
        ensure(all(str(cue.get("path", "")).endswith(".ogg") and int(cue.get("duration_msec", 0)) == expected_duration and res_path_to_disk(str(cue.get("path", ""))).is_file() for cue in cues.values() if isinstance(cue, dict)), errors, f"{manifest_name} has missing or non-OGG runtime cues")
    for autoload_path in (ROOT / "scripts" / "autoload" / "MusicAudio.gd", ROOT / "scripts" / "autoload" / "AmbientAudio.gd"):
        text = autoload_path.read_text(encoding="utf-8")
        ensure("const SAMPLE_RATE := 44100" in text and "RuntimeAudioLoaderScript.load_stream(path)" in text and '"imported_ogg"' in text and '"vorbis"' in text, errors, f"{autoload_path.name} lost imported Vorbis playback")

    if smoke_script_path.is_file():
        smoke_text = smoke_script_path.read_text(encoding="utf-8")
        for token in ("UNBOUND_WILD_CONCORDS_SMOKE", "campaign_six_unbound_oaths", "CampaignRulesScript.build_session", "CampaignRulesScript.record_session_completion", "BattleRules.create_battle_payload", "BattleRules.resolve_if_battle_ready", "ScenarioRules.evaluate_session", "validation_encounter_presentation_payload", "campaign_complete", "campaign_art_identity_count", "cross_commander_resource_only_carryover", "AudioStreamOggVorbis", "single_consolidated_smoke"):
            ensure(token in smoke_text, errors, f"Unbound-wild consolidated smoke is missing proof token: {token}")
    if smoke_scene_path.is_file():
        ensure("res://tests/unbound_wild_concords_smoke.gd" in smoke_scene_path.read_text(encoding="utf-8"), errors, "Unbound-wild smoke scene lost its exact script")
    if smoke_report_path.is_file():
        smoke = load_json(smoke_report_path)
        rows = smoke.get("rows", [])
        ensure(smoke.get("ok") is True and smoke.get("case_count") == 6 and smoke.get("save_version") == 9 and smoke.get("campaign_id") == campaign_id and smoke.get("campaign_complete") is True and smoke.get("campaign_chapter_count") == 6 and smoke.get("campaign_battle_victory_count") == 18 and smoke.get("campaign_art_identity_count") == 7 and smoke.get("cross_commander_resource_only_carryover") is True and smoke.get("single_consolidated_smoke") is True and len(rows) == 6 and all(row.get("battle_payload_count") == 3 and row.get("army_objective_met") and row.get("scenario_victory") and row.get("exact_identity_art") and row.get("save_round_trip_exact") and row.get("campaign_launch_exact") and row.get("campaign_battle_victory_count") == 3 and row.get("oath_flag_exact") and row.get("campaign_save_round_trip_exact") and len(row.get("unit_ids", [])) == 2 for row in rows), errors, "Unbound-wild consolidated campaign/gameplay/art/save smoke report is not fully green")
    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        packaging_text = packaging_path.read_text(encoding="utf-8")
        ensure("REQUIRED_UNBOUND_WILD_CONCORDS_ATLAS_NAME" in packaging_text and "unbound_wild_concords_atlas.png.import" in packaging_text and "== 47" in packaging_text, errors, f"{packaging_path.name} must audit the packaged unbound-wild atlas")


def validate_six_marchland_seats(errors: list[str]) -> None:
    batch_id = "content-six-marchland-seats-10184"
    towns = items_index(load_json(CONTENT_DIR / "towns.json"))
    factions = items_index(load_json(CONTENT_DIR / "factions.json"))
    scenarios = items_index(load_json(CONTENT_DIR / "scenarios.json"))
    groups = items_index(load_json(CONTENT_DIR / "army_groups.json"))
    heroes = items_index(load_json(CONTENT_DIR / "heroes.json"))
    manifest_path = ROOT / "art" / "towns" / "source" / "generated" / "marchland_seats" / "manifest.json"
    smoke_script = ROOT / "tests" / "six_marchland_seats_smoke.gd"
    smoke_scene = ROOT / "tests" / "six_marchland_seats_smoke.tscn"
    smoke_wrapper = ROOT / "tests" / "six_marchland_seats_smoke.py"
    smoke_report = ROOT / ".artifacts" / "six_marchland_seats_smoke" / "report.json"
    author_script = ROOT / "tools" / "author_six_marchland_seats.py"
    expected = {
        "town_amberweir_granary": ("faction_embercourt", "hero_embercourt_belis_rainledger", "rainledger-amberweir-long-march", "amberweir", "hero_orrik", "946f20a3b201e627beca0e7d154e881624dc6afcf7b6c28a96948eade38c8a07"),
        "town_moonbite_reedshrine": ("faction_mireclaw", "hero_mireclaw_nix_votivejaw", "votivejaw-moonbite-long-march", "moonbite", "hero_sunvault_essa_daynote", "f05ccdc207acf0f777fefde7ee78f4852129af8e24206c3ff4f9d6ee9ff8bedd"),
        "town_splitprism_duelcourt": ("faction_sunvault", "hero_sunvault_renn_facetlane", "facetlane-splitprism-long-march", "splitprism", "hero_thornwake_veyra_seedseer", "3fe076a9a0d9f2e381d70685c1ca9bda784cec4d3474499ec3772ea1ac1cab6a"),
        "town_woundroot_hearthgrove": ("faction_thornwake", "hero_thornwake_merek_greenbarrow", "greenbarrow-woundroot-long-march", "woundroot", "hero_brasshollow_pava_ashmeter", "f0938b6de12e626479a0d8671d6bff3acdd93e30b594b67c7944adab483074d5"),
        "town_whitegauge_calibration_yard": ("faction_brasshollow", "hero_brasshollow_lina_gaugesavant", "gaugesavant-whitegauge-long-march", "whitegauge", "hero_veilmourn_thir_obituaryink", "cd9f56ba0eac275caa136ba2b8787775f105c7e376b55d01d664afdfebdf0967"),
        "town_dreamwake_oracle_harbor": ("faction_veilmourn", "hero_veilmourn_morwen_wakeoracle", "wakeoracle-dreamwake-long-march", "dreamwake", "hero_embercourt_helva_tollbrand", "8b894403b88e6bee8fc1ddfb902f548b56078fe09c95b3bb780860bc541ffeef"),
    }
    for path in (manifest_path, smoke_script, smoke_scene, smoke_wrapper, author_script):
        ensure(path.is_file(), errors, f"Missing Six Marchland Seats owner: {path.relative_to(ROOT)}")
    if not manifest_path.is_file():
        return
    manifest = load_json(manifest_path)
    rows = {str(row.get("town_id", "")): row for row in manifest.get("items", []) if isinstance(row, dict)}
    ensure(manifest.get("source_model") == "built_in_image_gen" and manifest.get("content_batch_id") == batch_id and manifest.get("runtime_size") == [1600, 900] and manifest.get("source_size") == [1536, 1024] and set(rows) == set(expected), errors, "Six Marchland Seats source manifest contract changed")
    runtime_payloads = []
    source_payloads = []
    for town_id, (faction_id, hero_id, scenario_id, prefix, rival_hero_id, runtime_sha) in expected.items():
        town = towns.get(town_id, {})
        scenario = scenarios.get(scenario_id, {})
        group = groups.get(f"army_{prefix}_long_march_company", {})
        row = rows.get(town_id, {})
        source_path = res_path_to_disk(str(row.get("source_path", "")))
        runtime_path = res_path_to_disk(str(row.get("runtime_path", "")))
        source_bytes = source_path.read_bytes() if source_path.is_file() else b""
        runtime_bytes = runtime_path.read_bytes() if runtime_path.is_file() else b""
        ensure(town.get("faction_id") == faction_id and town.get("content_status") == "marchland_seat_live" and town.get("content_batch_id") == batch_id and town.get("marchland_seat", {}).get("lead_hero_id") == hero_id and town.get("marchland_seat", {}).get("scenario_id") == scenario_id, errors, f"{town_id} Marchland Seat identity changed")
        ensure(town_id in factions.get(faction_id, {}).get("town_ids", []) and len(town.get("buildable_building_ids", [])) >= 20 and len(town.get("garrison", [])) == 3 and len(town.get("spell_library", [])) >= 2, errors, f"{town_id} is not a complete faction town")
        ensure(heroes.get(hero_id, {}).get("faction_id") == faction_id, errors, f"{town_id} lead hero faction changed")
        ensure(scenario.get("content_status") == "marchland_seat_long_form_skirmish_live" and scenario.get("content_batch_id") == batch_id and scenario.get("map_size") == {"width": 18, "height": 12} and len(scenario.get("map", [])) == 12 and all(len(map_row) == 18 for map_row in scenario.get("map", [])), errors, f"{scenario_id} long-form map contract changed")
        ensure(scenario.get("hero_id") == hero_id and scenario.get("player_faction_id") == faction_id and scenario.get("selection", {}).get("availability") == {"campaign": False, "skirmish": True} and scenario.get("player_army_id") == f"army_{prefix}_long_march_company", errors, f"{scenario_id} exact skirmish launch identity changed")
        ensure(len(scenario.get("towns", [])) == 2 and len(scenario.get("encounters", [])) == 4 and len(scenario.get("resource_nodes", [])) == 10 and len(scenario.get("artifact_nodes", [])) == 2 and len(scenario.get("script_hooks", [])) == 5, errors, f"{scenario_id} composed content count changed")
        victory = scenario.get("objectives", {}).get("victory", [])
        defeat = scenario.get("objectives", {}).get("defeat", [])
        ensure(len(victory) == 6 and len(defeat) == 3 and any(row.get("placement_id") == f"{prefix}_counterstroke" for row in victory if isinstance(row, dict)), errors, f"{scenario_id} objective chain changed")
        final_front = next((placement for placement in scenario.get("encounters", []) if placement.get("placement_id") == f"{prefix}_front_4"), {})
        ensure(final_front.get("enemy_commander_state", {}).get("roster_hero_id") == rival_hero_id, errors, f"{scenario_id} roster-backed rival changed")
        ensure(group.get("faction_id") == faction_id and group.get("content_batch_id") == batch_id and len(group.get("stacks", [])) == 5, errors, f"{scenario_id} expanded opening company changed")
        ensure(source_path.is_file() and png_size(source_path) == (1536, 1024) and hashlib.sha256(source_bytes).hexdigest() == row.get("source_sha256") and len(str(row.get("prompt", ""))) >= 160 and len(str(row.get("accessible_description", ""))) >= 80, errors, f"{town_id} generated source or provenance changed")
        ensure(runtime_path.is_file() and png_size(runtime_path) == (1600, 900) and hashlib.sha256(runtime_bytes).hexdigest() == runtime_sha == row.get("runtime_sha256") and Path(f"{runtime_path}.import").is_file(), errors, f"{town_id} runtime scenic art or import changed")
        source_payloads.append(source_bytes)
        runtime_payloads.append(runtime_bytes)
    ensure(len(source_payloads) == 6 and len(set(source_payloads)) == 6 and len(runtime_payloads) == 6 and len(set(runtime_payloads)) == 6, errors, "All six Marchland Seat source/runtime panoramas must remain byte-distinct")
    if smoke_script.is_file():
        text = smoke_script.read_text(encoding="utf-8")
        for token in ("SIX_MARCHLAND_SEATS_SMOKE", "BattleRulesScript.create_battle_payload", "ScenarioScriptRulesScript.process_hooks", "TownRules.build_active_town", "TownRules.recruit_active_town", "OverworldRules.capture_town_by_placement", "ScenarioRulesScript.evaluate_session", "marchland_seats_contact_sheet.png", '"single_consolidated_smoke": true'):
            ensure(token in text, errors, f"Six Marchland Seats consolidated smoke is missing proof token: {token}")
    if smoke_scene.is_file():
        ensure("res://tests/six_marchland_seats_smoke.gd" in smoke_scene.read_text(encoding="utf-8"), errors, "Six Marchland Seats smoke scene lost its exact script")
    ensure(smoke_report.is_file(), errors, "Six Marchland Seats consolidated smoke report is missing")
    if smoke_report.is_file():
        report = load_json(smoke_report)
        ensure(report.get("ok") is True and report.get("case_count") == 6 and report.get("direct_battle_victory_count") == 24 and report.get("counterstroke_battle_victory_count") == 6 and report.get("named_rival_count") == 6 and report.get("town_build_count") == 6 and report.get("town_recruit_count") == 6 and report.get("exact_scenic_art_count") == 6 and report.get("scenario_victory_count") == 6 and report.get("save_round_trip_count") == 6 and report.get("map_capture_count") == 6 and report.get("save_version") == 9 and report.get("single_consolidated_smoke") is True and len(report.get("rows", [])) == 6, errors, "Six Marchland Seats consolidated smoke report is not fully green")
    for packaging_path in (PACKAGING_LINUX_EXPORT_SMOKE_SCRIPT_PATH, PACKAGING_WINDOWS_EXPORT_SMOKE_SCRIPT_PATH):
        text = packaging_path.read_text(encoding="utf-8")
        ensure(text.count("art/towns/runtime/backdrops/marchland_seats/") == 6 and all(town_id in text for town_id in expected), errors, f"{packaging_path.name} must audit all six packaged Marchland Seat backdrops")


